INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-002', 'ho-phach-la-gi-lich-su-khai-thac-va-su-dung-ho-phach', 'Hổ phách là gì? Lịch sử khai thác và sử dụng Hổ phách', 'Thế Giới Đá Quý',
    '/uploads/news/art-002-1-vong-tay-ho-phach-12-ly-vang-dam-0.jpg', 'Hổ phách khá quen thuộc với nhiều nguời thích đeo những đồ trang sức phong thủy như vòng tay, mặt dây chuyền….Vậy Hổ phách là gì? Tại sao mọi người lại thích dùng Hổ phách trong vật dụng phong thủy của mình? Cách bảo quản nó ra sao thì không phải ai cũng biết. Trong bài viết hôm nay chúng ta sẽ đi trả lời từng câu hỏi một, để làm rõ hơn các vấn đề trên nhé.', '**Hổ phách là gì? Lịch sử khai thác và sử dụng Hổ phách**

Hổ phách khá quen thuộc với nhiều nguời thích đeo những đồ trang sức phong thủy như vòng tay, mặt dây chuyền….Vậy Hổ phách là gì? Tại sao mọi người lại thích dùng Hổ phách trong vật dụng phong thủy của mình? Cách bảo quản nó ra sao thì không phải ai cũng biết. Trong bài viết hôm nay chúng ta sẽ đi trả lời từng câu hỏi một, để làm rõ hơn các vấn đề trên nhé.

**Hổ phách là gì?**

Hổ phách được các nhà cổ sinh phát hiện là vật chất có thể trả lời các câu hỏi về cuộc sống địa cầu trong giai đoạn nguyên thủy như: Tên của các loài vật được bao bọc trong lớp Hổ Phách (hiện có 1000 loại được xác định tên).Do đó, Hổ phách đóng vai trò là người trả lời những chứng tích thời gian.

Bởi Hổ Phách là thành phần của nhựa cây nguyên sinh hàng triệu năm trên tế giới, chúng bao quanh mẫu vật như lá, đá, côn trùng….Nhưng loại Hổ phách đẹp nhất phải được cấu tạo từ nhựa loài thông cổ Pityoxylon succinifer Kauss nay đã biến mất tuyệt chủng và không còn tìm thấy nữa.Hổ phách được sử dụng làm đồ trang sức từ thời kỳ đồ đánhờ nhờ vẻ đẹp của nó.

Hổ phách có rất nhiều tên gọi như: huyết phách, minh phách, hồng tùng chi….Tên khoa học là Succinym.

![Hổ phách là gì? Sản phẩm hổ phách được kiểm định](/uploads/news/art-002-1-vong-tay-ho-phach-12-ly-vang-dam-0.jpg)

[Vòng tay hổ phách 12 ly vàng đậm kiểm định SJC](https://web.archive.org/web/20160409232428/http://thegioidaquy.net/phong-thuy/vong-tay-ho-phach-12-ly-vang-dam-kiem-dinh-SJC-2523.html)được cung cấp bởi Phong thuỷ Hoa Mộc Lan

**Lịch sử khai thác sử dụng Hổ phách trên thế giới?**

Cũng như những khoáng vật quý trên thế giới, Hổ phách được rất nhiều quốc gia, dân tộc tranh dành để tích trữ trong kho của cải của mình. Đối với người Trung Quốc, Hổ Phách được coi là một vật dụng phong thủy mang lại may mắn cho người sở hữu nó. Những miến Hổ Phách lớn quý giá thường được dâng lên cho vua, quan lại, phi tần v.v..để thể hiện tấm lòng của người tặng.Còn trong nhân gian Hổ phách sử dụng để làm tram cài, đồ trang sức…nó tượng trưng cho sự giàu có.

Ở châu Âu, người Hi Lạp gọi Hổ Phách là Electron vì nó mang tính điện khi cọ sát với vải, nó có thể hút những tinh thể cực nhỏ. Người La Mã sử dụng chiến tranh để chiếm đóng và kiểm soát các vùng có Hổ phách vì vị vua Nero rất chuộng hổ phách, và giá của nó còn cao hơn cả 1 nô lệ da đen khỏe mạnh.Người Đức cổ đốt hổ phách để có hương thơm, do đó họ gọi nó là bernstein hay đá cháy.

Trong một số tác phẩm nghệ thuật và trang sức để lại thời Trung Cổ thì[Hổ Phách](https://web.archive.org/web/20160409232428/http://thegioidaquy.net/phong-thuy/da-phongthuy-223-Da-Ho-Phach)được dùng để làm chuỗi hạt cầu nguyện vì cho rằng Hổ phách mang linh khí của trời đất, sẽ thấu hiểu được trái tim con người.Cho nên, một số tổ chức của giới hiệp sĩ kiểm soát việc kinh doanh và việc sở hữu trái phép hổ phách nguyên liệu là bất hợp pháp ở hầu hết châu Âu vào năm 1400.

Đối với người Châu Á, nhất là lĩnh vực Đông y, các lương y cho rằng Hổ phách có tính bình, vụ ngọt có khả năng an thần, định kinh, lợi tiểu, tán ứ huyết vv… Trong lĩnh vực trang sức thì Hổ phách được mài giũa và cắt gọt thành đồ thủ công mỹ nghệvà làm các loại mặt dây chuyền hổ phách.

**Có bao nhiêu loại Hổ phách?**

Hổ phách có rất nhiều màu như: Trắng, Vàng, Vàng kim, Cam, Nâu, Xanh, Xanh lục và Đỏ. Đối với mỗi quốc gia có sở thích về màu Hổ phách khác nhau như: Người Mỹ thích Hổ Phách màu trong suốt, người Pháp thì thích Hổ phách mây (màu đục, vệt trắng sương như mây). Người Trung Quốc, Nhật Bản, Hàn Quốc thì chuộng Hổ phách màu đỏ, vì quan niệm nó trừ tà ma và mang lại may mắn.

Nhưng đối với dân chơi Hổ phách thì quý nhất lại là Hổ phách màu xanh vào ban ngày vì nó gây ra bức xạ màu xanh của ánh sáng. Hổ phách được làm đồ trang sức như dây Hổ phách phong thủy hạt tròn, hoặc chạm trổ để làm nhẫn, mặt dây chuyền.

![Mặt dây chuyền đá hổ phách](/uploads/news/art-002-2-mat-day-chuyen-ho-phach-cuc-dep-0.jpg)

Mặt dây chuyền đá hổ phách

Các loại Hổ phách được phân bố ở nhiều nơi: Hổ phách vùng Baltic thì cổ hơn nên được thị trường ưa chuộng, nhưng hổ phách ở Dominica thì lại nhiều xác côn trùng hơn. Trong vùng Baltic, mỏ hổ phách lớn nhất ở tây Kaliningrad thuộc Nga, ngoài ra còn tìm thấy hổ phách ở Lithuania, Estonia, Latvia, Ba Lan và Đức, thỉnh thoảng hổ phách lại trôi dạt vào bờ biển Baltic thuộc Đan Mạch và Na Uy. Các nguồn hổ phách khác ở các nước như Miến Điện, Liban, đảo Scicily, Mexico, Rumani và Canada.

**Cách bảo quản và làm sạch Hổ Phách**

Hổ phách là loại đá khá mềm, nên không được chân cất nó với đồ kim Hoàn vì dễ bị trầy xước. Không rửa Hổ phách bằng xà phòng có tính tẩy cao, hay xịt nước hoa lên Hổ phách vì nó gây oxi hóa cho chúng. Khi vệ sinh Hổ phách chỉ cần lau nhẹ bằng vải mềm thếm nước được vắt ráo, Hổ phách sẽ sạch bong.

*Sau khi đọc xong bài viết hổ phách có nguồn gốc từ đâu? Sẽ giúp bạn có thêm nhiều khiến thức về loại linh vật phong thuỷ may mắn này từ TheGioiDaQuy.net. Phong thuỷ Hoa Mộc Lan nổi tiếng Tp HCM cung cấp các loại hổ phách chất lượng cao, cam kết 100% là sản phẩm đến từ thiên nhiên.*',
    '2016-04-07 09:00:00', 0, 366, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-003', 'truyen-thuyet-phung-hoang', 'Truyền thuyết Phụng Hoàng', 'Thế Giới Đá Quý',
    '/uploads/news/thumb-art-003-truyen-thuyet-phung-hoang-0.jpg', 'Trong truyền thuyết phương Đông và phương Tây đều mô tả Phụng Hoàng là một loài chim kì diệu. Phụng Hoàng sở hữu một tiếng ca du dương, có tác dụng thần diệu về tinh thần, giúp người nghe bình tâm và lấy lại can đảm.', '- Nhắc đến**sự bất tử và tái sinh**, người ta không thể không nhắc đến 1 loài chim chỉ có trong truyền thuyết:**Ph****ụng Hoàng**. Phụng Hoàng là sự kết hợp các đặc điểm xinh đẹp nhất của nhiều giống chim: đầu gà, chiếc cổ cao của chim hạc, và bộ đuôi thướt tha rực rỡ của loài công. Tiếc rằng chúng chỉ tồn tại trong trí tưởng tượng của con người.

- Trong truyền thuyết phương Đông và phương Tây đều mô tảPhụng Hoànglà một loài chim kì diệu. Ngoài việc có thể mang những vật có khối lượng lớn hơn trọng lượng của mình nhiều lần, nước mắt còn có tác dụng chữa lành các vết thương.

-*Ph**ụ**ng Hoàng sở hữu một tiếng ca du dương*, có tác dụng thần diệu về tinh thần, giúp người nghe bình tâm và lấy lại can đảm.

- Máu và thịt phượng hoàng có thể giúp con người trường sinh bất tử. Lông phụng hoàng được sử dụng như 1 loại bùa hộ mệnh hoặc vũ khí lợi hại để chống lại cái ác.

- Theo thần thoại Trung Quốc ,**Ph****ụ****ng Ho****à****ng**là linh vật thứhai chỉsau Rồng. Nólàbiểu tượng của ân sủng và đức tinh. Hình ảnh về phượng hoàng đã xuất hiện tại Trung Quốc cách đây trên bảy nghìn năm, thông thường trong các miếng ngọc và trên các vật tổ may mắn. Nó thường làvật tổcủa các bộ lạc miền Đông thời cổ đại ở Trung Quốc.

- Theo truyền thuyết, Phụng hoàng thường xuất hiện trong thời kỳ hòa bình và thịnh vượng. Tại Trung Hoa thời cổ đại, có thể tìm thấy hình ảnh của phụng hoàng trong các trang trí của đám cưới hay của hoàng tộc cùng với con rồng. Điều này là do người Trung Quốc coi rồng và phụng là biểu tượng cho quan hệ hạnh phúc giữa chồng và vợ, một kiểu ẩn dụ khác của âm và dương.

[![mat-Rong-Phung-bat-quai-da-chalcedony-xanh](/uploads/news/art-003-1-1-mat-rong-phung-bat-quai-da-chalcedony-xanh-0.jpg)](https://web.archive.org/web/20150328173747/http://thegioidaquy.net/phong-thuy/mat-rong-phung-bat-quai-da-chalcedony-xanh-950.html#.VPMfcHysVlw)

*[Mặt Rồng Phụng bát quái phong thuỷ](https://web.archive.org/web/20150328173747/http://thegioidaquy.net/phong-thuy/mat-rong-phung-bat-quai-da-chalcedony-xanh-950.html#.VPMfcHysVlw)đem lại may mắn, hạnh phúc tình duyên*

- Tại Nhật Bản, cùng với mặt trời,**chim****Ph****ụ****ng hoàng là một trong những biểu tượng của Đế quốc Nhật Bản**. Trong những thiết kế hình Xăm Phụng Hoàng của Nhật Bản, thường kết hợp với Rồng, tượng trưng cho âm và dương, sự kết hợp hài hòa của đức tính tốt nhất của phụ nữ và nam tính.

- Ngoài ra,**Ph****ụ****ng Hoàng**được tìm thấy trong những hình khắc trên thanh gươm,hay được thêu trên kimono.

- Trong thần thoại Ai Cập thìPhụng hoàng (phoenix hay phœnix) là một dạng chim lửa thần thánh và linh thiêng. được cho là sẽ phục sinh sau khi bị thương, vì thế nó gần như là bất tử và không thể bị đánh bại; một biểu tượng của lửa và thánh thần.

- Cóthểnói,Phụng Hoàng làmột loài chim vô cùng thiêng liêng, cao quý. Loài chim này thường sống trên những ngọn núi cao, xa xôi mà con người không thể vươn tới. Nếu có ai đó muốn tìm được chúng để mưu cầu sức mạnh hoặc sự bất tử sẽ phải vượt qua những thử thách chết người.

- Tuy là một sinh vật thuần khiết, chỉ ăn trái cây, nhưng vì dễ dàng đọc được ý nghĩ của người ta, nên khi phụng hoàng phát hiện kẻ đến tìm có mưu đồ xấu, nó sẽ vươn dài những móng vuốt cực kỳ sắc bén để chống trả đến cùng. Ngược lại, với những người tốt cần hỗ trợ, chỉ cần chứng tỏ được lòng quyết tâmbằng cách vượt qua chặng đường cam khổ, tìm được tổ phụng hoàng, nó sẽ ân cần và hết lòng giúp đỡ.

[*Thegioidaquy.net*](https://web.archive.org/web/20150328173747/http://thegioidaquy.net/phongthuy.html)',
    '2015-03-01 09:00:00', 0, 409, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-004', 'cach-dat-tuong-di-lac-hop-phong-thuy', 'Cách đặt Tượng Di Lặc hợp phong thủy', 'Thế Giới Đá Quý',
    '/uploads/news/thumb-art-004-cach-dat-tuong-di-lac-hop-phong-thuy-0.jpg', 'Trong Phong Thủy người ta thường rất thích chọn Tượng Phật Di Lặc có khuôn mặt cười hả hê, với mong muốn sẽ nhận được thật nhiều niềm vui và mọi sự luôn được như ý. Hãy cùng chúng tôi tìm hiểu các đặt Tượng Di Lặc sao cho hợp phong thủy nhé!', '- Trong thếgiới hiệnđại ngày nay, chúng ta cóthểdễdàng thấy hìnhảnh[Phật Di Lặc](https://web.archive.org/web/20150329105211/http://thegioidaquy.net/phong-thuy/di-lac-da-da-nang-1168.html#.VPMKbHysVlw)hiện hữuở khắp mọi nơi như: nhàriêng, cửa hàng, khách sạn hoặc tại các chùa chiền.Người ta thường rất thích chọn Tượng Phật Di Lặc có khuôn mặt cười hả hêđểbày trítrong nhàvới mong muốn sẽ nhận được thật nhiều niềm vui và mọi sự luôn được như ý.

- Ngoài việc chọn mua**Phật Di Lặc**chúng ta cũng cần phải chúýđến việc bốtrịTượng Phật sao cho mang lại nhiều lợiích phong thủy cho mình.Đây làviệc làm hết sức cần thiết bởi việc bốtríTượng Di Lặc trong nhàmột cách tùy tiện sẽlàm cho tượng không thểphát huyđược năng lượng phong thủy, thậm chícòn cótácđộng xấuđến giađình.

**- Phật Di Lặc**thường đặt tôn kính ở những nơi mang ý nghĩa sum vầy, đoàn viên, thăm viếng để biểu trựng gia hộ cho mọi điều được an lạc, thái hòa, vui tươi khi gia chủ được tiếp kiến bất cứ ai. Vì thế, ta thường thấy Ngài được đặt trang trọng tại phòng khách lớn hoặc đối diện ngay cửa chính hướng ra ngoài ngự trên bàn thờ ông Địa - thần Tài.

- Bày tượng Phật đối diện với cửa chính: Vị trí này được cho là giúp Phật biến toàn bộ khí vào nhà thành năng lượng tốt.

- Nên***đặt tượng Phật Di Lặc ở độ cao khoảng 1m***, nhìn thẳng ra cửa nhà. Nếu không có được vị trí lý tưởng nói trên, hãy bày tượng ở một chiếc bàn cạnh tường hoặc ở góc xa nhất của phòng nhưng cũng phải đảm bảo tượng Phật đối mặt với cửa chính.

[![tuong-Di-Lac-da-Kim-Sa](/uploads/news/art-004-1-1-tuong-di-lac-da-kim-sa-0.jpg)](https://web.archive.org/web/20150329105211/http://thegioidaquy.net/phong-thuy/di-lac-da-kim-sa-471.html#.VPMUNXysVlw)

*[Tượng Phật Di Lặc đá kim sa](https://web.archive.org/web/20150329105211/http://thegioidaquy.net/phong-thuy/di-lac-da-kim-sa-471.html#.VPMUNXysVlw)mang lại sựan lạc may mắn*

- Bày tượng Phật ở bàn làm việc giúp bạn hoàn thành công việc tốt hơn, đồng thời giảm bớt căng thẳng và tranh cãi với đồng nghiệp.

- Học sinh muốn đạt thành tích cao có thể**đặt tượng Di Lặc**trên bàn học để tăng cảm hứng học tập.

- Với những người làm việc trong môi trường cạnh tranh, những người nắm giữ những vị trí chủ chốt của công ty hay các chính trị gia… thì việc đặt**Phật Di Lặc**ở nơi làm việc hoặc tại nhà riêng giúp mang lại nhiều sự may mắn và loại bớt sự thù địch.

- Đặt tượng Phật trong xe ô tô giúp giảm bớt lo âu, tránh tai nạn và mang lại tin vui.Khi căng thẳng hoặc lo âu, nhìn vào hình ảnh tượng Phật Cười cũng có thể giúp đầu óc minh mẫn giảm bớt căng thẳng, mệt mỏi, phiền muộn....

- Tóm lại,**T****ượ****ng****Phật Di Lặc**được cholà món quà lý tưởng cho bất cứ dịp vui nào, với người đang gặp nhiều rủi ro, đây cũng là món quà hết sức ý nghĩa.

[![di-Lac-ngoi-da-trang](/uploads/news/art-004-2-1-di-lac-ngoi-da-trang-0.jpg)](https://web.archive.org/web/20150329105211/http://thegioidaquy.net/phong-thuy/tuong-da-di-lac-1080.html#.VPMVBnysVlw)

*[Tượng di lặc](https://web.archive.org/web/20150329105211/http://thegioidaquy.net/phong-thuy/tuong-da-di-lac-1080.html#.VPMVBnysVlw)may mắn an lạc, phù hợp cho người mạng Kim mạng Thủy*

- Chú ý: tuyệt đối không được bày tượng Phật trong nhà bếp, phòng tắm, phòng ngủ hay đặt trực tiếp trên sàn nhà.

- Tại các căn hộ,Phật Di Lặc không nhất định là phải né tránh có lầu phía trên, khác hẳn ta thờ Phật Quan Âm là luôn ở vị trí cao nhất trong vị thế căn nhà hay căn hộ.

- Trong**Phong Thủy**, nếu trên tượng Phật có lầu gác mà người ta có thể đi lên xuống, dẫm qua lại ở phía trên tượng Phật, thì gia đình sẽ gặp nhiều chuyện lận đận. Vìvậy khiđặt tượng Phật Di Lặc cần phải đảm bảo chắc chắn rằng phía trên nơi đặt tượng Phật, không có ai đi qua lại, và tượng Phật được đặt ở nơi trang nghiêm, ai nhìn thấy cũng cung kính, thì gia đình sẽ gặp nhiều chuyện vui và may mắn.

- Nên*đặttượngPhật Di Lặc**ở cung Đông của ngôi nhà*hay phòng kháchđểtạo sự hài hòa cho cả gia đình và hóa giải mọi rắc rối, cãi cọ.

[*Thegioidaquy.net*](https://web.archive.org/web/20150329105211/http://thegioidaquy.net/phongthuy.html)',
    '2015-03-01 09:00:00', 0, 452, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-005', 'phat-di-lac', 'Phật Di Lặc', 'Thế Giới Đá Quý',
    '/uploads/news/thumb-art-005-phat-di-lac-0.jpg', 'Phật Di Lặc hay còn có tên gọi khác là Phật Cười. Trong phong thủy, Phật Di Lặc là biểu tượng tuyệt đối của sự hạnh phúc. Bởi nụ cười của Phật Di Lặc có sức mạnh lan tỏa tới mức nó luôn tỏa sáng trên khuôn mặt hiền từ và phúc hậu của Ngài. Phật ở nơi đâu nơi đó sẽ có hạnh phúc.', '**1.****T****ìm hi****ểu v****ềPh****ật Di L****ặc:**

- Trong thếgiới hiệnđại ngày nay, chúng ta cóthểdễdàng thấy hìnhảnh[Phật Di Lặc](https://web.archive.org/web/20150512173737/http://thegioidaquy.net/phong-thuy/di-lac-da-da-nang-1168.html#.VPMKbHysVlw)hiện hữuởkhắp mọi nơi như: nhàriêng, cửa hàng, khách sạn hoặc tại các chùa chiền.

- Trong Phật giáo Tây Tạng, Phật Di Lặcđược thờcúng rộng rãi vàphổbiến với ý nghĩa Phật sẵn sangđứng dậyđi giáo hóa chúng sinh. P*hật Di Lặcởnhững hìnhảnh banđầuđược mô tảnhưmột vịhoàng tửtuấn tú*, thanh mảnh vàthường mang trên người trang phục của hoàng giaẤnĐộ.

- Theo truyền thuyết,**Phật Di Lặc**làvịPhật thứ5, thay thếPhật Thích Ca Mâu Ni vàcũng làvịPhật cuối cùng xuất hiện trên tráiđất. Di Lặc làvịBồTát xuất hiện trên TráiĐấtđãđược giác ngộhoàn toàn, chứng ngộthành Phật, giảng dạy Phật Pháp vàgiáo hóa chúng sinh.

-Phật Di Lặc hay còn cótên gọi khác làPhật Cười. Niềm vui lớn nhất của vịBồTát này chính làhóa giải những cơn giận dữ, buồn phiền,áp lực, căng thẳng của con người, mangđến cho họsựvui vẻ, hạnh phúc. Di Lặc chính làbiểu tượng của sựhài hòa vàniềm vui. Trong phong thủy,**Phật Di Lặc**làbiểu tượng tuyệtđối của sựhạnh phúc. Bởi***nụcười của Phật Di Lặc***cósức mạnh lan tỏa tới mức nóluôn tỏa sáng trên khuôn mặt hiền từvàphúc hậu của Ngài. Phậtởnơiđâu nơiđósẽcóhạnh phúc.

[![di-Lac-da-Labradorite-35-0_1](/uploads/news/art-005-1-1-di-lac-da-labradorite-35-01.jpg)](https://web.archive.org/web/20150512173737/http://thegioidaquy.net/phong-thuy/di-lac-da-labradorite-35-3102.html#.VPMMLnysVlw)

*[Mặt Di Lặc phong thuỷ](https://web.archive.org/web/20150512173737/http://thegioidaquy.net/phong-thuy/di-lac-da-labradorite-35-3102.html#.VPMMLnysVlw)đem lại giàu có, an lạc cho người đeo*

- Chỉ cần nhìn ngắm khuôn mặt Phật thì người buồn phiền cũng có thể giảm căng thẳng, phiền muộn và cảm thấy vui lên. Xoa bụng Phật cũng được cho là sẽ mang lại nhiều may mắn và sự tốt lành.

- Trong**Phong Thủy**người ta thường rất thích chọn những tượng Phật có khuôn mặt cười hả hê, với mong muốn sẽ nhận được thật nhiều niềm vui và mọi sự luôn được như ý.

[![mat-Di-Lac-da-den-Phat-Son](/uploads/news/art-005-2-1-mat-di-lac-da-den-phat-son-0.jpg)](https://web.archive.org/web/20150512173737/http://thegioidaquy.net/phong-thuy/mat-di-lac-da-phat-son-989.html#.VPMK5HysVlw)

***[Phật Di Lặc](https://web.archive.org/web/20150512173737/http://thegioidaquy.net/phong-thuy/mat-di-lac-da-phat-son-989.html#.VPMK5HysVlw)**làbiểu tượng tuyệtđối của sựhạnh phúc*

[if !supportLists]**2.**[endif]**S****ự****kh****á****c nhau gi****ữ****a Ph****ậ****t Di L****ặ****c v****à****Th****ầ****n T****à****i:**

- Cần phân biệt rõ ràng giữa**Phật Di Lặc và Thần Tài**. Nhà Phật không coi trọng chuyện tiền tài, phúc lộc, tất cả chỉ là vật ngoài thân. Vì vậy, hình ảnh Phật Di Lặc - vị phật tượng trưng cho vị lai, cho thế giới tốt đẹp trong tương lai hoàn toàn không nên bị nhầm lẫn với Thần Tài.

- Phát tích của Thần tài là gắn liền với sự ra đời của Đạo Lão từ Trung Quốc, chỉ có hình dáng bề ngoài là có nét tương đồng. Người ta thờ Phật Di Lặc để cầu mong sự an lạc chứ không cầu tiền, cầu lộc. Đấy là lý do vì sao mà Thần Tài lại cầm theo những biểu tượng của tiền tài và những hình ảnh đó hoàn toàn không xuất hiện ở Phật Di Lặc.

[**Thegioidaquy.net**](https://web.archive.org/web/20150512173737/http://thegioidaquy.net/phongthuy.html)',
    '2015-03-01 09:00:00', 0, 495, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-006', 'y-nghia-ho-ly-trong-phong-thuy', 'Ý nghĩa Hồ Ly trong phong thủy', 'Thế Giới Đá Quý',
    '/uploads/news/thumb-art-006-y-nghia-ho-ly-trong-phong-thuy-0.jpg', 'Hồ Ly là tên gọi của cáo đã tu luyện thành tinh. Theo phong thủy, Việc sở hữu vật phẩm được chế tác từ Hồ Ly, đặc biệt là đối với phụ nữ sẽ mang lại sự may mắn vượt bậc về đường tình duyên và hôn nhân cho họ.', 'Trong truyền thuyết,[HồLy](https://web.archive.org/web/20150403092600/http://thegioidaquy.net/phong-thuy/da-phongthuy-298-Ho-Ly-phong-thuy/)được coi làmột loài vật cực kỳthông minh, lém lỉnh. Hồly làtên gọi của cáođã tu luyện thành tinh.

[if !supportLists]**1. Truyền thuyết vềHồLy**

- Tại Trung Quốc từthời xa xưađã córất nhiều giai thiệu truyềnđời vềHồLy Tinh. Tương truyền HồLy Tinh chính làloại cáo tu luyện thành tinh chuyển hóa thân thành những mỹnhân tuyệtđẹpđểhớp hồnđàn ông. Chính vìvậy, nhiều người thường hay gọi những giai nhân lẳng lơ, chuyên quyến rũnam nhân thờiấy làHồLy Tinh.

- Nhân gian cho rằng HồLy Tinh chính làyêu quái, người Phương Tây goijlaf Fox Spirit. ChữSpiritởđây hàm ý làchỉlànhững sinh vật uyên bác, tinh khôn, cótuổi thọkéo dài hàng trămđến hàng ngàn năm.

- Theo truyền thuyết,***HồLy***Tinh tu luyện càng lâu năm, càng mạnh sẽcócàng nhiềuđuôi.

**2. Ý nghĩa phong thủy của HồLy**

-**HồLy**làmột trong sốnhữngđộng vật phổbiếnđượcđược sửdụng*trong phong thủy.*Theo phong thủy, việc sởhữu HồLy (tượng, hayđồtrang sức…)đặc biệtđối với phụnữsẽmang lại sựmay mắn vượt bậc vềđường tình duyên, hôn nhân, giữgìn hạnh phúc lứađôi cho họ.

- Chúng ta cũng cần chúý vềchất liệu khi chọn mua linh vật nàyđểmang lại hiệu quảphong thủy cao nhất. Vềchất liệu chếtạo HồLy kháphong phúnhư: bằng kim loại hoặcđáquý… Tuy nhiên phổbiến nhất vẫn là**HồLyđược chếtác bằngđáThạch anh, đá ngọc bích hoặc đá mắt hổ.**

[![mat-ho-ly-da-ngoc-bich](/uploads/news/art-006-1-1-mat-ho-ly-da-ngoc-bich-0.jpg)](https://web.archive.org/web/20150403092600/http://thegioidaquy.net/phong-thuy/ho-ly-da-ngoc-bich-3335.html#.VOF09-asVlw)

*[Mặt Hồ ly đá ngọc bích](https://web.archive.org/web/20150403092600/http://thegioidaquy.net/phong-thuy/ho-ly-da-ngoc-bich-3335.html#.VOF09-asVlw)sẽ giúp chủ nhân của nó kích hoạt tình cảm gia đạo, kích hoạt tình duyên vượt bậc.*

- Chất liệuđược chếtạo từđáthạch anh cũng cónhiều loại với màu sắc khác nhau sẽcho chúng ta những công dụng phong thủy riêng của chúng. Khi sửdụng HồLy tốt nhất nên chọn màu Hồng, xanh, vàng.

-***HồLy chếtác từthạch anh hồng***đượcđánh bóng lung linh, phản chiếuánh sáng giúp cho người dùng cókhảnăng giao tiếp tốt,ăn nói linh hoạt, hấp dẫn người nghe. Tính thíchứng linh hoạt cao trước mọi tình huống dùởtrong hoàn cảnh nguy hiểm cũng cóthểung dung màthoát nhưcágặp nước vậy.

[![mat-ho-ly-thach-anh-hong-lon](/uploads/news/art-006-2-1-mat-ho-ly-thach-anh-hong-lon-0.jpg)](https://web.archive.org/web/20150403092600/http://thegioidaquy.net/phong-thuy/mat-ho-ly-thach-anh-hong-2392.html#.VOF2VOasVlw)

*[Mặt hồ ly thạch anh hồng phong thuỷ](https://web.archive.org/web/20150403092600/http://thegioidaquy.net/phong-thuy/mat-ho-ly-thach-anh-hong-2392.html#.VOF2VOasVlw)giúp hoá giải khó khăn cho người đeo*

- Đối với những người hoạtđộng trong các lĩnh vực như: hoạtđộng môi giới, nhân viên tưvấn, ngành giải tríthìnênđeo HồLyđáthạch anh hồng trên người.

-Hồ ly được chế tạo từ đá ngọc bíchsẽ giúp chủ nhân của nó kích hoạt tình cảm gia đạo, kích hoạt tình duyên vượt bậc.

- Tuyệtđối không nên sửdụng HồLy làm bằngđồng hoặcđược chếtạo từchất liệu nhân tạo vìnhưthếsẽmang nhiều sát khíhơn làcát khí.

- Nên tẩy uếtrước khi sửdụng HồLy làm trang sứcđểđeo bên người. Khác với TỳHưu,**HồLy**vẫn cóthểđeo bên mình khiđang làm chuyện vợchồng.

[*Thegioidaquy.net*](https://web.archive.org/web/20150403092600/http://thegioidaquy.net/phongthuy.html)',
    '2015-02-16 09:00:00', 0, 538, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-007', 'bieu-tuong-linh-vat-de-phong-thuy-nam-2015', 'Biểu tượng linh vật Dê phong thủy năm 2015', 'Thế Giới Đá Quý',
    '/uploads/news/thumb-art-007-bieu-tuong-linh-vat-de-phong-thuy-nam-2015-0.jpg', 'Theo phong thủy Phương Đông, biểu tượng linh vật đại diện cho năm 2015 là con dê. Trong phong thủy, Dê được cho là biểu tượng của sự bình yên hòa thuận. Nó đại diện cho trí nhớ, sự thông minh, nhanh nhẹn.', '- Dêlàcon vật khágần gũi trong văn hóa của người ÁĐông. Trong 12 con giáp,***Dêđược xem làbiểu tượng của tính ôn hòa***, may mắn, nhanh nhẹn. Bởi vìDêtức làlộc nên nóđại diện cho tài lộc.

- Mặc dùDêkhông phải làcon vật cócông dụng mạnh mẽtrong việc chiêu tài hóa sát nhưng Dêlại làmột trong những pháp khíThiên Tài, tứcám chỉcóthểmangđến tài lộc, những nguồn tài chính bất ngờmay mắn trong kinh doanh cho chủsởhữu.Đặc biệt linh vật phong thủy này rất thích hợp cho những người làm việc trong lĩnh vực chứng khoắn hoặcđầu tưngắn hạn.

- Trong phong thủy, biểu tượng con dêđược chếtạo từnhững chất liệu khác nhau như:đáquý, vàng, mạvàng hoặcđồchếtác bằngđồng…vớI kiểu dáng vô cùng phong phúvàđa dạng. Khi lựa chọn vật phẩm phong thủy này bạn cần lưu ýđến chất liệu tạo thành nóđểphát huy tốiđa hiệu quảphong thủy của vật phẩm này.[Dêphong thủy](https://web.archive.org/web/20150403092821/http://thegioidaquy.net/phong-thuy/da-phongthuy-287-De-phong-thuy/)được chếtác từngọc,đáquý cógiátrịphong thủy hơn cả, rất tốt cho tài lộc. cólợi trong công việc kinh doanh, làmăn cũng nhưcác hoạtđộngđầu tưngắn hạn.

[![mat-cam-thach-con-De](/uploads/news/art-007-1-1-mat-cam-thach-con-de-0.jpg)](https://web.archive.org/web/20150403092821/http://thegioidaquy.net/phong-thuy/mat-cam-thach-con-de-1884.html#.VOBoseasVlw)

*[Mặt cẩm thạch con dê](https://web.archive.org/web/20150403092821/http://thegioidaquy.net/phong-thuy/mat-cam-thach-con-de-1884.html#.VOBoseasVlw)mang lại bình an may mắn cho người đeo*

- Trong âm dương**Dê tượng trưng cho quẻ Đoài**, biểu hiện cho sự nhanh nhẹn vui vẻ, lợi cho con cái nên nó còn dùng để tăng cường trong mối quan hệ gia đình, cầu sinh con cái.

-**Bài tríDêPhong thủy**trong nhàhoặcđeo trang sức cólinh vật phong thủy này giúp tăng thêm ý chívàsựkiên nhẫn cho chủnhân. Nócótác dụng trong việc bồiđắp lòng kiên trìvàý chíphấnđấu của bạn.

[![de-phong-thuy-thach-anh-tim](/uploads/news/art-007-2-1-de-phong-thuy-thach-anh-tim-0.jpg)](https://web.archive.org/web/20150403092821/http://thegioidaquy.net/phong-thuy/De-phong-thuy-thach-anh-tim-2706.html#.VOBnweasVlw)

*[Dê phong thuỷ](https://web.archive.org/web/20150403092821/http://thegioidaquy.net/phong-thuy/De-phong-thuy-thach-anh-tim-2706.html#.VOBnweasVlw)đem lại sự sung túc đầy đủ.*

- Khi công việc của bạn không thuận lợi hoặc gặp nhiềuđiều không hay, thịphi của tiểu nhân thìcách tốt nhất làsửdụng linh vật Dêphong thủyđểhóa giải tình trạng này.

- Con dêchủyếu làbiểu tượng của sựôn hòa nên khi bài tríDêtại bàn làm việc sẽgiúp chủnhân luôn giữđược sựđiềmđạm, tĩnh tâm, tốt cho các mối quan hệgiao tiếp.

- Trong phong thủy,dê là biểu tượng của cát tường may mắn và tránh thị phi. Năm 2015 này lànăm Ất Mùi, việc sở hữu**linh vật dê phong thủy**này càng có ý nghĩa nhiều hơn bởi nó tượng trưng cho mọi việc tốt lành xuyên suốt cả năm.

- Theo huyết về12 con giáp, Tuổi Sửu vàTuổi Mùi xung khắc nên những người Tuổi Sửu không nên sửdụng biểu tượng Dê.

- Với những người tuổi Hợi, Mão, Mùi (tam hợp), tượng dê là một vật phẩm nên có nhất trong nhà, công sở để chào đón một năm mới đầy thuận lợi.

- Phương vịthích hợpđểbài tríbiểu tượng Dêlàhướng Nam hoặc Tây nam. Tránh bài tríDêởhướng Bắc hoặcĐông Bắc.

[*Thegioidaquy.net*](https://web.archive.org/web/20150403092821/http://thegioidaquy.net/phongthuy.html)',
    '2015-02-15 09:00:00', 0, 581, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-008', 'bieu-tuong-trau-phong-thuy-va-nhung-y-nghia-cua-no', 'Biểu tượng trâu phong thủy và những ý nghĩa của nó', 'Thế Giới Đá Quý',
    '/uploads/news/thumb-art-008-bieu-tuong-trau-phong-thuy-va-nhung-y-nghia-cua-no-0.jpg', 'Trâu phong thủy là biểu tượng cho sự phú quý, cát tường bởi tính cách của trâu là chịu thương, chịu khó rất chăm chỉ làm việc. Đặt biểu tượng trâu phong thủy trong nhà hoặc đeo trang sức có linh vật này sẽ có khả năng giúp phúc khí hội tụ xung quanh bạn, sự nghiệp nhanh chóng thành công và phát đạt.', '- Từxưađến nay, trâuđược cho làcon vật gắn liền với nhiềuđức tính tốt nhưsựbền bỉ,đức tính hiền lành, mạnh mẽ. Chính vì vậy,*Trâu là biểu tượng của sự an lành, no đủ.*

- Trong 12 con giáp, Trâu làSửu, còn trong sơđồbát quái Trâu làquẻkhôn, chủyếu vềđai, mangđến sựthịnh vượng, bền vững.Đối với những người nông dân, con trâu thật sựlàmột người bạn gắn bóvô cùng thân thiết. Người xưa quan niệm rằng,đời người cóba việc quan trọng là“Tậu trâu, cưới vợ, làm nhà”. Con trâu vốn làđầu cơnghiệp của người nông dân. Chính vìvậy,trâuđã trởthành biểu tượng của sựphúquý, cát tường.

- Trong phong thủy,**biểu tượng con trâu**được chếtạo từnhững chất liệu khác nhau như:đáquý, gỗ…vớI kiểu dáng vô cùng phong phúvàđa dạng. Khi lựa chọn vật phẩm phong thủy này bạn cần lưu ýđến chất liệu tạo thành nóđểphát huy tốiđa hiệu quảphong thủy của vật phẩm này.[Trâu phong thủy](https://web.archive.org/web/20150331070144/http://thegioidaquy.net/phong-thuy/da-phongthuy-286-Trau-phong-thuy/)được chếtác từngọc,đáquý cógiátrịphong thủy hơn cả, rất tốt cho tài lộc. cólợi trong công việc kinh doanh, làmăn cũng nhưcác hoạtđộngđầu tưdài hạn.

- Không nên sửdụng Trâuđược chếthác bằng gỗvìtheo ngũhành Mộc khắc Thổvàtheo phong thủy thìnósẽkhông thểphát huyđược tác dụng của**tượng Trâu.**

- Thời xa xưa các quan lại hay dùng tượng Trâu hoặcđồtrang sức cólinh vật nàyđược chếtác bằng ngọcđáquý vừa cótác dụng phong thủy vừa thểhiệnđượcđịa vịcũng nhưsựcao sang quý phái của mình.

[![mat-con-Trau-da-chacedol](/uploads/news/art-008-1-1-mat-con-trau-da-chacedol-0.jpg)](https://web.archive.org/web/20150331070144/http://thegioidaquy.net/phong-thuy/mat-day-chuyen-cham-trau-da-chalcedony-2187.html#.VOAV-uasVlw)

*[Mặt dây chuyền con Trâu](https://web.archive.org/web/20150331070144/http://thegioidaquy.net/phong-thuy/mat-day-chuyen-cham-trau-da-chalcedony-2187.html#.VOAV-uasVlw)[phong thuỷ](https://web.archive.org/web/20150331070144/http://thegioidaquy.net/phong-thuy/mat-day-chuyen-cham-trau-da-chalcedony-2187.html#.VOAV-uasVlw)đem lại tài lộc may mắn*

- Bên cạnhđó,*trâu phong thủy còn cóthểdùngđểtrấn yểm các hung tinh*nhưNhi Hắc, NgũHoàng, giúp xoay chuyển tình thếbiến hung thành cát.

- Khi mua vật phẩm phong thủy này chúng ta cũng cần phải chúýđến vịtríđặt sao cho phát huyđược hết khảnăng phong thủy của nó. Nếu chúng ta chỉđặt tùy tiệnởmột chỗnàođósao cho phùhợp với căn nhàthì**Tượng trâu**chỉsẽtrởthành vật trang tríbình thường màkhông hềcómột chút công dụng phong thủy nào cả.

- Đểphát huyđược năng  lượng phong thủy vàlinh khícủa trâu thìbạn nênđặt vật phẩm phong thủy nàyởhướng Bắc hoặc hướngĐông Bắc của ngôi nhàlàphùhợp nhất.

[![trau-phong-thuy-thach-anh-tim](/uploads/news/art-008-2-1-trau-phong-thuy-thach-anh-tim-0.jpg)](https://web.archive.org/web/20150331070144/http://thegioidaquy.net/phong-thuy/trau-phong-thuy-thach-anh-tim-2712.html#.VOAY7OasVlw)

*[Trâu phong thuỷ](https://web.archive.org/web/20150331070144/http://thegioidaquy.net/phong-thuy/trau-phong-thuy-thach-anh-tim-2712.html#.VOAY7OasVlw)giúp tích trữ tài lộc, đem lại sung túc.*

-***Tránh bài trítượng Trâuởhướng Nam hoặc Tây Nam***vìđây làvịtrítương xung với trâu.

-Tượng trâucũng cóthểđược trưng bàyởphòng khách hay trên bàn làm việc, hoặcởcác nơi vượng tinh như: Lục Bạch, Bát Bạch phối chiếu.

- Tuyệtđối khôngđượcđặt vật phẩm phong thủy nàyởcạnh nhàvệsinh, trên bàn học, bàn thờhayởnhững nơi hung tinh Nhi Hắc Tam Bích chiếuđến.

-*Trâu làbiểu tượng phong thủy*cótác dụng hỗtrợngười Tuổi Tỵ, Dậu, Hợi, Tý, Sửu. Những người tuổi Mùi không thích hợpđểsửdụng**trâu phong thủy**vìSửu-Mùi vốn xung khắc nhau sẽkhông phát huyđược linh khícủa nó.

[*Thegioidaquy.net*](https://web.archive.org/web/20150331070144/http://thegioidaquy.net/phongthuy.html)',
    '2015-02-15 09:00:00', 0, 624, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-009', 'khi-phong-thuy', 'Khỉ phong thủy', 'Thế Giới Đá Quý',
    '/uploads/news/thumb-art-009-khi-phong-thuy-0.jpg', 'Bạn có biết trong phong thủy, khỉ được xem là biểu tượng cho sự cao sang quyền quý. Cũng chính vì vậy mà Vật phẩm khỉ phong thủy được chế tạo bằng đá quý hay bằng đồng rất được mọi người ưa chuộng trong việc sử dụng để làm quà tặng.', '- Từxưađến nay, loài khỉđược coi làtổtiên của loài người.  So với các linh vật phong thủy khác,[khỉlàvật phẩm phong thủy](https://web.archive.org/web/20150416030147/http://thegioidaquy.net/phong-thuy/da-phongthuy-283-Khi-phong-thuy/)được sửdụng kháphổbiến. Từthời cổxưaởTrung Hoa, người Hán cho rằng khỉchính làcon vật may mắn. Bởi khỉcòn cótên gọi khác là“Hầu”. Từ“Hầu” nàyđồng âm với từ“Hầu” – với ý nghĩa tước vịquyền quý.

- Trong phong thủy,**khỉđược xem làbiểu tượng cho sựcao sang quyền quý**. Cũng chính vìvậy màVật phẩm*khỉphong thủy*được chếtạo bằngđáquý hay bằngđồng rấtđược mọi ngườiưa chuộng trong việc sửdụngđểlàm quàtặng.

- Đặt một***tượng Khỉ phong thủy trên bàn làm việc hoặc đeo trang sức có biểu tượng này***sẽ tốt cho ngườiđeo trong việc việc cầu công danh, thăng quan tiến chức của bản thân. Bởi “Phong Hầu” cũng cónghĩa làthăng quan, phong chức tước.

[![phong-Hau-Nhu-Y](/uploads/news/art-009-1-1-phong-hau-nhu-y-0.jpg)](https://web.archive.org/web/20150416030147/http://thegioidaquy.net/phong-thuy/phong-hau-nhu-y-2626.html#.VNzMLeasVlw)

*[Phong HầuNhư Ý](https://web.archive.org/web/20150416030147/http://thegioidaquy.net/phong-thuy/phong-hau-nhu-y-2626.html#.VNzMLeasVlw)là biểu tượng phong thuỷmang hàm ý được thăng quan lên chức như ý nguyện, tài lộc phú quý vô đều đều*

-*Khỉphong thủy thườngđược chếtạo với nhiều kiểu dáng vàchất liệu khác nhau*từgỗ, ngọc (đáquý), pha lê,đúcđồng, mạvàng vàthậm chílàvàng nguyên chất. Tuy nhiên chất liệu bằng ngọc (đáquý) vàđồngđượcưa chuộng hơn hẳn vìnócókhảnăng giúp phát huy tốiđa năng lực phong thủy của vật phẩm này.

- Biểu tượng Khỉởnhững tưthếkhác nhau sẽthểhiện vàmang lại những ý nghĩa cát tường riêng của nó. Nếu chúng ta thấy biểu tượng Khỉcưỡi trên lưng ngựa thìbiểu tượngđóchính là**“Mã thượng Phong Hầu”.**

“Mã thượng phong hầu” có nghĩa là sự thăng tiến, bay cao đến đỉnh của vinh quang, đến đích của thành công, sự thăng quan tiến chức đến mức người khác phải kính nể và tuân phục.

*Đặt một tượng “Mã thượng phong hầu” trên bàn làm việc hoặc đeo trên cổ sẽ tốt cho việc cầu danh*, thăng quan tiến chức. Bởi “Phong hầu” Cũng có nghĩa là thăng quan, được phong tước.

[![ma-thuong-phong-hau-bang-dong](/uploads/news/art-009-2-1-ma-thuong-phong-hau-bang-dong-0.jpg)](https://web.archive.org/web/20150416030147/http://thegioidaquy.net/phong-thuy/ma-thuong-phong-hau-bang-dong-1090.html#.VNzOaeasVlw)

*[Mã thượng phong hầu phong thuỷ](https://web.archive.org/web/20150416030147/http://thegioidaquy.net/phong-thuy/ma-thuong-phong-hau-bang-dong-1090.html#.VNzOaeasVlw)giúp may mắn, thăng quan tiến chức.*

Lưu ý: Các linh vật phong thủy cần được khai quang cẩn thận, đặt đúng vị trí và xem ngày giờ đặt. Có như vậy mới có tác dụng phát huy hết công năng sử dụng của các linh vật phong thủy đồng thời tránh được phản tác dụng khi đặt sai vị trí.

[*Thegioidaquy.net*](https://web.archive.org/web/20150416030147/http://thegioidaquy.net/phongthuy.html)',
    '2015-02-12 09:00:00', 0, 667, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-010', 'cop-phong-thuy', 'Cọp phong thủy', 'Thế Giới Đá Quý',
    '/uploads/news/thumb-art-010-cop-phong-thuy-0.jpg', 'Bạn có biết trong phong thủy, Cọp là biểu tượng của sự oai nghi, quyền lực. Vật phẩm phong thủy này đặc biệt rất hợp với người Tuổi Dần. Cọp là vật phẩm phong thủy rất linh thiêng nằm trong bộ Tứ Linh: Long, Phượng, Quy, Cọp.', '- Hổlàvật phẩm phong thủy rất linh thiêng nằm trong bộTứLinh: Long, Phượng, Quy, Hổ. Linh vật phong thủy này làcon vật linh thiêng thứhaiđứng sau Rồng. Nóthườngđi với Rồng vàđược xem nhưlàmột cặp bổtrợlẫn nhau.

-[Cọp](https://web.archive.org/web/20150416030137/http://thegioidaquy.net/phong-thuy/da-phongthuy-279-Cop-phong-thuy/)làlinh vật cao quý vàlinh thiêng,đầy quyền uy vàcólinh khícực mạnh thông quađôi mặt sắc vàbộnanh nhọn của chúng. Vìthếchúngđược tôn là“Chúa tểsơn lâm”.*Trong phong thủy*, Cọp làcon vật thườngđược tạc thành tượngđểđặt trong chùa hoặc khắc trên nhàthờ, miếuđểhộthần linh.

- Cọpcòn làbiểu tượng cho sức mạnh, uy quyền, hỗtrợconđường công danh học hành vàsựthăng tiến trong sựnghiệp.

- Đặc biệt vật phẩm phong thủy này rất thích hợp cho người cóbản mệnh tuổi Dần.Đeo trang sức hoặc trưng bày vật phẩm có**hình tượng Cọp bằng chất liệuđáquý**sẽmang lại cát khírất lớn cho chủnhân. Linh vật phong thủy này làpháp khícủa công danh, tài lộc vàquyền lực. Cọp tượng trưng chođỉnh cao chót vót của sựthànhđạt sựphát triển vượt bậc. Chúng cókhảnăng giúp cho chủsỡhữu chống lại tiểu nhân,đem lại sựmay mắn vềconđường công danh học hành thi cửvàsựnghiệp.

[![mat-cam-thach-con-Cop](/uploads/news/art-010-1-1-mat-cam-thach-con-cop-0.jpg)](https://web.archive.org/web/20150416030137/http://thegioidaquy.net/phong-thuy/mat-cam-thach-con-cop-1885.html#.VNjHUuasVlw)

*[Đá mặt cẩm thạch con cọp](https://web.archive.org/web/20150416030137/http://thegioidaquy.net/phong-thuy/mat-cam-thach-con-cop-1885.html#.VNjHUuasVlw)mang lại bình an may mắn.*

**- Cọp phong thủy**cótác dụng trấn yểm khi nhàbạn bịphạm vào cấm kỵhoặc sát tinh chiếu tướng.

- Theo phong thủy,*nênđặt Cọp tại phòng khách*,*trên bàn làm việc hoặcởcác nơi cócác Vượng Tinh như*: Lục Bạch, Bát Bạch phối chiếu. Chúng cótác dụng trấn yểm nơi hung tinh chiếuđếnđểhỗtrợcho những người cóbản mệnh thuộc Dần, Ngọ, Tuất, Mão, Thìn.

[![cop-phong-thuy-thach-anh-tim](/uploads/news/art-010-2-1-cop-phong-thuy-thach-anh-tim-0.jpg)](https://web.archive.org/web/20150416030137/http://thegioidaquy.net/phong-thuy/cop-phong-thuy-thach-anh-tim-2711.html#.VNjKaOasVlw)

*[Cọp phong thuỷ](https://web.archive.org/web/20150416030137/http://thegioidaquy.net/phong-thuy/cop-phong-thuy-thach-anh-tim-2711.html#.VNjKaOasVlw)giúp xua đuổi tiểu nhân, thăng tiến công danh.*

- Nên dùng hướng Chính Bắc, Tây Bắc hoặc hướng Tâyđểtăng cường cát khícho các sao tốtởcác hướng này hoặc dùng trấn yểm khi bịSát hướng bằng cách**đặt con Cọp bằngđáquý vào vịtríđó**.

- Khiđặt Cọp phong thủy cần chúý nênđặt sao choĐầu của Cọp phải hướngđược ra ngoài, tránhđặtđầu Cọp hướng vào bên trong nhàcủa gia chủ.

- Lưu ý***tuyệtđối tránhđặt Cọp phong thủy***ởnhững nơi ô uế, khôngđược sạch sẽnhư: nhàvệsinh hay trong phòng ngủ.

*[*Thegioidaquy.net*](https://web.archive.org/web/20150416030137/http://thegioidaquy.net/phongthuy.html)*',
    '2015-02-09 09:00:00', 0, 710, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-011', 'cach-su-dung-guong-bat-quai-hop-phong-thuy', 'Cách sử dụng gương Bát quái hợp phong thủy', 'Thế Giới Đá Quý',
    '/uploads/news/art-013-1-1-bat-quai-ho-phu-lon-1.jpg', 'Gương bát quái là một trong những công cụ nổi tiếng và phổ biến thường được sử dụng trong phong thủy để bảo vệ, khắc phục, hoặc hóa giải phong thủy cho những hướng nhà xấu.', '-**Gương bát quái**là một trong những công cụ nổi tiếng và phổ biến nhất được sử dụng trong phong thủy để bảo vệ, khắc phục, hoặc hóa giải cho các ngôi nhà có hướng xấuđểcóthể thu hút may mắn.

- Ngày nay,*g**ương bát quái là công cụ bị lạm dụng nhất trong việc thực hành phong thủ*y. Gương này không được treo trong nhà hay văn phòng vì làm như vậy có thể dẫn đến thảm họa và tác hại không lường trước đước. Để gương bát quái hoạt động chính xác, nó phải được đặt đúng chỗ, từng loại gương cũng cần đặt theo từng vị trí khác nhau, vị trí không đúng có thể gây tổn hại cho các nhà hàng xóm và cả gia chủ.

- Đối với những địa điểm mang tính chất tôn giáo, tín ngưỡng như nhà thờ, chùa, đình, miếu… thường là nơi có linh khí.***Theo phong thủy***, những ngôi nhà nằm đối diện với nơi thờ phụng linh thiêng là ở vào thế cô dương sát. Khi ở vào thế cô dương sát, vượng khí của ngôi nhà sẽ bị cuốn hết đi.Đểgiải trừthếnày, tại cửa chính của ngôi nhà, bạn hãy treo[gương Bát quái Hổ phù](https://web.archive.org/web/20150127082956/http://thegioidaquy.net/phong-thuy/bat-quai-ho-phu-lon-1554.html#.VMKFPNKsVlw)để giữ vượng khí lại và không cho âm khí xâm phập vào nhà. Nếu ngôi nhà không ở vào thế đối diện với nơi thờ phụng mà nằm lệch một bên, bạn chỉ cần dùng gương lồi là đủ. Ngoài ra, bạn hãy trồng một cây hoa giấy phía trước nhà, cách cửa chính hơn 5m. Tại góc dưới mái nhà phía trước, bạn hãy treo 2 chiếc chuông gió ở 2 bên.

[![bat-quai-Ho-phu-lon](/uploads/news/art-013-1-1-bat-quai-ho-phu-lon-1.jpg)](https://web.archive.org/web/20150127082956/http://thegioidaquy.net/phong-thuy/bat-quai-ho-phu-lon-1554.html#.VMKFVtKsVlx)

*[Bát Quái Hổ phù phong thuỷ](https://web.archive.org/web/20150127082956/http://thegioidaquy.net/phong-thuy/bat-quai-ho-phu-lon-1554.html#.VMKFVtKsVlx)dùng trấn trạch, đem lại bình an cho gia đạo*

- Nếu nhà bạn có một lối vào chính đối diện với một nghĩa trang, bệnh viện, cảnh sát, nhà thờ và trường học, một gương bát quái sẽ giúp sát khí dội ngược ra khi bay vào nhà của bạn, ngăn chặn không cho sát khí xâm nhập.

- Khi một hình bát quái được để trên một lối vào chính, nó sẽ phục vụ để xua đi tà khí, những người có ý định xấu hoặc những người mang theo điềm rủi.

- Để loại bỏ các mối đe dọa của "mũi tên độc" từ đèn đường, cột thẳng, cây to hoặc các tòa nhà sẽ ảnh hưởng đến bạn và gia đình của bạn,**đặt gương bát quái ở tường sao cho gương chiếu thẳng vào các vật trở ngại này.**
[if !supportLineBreakNewLine]

- Lưu ý: Bất kỳ may mắn, sinh khí nào đi vào từ nơi có treo gương bát quái cũng đều bị phân tán nếu treo gương bát quái ở cửa chính.

- Cáchình bát quáicũng khuếch tán những ảnh hưởng của "mũi tên độc" có nguồn gốc từ các góc của tòa nhà hay góc độ khác hướng chỉ về phía nhà của bạn.

- Nếu nhà của bạn là nơi giao nhau của một ngã ba, với xe ô tô liên tục lái xe hướng đầu vào nhà, một gương bát quái sẽ ngăn chặn bất kỳ sát khí tốc độ nào đến gần và bạn sẽ cảm thấy bớt áp lực trong cuộc sống.

-**Bát quái ngăn chặn nhiều việc nguy hiểm**, ngăn ngừa bệnh tật, tai nạn, trầm cảm và cái chết của các thành viên trong một gia đình, nếu được sử dụng một cách chính xác trong những cách nêu trên.

- Ngoài ra, bạn nên nhớ luôn luôn đặt hình bát quái trên cửa ra vào hoặc cổng mà "mũi tên độc" chỉ thẳng vào nhà. Tuyệtđối*g**ương bát quái không bao giờ được đặt bên trong nhà*- nó chỉ phát huy tác dụng mạnh mẽ và tốt nhất khi trưng bày ngoài trời.

[*Thegioidaquy.net*](https://web.archive.org/web/20150127082956/http://thegioidaquy.net/phongthuy.html)',
    '2015-01-24 09:00:00', 0, 839, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-012', 'y-nghia-quan-cong-trong-phong-thuy', 'Ý nghĩa Quan Công trong phong thủy', 'Thế Giới Đá Quý',
    '/uploads/news/art-014-1-1-mat-day-chuyen-quan-cong-da-ruby-97ct-0.jpg', 'Quan Công ( hay còn gọi là Quan Vân Trường, Quan Vũ) được cho là biểu tượng bảo vệ chủ nhân xua đi những điều xấu hoặc sát khí xâm nhập vào nhà qua cửa.', '[Quan Công](https://web.archive.org/web/20150127083846/http://thegioidaquy.net/phong-thuy/da-phongthuy-299-Quan-Cong-phong-thuy)tên thật là Quan Vũ, tự là Trương Sinh sau đổi thành Vân Trường. Ông làngười làng Giải Lương tỉnh Hà Đông (Trung Quốc). Làngườiđi theo phò tá Lưu Bị, Quan Công luôn một lòng vì chủ không quản ngại vào nơi nước sôi lửa bỏng .Luôn giữ một tấm lòng son sắt sáng ngời. Sau khi mất đã được quy y cửa Phật, được hiển thánh và được nhân dân đời đời thờ phụng. Quan Công là vị thánh chuyên trấn áp hung khí, giúp gia chủchống lại tà ma ngoại đạo.

*Đeo trang sức cóhìnhả**nh Quan Công*hoặcđặt hình ảnh Quan Công trong nhà, đặc biệt ở vị trí đối diện cửa trước, vẻ mặt nghiêm nghị của ông sẽ xua đi những điều xấu và sát khí xâm nhập vào nhà qua cửa.

Người ta tin rằng tất cả năng lượng âm đều không thể vào nhà nếu có sự hiện hữu của***Quan Công***. Hai người anh em của ông (Lưu Bị và Trương Phi) cũng được xem là những hình ảnh may mắn đặt trong nhà.

Ngoài ý nghĩa là biểu tượng phong thủy, thìtượng Quan Công có ý nghĩa trang trí cho ngôi nhàcủa gia chủ, cũng như văn phòng của những nhà lãnh đạo góp phần làm tăng thêm sự uy nghiêm, sang trọng.

Mẹo dân gian:**Tượng Quan Công**phải đặt nhìn ra cửa, tránh đặt quá thấp, và đặt tại những nơi ô uế như ở gần nhà vệ sinh, bàn ăn..Nên đặt tượng Quan Công ở phòng khách, thư phòng, tránh đặt trong phòng ngủ, vì như thế sẽ làm mất đi tính tôn nghiêm của biểu tượng.

*Nênđeo trang sức cótượng quan côngđược chếtạo từđátựnhiên*. Nhưthếbiểu tượng Quan Công sẽ có ý nghĩa phong thủy hơn làđược chếtạo từnhững chất liệu khác.

Sau đây làmột sốloại trang sứcđược chếtạo từđátựnhiên vềhình tượng Quan Côngđang được trưng bán tại Cửa hàng Phong thủy Hoa Mộc Lan của chúng tôi nhưsau:

**1. Mặt dây chuyền Quan Công đá Ruby:**

- Đây là mặt đá phong thuỷ Quan Công giúp bảo vệ, hộ mệnh, đem lại may mắn trong công danh, sự nghiệp, phù hợp cho người mạng Hoả, mạng Thổ và cho người sinh tháng 7.

-**Mặt ruby Quan Công có màu đỏ sậm**, hàng đẹp, chỉ có 2 mặt.

[![mat-day-chuyen-Quan-Cong-da-ruby-](/uploads/news/art-014-1-1-mat-day-chuyen-quan-cong-da-ruby-97ct-0.jpg)](https://web.archive.org/web/20150127083846/http://thegioidaquy.net/phong-thuy/mat-day-chuyen-quan-cong-da-ruby-97ct-3308.html#.VMJ8XNKsVlw)

*[Mặt dây chuyền Quan Công đá Ruby](https://web.archive.org/web/20150127083846/http://thegioidaquy.net/phong-thuy/mat-day-chuyen-quan-cong-da-ruby-97ct-3308.html#.VMJ8XNKsVlw)giúp bảo vệ, hộ mệnh, đem lại may mắn*

**2. Mặt Quan Công đọc sách đá Obsidian:**

- Mặt dây chuyền Quan Công đọc sách đá Obsidian, mặt lớn chạm rất đẹp, phù hợp cho người làm lãnh đạo.

- Kích thướcmặt đá: cao 65-66mm, ngang 45-46mm,dày 17-18mm, nặng trên 70kg.

[![mat-Quan-Cong-doc-sach-da-Obsidian](/uploads/news/art-014-2-1-mat-quan-cong-doc-sach-da-obsidian-0.jpg)](https://web.archive.org/web/20150127083846/http://thegioidaquy.net/phong-thuy/mat-quan-cong-doc-sach-da-Obsidian-3179.html#.VMJ9eNKsVlw)

*Mặt dây chuyền[Quan Công](https://web.archive.org/web/20150127083846/http://thegioidaquy.net/phong-thuy/mat-quan-cong-doc-sach-da-Obsidian-3179.html#.VMJ9eNKsVlw)đọc sách đá Obsidian*

[*Thegioidaquy.net*](https://web.archive.org/web/20150127083846/http://thegioidaquy.net/phongthuy.html)',
    '2015-01-24 09:00:00', 0, 882, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-013', 'y-nghia-tien-xu-trong-phong-thuy', 'Ý nghĩa tiền xu trong phong thủy', 'Thế Giới Đá Quý',
    '/uploads/news/art-015-1-1-day-treo-nut-than-mai-hoa-kim-tien-0.jpg', 'Theo phong thủy, tiền xu là biểu tượng của nguồn tài lộc và của cải. Cát khí của nó không những làm gia tăng tài lộc mà còn đem lại nhiều may mắn về công danh, sự nghiệp, giải trừ tai họa, tiểu nhân…', 'Tiền xu là một trong những vật phẩm phong thủy quan trọng tượng trưng cho của cải. Hãy cùng chúng tôi tìm hiểu ý nghĩa một sốloại tiền xu trong phong thủy các bạn nhé.

[if !supportLists]**1.Tiền Mai Hoa**

- Trong số các loại tiền xu dùng trong phong thủy,[tiền Mai Hoa](https://web.archive.org/web/20150125084611/http://thegioidaquy.net/phong-thuy/mai-hoa-kim-tien-no-lon-1684.html#.VLqoRdKsVlw)có 5 cánh tượng trưng cho ngũ hành, là vật chuyên dùng để trấn yểm hung khí, đem lại sự thịnh vượng về tài lộc cho chủ nhân.

- Bạn có thể bày***tiền Mai Hoa***trên bàn, trong phòng khách, văn phòng, cửa hàng. Cũng có thể bày tiền Hoa Mai trên bàn thờ, trên két bạc, treo ở cửa ra vào… nơi các cát tinh Lục Bạch, Diên Niên, Sinh Khí phối chiếu để gia tăng tiền bạc.

- Chú ý,t*ránh đặt tiền Mai Hoa trong nhà vệ sinh*, nơi ẩm thấp, trong phòng ngủ… nơi các hung tinh Thất Xích, Lục Sát, Tuyệt Mệnh phối chiếu.

[![day-treo-nut-than-Mai-Hoa-Kim-Tien](/uploads/news/art-015-1-1-day-treo-nut-than-mai-hoa-kim-tien-0.jpg)](https://web.archive.org/web/20150125084611/http://thegioidaquy.net/phong-thuy/day-tien-hoa-mai-1472.html#.VLqow9KsVlw)

*["Mai Hoa Kim Tiền"](https://web.archive.org/web/20150125084611/http://thegioidaquy.net/phong-thuy/day-tien-hoa-mai-1472.html#.VLqow9KsVlw)là vật phẩm phong thuỷ giải trừ tiểu nhân tránh thị phi và mang lại sự may mắn công danh tài lộc*

[if !supportLists]**2.Dây Treo Ba Tiền NútĐỏ**

- Số 3 tượng trưng cho Thiên – Địa – Nhân (Thiên Thời - Địa Lợi - Nhân Hòa), tức là mang đến những điều tốt, là biểu tượng cho sự thịnh vượng cát lành.

- Để thu hút sự thành công của các dự án trong kinh doanh, bạn hãy cung cấp năng lượng tốt cho các hồ sơ có liên quan bằng cách buộc***3 đồng tiền xu cổ với dây màu đỏ***rồi dán vào bìa hồ sơ (bằng băng dính trong), hướng mặt dương (có chữ) lên trên. Điều này có thể sẽ tạo ra năng lượng thịnh vượng và mang lại sự thành công trong công việc của bạn.

[![ba-tien-tai-loc-no-do](/uploads/news/art-015-2-1-ba-tien-tai-loc-no-do-0.jpg)](https://web.archive.org/web/20150125084611/http://thegioidaquy.net/phong-thuy/ba-tien-tai-loc-no-do-1473.html#.VLqp1NKsVlw)

*[Ba Tiền Tài Lộc phong thuỷ](https://web.archive.org/web/20150125084611/http://thegioidaquy.net/phong-thuy/ba-tien-tai-loc-no-do-1473.html#.VLqp1NKsVlw)giúp sinh sôi tài lộc của cải, mau giàu có*

[if !supportLists]**3.[endif]Tiền xu Bát Quá****i**

- Trong phong thuỷ thì**đồng xu**in hình Bát Quái là một trong những vật phẩm cơ bản để chế hoá và chữa những cấm kỵ phạm phải.

-Đồng xuBát quái là biểu tượng của sự giàu có, phát về tài lộc. Đồng xu này thường dùng là đồng tiền ở thời vua Càn Long có hai mặt Âm Dương thể hiện nguyên lý Âm Dương hài hoà. Tiền hình trọn tượng trưng cho Thiên, ở giữa có lỗ vuông tượng trưng cho Địa. Trên đồng tiền có in hình Bát Quái thể hiện Đạo lý Thiên - Địa - Nhân tương hợp tất tạo phúc và hưởng phú quý.

- Đồng xu Tử Vi có in hình Bát Quái tượng trưng cho “Đạo”, tức là cát khí. Bạn có thể treo đồng xu này ở nhà, cửa hàng, văn phòng hoặc trên xe ô tô có thể chống lại hung khí, xua đuổi tà ma, đem lại sức khoẻ và tài lộc cho gia chủ.
[if !supportLineBreakNewLine]

[*Thegioidaquy.net*](https://web.archive.org/web/20150125084611/http://thegioidaquy.net/phongthuy.html)',
    '2015-01-18 09:00:00', 0, 925, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-014', 'ky-lan-phong-thuy', 'Kỳ Lân Phong Thủy', 'Thế Giới Đá Quý',
    '/uploads/news/art-016-1-1-ky-lan-nhu-y-cam-thach-trang-0.jpg', 'Kỳ Lân là một linh vật phong thủy trong bộ Tứ Linh: Long, Lân, Quy, Phụng. Theo phong thủy, Kỳ Lân là linh vật phong thủy báo hiệu điềm lành, sự thái bình thịnh vượng.', 'Lân là con cái, còn con đực gọi là Kỳ, nên được gọi chung là Kỳ Lân.Tương truyền rằng mỗi khi nơi nào có Kỳ Lân xuất hiện thì nơi đó có thánh nhân ra đời cứu giúp dân chúng. Do đó, Kỳ Lân làlinh vật báo hiệu điểm lành, sắp có thái bình thịnh vượng.

[Kỳ Lân](https://web.archive.org/web/20150126100903/http://thegioidaquy.net/phong-thuy/da-phongthuy-297-Ky-Lan-phong-thuy/)cũng là một loài thụy thú, thời xưa còn gọi là Nhân Thú, nó mang hai ý nghĩa: Cát Tường vàNhân Từ.

Tương truyền Kỳ Lân rất thích giúp đỡ người tốt, nó thường đặc biệt quan tâm chiếu cố đến những người có long hiếu thảo và biết làm việc thiện, nên mới có tên là Nhân Thú (loài thú nhân ái).

Khi Kỳ Lân gặp kẻ xấu, nó liền đuổi cắn, vì thế những nhà hoặc công ty nào chuyên làm việc xấu có liên quan đến những chuyện bất chính, phi nghĩa như cờ bạc, ma túy, mại dâm thì đều không thể đặt hoặcđeo trang sức có***hình Kỳ Lân***trong nhà được.

Phần đầu Kỳ Lân giống rồng, dài và có hai sừng,*thân Kỳ Lân giống thân của hươu*, có vảy khắp người, lông đuôi thường cong, thần thái vô cùng sinh động, là loại Thụy Thú biểu tượng của đất nước Trung Hoa cổ đại.

Ngày nay, trên thị trường chúng ta có thể mua được Kỳ Lân với đủ các loại trang sức hoặc tượng từlinh vật phong thủy này như***m****ặt dây chuyền cóhình kỳ****lân***….

[![ky-Lan-Nhu-Y-cam-thach-trang](/uploads/news/art-016-1-1-ky-lan-nhu-y-cam-thach-trang-0.jpg)](https://web.archive.org/web/20150126100903/http://thegioidaquy.net/phong-thuy/ky-lan-nhu-y-cam-thach-trang-3051.html#.VLqXBdKsVlw)

*[Mặt đeo Kỳ lân phong thuỷ cẩm thạch trắng](https://web.archive.org/web/20150126100903/http://thegioidaquy.net/phong-thuy/ky-lan-nhu-y-cam-thach-trang-3051.html#.VLqXBdKsVlw)đem lại tài lộc và bình an.*

Tổ tiên của chúng ta tin rằng loài Thụy Thú này có một nguồn sức mạnh và sức ảnh hưởng thần bí nguyên thủy.

Các loài Thụy Thú đều là biểu tượng của sự cát tường, là hóa thân của những điềm lành. Tất nhiên Kỳ Lân cũng có những đặc tính này. Ngoài ra**Kỳ Lân còn có một số tác dụng sau:**

-Đeo trang sức Kỳ Lântrên người có tác dụng tránh tà ngăn sát khí.

- Kỳ Lân có tác dụng hóa giải Tam sát. Tam sát nằm ở những vị trí khác nhau tùy theo từng năm, chúng ta có thể tìm thấy vị trí của Tam sát trong các cuốn lịch vạn sự hàng năm. Muốn hóa giải Tam sát cần dùng 3 con Kỳ Lân (tốt nhất là những con Kỳ Lân đã khai quang), đặt chúng ở vị trí Tam sát, đầu hướng về phương Tam sát.

- Kỳ Lân có khả năng thay đổi gia vận theo chiều hướng tốt, làm giảm tai họa, Kỳ Lân là con vật tượng trưng cho sự may mắn, có tác dụng trấn trạch tị tà, tăng thêm điềm lành cho gia đình, không chỉ giúp sự nghiệp của gia chủ thuận lợi mà còn làm cho tài vận biến chuyển tố đẹp. Ngoài ra, Kỳ Lân còn giúp gia chủ trừ bỏ những điều xui xẻo, những điều làm trì trệ sự may mắn của gia đình, Còn về khả năng chuyển thời vận, tốt nhất nên dùng***Kỳ Lân đã khai quang***.

- Kỳ Lân có tác dụng hóa giải Bạch Hổ. Đặt một đôi Kỳ Lân ở phương Bạch Hổ trong nhà có thể hóa giải hung tính của phương Bạch Hổ, làm cho mọi người sống trong nhà được bình an. Đặc biệt là bên ngoài phương Bạch Hổ ở vị trí có ống khói hoặc những vật nhọn xung xạ, càng cần đặt một cặp Kỳ Lân đã khai quang.

Kỳ Lân là Thụy Thú, nên bất cứ nhà nào bất cứ vị trí nào cũng có thể đặt Kỳ Lân. Sau khi khai quang nó có tác dụng trấn trạch tị tà, mang thêm điềm lành. Ngoài ra, tạo hình Kỳ Lân rất đẹp, là một món quà tặng rất có ý nghĩa cho người thân và bạn bè khi về nhà mới.

[*Thegioidaquy.net*](https://web.archive.org/web/20150126100903/http://thegioidaquy.net/phongthuy.html)',
    '2015-01-18 09:00:00', 0, 968, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-015', 'tang-van-may-tinh-duyen-voi-doi-chim-uyen-uong-da-tu-nhien', 'Tăng vận may tình duyên với đôi chim uyên ương đá tự nhiên', 'Thế Giới Đá Quý',
    '/uploads/news/art-017-1-1-doi-uyen-uong-0.jpg', 'Theo phong thủy, đôi chim uyên ương là biểu tượng rất mạnh trong tình yêu về hạnh phúc hôn nhân và đời sống lứa đôi. Chính vì vậy, nhiều người đã lựa chọn trưng bày hình ảnh một cặp đôi chim uyên ương đá tự nhiên để kích hoạt vận may tình duyên của mình.', '- Là một biểu tượng may mắn,[đôi chim uyên ương đá tự nhiên](https://web.archive.org/web/20150126100935/http://thegioidaquy.net/phong-thuy/doi-uyen-uong-thach-anh-hong-lon-609.html#.VLkpmNKsVlw)tượng trưng cho tình yêu và hôn nhân hạnh phúc. Vì thế, để tăng vận may tình duyên của mình, hãy chọn***đặt một cặp chim uyên ương bằng đá tự nhiên***ở góc Tây – Nam của phòng ngủ hoặc phòng khách. Nếu kết hợp với một lẵng hoa mẫu đơn cùng với chiếu sáng đầy đủ thì như dệt gấm thêu hoa trong cuộc sống hôn nhân, lứa đôi.

- Cần lưu ý chỉ nên chọn*đôi chim uyên ương được làm bằng đá quý tự nhiê*n. Bởi những vật liệu này mang hành Thổ sẽ có tác dụng tăng cường năng lượng dương trong căn phòng.

- Tuyệt đối không nên chọn mua một**đôi chim uyên ương**được chạm khắc trên gỗ, bởi gỗ là hành Mộc tương khắc với hành Thổ (chủ yếu về hướng đào hoa) tại khu vực Tây-Nam phòng ngủ. Điều này trở nên phản tác dụng.

- Điều quan trọng nhất đối với việc trung bày đôi chim uyên ương là bạn đừng bao giờ trưng bày một con uyên ương riêng lẻ. Vì khi đó chim uyên ương lại tượng trưng cho sự cô đơn, lẻ loi và buồn bã. Điều này sẽ có ảnh hưởng rất xấu đến đời sống tình cảm của bạn.

-***Bạn cũng không nên trưng bày ba con uyên ương***, vì nó tượng trưng cho thành phần thứ ba xen vào cuộc sống lứa đôi của bạn. Điều này hiển nhiên là điều mà bạn hoàn toàn không mong đợi. Vì vậy hãy ghi nhớ chỉ trưng bày một cặp uyên ương, không hơn, không kém. Chỉ trong trường hợp đó, đôi chim uyên ương mới phát huy triệt để nguồn năng lượng của mình.

[![doi-uyen-uong](/uploads/news/art-017-1-1-doi-uyen-uong-0.jpg)](https://web.archive.org/web/20150126100935/http://thegioidaquy.net/phong-thuy/doi-chim-Uyen-Uong-thach-anh-tim-1822.html#.VLkoitKsVlw)

*[Đôi Uyên Ương thạch anh tím](https://web.archive.org/web/20150126100935/http://thegioidaquy.net/phong-thuy/doi-chim-Uyen-Uong-thach-anh-tim-1822.html#.VLkoitKsVlw)đem lại may mắn tình cảm gia đình và thắt chặt tình duyên.*

**Một số biện pháp giúp phụ nữ độc thân nhanh chóng tìm được ý trung nhân**

- Đối với một người**phụ nữ độc thân đang tìm kiếm tình yêu**và muốn hướng đến hôn nhân chúng ta có rất nhiều cách giúp tăng cường vận khí trong nhà. Trước hết bạn nên củng cố năng lượng dương vì nó trực tiếp ảnh hưởng đến cuộc sống tình cảm. Giải pháp cho vấn đề này là đặt mộtđôi chim uyênương bằngđátựnhiên bên cạnh một ngọn đèn chiếu sáng ở góc Tây – Nam phòng khách và phòng ngủ của bạn.

- Ngoài ra, tất cả tranh ảnh nghệ thuật trang trí trong nhà phải tượng trưng cho sự nam tính. Bạn có thể treo tranh ảnh thần tượng như nam diễn viên, nhóm ca nam, thậm chí tranh ảnh của hoàng đế và treo gần những vật mà bạn ưa thích để người mà bạn muốn thu hút sẽ thích hợp với cách sống của bạn.

- Đôi khi, bạn cũng nên treo tranh ảnh một cặp tình nhân để cân bằng năng lượng. Âm nhạc sẽ cung cấp thêm sinh khí cho ngôi nhà, những vật trang trí được trưng bày theo cặp cũng mang lại sự hài hòa.

- Điều cần chú ý, bạn nên hạn chế sử dụng năng lượng âm trong trang trí. Đối với đồ đạc nội thất màu đen và thảm màu tối nên cân bằng với ánh sáng mạnh nhưng không chói mắt để căn phòng được đầy đủ ánh sáng. Tốt nhất, bạn hãy tăng cường năng lượng dương trong phòng khách. Không nên để quá nhiều năng lượng dương trong phòng ngủ, vì điều này sẽ tạo ra những trở ngại trong quá trình tìm kiếm bạn đời.

- Với những chia sẻ như trên, hy vọng rằng mọi người sẽ có những phương án thích hợp***để tăng cường nguồn năng lượng cho đời sống tình cảm của mình***.

[*Thegioidaquy.net*](https://web.archive.org/web/20150126100935/http://thegioidaquy.net/phongthuy.html)',
    '2015-01-16 09:00:00', 0, 1011, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-016', 'ngua-phong-thuy-va-cach-bay-tri', 'Ngựa phong thủy và cách bày trí', 'Thế Giới Đá Quý',
    '/uploads/news/art-018-1-1-ngua-phong-thuy-thach-anh-tim-0.jpg', 'Bạn có biết Ngựa phong thủy là một trong số những quà tặng phong thủy rất được mọi người ưa chuộng hiện nay. Việc bày trí ngựa phong thủy sẽ có tác dụng cải thiện trong việc đột phá xoay chuyển những cục diện bế tắc, giúp chủ nhân thăng tiến trong sự nghiệp.', '**1.****Đôi nét về Ngựa Phong thủy:**

-**Con ngựa**là biểu tượng của sự bền bỉ, sinh sôi và thịnh vượng. Vì thế, mọi người thích trưng bày tượng**ngựa phong thủy**tại những vị trí đẹp trong nhà với hy vọng “Mã đáo thành công”.

- Bản chất ngựa là con vật có số mệnh khỏe mạnh, hào phóng, táo bạo, không ràng buộc. Do đó khi bài trí*linh vật phong thủ*y này trong nhà hay đeo những trang sức phong thủy có linh vật này trên người sẽ làm cho chủ nhân trở nên vui vẻ, tràn đầy năng lượng, có tác dụng cải thiện trong việc đột phá xoay chuyển những cục diện bế tắc, giúp chủ nhân thăng tiến trong sự nghiệp.

- Ngoài ra,*Con ngựa cũng là biểu tượng cho sự trung thành*. Cũng chính vì lẽ đó mà người ta thường hay chọn Ngựa phong thủy để làm quà tặng nhau trong ngày lễ tình nhân Valentine bởi không chỉ vì hình ảnh ngựa đẹpmà nó còn mang lại ý nghĩa rằng người bạn đời của mình sẽ trung thành trong tình yêu.

-**Ngựa phong thủy đá tự nhiên**và bằng đồng là một trong số những quà tặng phong thủy rất được mọi người ưa chuộng hiện nay.Bởi trong phong thủy, Ngựa bằng đá tự nhiên, bằng ngọc hoặc bằng đồng sẽ mang đến cho chủ nhân công năng mạnh và hiệu quả phong thủy cao gấp nhiều lần so với  được chế tạo từ những chất liệu khác.

[![ngua-phong-thuy-thach-anh-tim](/uploads/news/art-018-1-1-ngua-phong-thuy-thach-anh-tim-0.jpg)](https://web.archive.org/web/20150126133720/http://thegioidaquy.net/phong-thuy/Ngua-phong-thuy-thach-anh-tim-2707.html#.VLki49KsVlw)

*[Ngựa phong thuỷ thạch anh tím](https://web.archive.org/web/20150126133720/http://thegioidaquy.net/phong-thuy/Ngua-phong-thuy-thach-anh-tim-2707.html#.VLki49KsVlw)đem lại tài lộc và may mắn cho người hay đi làm ăn xa.*

- Nhứng người kinh doanh, đầu tư, hay đi xa… rất thích chọn những biểu tượng tuấn mã trong tư thế chạy.

[if !supportLists]**2.**[endif]**Cách bày trí hợp phong thủy đối với Tượng ngựa:**

-***Con ngựa trong phong thủy phân chia là “Hung thú” hay “Cát thú”***. Nhưng hầu hết mọi người đều cho rằng Ngựa là linh vật phong thủy cát thú dùng để thăng tiến. Chính vì vậy, để phát huy hết hiệu suất linh lực do vật phẩm phong thủy này mang lại thì ngoài việc chú ý đến kiểu dáng, chất liệu, chúng ta phải chú ý đến phương hướng và cách bài trí của nó.

-**Ngựa phong thủy**tốt nhất nên được ở phòng khách. Phòng khách là nơi dừng khí, tiếp nhận các dòng khí tốt và xấu vào nhà. Vì vậy vật phẩm phong thủy này sẽ phát huy tác dụng tốt khi được đặt tại phòng khách.

- Theo quan niệm dân gian, bài trí ngựa trên bàn làm việc hoặc chỗ tài vị trong nhà (hướng ra cổng lớn hoặc cửa sổ) sẽ đại cát.

- Bài trí ngựa không nên đơn điệu một con, mà cần đặt thêm các biểu tượng bên cạnh và quay đầu vào nhà mới tốt. Như đặt tượng Phật Di Lặc biểu tượng tuyệt đối của hạnh phúc. Miệng cười tươi, bụng lớn là biểu tượng cho sự vui vẻ, an lạc, may mắn, hạnh phúc và tốt lành.

[![tuong-Di-Lac-go-dung-cao-3m.](/uploads/news/art-018-2-1-tuong-di-lac-go-dung-cao-3m-0.jpg)](https://web.archive.org/web/20150126133720/http://thegioidaquy.net/phong-thuy/tuong-di-lac-1085.html#.VLkh2tKsVlx)

*[Tượng Phật Di Lặc](https://web.archive.org/web/20150126133720/http://thegioidaquy.net/phong-thuy/tuong-di-lac-1085.html#.VLkh2tKsVlx)biểu tượng tuyệt đối của hạnh phúc*

Tóm lại, trước khi mua ngựa phong thủy nói riêng cũng như đồ phong thủy nói chung, gia chủ nên xem xét cẩn thận nhu cầu về loại đồ đó, sau đó phải cần có sự tư vấn của người am hiểu về phong thủy để chọn đồ hợp với mệnh và tuổi (của gia chủ), rồi xác định vị trí đặt ngựa phù hợp, hướng nhà, chứ không nên đặt tùy tiện.

Tuyệt đối không dùng đồ xấu xí, đồ cũ, uể bẩn hoặc đồ để quá lâu… vì có thể đã phát sinh nhiều năng lượng xấu.

[*Thegioidaquy.net*](https://web.archive.org/web/20150126133720/http://thegioidaquy.net/phongthuy.html)',
    '2015-01-16 09:00:00', 0, 1054, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-017', 'y-nghia-cua-vat-pham-phong-thuy-bang-da-tu-nhien-ung-voi-12-con-giap', 'Ý nghĩa của vật phẩm phong thủy bằng đá tự nhiên ứng với 12 con giáp', 'Thế Giới Đá Quý',
    '/uploads/site_assets/Phongthuy-HoaMocLan-thegioidaquy.jpg', 'Mỗi linh vật phong thủy bằng đá tự nhiên trong 12 con giáp đều mang những ý nghĩa riêng. Dựa trên tính cách, bản chất riêng của từng linh vật mà mỗi linh vật sẽ mang đến những vận may khác nhau cho gia chủ. Hãy cùng chúng tôi tìm hiểu nhé!', '**1.Con chuột:**

- Chuột làloài cósức sinhđẻởcấp sốnhân. Với thân hình nhỏnhắn, chuột cóthểdễdàng lẫn trốnởkhắp mọi nơiđểtìm thứcăn. Dođóchúng luôn tồn tại vàliên tục phát triển không ngừng.

- Tuy làsinh vật nhỏbénhưng chuột lạiđứngđầu trong*12 con giáp*. Bởi Con chuột mang hành thủy. Vũ trụ hình thành đầu tiên sinh ra nước. Nước có sự sống sinh ra vạn vật… Vì thế người ta trưng bày tượng*[**chuột phong th****ủy bằngđátựnhiê****n**](https://web.archive.org/web/20150126102243/http://thegioidaquy.net/phong-thuy/chuot-phong-thuy-thach-anh-tim-2713.html#.VLPQV9KsVlx)*với mong muốn một sự bắt đầu và sự phát triển trường tồn.

[if !supportLists]**2.****Con trâu**

- Trâu phong thủyđược coi là biểu tượng cát lợi. Nếu***đặt tượng trâu phong thủyở****hướng Đông Bắc***thiên về Bắc thì gia chủ sẽ lại càng đại cát đại lợi.

[if !supportLists]**3.****Con hổ**

- Hổ là con vật linh thiêng và đầy uy quyền thường được thờ phụng, chính vì thế nó là biểu tượng cho quyền lực, cho công danh học hành và sự tăng tiến trong kinh doanh.

-*Đặ**t tượng hổphong thủy bằngđátựnhiên*ởcác hướng Chính Bắc, Tây Bắc, Tây sẽgiúp tăng cường cát khí cho các sao tốt ở các hướng này, trấn yếm khi bị Sát hướng.

[if !supportLists]**4.Con mèo**

- Trongphong thủy, tượng mèo được xem là linh thú cát tường, có thể nhờ linh lực của nó để hóa giải sát khí.

**5. Con rồng**

- Đây là một con vật không có thật. Nhưng trong suy nghĩ của mọi người, rồng mang lại rất nhiều may mắn. Nếu gia chủ muốn quan hệ ngoại giao ngày càng tiển triển thuận lợi thì nên đặt tượng rồngbằngđátựnhiênởhướngnhìn ra cửa.

*[Rồng phong thuỷ thạch anh hồng](https://web.archive.org/web/20150126102243/http://thegioidaquy.net/phong-thuy/rong-phong-thuy-thach-anh-hong-2664.html#.VLPRK9KsVlw)*giúp đem lại may mắn thăng tiến sự nghiệp.

[if !supportLists]**6.****Con rắn**

- Theo phong thủy, việc**b****ài trítượng rắn bằngđáquý trong nhàhay văn phò****ng**sẽgiúp chủnhân gặpđược nhiều may mắn hơn trong cuộc sống, khiến công việc luôn thuận lợi, trôi chảy. Bởi trong 12 con giáp, chỉcórắn làcókhảnăng “lột da”đểphát triển với hàm ý rũbỏlại những cái khókhắn sóng gióđã qua của năm cũđểtiến lên trong năm mới một cáchđầy hứa hẹn, vượng tài tăng lộc.

[if !supportLists]**7.****Con ngựa**

- Nói đến ngựa là nói đến việc xoay chuyển tài vận khiến sự nghiệp phát triển. Chính vì thế, trong nhà*bày trí**tượng ngựa phong thủy bằngđá**quý*theo hướng Tây-Nam sẽcótác dụng thúc đẩy sự nghiệp ngày càng phát đạt, tấn tới. Đây là phương vị mang lại nhiều tài lộc nên chủ nhân cần lưu ý thì mới cóthểgiúp cho linh vật này phát huy hết tác dụng.

**8. Con dê**

- Tượng dêphong thủy bằngđáquýcó thể tăng tính nhẫn nại và ý chí cho gia chủ.

**9.**[endif]**Con khỉ**

**-**Loài khỉ được coi là tổ tiên của loài người. Trong phong thủy, Khỉ Phong Thủy được coi là biểu tượng cho sự quyền quý. Nếu đặt tượng khỉ phong thủy bằngđátựnhiênở vị trí thích hợp sẽ mang lại điều tốt đẹp và may mắn cho gia chủ. Ngoài ra, cũng có thể sử dụng biểu tượng này làm vật trang sức đeo trên người.

*Mặt dây chuyền[Mã thượng phong hầu đá cẩm thạch](https://web.archive.org/web/20150126102243/http://thegioidaquy.net/phong-thuy/ma-thuong-phong-hau-da-cam-thach-1336.html#.VLPSRtKsVlw)giúp chủ nhân thăng quan tiến chức trong sự nghiệp*

**10. Con gà**

-**Đặ****t tượng gàphong thủyđáquý trong nhà**có tác dụng làm tinh thần phấn chấn và luôn tiến về phía trước,thúc đẩy bản thân, nâng cao tinh thần hăng hái làm việc.

**11. Con chó**

- Chó là loài động vật rất thân thiết và gần gũi với con người. Ngoài làm bạn với chủ, nó còn đảm nhiệm một công việc hết sức quan trọng là coi giữ nhà cửa. Trong nhà có thể đặt tượng chó nhưng không nên bày hai con ở hai bên. Vì sự kết hợp này mang lại điều xui xẻo, bất lợi cho gia chủ.

**12. Con lợn**

- Trong phong thủy, lợn mang lại may mắn cho gia chủ và đại diện cho sự thịnh vượng, giàu có và khả năng sinh sản, thành công trong công việc. Ngoài ra, lợn còn tượng trưng cho sự đầy đủ thức ăn, niềm vui vật chất, sự an toàn trong nhà.

-*Đặt lợn phong thủy bằngđáở góc cung Tài Lộc (Đông Nam)*để thu hút vận may về sự giàu sang. Có thể bày trên bàn trong phòng khách, văn phòng, cửa hàng, bày trên bàn thờ, két bạc, bàn làm việc…

[*Thegioidaquy.net*](https://web.archive.org/web/20150126102243/http://thegioidaquy.net/phongthuy.html)',
    '2015-01-12 09:00:00', 0, 1097, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-018', 'ga-phong-thuy-bang-da', 'Gà phong thủy bằng đá', 'Thế Giới Đá Quý',
    '/uploads/site_assets/Phongthuy-HoaMocLan-thegioidaquy.jpg', 'Trong phong thủy, Gà bằng đá quý thường được sử dụng khá phổ biến như là một vật phẩm phong thủy để cầu may mắn, đại cát đại lợi cho chủ nhân. Ngoài ra, bài trí gà trống còn giúp mang lại hạnh phúc và may mắn cho gia chủ.', '"Gà" chữ hán đọc là "Kê", đồng âm với cát " (điều tốt, đối với hung). Do đó "gà" biểu trưng cho điều tốt. Kê (gà) là con vật có đủ năm đức tính tốt của nam nhi : Văn, Vũ, Dũng, Nhân, Tín.

Trong phong thủy,[biểu tượng gà](https://web.archive.org/web/20260411182230/http://thegioidaquy.net/phong-thuy/da-phongthuy-273-Ga-phong-thuy/)thường được sử dụng khá phổ biến nhưlàmột vật phẩm phong thủyđểcầu may mắn,đại cátđại lợi cho chủnhân. Nócó thể là giải trừ các thế sát cho ngôi nhà hoặc giải trừ “đào hoa sát” cho cá nhân, tránh bị tiểu nhân nói xấu sau lưng. Ngoài ra, bài trí gà trống còn giúp mang lại hạnh phúc và may mắn cho gia chủ.

[if !supportLists]**1.[endif]****Chất liệu gà**

- Chất liệu của con vật có vai trò quyết định đến***hiệu quả sử dụng về mặt phong thủy***. Bày tríhoặcđeo trang sứcgàphong thủyđáquý cócông dụng hóa sát, xuađuổi thịphi.

- Cần lưu ý, gàđược chếtạo bằng chất liệu cao su hoặc nhựa thìhoàn toàn không cótác dụng phong thủy vìchúng không cólinh lực.

[if !supportLists]**2.[endif]Cách bài trígàhợp phong thủ****y**

[if !supportLists]**a.[endif]Trong nhà****:**

- Theo quan niệm ngũ hành, gà (Dậu ở hướng Tây) là con vật thuộc hành Kim, phù hợp khi bài trí ở hướng Tây của căn phòng. Ngoài ra, bạn có thể bài trí gà phong thủy tại văn phòng hay phòng khách (hướng Nam) để thu hút may mắn cho gia chủ trong cuộc sống và công việc.

*[Gà phong thuỷ thạch anh tím](https://web.archive.org/web/20260411182230/http://thegioidaquy.net/phong-thuy/Ga-phong-thuy-thach-anh-tim-2704.html#.VKq73tKsVlw)đem lại tiền tài và xua đuổi thị phi.*

- Người Trung Quốc tin rằng,**gà phong thủy**sẽ ngăn cản được năng lượng xấu và những xung đột. Có thể bài trí gà phong thủy trong phòng ăn để bảo vệ gia đình khỏi năng lượng không tốt từ ống thoát khí. Các ống thoát khí mang hình ảnh của con rắn nên được coi là điềm xấu.

-Nếu đặt gà phong thủy trong phòng kháchnhìn thẳng ra trước cửa nhà có thể ngăn chặn được sự không chung thủy của người bạn đời. Khi chồng hoặc vợ đã có tình cảm với người khác ở bên ngoài, thì nên đặt một cặp gà trống bên trong tủ quần áo của chồng hoặc vợ, mỗi góc tủ một con để hóa giải.

- Xét về mặt chiêu tài, mặc dù không có được tác dụng lớn như biểu tượngcóc 3 chânnhưng bạn vẫn có thể bài trí biểu tượng gà phong thủy trong nhà để thu hút tài lộc.

*[Gà thạch anh hồng](https://web.archive.org/web/20260411182230/http://thegioidaquy.net/phong-thuy/ga-thach-anh-hong-lon-280.html#.VKq85tKsVlw)kích hoạt cung tình duyên cho chủ nhân*

[if !supportLists]**b.[endif]Trong kinh doanh:**

- Gà phong thủy được sử dụng trong văn phòng và các doanh nghiệp vì nó có khả năng thúc đẩy sự nghiệp phát triển.

- Trong kinh doanh, có thể bài trí gà phong thủy ở khu vực đối diện với các dãy phòng để ngăn chặn sự bất đồng.

- Bên cạnh đó, con gà trống, với tư thế vương giả của chúng, cũng được cho là rất tốt cho các nhà lãnh đạo.

[*Thegioidaquy.net*](https://web.archive.org/web/20260411182230/http://thegioidaquy.net/phongthuy.html)',
    '2015-01-06 09:00:00', 0, 1140, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-019', 'tang-tai-van-tran-trach-nho-long-quy-phong-thuy-bang-da-quy', 'Tăng tài vận, trấn trạch nhờ Long Quy Phong thủy bằng đá quý', 'Thế Giới Đá Quý',
    '/uploads/news/art-022-1-1-long-quy-lon-da-den-phat-son-0.jpg', 'Long Quy phong thủy hay còn gọi Rùa đầu Rồng. Đây là một linh vật huyền thoại trong dân gian về sự kết hợp giữa “Rồng” và “ Rùa” mang ý nghĩa tăng tài lộc, thịnh vượng trong việc làm ăn.', 'Trong phong thủy, ngoài TỳHưu vàThiềm Thừlàhai linh vật mang ý nghĩa rất lớn vềviệc mang tài lộc, tiền tại vàsựphátđạt, thì[Long Quy phong thủy](https://web.archive.org/web/20150107174417/http://thegioidaquy.net/phong-thuy/da-phongthuy-270-Long-Quy-phong-thuy-Rua-dau-Rong-/)bằngđáquý cũng làmột linh vật mang ý nghĩa chiêu tài, tăng tài vận, sựbền vững vàthịnh vượng trong kinh doanh cho chủnhân.

Theo truyền thuyết,***Long Quy phong th****ủy hay còn gọi Rùađầu Rồ****ng***.Đây làmột linh vật huyền thoại trong dân gian vềsựkết hợp giữa “Rồng” và“ Rùa”. Cảhai loài này vốn nằm trong bộTứLinh (Long, Lân, Quy, Phụng) nên lại càng tăng thêm sựlinh thiêng cho vật phẩm phong thủy này.

Long Quy phong thủy bằngđáquý cònđược cho làVương Trượng của văn phòng. BởiLong Quy (Rùađầu Rồng)tượng trưng cho phước lành, thành công, sức mạnh của quyền lực, sựmay mắn vàthịnh vượng trong nghềnghiệp cũng nhưtrong việc làmăn, kinh doanh.

Chúng ta***nênđặt Long Quy trên bàn thờthần tài***, trên két sắt, trên bàn làm việc hoặc vùng gần cửa chínhđểvượng tài lộc, kinh doanh thuận lợi. Hoặcđặt chúngởphía sau lưng bạn tại nơi làm việc sẽcótác dụng giúp hỗtrợtrong việc nhậnđược sựgiúpđỡtừcấp trên cũng nhưsựthăng tiến trong việc làm. Người ta tin rằng, nếuđặt Long Quy phong thủy bằngđátrong văn phòng sẽnhậnđược sựgiúpđỡtrong công việc, sếp tin dùng vàmọi việc việcđềuđược trôi chảy, thuận lợi.

[![long-Quy-lon-da-den-Phat-Son](/uploads/news/art-022-1-1-long-quy-lon-da-den-phat-son-0.jpg)](https://web.archive.org/web/20150107174417/http://thegioidaquy.net/phong-thuy/long-quy-lon-da-den-phat-son-543.html#.VKTeHtKsVlw)

*[Long Quy phong thuỷ](https://web.archive.org/web/20150107174417/http://thegioidaquy.net/phong-thuy/long-quy-lon-da-den-phat-son-543.html#.VKTeHtKsVlw)tăng tài lộc may mắn công danh và sức khoẻ*

Ngoài ra,**Long Quy phong th****ủy bằngđá****quý**còn cótác dụng trong việc trấn trạch, giải trừhạn vậnđặc biệt làcác hung tinh như: Tam Bích, Nhi Hắc, Thất Xích, Hoa Hai cho gia chủ.

Long Quy nếuđặt tại vịtrítài vịsẽcótác dụng thúcđẩy tài lộc,đặt tại vịtríTam Sát hoặc nhiều thủy khíthìcótác dụng hóa giải rất lớn, không những cóthểhóa giải tranh cãi màcònđem lại nhân duyên nữa.

*Long Quy phong thủ**y*bài tríởphía hậu nhàcótác dụng Trấn Trạch. Bởi Long Quy trước tiên mang hàm nghĩa vinh quy, ngụý rằng Vinh hoa phúqúy hay Áo gấm vềlàng. Cho nên nóiđến Long Quy thìchúng ta sẽnghĩngay nólàmột linh vật rất tốt lành.

Cách chọn mua Long Quy phong thủy:

[if !supportLists]-[endif]Nên chọn mua những sản phẩm Long Quy phong thủyđược chếtạo từđáquý thiên nhiên.

[if !supportLists]-[endif]Đầu Rồng cósừng, nếu cóhai sừng thìcàng tốt. Bởi vìmột sừng cóthểbảo vệchủnhânđược bình an. Sừng còn lại giúp cho nhân tăng tài vận.

[![long-Qui-uy-manh-da-huyet-thach](/uploads/news/art-022-2-1-long-qui-uy-manh-da-huyet-thach-0.jpg)](https://web.archive.org/web/20150107174417/http://thegioidaquy.net/phong-thuy/long-quy-da-huyet-thach-lon-542.html#.VKTVzNKsVlw)

*[Long Quy phong thủy Đá huyết thạch](https://web.archive.org/web/20150107174417/http://thegioidaquy.net/phong-thuy/long-quy-da-huyet-thach-lon-542.html#.VKTVzNKsVlw)mang lại tài vận tốt cho chủ nhân*

[if !supportLists]-[endif]Vật phẩm phong thủy này sau khi mua vềcần phải dùng chu sa khai quang mới cóthểphát huy tốiđa sức mạnh của nó.

[if !supportLists]-[endif]Hình dáng Long Quy phải cóthần khí

[*Thegioidaquy.net*](https://web.archive.org/web/20150107174417/http://thegioidaquy.net/phongthuy.html)',
    '2015-01-01 09:00:00', 0, 1226, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-020', 'rong-da-phong-thuy-va-nhung-dieu-can-biet', 'Rồng đá phong thủy và những điều cần biết', 'Thế Giới Đá Quý',
    '/uploads/news/art-023-1-1-mat-rong-bay-da-obsidian-0.jpg', 'Rồng đá phong thủy được cho là “Long khí”, là sinh lực của vũ trụ. Nó có tác dụng cải thiện mối quan hệ giao tiếp, hóa giải và tăng thêm tài vận cho gia chủ.', '[Rồngđáphong thủy](https://web.archive.org/web/20150107004842/http://thegioidaquy.net/phong-thuy/da-phongthuy-268-Rong-phong-thuy/)làlinh vật thần thoại tượng trưng cho Thiên mệnh cao cảvàtối thượng của các vịVua chúa ngày xưa. Ngày nay, trong phong thủy, Rồngđược cho là“Long khí”, làsinh lực của vũtrụ. Nóẩn hiện trong lòngđất, vận chuyển thành “long mạch”.

Trong phong thủy, linh vật**Rồng****Phong Thủy**đứng thứ 5 trong thuyết 12 con giáp và theo truyền thuyết xa xưa Rồng là con vật linh thiêng, là con thú tốt lành, mình rồng dài, trên thân có nhiều vẩy, trên đầu có sừng như sừng hươu, chân có móng vuốt, rồng có nhiều tài như bay trên trời, bơi dưới nước… có tác dụng trừ khử tiểu nhân, đem lại vận may cho gia đình đặc biệt là những quý cô độc thân.

*Rồng phong thủ**y*thườngđược chếtác từnhiều chất liệu khác nhau. Tuy nhiênđểcon Rồng phong thủy cóthểphát huyđược linh lực hoàn toàn của nó, tốt nhất chúng ta nên chọn Rồng phong thủyđược chếtác từđá. Nhưvậy nómới cóđược cảm giác cao quý vàsang trọng.

Chúngđược chếtạo thành trang sức hoặc vật phẩm phong thủy dưới nhiều dạng khác nhau như:**Mặt dây chuyền tụrồngđáruby**,**Bồn tụtài cáRồngđámã não**,**Rồng phong thủy thạch anh tím…**

**[![mat-Rong-bay-da-Obsidia](/uploads/news/art-023-1-1-mat-rong-bay-da-obsidian-0.jpg)](https://web.archive.org/web/20150107004842/http://thegioidaquy.net/phong-thuy/mat-rong-bay-da-Obsidian-3181.html#.VKBPRsgU)**

*[Mặt dây chuyền hình Rồng](https://web.archive.org/web/20150107004842/http://thegioidaquy.net/phong-thuy/mat-rong-bay-da-Obsidian-3181.html#.VKBPRsgU)[đá Obsidia](https://web.archive.org/web/20150107004842/http://thegioidaquy.net/phong-thuy/mat-rong-bay-da-Obsidian-3181.html#.VKBPRsgU)n đem lạ quyền lực cho gia chủ*

[if !supportLists]**1.Cách bài tríRồngđáphong thủ****y:**

[if !supportLists]-Theo các chuyên gia phong thủy, Chúng ta*n**ênđăt tượng Rồngđáphong thủyởhướngĐ**ôn*g. Nếu bài trítheo ngũphương vị, bao gồm: Thanh Long, Bạch Hổ, Chu Tước, Huyền Vũthìnên bài trítại bên trái.

[if !supportLists]-Bày trí**m****ộtđôi Rồngđáphong thủy hướng ra cửa tại vịtrítường bên trái hoặc trên bàn làm việc**sẽcótác dụng cải thiện mối quan hệvàtăng tài vận cho gia chủ.

[if !supportLists]-Vịtrítốt nhấtđểđặt Rồngđáphong thủy sao cho việc kinh doanh thuận lợi, tài lộc vào nhàvàsựnghiệp phát triển chính làđặt chúng trên bểcá. Tuy nhiên chúng ta cần lưu ý, nếu bài trítrên bểcáthìnên chọn kích cỡRồngđáphong thủy vừa phải, nếu quáto sẽkhông tốtđối với vận khíngôi nhà.

[![rong-phong-thuy-thach-anh-hong](/uploads/news/art-023-2-1-rong-phong-thuy-thach-anh-hong-0.jpg)](https://web.archive.org/web/20150107004842/http://thegioidaquy.net/phong-thuy/rong-phong-thuy-thach-anh-hong-2664.html#.VKBOmsgU)

*[Rồng phong thuỷ đá thạch anh hồng](https://web.archive.org/web/20150107004842/http://thegioidaquy.net/phong-thuy/rong-phong-thuy-thach-anh-hong-2664.html#.VKBOmsgU)giúp đem lại may mắn thăng tiến sự nghiệp.*

[if !supportLists]-Chúng ta cũng cóthể***b**ài tríRồngđáphong thủ**y***tại hướng bắc trong nhà. Bởi trong ngũhành hướng bắc làthuộc Thủy.

[if !supportLists]-Nếu bài trí con rồng là để hóa giải thì phải theo đặc tính của rồng bài trí mới phát huy khả năng. Nhưng nếu là xuyên tâm sát và có đường đâm thẳng vào nhà, bài trí rồng phong thủy không có hiệu quả mấy. Do con rồng có một khí thế vua, có quyền uy và sức mạnh, cho nên với những khí uế, khí âm, khí tà ít có tác dụng trấn áp.

[if !supportLists]-Ngoài ra, những chỗ có sát khí nặng như cục cảnh sát, quân dinh, nhà tù…bài trí con rồng phong thủy cũng có thể phát huy linh lực của nó để hóa giải. Nếu nhà ở gần chùa miếu thì không tốt, có thể bài trí một đôi rồng phong thủy hướng với những chỗ này thì có thể hóa giải, như thế khiến trạng thái tinh thần càng tốt lên.

[if !supportLists]**2.[endif]Nhữngđiều kiêng kỵkhi bài tríRồngđáphong thủ****y**

[if !supportLists]-[endif]Vì***R**ồng làcực dươ**ng***, dođókhông nênđặt chúng trong phòng ngủ.

[if !supportLists]-Khi bài trí đầu rồng nên hướng ra ngoài cửa, không được hướng vào trong nhà. Con rồng hướng ra ngoài là biểu tượng long người chảy ra ngoài.

[if !supportLists]-Con rồng phải bài trí vị trí của rồng, không được bài trí tại vị trí của con hổ, không thì long hổ đấu nhiều sẽ ảnh hưởng đến người trong nhà.

-[endif]Những điêu khắc hình rồng nên treo hướng Thanh Long của phòng khách hoặc phòng thờ.

[*Thegioidaquy.net*](https://web.archive.org/web/20150107004842/http://thegioidaquy.net/phongthuy.html)',
    '2014-12-29 09:00:00', 0, 319, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-021', 'coc-ba-chan-bang-da-phong-thuy-va-nhung-dieu-can-biet', 'Cóc ba chân bằng đá phong thủy và những điều cần biết', 'Thế Giới Đá Quý',
    '/uploads/news/art-024-1-1-coc-ba-chan-thach-anh-toc-trang-dam-0.jpg', 'Cóc ba chân còn có tên gọi khác là thiềm thừ có tác dụng trấn trạch, giữ của cải và tài lộc cho gia chủ. Vật phẩm phong thủy Cóc ba chân thường thấy là chúng ngồi trên những đồng tiền và ngậm đồng tiền thường được đặt ở góc tụ tài, đầu hướng vào trong nhà.', 'Hiện nay,[Cóc ba chânđược chếtác bằngđáquý](https://web.archive.org/web/20150107183812/http://thegioidaquy.net/phong-thuy/da-phongthuy-267-Coc-Ba-Chan/)làmột linh vật rấtđượcưa chuộngđểsửdụng trong việc cầu tài lộc. Chúngđược xếp thứhai chỉsau TỳHưu. Theo phong thủy, chúng tađang sống trong HạNguyên Vận 8 thuộc Bát Trạch (Hành Thổ) từnăm 2004đến năm 2023 (Chu kỳ20 năm), vìvậy***chất liệu tạo cóc ba chân bằngđálàtốt nhất***vàphải làđáthiên nhiên thìmới giữđược nguyên khítích tụqua thời gian củađá, làm cho linh vật này trởnên linh thiêng hơn.

Vật phẩm phong thủy**C****ó****c ba chân**thường thấy làchúng cóthêm một chânởphía sau.Đócũng chính làlý do màngười ta gọi chúng làCóc ba chân. Chúng ngồi trên nhữngđồng tiền hoặc ngậmđồng xu trên miệng….thườngđượcđặtởgóc tụtài,đầu hướng vào trong nhà.*Hìnhảnh Cóc ngậmđồng xu trên miệng*tượng trưng cho việc mang tài lộc vào nhàcho gia chủ.

[if !supportLists]**1.**[endif]**C****á****ch****đặ****t C****ó****c ba chân****đú****ng theo phong th****ủ****y**

[if !supportLists]-Ngày nay,**Phong th****ủ****y**đã trởnên phổbiến vàgắn liềnđời sống con người. Họtrởnên quan tâm hơn vàứng dụng phong thủy vào cuộc sống nhiều hơn. Nhưng việcứng dụng các linh vật phong thủyđúng cách sao chođem lại lợiích vànhữngđiều tốtđẹp cho gia chủthìkhông phải ai cũng biết vàáp dụngđúng.Điển hình làviệc bốtrívật phẩm phong thủy Cóc ba chân bằngđáquý ngậm tiền.

[if !supportLists]-Theo suy nghĩthông thường, khi trưng bày một vật gìđóta thường cóxu hướng làhướng mặt tiền ra bên ngoài, còn phần lưng thìquay vào bên trong. Nhưngđối với vật phẩm Cóc ba chân ngậm tiền bằngđáthìhoàn toàn ngược lại với suy nghĩthông thường của mọi người.Khiđặt linh vật phong thủynày chúng ta phảiđặt cóc ngậm tiền hướng vào bên trong nhà,*tuyệtđối kiêng kịđặt cóc hướng ra phía bên ngoài cửa*, kểcảcửa chính hay cửa sổ. Bởi chúng ta cóthểhiểu rằng Cóc ba chân ngậm tiền vào nhàcho gia chủ, dođóviệcđặt chúng hướng ra bên ngoài làkhông tốt cho gia chủ.

[![coc-ba-chan-thach-anh-toc-trang-dam](/uploads/news/art-024-1-1-coc-ba-chan-thach-anh-toc-trang-dam-0.jpg)](https://web.archive.org/web/20150107183812/http://thegioidaquy.net/phong-thuy/coc-ba-chan-thach-anh-toc-trang-dam-2513.html#.VKBEIsgU)

*[Cóc ba chân thạch anh tóc trắng đậm](https://web.archive.org/web/20150107183812/http://thegioidaquy.net/phong-thuy/coc-ba-chan-thach-anh-toc-trang-dam-2513.html#.VKBEIsgU)phù hợp cho người mạng Kim và mạng Thuỷ.*

[if !supportLists]-[endif]Cần phải lưu ý làkhi trưng bày những linh vật phong thủy chúng ta không nên quayđi quay lại nhiều lần theo những chiều hướng khác nhau. Một sốgiađình thường hay**tr****ưng bày Có****c ba chân**ngậm tiềnởbàn thờThổĐịa, Thần Tài ban ngày thìcho Cóc hướng ra ngoài cửa, tốiđến thìquay Cóc hướng lại vào trong nhà. Trưng bày nhưvậy làkhôngđúng với phong thủy. Dođócách tốt nhất làchúng ta phảiđặc Cóc ba chân hướng vào trong nhà, hướng vào bàn thờôngđịa, thần tài tượng trưng cho việc Cóc mang tài lộc nhảy vào trong nhà.

[if !supportLists]-**Cóc ba chân bằngđá****quý**cũng cóthểđượcđặt dưới gầm bàn làm việc, ghế, trong tủ, trong két sắt vớiđầu hướng vào bên trong, lưng quay ra ngoài.

[if !supportLists]**2.**[endif]**Nh****ữ****ng v****ị****tr****í****ki****ê****ng k****ỵ****khi****đặ****t C****ó****c ba chân b****ằ****ng****đá****:**

[if !supportLists]-Tuyệtđối khôngđặt trong phòng bếp, phòng tắm vànhàvệsinh. Nếuđặt**C****ó****c ba chân**ởnhững vịtrínày sẽphản tác dụng. Cóc trởnên hung dữ, mang lại vận rủi, tàn phánăng lượng tốtđẹp của gia chủ.

[![coc-ba-chan-thach-anh-den](/uploads/news/art-024-2-1-coc-ba-chan-thach-anh-den-0.jpg)](https://web.archive.org/web/20150107183812/http://thegioidaquy.net/phong-thuy/coc-ba-chan-thach-anh-den-2238.html#.VKBFBsgU)

*[Cóc ba chân thạch anh đen phong thuỷ](https://web.archive.org/web/20150107183812/http://thegioidaquy.net/phong-thuy/coc-ba-chan-thach-anh-den-2238.html#.VKBFBsgU)đem lại tài lộc may mắn.*

[if !supportLists]**3.**[endif]**Khai quang cho C****ó****c ba Chân:**

[if !supportLists]-Theo kinh nghiệm trong phong thủy, Khi khai quang linh vật này tốt nhất chỉnên cómột mình gia chủ. Bởi sau ngay khi khai quang, Cóc ba chân bằngđánhìn thấy aiđầu tiên thìchúng sẽmãi mãi chỉphùhộcho ngườiđó.

[if !supportLists]-Cách khai quang cho Cóc ba chân nhưsau:

+ Chọn một ngàyđẹp, tắm rửa sạch sẽcho Cóc ba chân

+ Lấy nửa thùng nước giếng + nửa thùng nước mưa

+Đổnước vàođồchứa Cóc ba chânđã chuẩn bịtừtrước. Lưu ý,đồchứa phải sạch sẽ.

+Đặt Cóc ba chân vào nước ngâm 3 ngày 3đêm

+ Sauđólấy ra, dùng khăn bông sạch sẽlau khô linh vật này

+ Lấy một chút nước chèvẩy vào mắt Cóc ba chân.Đây gọi là“Khai quangđiểm nhãn”.

Thực hiện những bước trên, chúng tađã hoàn tất quátrình khai quang cho linh vật phong thủy này.

[*Thegioidaquy.net*](https://web.archive.org/web/20150107183812/http://thegioidaquy.net/phongthuy.html)',
    '2014-12-29 09:00:00', 0, 362, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-022', 'bi-an-da-phong-thuy', 'Bí ẩn Đá phong thủy', 'Thế Giới Đá Quý',
    '/uploads/news/art-025-1-1-mat-am-duong-da-ngoc-bich-0.jpg', 'Từ Thời Hy Lạp cổ đại, Đá quý đã được xem như một bảo vật phong thủy vì những năng lực kỳ diệu của chúng. Không chỉ ẩn chứa những sắc màu với vẻ đẹp lung linh huyền ảo, mỗi viên đá quý còn mang đến một sức mạnh kỳ diệu về thế giới tâm linh. Hãy cùng chúng tôi khám phá những bí ẩn kỳ diệu này nhé!', '[Thếgiớiđáquý](https://web.archive.org/web/20141231012804/http://thegioidaquy.net/phongthuy.html)làmột thếgiới vô cùngđa dạng vàphong phú. Mỗi loạiđáquý khác nhau sẽchứađựng những năng lực kỳdiệu riêng của chúng.

TừThời Hy Lạp cổđại,***Đáquýđãđược xem nhưmột bảo vật phong thủ****y***vìchúng không chỉẩn chứa những sắc màu với vẻđẹp lung linh huyềnảo, màmỗi viênđáquý còn mangđến một sức mạnh kỳdiệu vềthếgiới tâm linh.

Ngày nay, việc sửdụngđáquýđểchếtạo những mónđồtrang sức xinh xắn nhưdây chuyền, nhẫn, vòng tay…đã không còn xa lạgìđối với các tínđồthời trang.

Cóthểnói,**Đá****quý**đã trởnên một vật phẩm phong thủy vô cùng phổbiến. Chúngđược sửdụng nhưmột thiên thần hộmệnh, giúp chủnhân gặp nhiều may mắn vàphòng tránh những taiương xảyđến. Một sốloạiđáquý hiện nay rấtđượcưa chuộng trên thịtrường như:*Đáthạch anh,đángọc bích,đácẩm thạch…*

[if !supportLists]-Thạch anh làmột loạiđáphổbiến trong thiên nhiên. Chúng cókhảnăng nhận, kích hoạt vàchuyển giao năng lượng. Nhờđónókích thích các chức năng của não, giúp ngườiđeo sẽminh mẫn hơn khi xửlý công việc.

[if !supportLists]-*Trang sức đá ngọc bích**như vòng đeo tay, mặt đeo cổ*luôn là biểu tượng của may mắn và sức khỏe.Từ xưa nhiều người tin rằng đeo**đá ngọc bích**sẽ đem lại may mắn, tránh được vận rủi. Hàng ngàn năm trước các vua chúa đã không ngừng say mê**ngọc**vì họ tin rằng**viên ngọc quý**giúp họ luôn cường tráng và gia tăng tuổi thọ.

[![mat-Am-Duong-da-ngoc-bich](/uploads/news/art-025-1-1-mat-am-duong-da-ngoc-bich-0.jpg)](https://web.archive.org/web/20141231012804/http://thegioidaquy.net/phong-thuy/mat-am-duong-da-ngoc-bich-3285.html#.VJhCYsgU)

*[Mặt dây chuyền Âm Dương đá ngọc bích](https://web.archive.org/web/20141231012804/http://thegioidaquy.net/phong-thuy/mat-am-duong-da-ngoc-bich-3285.html#.VJhCYsgU)thích hợp cho nam và nữ mạng Mộc,***Hoả đeo.**

[if !supportLists]-**Trong phong thủy**, Đá Cẩm Thạch được sử dụng trong nhiều thế kỷ qua bởi loại đá này có tác dụng làm hài hòa các khía cạnh trong cuộc sống,  xua đuổi tà ma, làm cho người đeo cảm thấy an tâm, hạnh phúc và tràn đầy năng lượng.

Ngoài việc sửdụngđáquýđểlàmđồtrang sức, bùa hộmệnh, người ta còn kết hợp chúng vớiđồnội thất theo quan niệm phong thủy.

Bạn cóbiết,**m****ột viênđáquýđượcđượcđúng chỗ**làđiều vô cùng quan trọng. Bởi chúng không chỉgóp phần mang lại vẻđẹp hoàn mỹcho ngôi nhàmàviệcđặtđúng vịtríhợp phong thủy còn cótác dụng nhưvật bảo vệmang lại sựêmấm hạnh phúc cho giađình. Cụthểnhưsau:

- Tại những vịtrínhưgóc nhàtối hay góc chết trên cầu thang lànhững nơi thường hay chứa khíhung tùđọng gây hại cho sức khỏe giađình.Đểhóa giải ta chỉcầnđặt vào nơiấy một***vi**ênđáthạ**ch anh***làhoàn toàn cóthểgiúp cải thiện tình hình một cáchđáng kể. Nhờđónăng lượng sẽđược khuấyđộng.

*[Qủa cầu đá thạch anh tím](https://web.archive.org/web/20141231012804/http://thegioidaquy.net/phong-thuy/qua-cau-da-thach-anh-tim-dam-85-3251.html#.VJhDesgU)có khả năng hóa giải, xua tan khí hư tồn đọng*

- Thạch anh hồngđược coi làlá bùa hộ mệnh cho các mối quan hệ. Nókhông chỉ giúp bạn giảm tress và giảm thiểu những cơn nóng giận bộc phát mà còn giúp bạn thoải mái và tự tin hơn.

- Các chuyên gia phong thủy cho rằng, nơi kinh doanh nếuđặt nhiều Thạch anh hồng trong tầm mắt cótác dụng giảm tính đa nghi của khách hàng, làm cho khách hàng ít so sánh và an tâm khi mua hàng.

*[Thegioidaquy.net](https://web.archive.org/web/20141231012804/http://thegioidaquy.net/phongthuy.html)*',
    '2014-12-23 09:00:00', 0, 405, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-023', 'chon-mau-sac-trang-suc-theo-phong-thuy', 'Chọn màu sắc trang sức theo phong thủy', 'Thế Giới Đá Quý',
    '/uploads/news/art-026-1-1-ty-huu-thach-anh-vang-nho-0-new.jpg', 'Việc chọn trang sức có màu sắc phù hợp với phong thủy là vô cùng quan trọng vì nó sẽ mang lại sức khỏe, tiền tài, may mắn cho người đeo. Bởi nếu chọn màu sắc trang sức không phù hợp với cung mệnh có thể sẽ đem lại những điều không may mắn cho chủ sỡ hữu.', 'Bạn cóbiết ý nghĩa của việc***ch****ọn màu sắc trang sức theo phong thủ****y***? Việc chọn trang sức cómàu sắc phùhợp với phong thủy làvô cùng quan trọng vìnósẽmang lại sức khỏe, tiền tài, may mắn cho ngườiđeo. Bởi nếu chọn màu sắc trang sức không phùhợp với cung mệnh cóthểsẽđem lại nhữngđiều không may mắn cho chủsỡhữu. Hãy cùng chúng tôi tham khảo cách chọn màu sắc trang sức theo phong thủy phùhợp cho từng cung mệnh theo bài viết dướiđây các bạn nhé!

[if !supportLists]**1.**[endif]**Ch****ọ****n m****à****u s****ắ****c trang s****ứ****c ph****ù****h****ợ****p cho ng****ườ****i M****ệ****nh Kim:**

[if !supportLists]-[endif]Đối với người Mệnh Kim,*n**ên sửdụng những loại trang sức cómàu củađấ**t*như: màu nâuđất, màu vàng thổđểcósức khỏe dồi dào. Bởi theo quy luật tương sinh: “Thổsinh Kim màđất lại bao bọc vànuôi dưỡng kim”.

[if !supportLists]-[endif]Ngoài ra người Mệnh Kim cóthểdùng màu sắc tương hợp khác như: màu trắng..đểchọn làm màu trang sức cho mình.

[if !supportLists]-[endif]Đểcóthểkhắc chếMộc, người thuộc cung mạng này nên lựa chọn các loại trang sức cómàu xanh lácây, xanh da trời.

[if !supportLists]-[endif]**Một sốloại trang sứcđáquý phùhợp với người mệnh Kim là**:[Đáthạch anh và](https://web.archive.org/web/20141231013323/http://thegioidaquy.net/phong-thuy/da-phongthuy-134-Thach-Anh-Vang-Citrine-/)[ng](https://web.archive.org/web/20141231013323/http://thegioidaquy.net/phong-thuy/da-phongthuy-134-Thach-Anh-Vang-Citrine-/), đá Sapphire trắng, đá thạch anh trắng...

[![ty-huu-thach-anh-vang-nho](/uploads/news/art-026-1-1-ty-huu-thach-anh-vang-nho-0-new.jpg)](https://web.archive.org/web/20141231013323/http://thegioidaquy.net/phong-thuy/ty-huu-thach-anh-vang-nho-2410.html#.VJGp69KsVlw)

*[Tỳ hưu thạch anh vàng](https://web.archive.org/web/20141231013323/http://thegioidaquy.net/phong-thuy/ty-huu-thach-anh-vang-nho-2410.html#.VJGp69KsVlw)phù hợp với người mệnh Kim*

[if !supportLists]-[endif]Tuyệtđối tránh dùng các loại trang sức cómàu thuộc hành Hỏa như:đỏ, hồng, tím cam.

[if !supportLists]**2.**[endif]**Ch****ọ****n m****à****u s****ắ****c trang s****ứ****c ph****ù****h****ợ****p cho ng****ườ****i M****ệ****nh M****ộ****c:**

[if !supportLists]-[endif]Người mệnh Mộc hợp nhất với*các loại trang sức cómàu sắc bắt nguồn từThủy*nhưmàuđen, xám, xanh nước biển vàmàu nâu (vìđây làmàu của gỗđại diện cho Mộc).Đeo trang sức cónhững màu sắc này sẽcótác dụng nuôi dưỡng nguồn năng lượng, mang lạI tài lộc, danh vọng cho ngườiđeo.

[if !supportLists]-[endif]Đểđạt sựtương hợp, người mệnh Mộc cóthểchọn những màu sắc nhưxanhđểlàm trang sức sẽtốt cho sức khỏe của họ.

[if !supportLists]-[endif]*Một sốloại trang sứcđáquý phùhợp với người mệnh Mộ**c*nhưđáPeridot,đáthạch anh khói, thạch anh xanh,đámã não…

[if !supportLists]-[endif]Không nênđeo các loại trang sức cómàu trắng, bạc, màu kem nhưđáthạch anh trắng, thạch anh pha lê, sapphire trắng…

[if !supportLists]**3.**[endif]**Ch****ọ****n m****à****u s****ắ****c trang s****ứ****c ph****ù****h****ợ****p cho ng****ườ****i M****ệ****nh Th****ủ****y:**

[if !supportLists]-[endif]Theo âm dương ngũhành, người mệnh Thủy**ph****ùhợp với những loại trang sức nhưbạc,đámàu trắng hoặc những màu sắc cóá****nh kim**vìtheo mối quan hệtương sinh “Kim sinh Thủy”.

[if !supportLists]-[endif]Đểđạtđược sựtương hợp, người thuộc cung mệnh này nên chọnđácómàu thuộc mệnh Thủy –đại diện của nước nhưcác màu xanh hoặcánh trắng phađen.

[if !supportLists]-[endif]Một sốloại trang sứcđáquý phùhợp với người mệnh Thủy như:ĐáSapphiređen, thạch anh trắng…

[![phat-ban-menh-Thien-Thu-Thien-Nhan-da-quy-thach-anh-trang](/uploads/news/art-026-2-1-phat-ban-menh-thien-thu-thien-nhan-da-quy-thach-anh-trang-0.jpg)](https://web.archive.org/web/20141231013323/http://thegioidaquy.net/phong-thuy/phat-ban-menh-thien-thu-thien-nhan-da-quy-thach-anh-trang-3015.html#.VJGqq9KsVlw)

*[Mặt dây chuyền phật bản mệnh Thiên Thủ Thiên Nhãn đá thạch anh trắng](https://web.archive.org/web/20141231013323/http://thegioidaquy.net/phong-thuy/phat-ban-menh-thien-thu-thien-nhan-da-quy-thach-anh-trang-3015.html#.VJGqq9KsVlw)giúp mọi việc được thuận lợi*

[if !supportLists]-[endif]Nên tránh dùng*c**ác loại trang sứ**c*cómàu vàng sậm, nâuđất vìđólànhững gam màu thuộc hành Thổsẽngăn chặn chếngựHành Thủy, gây bất lợiđối với ngườiđeo.

[if !supportLists]**4.**[endif]**Ch****ọ****n m****à****u s****ắ****c trang s****ứ****c ph****ù****h****ợ****p cho ng****ườ****i M****ệ****nh H****ỏ****a:**

[if !supportLists]-[endif]“Mộc sinh Hỏa”, Người thuộc mệnh Hỏa nên chọn những trang sức cómàu sắc tương sinh thuộc hành Mộc nhưxanh lácây, xanh da trời.

[if !supportLists]-[endif]Đểđạtđược sựtương hợp, người thuộc cung mệnh này cóthểchọn những tông màu thuộc hành Hỏa nhưtím,đỏ, cam, hồng nhằm mang lại nguồn năng lượng dồi dào, biểu tượng cho sức mạnh, lòngđam mêvàmay mắn.

[if !supportLists]-[endif]**Một sốloại trang sứcđáquý phùhợp với người mệnh Hỏa như**: trang sức cógắnđáRuby,đágarnet, thạch anh hồng…

[if !supportLists]-[endif]Tuyệtđối khôngđược sửdụng những loạiđácómàuđen, xám, xanh nước biểnđểlàm trang sức vìnhững màu sắc này tượng trương cho mạng Thủy sẽđem lại nhữngđiều không tốt cho những người thuộc cung mệnh Hỏa. Bởi Thủy sẽdập tắt Hỏa.

[if !supportLists]**5.**[endif]**Ch****ọ****n m****à****u s****ắ****c trang s****ứ****c ph****ù****h****ợ****p cho ng****ườ****i M****ệ****nh Th****ổ****:**

[if !supportLists]-[endif]Người mệnh Thổnên sửdụng các loại trang sức cómàu vàng nhạtđểtăng thêm sức mạnh tinh thần.

[if !supportLists]-[endif]Đểđạtđược sựtương hợp, người mệnh Thổnên sửdụng những màu sắc gắn liền vớiđất nhưmàu nâu nhằm tạo sựổnđịnh, mang lại cảm giác an toàn,được bảo vệcho ngườiđeo. Một sốmàu sắc khác gắn liền với Hỏa nhưmàuđỏ, hồng, cam, tím cũngđem lại may mắn, thịnh vượng vàsức khỏe cho ngườiđeo.

[if !supportLists]-[endif]Trang sức phùhợp với người mệnh Thổlà: trang sức cógắnđáthạch anh vàng, thạch anh tím,đágarnet,đáruby…

[if !supportLists]-[endif]Không nên dùng những trang sức cómàu xanh lácây, xanh da trời vìchúngđại diện cho hành Mộc.Đây làsựtương khắc bởi Mộc sẽhút hết sựmàu mỡvàlàm suy kiệtđất (Thổ) khiến người sửdụng nósuy yếu vềmặt sức khỏe vàgặp khókhăn trong tài chính.

[*Thegioidaquy.net*](https://web.archive.org/web/20141231013323/http://thegioidaquy.net/phongthuy.html)',
    '2014-12-18 09:00:00', 0, 448, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-024', 'y-nghia-qua-cau-phong-thuy', 'Ý nghĩa qủa cầu phong thủy', 'Thế Giới Đá Quý',
    '/uploads/news/art-027-1-1-qua-cau-thach-anh-trang-tinh-khiet-65-0.jpg', 'Qủa cầu phong thủy là vật phẩm phong thủy thường được dùng trong việc chiêu tài hóa sát nhằm đem lại vận may về sức khỏe, học tập, và công danh sự nghiệp cho chủ nhân.', '[Qủa cầu phong thủ](https://web.archive.org/web/20141231011842/http://thegioidaquy.net/phong-thuy/qua-cau-thach-anh-trang-tinh-khiet-65-3049.html#.VJGfO9KsVlw)[y](https://web.archive.org/web/20141231011842/http://thegioidaquy.net/phong-thuy/qua-cau-thach-anh-trang-tinh-khiet-65-3049.html#.VJGfO9KsVlw)làmột vật phẩm phong thủy cótác dụng chiêu tài hóa sát,đem lại vận may vềsức khỏe, học tập, vàcông danh sựnghiệp cho chủnhân.

Đặt quảcầu phong thủy trên bàn làm việc sẽmang lại sựthông tuệ, uyên bác, sáng suốt, mởmang mối quan hệngoại giao cho bạn. Cũng chính vìlẽđómàhầu hết các doanh nghiệp thànhđạt, những người giàu có, các luật sư, chính trịgia thườngđặt trên bàn làm việc của mình***m****ột quảcầu phong thủ****y***.

Ngoài ra nócòn cótác dụngđem lại sựtôn trọng, tựtin vàmay mắn cho chủsởhữu, chếngựhung khígiúp chủnhân tránhđược những luồng khíxấuđeo bám.

Đểphát huy tốiđa sức mạnh của vật phẩm này, chúng ta hãy cùng tìm hiểu vịtríđặt quảcầu vàcách chọn màu sắc quảcầu hợp với bản mệnh sao chođem lại nhiều may mắn nhất cho chủsởhữu các bạn nhé!

[if !supportLists]**1.**[endif]**Ch****ọ****n h****ướ****ng****đặ****t qu****ả****c****ầ****u phong th****ủ****y d****ự****a theo m****à****u s****ắ****c:**

[if !supportLists]-[endif]*Qủa cầu phong thủy cómàu lục, tím nhạ**t*nên bốtríởhướngĐông.

[if !supportLists]-[endif]Qủa cầu phong thủy cómàu trắng nên bốtríởhướng Tây.

[if !supportLists]-[endif]Qủa cầu phong thủy cómàuđỏnên bốtríởhướng Nam

[if !supportLists]-[endif]Qủa cầu phong thủy cómàuđen, lam, trànên bốtríởhướng Bắc

[if !supportLists]-[endif]Qủa cầu phong thủy cómàu vàng, da cam nên bốtríởphương vịtrung tâm

[if !supportLists]**2.**[endif]**M****ộ****t s****ố****l****ư****u ý khi b****à****i tr****í****qu****ả****c****ầ****u phong th****ủ****y:**

[if !supportLists]-[endif]**Đối với Qủa cầu phong thủy cóngũhành Thổ**cótác dụng thúcđẩy tài vận thườngđượcđặtởgiữa nhàđểtăng sinh khícho các thành viên trong giađình. Ngoài ra nếuđặt quảcầuởbàn học sẽgiúp cho trẻham học, nhớlâu.

[if !supportLists]-[endif]Không nênđặt quảcầu phong thủyởgóc phòng, nhàbếp hoặcđườngđi. Cần phải tìm phương vịcátđểđặt chúng. Bởi nếuđặt quảcầu phong thủyởnhững phương hung thìnăng lượng của nósẽthúcđẩy sát khí, gây bất lợi cho chủnhân.

[if !supportLists]**3.**[endif]**Ch****ọ****n m****à****u s****ắ****c c****ủ****a c****ầ****u phong th****ủ****y theo tu****ổ****i**

[if !supportLists]**a.**[endif]**Q****ủ****a c****ầ****u phong th****ủ****y m****à****u tr****ắ****ng:**

[if !supportLists]-[endif]Thích hợp với những người tuổi Tý, Thân, Dậu, Hợi

[if !supportLists]-[endif]Qủa cầu phong thủy màu trắngđược gọi là“Vua phong thủy”, cótác dụng tăng trínhớ, khai vận.

[![qua-cau-thach-anh-trang-tinh-khiet](/uploads/news/art-027-1-1-qua-cau-thach-anh-trang-tinh-khiet-65-0.jpg)](https://web.archive.org/web/20141231011842/http://thegioidaquy.net/phong-thuy/qua-cau-thach-anh-trang-tinh-khiet-65-3049.html#.VJGk_NKsVlx)

*[Quả cầu đá thạch anh trắng](https://web.archive.org/web/20141231011842/http://thegioidaquy.net/phong-thuy/qua-cau-thach-anh-trang-tinh-khiet-65-3049.html#.VJGk_NKsVlx)giúp trấn trạch, đem lại bình an và may mắn cho người mạng Kim, mạng Thuỷ.*

[if !supportLists]**b.**[endif]**Q****ủ****a c****ầ****u phong th****ủ****y m****à****u t****í****m:**

[if !supportLists]-[endif]Thích hợp với những người tuổi Sửu, Tý, Ngọ, Thìn, Mùi, Tuất

[if !supportLists]-[endif]*Quả cầu phong thủy màu tí**m*giúp tạo vận khí tốt, đem lại may mắn và giàu có. Thích hợp làm quà tặng trưng trên bàn làm việc, trưng trong văn phòng, quầy thu ngân tủ tiền hoặc góc tài lộc. Ngoài ra nócòn cótác dụng tăng cường trítuệ,ổnđịnh tâm lý cho chủsởhữu.

[![qua-cau-da-thach-anh-tim-dam](/uploads/news/art-027-2-1-qua-cau-da-thach-anh-tim-dam-85-0.jpg)](https://web.archive.org/web/20141231011842/http://thegioidaquy.net/phong-thuy/qua-cau-da-thach-anh-tim-dam-85-3251.html#.VJGmhNKsVlw)

*[Qủa cầu đá thạch anh tím đậm](https://web.archive.org/web/20141231011842/http://thegioidaquy.net/phong-thuy/qua-cau-da-thach-anh-tim-dam-85-3251.html#.VJGmhNKsVlw)thích hợp làm quà tặng trưng trên bàn làm việc*

[if !supportLists]**c.**[endif]**Q****ủ****a c****ầ****u phong th****ủ****y m****à****u v****à****ng:**

[if !supportLists]-[endif]Thích hợp với người tuổi Sửu, Thìn, Mùi, Tuất, Thân, Dậu

[if !supportLists]-[endif]***Quả cầu phong thuỷ màu và**ng***cótác dụng gia tăng tài lộc vàmay mắn trong kinh doanh.

[if !supportLists]**d.**[endif]**Q****ủ****a c****ầ****u phong th****ủ****y m****à****u****đ****en:**

[if !supportLists]-[endif]Thích hợp với tuổi Sửu, Thìn, Mùi, Tuất, Thân, Dậu

[if !supportLists]-[endif]Qủa cầu phong thủy màuđen cótác dụng làm tăng dũng khí, khả năng tiên tri, niềm tin vàuy danh cho chủnhân.

[![qua-cau-thach-anh-den](/uploads/news/art-027-3-1-qua-cau-thach-anh-den-125-0.jpg)](https://web.archive.org/web/20141231011842/http://thegioidaquy.net/phong-thuy/qua-cau-thach-anh-den-125-2586.html#.VJGnMtKsVlx)

*[Quả cầu thạch anh đen phong thuỷ](https://web.archive.org/web/20141231011842/http://thegioidaquy.net/phong-thuy/qua-cau-thach-anh-den-125-2586.html#.VJGnMtKsVlx)giúp tăng khả năng tiên tri.*

[if !supportLists]**e.**[endif]**Q****ủ****a c****ầ****u phong th****ủ****y m****à****u h****ồ****ng:**

[if !supportLists]-[endif]Thích hợp với tuổi Sửu, Thìn, Mùi, Tuất, Tỵ, Ngọ

[if !supportLists]-[endif]Qủa cầu phong thủy màu hồng cótác dụng làm tăng vận may vềđường tình duyên vàsựnghiệp cho chủnhân.

[*Thegioidaquy.net*](https://web.archive.org/web/20141231011842/http://thegioidaquy.net/phongthuy.html)',
    '2014-12-17 09:00:00', 0, 491, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-025', 'tim-hieu-ve-da-aquamarine', 'Tìm hiểu về đá Aquamarine', 'Thế Giới Đá Quý',
    '/uploads/site_assets/Phongthuy-HoaMocLan-thegioidaquy.jpg', 'Đá quý Aquamarine còn có tên gọi là Ngọc xanh biển. Bởi theo tiếng La Tinh có nghĩa là màu xanh nước biển. Loại đá này thuộc họ đá quý Beryl. Chúng rực rõ bởi sắc màu xanh biển tuyệt đẹp dao động từ màu xanh biển nhạt đến màu xanh biển đậm.', '[if !supportLists]**1.[endif]Khái quát chung vềĐá****Aquamarine**

-[Đá](https://web.archive.org/web/20141231013359/http://thegioidaquy.net/phong-thuy/mat-da-aquamarine-co-giam-dinh-da-quy-sjc-3288.html#.VJBdf9KsVlw)[quý Aquamarine](https://web.archive.org/web/20141231013359/http://thegioidaquy.net/phong-thuy/mat-da-aquamarine-co-giam-dinh-da-quy-sjc-3288.html#.VJBdf9KsVlw)làloạiđácóđộcứng cao từ7.5 – 8 trên thang Mohs vàcósựlấp lánh giống nhưthủy tinh. Chúng rực rõ bởi sắc màu xanh biển tuyệtđẹp daođộng từmàu xanh biển nhạtđến màu xanh biểnđậm. Cái tên**“Aquamarine”**được bắt nguồn từcách biểuđạt cũtrong tiếng Latin cónghĩa là“Nước biển”.

- Loạiđánày thuộc họđáquý Beryl. Một sốloạiđáquý khác cócùng họBeryl vớiAquamarinenhưsau: Morganite, Goshenite, Golden Beryl, Green Beryl vàBixbite.*Đáquý Aquamarineđược cho làhấp dẫn vàcógiátrịnhấ**t*khi nómang trong mình màu xanh nước biển cósắcđộđậm vàbão hòa.

- Hầu hết những nhàcung cấp hàngđầuĐáAquamarineđềuđến từBrazil, với nhiều mỏphân bốkhắpđất nước. Ngoài ra***đá****quý Aquamarine***cũngđược tìm thấyởÚc, Myanmar, Trung Quốc,ẤnĐộ, Madagascar, Mozambique…ỞViệt Nam,ĐáAquamarineđược tìm thấyởvùng Yên Bái, Tây NghệAn vàmột sốnơi khác.

[if !supportLists]**2.[endif]Đặcđiểm nhận biếtĐá****Aquamarine**

- Một sốđặcđiểm cóthểgiúp ta dễdàng nhận biết loạiđánày nhưsau: Màu sắc xanh nước biểnđộcđáo cùng vớiđộcứng tươngđối cao vàcósựlấp lánh của pha lê. Đá Aquamarine có độ trong suốt và độ tinh khiết tuyệt vời so với nhiều loại đá quý khác.

- Cường độ của màu sắc (Sắc độ) và độ trong suốt của đá là những tiêu chí quan trọng*khi đánh giá giá trị của viên đá aquamarine*.

*[Mặt đá Aquamarine](https://web.archive.org/web/20141231013359/http://thegioidaquy.net/phong-thuy/mat-da-aquamarine-co-giam-dinh-da-quy-sjc-3288.html#.VJBeHtKsVlw)đem lại nhiều may mắn và thịnh vượng cho gia chủ.*

[if !supportLists]**3.[endif]Tác dụng củaĐá****Aquamarine**

- Theo truyền thuyết của người châu Âu,***Aquamarine có nguồn gốc từ kho báu của các nàng tiên cá***và từ thời cổ đại, chúng được coi là đá may mắn của các thủy thủ.

*[Vòng tay Đá Aquamarine](https://web.archive.org/web/20141231013359/http://thegioidaquy.net/phong-thuy/vong-tay-da-aquamarine-10-ly-3290.html#.VJBe9dKsVlw)phù hợp cho người sinh trong tháng 3 dương lịch hoặc người mạng Thuỷ, Mộc.*

- Người Hy Lạp và La Mã cũng đã biếtAquamarine là đá quý của thủy thủ. Truyền thuyết kể rằng Aquamarines là những tài sản quý giá của nhiều nàng tiên cá và do đó sẽ bảo vệ các thủy thủ từ những sự nguy hiểm của biển cả, trong đó có thể tránh được những bệnh tật trên biển.

- Ở thời Cổ đại cũng như Trung cổ, con người tin rằng vũ trụ được phản ánh trong các loại đá. Do đó không có gì ngạc nhiên khi Aquamarine được gán cho hành tinh Neptune (sao Hải Vương).

-**Aquamarine**sẽ làm cho con người có cái nhìn trong sáng, tốt đẹp hơn cuộc sống. Aquamarine còn giúp chữa được chứng mất ngủ, nấc cục và hắt hơi.

- Aquamarine đem lại nhiều may mắn, làm tăngvẻ đẹp của người sở hữu và thịnh vượng cho gia chủ.

- A*quamarine cũng là một trong những birthstones*chính thức của tháng 3. Phong trào bí truyền làm sống lại niềm tin cổ xưa và các ngành công nghiệp đá quý đã làm cho nó một công cụ tiếp thị để thúc đẩy đá quý nhất định.

[*Thegioidaquy.net*](https://web.archive.org/web/20141231013359/http://thegioidaquy.net/phongthuy.html)',
    '2014-12-17 09:00:00', 0, 534, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-026', 'da-pyrit', 'Đá Pyrit', 'Thế Giới Đá Quý',
    '/uploads/site_assets/Phongthuy-HoaMocLan-thegioidaquy.jpg', 'Đá quý Pyrit còn có tên gọi khác là Đá vàng găm. Loại đá này có công thức hóa học là FeS2 với độ cứng theo thang Mohs dao động trong khoảng từ 6.0-6.5.', '-[Đá](https://web.archive.org/web/20260411175907/http://thegioidaquy.net/phong-thuy/da-phongthuy-301-Da-Pyrit-Vang-Gam)[Pyri](https://web.archive.org/web/20260411175907/http://thegioidaquy.net/phong-thuy/da-phongthuy-301-Da-Pyrit-Vang-Gam)t cótên gọiđược xuất phát từtiếng Hy Lạp “Pyros” – với ý nghĩa là“Ngọn lửa” vìloạiđánày khiđập vào nómột vật bằng kim loại sẽcókhảnăng phát ra tia lửa.

-*Đá**quý Pyrit*còn cótên gọi khác làĐávàng găm. Loạiđánày cócông thức hóa học làFeS2vớiđộcứng theo thang Mohs daođộng trong khoảng từ6.0-6.5. Cóthểnói loạiđánày tươngđối cứng vàđây làmột loại Sunfua duy nhất cóthểvạch lên bềmặt thủy tinh.

- Làmột hệtinh thểcânđối, chúng cókhối lượng riêng trung bình 5.0 – 6.5g/cm3.

- ĐáPyrit cóthểđược tìm thấyởnhiều nơi như:Đức, Tây Ban Nha, ThụyĐiển, Hoa Kỳ,…

- Màu sắcđặc trưng của loạiđánày chính làmàu vàng gămđồng thau sang trọng hơi giống với màu vàng kim loại.Đáquý Pyrit cótừmàu vàng bạcđến màu vàng kim. Một sốngười**c****óthểbịnhầm lẫn giữa Pyrit với vàng thậ****t**. Chính vìvậy, tại các nước Phương Tây,ĐáPyrit cònđược gọi là“Fools Gold”. Tuy nhiên, chúng ta cũng không quákhókhănđểphân biệt giữaĐáPyrit với vàng thật bởi trong tựnhiên,ĐáPyrit nhẹhơn vàng rất nhiều, nhưng chúng lại cóđộcứng hơn so với vàng thật vàkhông dễbịtrầy xước bởi móng tay hoặc dao bỏtúi. Ngoài ra chúng cókhối lượng riêng nhỏhơn so với vàng thật.

- Pyrit thườngđược sửdụng chủyếuđểchếtạo thành các vật phẩm hoặc trang sức phong thủy như: Mặt dây chuyềnđáPyrit,Đávàng găm Pyrit phong thủy…

*Mặt dây chuyền[Ông Thọ Dâng Đào đá Pyrit](https://web.archive.org/web/20260411175907/http://thegioidaquy.net/phong-thuy/ong-tho-dang-dao-da-Pyrit-3097.html#.VIrqm9KsVlw)*

- Pyritđãđược các nhàam hiểu học vềtính thần bícủađáthời nay cho rằng loạiđánày làbiểu tượng của Mặt trờiấmáp, giúp cho con người ta cónhững hồiức dễchịu.

*[Đá Pyrit (vàng găm)](https://web.archive.org/web/20260411175907/http://thegioidaquy.net/phong-thuy/da-vang-gam-920-3323.html#.VIrrndKsVlw)giúp cho con người ta cónhững hồiức dễchịu*

- Loại khoáng vật này cótác dụng bảo vệtâm lý của con người, giúp con người thoát khỏi những suy nghĩtiêu cực, làm cho con người ta hướngđến những hànhđộng chân thật.

-Các nhàgiảkiem thuật thời trung cổxưa cho rằngđáPyrit làmột loại khoáng vật rất quan trọng màvềnguyên tắc chúng cóthểbiến thành vàng.

- Ngoài những ý nghĩa vềmặt tâm linh,đáPyrit còn cómột sốtác dụng nhấtđịnh trong việcđiều trịbệnh nhưsau:

+**D****ựa trên cơsởloạiđáPyrit cókhảnăngđánh ra lử****a**, các thầy thuốc thời cổđạiđã dùngđáPyrit nhưlàmột loại khoáng vật màtrongđóẩn giấu “Linh hồn của ngọn lửa”.

+ Các nhàtrịliệu học hiệnđại thời nay tin rằngđáPyrit cóthểđiều chỉnh tất cảcác quátrình cảvềthểchất lẫn tinh thần trong cơthểcon người.

[*Thegioidaquy.net*](https://web.archive.org/web/20260411175907/http://thegioidaquy.net/phongthuy.html)',
    '2014-12-12 09:00:00', 0, 577, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-027', 'da-ngoc-lam-turquoise', 'Đá Ngọc Lam (Turquoise)', 'Thế Giới Đá Quý',
    '/uploads/news/art-031-1-1-vong-tay-da-turquoise-12ly-0.jpg', 'Đá quý Ngọc Lam hay còn gọi là đá Turquoise. Trong thiên nhiên loại đá này có màu xanh lam gồm một dải màu có thể trải dài từ xanh lá sang xanh da trời.', '**[*Đá**quý Ng**ọ**c Lam*](https://web.archive.org/web/20150101185805/http://thegioidaquy.net/phong-thuy/da-phongthuy-234-Da-Ngoc-Lam-Turquoise-)**làmột khoáng chất phốt phát ngậm nước của nhôm vàđồng vớiđộng cứng 6, mềm hơn thạch anh. Loạiđánày cómàu xanh lam với dải màu của nócóthểtrải dài từxanh lục sang xanh da trời.**M****à****u xanh lam c****ủ****a lo****ạ****i****đá****n****à****y**được tạo ra bởiđồng, màu lục bởi sắt vàmộtít của crom hóa trịhai. Ngoài ra loạiđánày cũng thường cónhững dải màuđen, nâu hoặc vàng chạy ngang qua tinh thểnày.

Loạiđánày thường cóđa sốởnhững khu mỏnổi tiếng như: Mỹ, Mexico, Israel, Iran, Afghanistan vàTrung Quốc vàBắc Iran.

***Đá******quý Turquoise***tỏa sáng với màu xanh bầu trời làmột trong những màuđượcưa chuộng nhấtđểchếtạo trang sức phong thủy cho ngườiđeo.

Đáquý Ngọc Lamtươngđối mềm. Nếu không biết cách bảo quản thìmàu sắcđácóthểchuyển sang tái nhợt khiđáđược mang trong một thời gian dài. Dođóđểgiữchođákhông bịđổi màu khiđeo cần phải bảo vệđátránh sựtiếp xúc với những loại mỹphẩm, nhiệt vàánh sáng mạnh. Tốt nhất nên lau chùiđáthường xuyên bằng loại vải mềm.

[![vong-tay-da-Turquoise-12ly](/uploads/news/art-031-1-1-vong-tay-da-turquoise-12ly-0.jpg)](https://web.archive.org/web/20150101185805/http://thegioidaquy.net/phong-thuy/vong-tay-da-san-ho-12-ly-943.html#.VH8MLtKsVlw)

*[Vòng tay đá ngọc lam (Turquoise)](https://web.archive.org/web/20150101185805/http://thegioidaquy.net/phong-thuy/vong-tay-da-san-ho-12-ly-943.html#.VH8MLtKsVlw)mang lại bình an may mắn cho người đeo*

[if !supportLists]**1.**[endif]**Ý ngh****ĩ****a phong th****ủ****y:**

- Người Ba Tưcho rằng:” Bàn tay màmang*m**ộ**t vi**ê**n**đá**quý Ng**ọ**c lam*thìchưa bao giờnhìn thấy nghèo nàn”.ỞMexico người ta thường trang trínhững mặt nạnghi thức với loạiđánày theo lòng tin của họvới thần thánh.

- Ngày nay những người dađỏởBắc Mỹvẫn còn sản xuất nhiềuđồnữtrang bạc truyền thống với đá ngọc lam. Vìhọtin rằng loàiđácósắc xanh này mởra sựkết nối trực tiếp giữa bầu trời vàbiển.

-Đángọc lamgiúp ngườiđeo chống lại những sức mạnh của bóng tối. Ngoài ra màu sắc của loạiđánày làm chúng ta cảm thấy hạnh phúc vàvui vẻvìnólàsựkết hợp giữa màu xanh nhẹcủa bầu trời vàbiển.

[![day-chuyen-da-turquoise](/uploads/news/art-031-2-1-day-chuyen-da-san-ho-0.jpg)](https://web.archive.org/web/20150101185805/http://thegioidaquy.net/phong-thuy/day-chuyen-da-san-ho-1725.html#.VH8NANKsVlw)

*[Dây chuyền đá Turquoise](https://web.archive.org/web/20150101185805/http://thegioidaquy.net/phong-thuy/day-chuyen-da-san-ho-1725.html#.VH8NANKsVlw)phù hợp cho người mạng Thuỷ mạng Mộc*

[if !supportLists]**2.**[endif]**Đặ****c t****í****nh ch****ữ****a b****ệ****nh:**

- Đángọc lam cósựtương thíchđặc biết với chakra cổhọng, tim vàtrán. Nócótác dụng rất tốt trong việc làm sạch cho cổhọng cũng nhưchữa những bệnh vềđau họng vàlàm sạch phổi. Nónâng cao khảnăng giao tiếp bằng tiếng vàbằng chữ, giúp ta nói ra cảm xúc thật của mình.

- Đángọc lamđượcđeođểbảo vệcon người khỏi những năng lượng xấu. Người ta cho rằng nóđổi màu khi chủnhân sắp cónguy hiểm vàbệnh tật. Nógiúp ngườiđeo tỉnh tảo khi làm những hànhđộng tâm linh.**Đá****ng****ọ****c lam**cótác dụng chữa bệnh rất tốt cảvềtinh thần lẫn thểchấtđồng thời củng cốsức mạnh cho cơthể.

- Làtinh thểcủa sựcân bằng,*đá**ng**ọ**c lam r**ấ**t tuy**ệ**t v**ờ**i trong vi**ệ**c gi**ữ**b**ì**nh t**ĩ**nh v**à**l**à**m di**ệ**u h**ệ**th**ầ**n kinh*. Nócóthểlàm giảm bớt lo lắng vàchữa bệnh suy nhược thầnkinh.

- Ngoài rađángọc làm còn cótác dụng làm giảm các bệnhđau cơvàxương khớp, bệnh da liễu, tiêu hóa, cao huyếtáp, bệnh suyễn, sốt vàđau mắt.

[*Thegioidaquy.net*](https://web.archive.org/web/20150101185805/http://thegioidaquy.net/phongthuy.html)',
    '2014-12-03 09:00:00', 0, 663, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-028', 'da-tourmaline', 'Đá Tourmaline', 'Thế Giới Đá Quý',
    '/uploads/news/art-032-1-1-vong-tay-da-tourmaline-9-ly-0.jpg', 'Đá Tourmaline có tên gọi bắt nguồn từ tiếng Sinhalese “Tura mali” có nghĩa là đá màu hỗn hợp. Đúng như tên gọi của nó, Đá Tourmaline là loại đá có rất nhiều màu sắc khác nhau.', '**[ĐáTourmaline](https://web.archive.org/web/20141218142116/http://thegioidaquy.net/phong-thuy/da-phongthuy-247-Da-Tourmaline)**làmột khoáng chất boron tinh thểsilicat phức tạp với các nguyên tốnhưNhôm, Sắt, Magiê, Natri, Lithium, Kali. Nhiều người cho rằng,đáTourmaline làmột khoáng chất duy nhất. Nhưng trên thực tế, loạiđánày gồm rất nhiều loại cótên gọi khác nhau bởi chúngđượcđặt tên dựa theo màu sắc. CóthểnóiĐáTourmaline làmột loạiđáquý vô cùng giátrị.

Theo truyền thuyết Ai Cập cũ,***Tourmaline tr****ên cuộc hành trình dài từtrung tâm của tráiđấtđi qua cầu vồ****ng***nóđã ghi nhận tất cảcác màu sắc của cầu vồng. Vìthếloạiđánày còn cótên gọi khác là“Đáquý của cầu vồng”.

Các nhàkhoa học rất quan tâmđến**đá****Tourmaline**do chúng cóthểthuđược mộtđiện tích phân cực khi bịnung nhiệt hay bịép.

ĐáTourmaline làloạiđáđược dùngđểmừng sinh nhật tháng 10ởMỹ.

ĐáTourmalineđược tìm thấyởnhiều nơi trên thếgiới như: Brazil, Sri Lanka, Phía Nam vàTây Nam Châu Phi, Zimbabwe, Tanzania, Mozambique, Mỹ..

[![vong-tay-da-tourmaline-9-ly](/uploads/news/art-032-1-1-vong-tay-da-tourmaline-9-ly-0.jpg)](https://web.archive.org/web/20141218142116/http://thegioidaquy.net/phong-thuy/vong-tay-da-tourmaline-9-ly-3238.html#.VHdS49KsVlw)

*[Vòng tay đá tourmaline phong thuỷ](https://web.archive.org/web/20141218142116/http://thegioidaquy.net/phong-thuy/vong-tay-da-tourmaline-9-ly-3238.html#.VHdS49KsVlw)phù hợp với tất cả các mạng*

ĐáTourmailine córất nhiều màu sắc khác nhau. Cụthểnhưsau:

[if !supportLists]**1.[endif]ĐáTourmalineđỏ**

-*Đá**Tourmaline*đỏcònđược gọi làRubellite. Nócómàuđỏđậm giống vớiĐáRuby.Đấy làloạiđáđược cho làcógiátrịnhất trong dòngđáTourmaline.

[if !supportLists]**2.ĐáTourmaline xanh lá****cây**

- ĐáTourmaline xanh lácây còn cótên gọi làChrome bởi nóchứa nhiều nguyên tốvi lượng crôm.  Loạiđánày rất hiếm. Chúngđược tìm thấyởĐông Phi vàthường chỉcóởkích cỡnhỏ.

- ĐáTourmaline xanh lácây cótác dụng mang lại niềm vui trong cuộc sống, khuyến khích lòng kiên nhẫn vàsựcởi mở. Ngoài ra nócòn thu hút tiền bạc vàmangđến sựthành công trong kinh doanh.

[if !supportLists]**3.ĐáTourmalineđ****en**

- ĐáTourmalineđen còn cótên gọi khác làSchorl.**Đây làloại Tourmaline kháphổbiến vàđược tìm thấy nhiều nhất.**

- ĐáTourmalineđen tạo ra năng lượng giúp bạn luôn suy nghĩtích cực trong mọi hoàn cảnh, mang lại may mắn, hạnh phúc cho chủnhân.

[if !supportLists]**4.ĐáTourmaline hồ****ng**

-*Đá**Tourmaline hồng*cũng làloạiđáphổbiến, dễđược tìm thấy.ĐáTourmaline hồng kết hợp với năng lượng nữtính tạo ra sựrungđộng cộng hưởng sâu sắcđểchữa lành các vết thương tình cảm. Mang viênđánày bên mình sẽmang lại cảm giác thoải mái, an toàn.

*[Dây chuỗi đá tourmaline phong thuỷ](https://web.archive.org/web/20141218142116/http://thegioidaquy.net/phong-thuy/day-chuoi-da-tourmaline-dai-3242.html#.VHdR4dKsVlw)đem lại may mắn, hổ trợ tốt cho sức khoẻ người đeo*

[if !supportLists]**5.Những màu sắc khá****c**

- Ngoài ra**đá****Tourmaline**còn cócác màu sắc khác như: hồng, nâu, vàng, cam, xanh da trời, tím, không màu…

- Một sốđáTourmaline cóhỗn hợp gồm hai hay nhiều màu sắc. Quan sát chũng ta sẽthấy nhiều màu sắc trên viênđátùy thuộc vào sựthayđổi củaánh sáng vàgóc nhìn.Điều nàyđược gây ra bởi sựthayđổi của các thành phần nguyên tốtrong viênđá.

- ĐáTourmaline hỗn hợp ba màu (Watermelon Tourmaline) tạo ra năng lượng thu hút tình yêu vàgiúp cân bằng nguồn năng lượng trong cơthể, mang lại sựbình yên trong tâm trí

[*Thegioidaquy.net*](https://web.archive.org/web/20141218142116/http://thegioidaquy.net/phongthuy.html)',
    '2014-11-28 09:00:00', 0, 706, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-029', 'thach-anh-am-khoi', 'Thạch anh ám khói', 'Thế Giới Đá Quý',
    '/uploads/site_assets/Phongthuy-HoaMocLan-thegioidaquy.jpg', 'Thạch anh ám khói là các biến thể nâu đến đen của thạch anh. Thạch anh ám khói được cho là viên đá của sự bảo vệ, giúp chủ nhân cân bằng tốt năng lượng tinh thần và thể chất.', '-[Thạch anhám khói](https://web.archive.org/web/20141212050820/http://thegioidaquy.net/phong-thuy/da-phongthuy-136-Thach-Anh-Khoi-Smoky-quartz-/)cònđược gọi là“Thanh trượt thạch” làvìthành phần carbon chứa trong thạch. Từngàn xưa,**thạch anhám khóiđãđược dùng nhưlàmột hộthạch**bởi chúng cókhảnăng báo hiệu cho ngườiđeo khi thạch chuyển sang màu xậm hơn. Dođó, chúng thường dùngđểđeo trên tay hay trước ngực, rất thích hợp cho những người làm rừng,đi biển hay làm việc tại những khu vực hầm mỏcónhiều chất bức xạ.

- Thạch anhám khóiđược cho làviênđácủa sựbảo vệ. Trong dòng họ*thạch anhám khó**i*thường cócác loại nhưsau: thạch anhám khói tóc trắng, thạch anhám khói trongđậm, thạch anh vàng hoặc vàng khói, thạch anhđen.

- Thạch anh vàng thường rất hiếm. Nócòn hiếm hơn cảthạch anh tím. Thạch anh vàng cònđược gọi làviênđákinh doanh. Nóthườngđược các chủkinh doanh nhưnhàhàng, siêu thị, khách sạnđặt ngay tại quầy thu ngân nhằm thu hút vận may, tài lộc, giúp chủnhân buôn may bánđắt.

-**Th****ạch anhám khó****i**ởtrong mộtđiều kiện môi trườngđặc biệt sẽchuyển thành thạch anhđen. Thạch anhđen làloại thạch anh cókhối lượng riêng rất nặng vàđộcứng cao nhất trong tất cảcác loại thạch anh. Năng lượng của thạch anhđen thích hợp với người mạng Thủy, Mộc, Kim. Nócótác dụng giúp cho chủsởhữu cóthểtiếp xúc với quyền năng huyền bícủa vũtrụ. Thạch anhđen tựnhiên cực kỳquý hiếm. Tuy nhiên, nếu thạch anhđenđược tạo nên dođốt xửlý sẽmang trong mình năng lượng âm,ảnh hưởng không tốt cho người sửdụng.

*[Mặt phật bản mệnh Đại Thế Chí đá thạch anh ám khói đậm gần thành đen](https://web.archive.org/web/20141212050820/http://thegioidaquy.net/phong-thuy/phat-ban-menh-dai-the-chi-da-thach-anh-den-3206.html#.VHdIPtKsVlw)mang may mắn và tài lộc cho người đeo*

- Trong nghệthuật phong thủy hay kiến trúc nội ngoại thất, thạch anh khói rấtđược yêu chuộng vàrất quý vìnólàmột “Hộthạch” cóthểbảo vệnhàcửa, người vàsinh vật xung quanh khỏi những tia bức xạđộc hại nhưtầng sóng từcao thế, sóng radio, sóngđiện thoại, TV…

- Ngoài ra việcđặt hoặcđểthạch anhám khói trước cửa nhàhay phòng làm việc cóthểgiúp giải trừnhữngđiều xấu từcác tia bức xạgây nên.

*[Qủa cầu thạch anh ám khói trong lớ](https://web.archive.org/web/20141212050820/http://thegioidaquy.net/phong-thuy/qua-cau-thach-anh-khoi-trong-lon-2403.html#.VHdJhNKsVlw)n phù hợp cho người mạng Thủy và Mộc*

-**Th****ạch anhám khó****i**cókhảnăng làm mạnh các mô, tếbào liên kết cũng nhưgân cốt, làm mạnh các gân khớp vàkích thích khảnăng thụtinh qua việcđiều tiết hormoneởtuyến thượng thận.

- Những cặp vợchồng hiếm muộn, muốn tăng khảnăng thụtinh thìnên uống nước ngâm của thạch anhám khói một thời gian.

- Vềcảm xúc,*th**ạch anhám khói cóthểgiúp mang lại sựbình an khi tâm trạng bịkích thí**ch*, xúcđộng căng thẳng quáđộ.Đeo thạch anhám khói trong người giúp giải trừnhững trượt khído tưtưởng gây nên.

[*Thegioidaquy.net*](https://web.archive.org/web/20141212050820/http://thegioidaquy.net/phongthuy.html)',
    '2014-11-27 09:00:00', 0, 749, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-030', 'tac-dung-cua-thach-anh-toc', 'Tác dụng của Thạch anh tóc', 'Thế Giới Đá Quý',
    '/uploads/news/art-034-1-1-mat-nhan-ty-huu-thach-anh-toc-vang-18-2.jpg', 'Thạch anh tóc là một biến thể của thạch anh trắng, thường được gọi là Rutilated Quartz. Các loại thạch anh tóc thường gặp như: Thạch anh tóc đỏ, thạch anh tóc xanh, thạch anh tóc vàng và thạch anh tóc đen.', 'Thạch anh tóc làloại thạch anh cóchứa các bao thểdạng kim, que với những màu sắc khác nhau. Với những bao thểhình que, kim nên trông từbên ngoài chúng giống nhưnhững sợi tóc nên người ta gọi nólàthạch anh tóc.

Trong số các loại thạch anh thì thạch anh tóc có trường năng lượng mạnh nhất. Các loại thạch anh tóc thường gặp như:[***Th***](https://web.archive.org/web/20141214133139/http://thegioidaquy.net/phong-thuy/da-phongthuy-140-Thach-Anh-Toc-Do-Red-rutile-quartz-/)***[ạch anh tócđỏ](https://web.archive.org/web/20141214133139/http://thegioidaquy.net/phong-thuy/da-phongthuy-140-Thach-Anh-Toc-Do-Red-rutile-quartz-/),[thạch anh tóc xanh](https://web.archive.org/web/20141214133139/http://thegioidaquy.net/phong-thuy/da-phongthuy-142-Thach-Anh-Toc-Xanh-Green-rutile-quartz-/),[th](https://web.archive.org/web/20141214133139/http://thegioidaquy.net/phong-thuy/da-phongthuy-138-Thach-Anh-Toc-Vang-Rutile-quartz-/)[ạch anh tóc và](https://web.archive.org/web/20141214133139/http://thegioidaquy.net/phong-thuy/da-phongthuy-138-Thach-Anh-Toc-Vang-Rutile-quartz-/)[ng](https://web.archive.org/web/20141214133139/http://thegioidaquy.net/phong-thuy/da-phongthuy-138-Thach-Anh-Toc-Vang-Rutile-quartz-/)và[thạch anh tócđ](https://web.archive.org/web/20141214133139/http://thegioidaquy.net/phong-thuy/da-phongthuy-141-Thach-Anh-Toc-Den-Black-rutile-quartz-/)****[en](https://web.archive.org/web/20141214133139/http://thegioidaquy.net/phong-thuy/da-phongthuy-141-Thach-Anh-Toc-Den-Black-rutile-quartz-/)**.*

[if !supportLists]**1.**[endif]**Tác****dụng của đá thạch anh tóc về mặt phong thủy:**

Loài ngườiđã biết tớiđáphong thủy thạch anh tóc từnhiều năm trướcđây vềtính chất màu nhiệm của nó.

***Đáphong thủy thạch anh tó**c***giúp chủnhân xuađuổi mọi nỗiưu phiền rầu rĩvàsựcôđơn. Nócótác dụng truyền cho chủnhân khảnăng thiên nhãn vàtiênđoán tương lai.

[if !supportLists]**a.**[endif]**Th****ạ****ch anh t****ó****c v****à****ng:**

-**C****ầmđáphong thủy thạch anh tóc và****ng**cótác dụng giúp ngườiđeo kiênđịnh, giữvững lập trường của mình trước những lời cầu khẩn, van xin của người khác hay làm những việc bất lợi cho bản thân.

- Đeo bên mìnhđáphong thủy*th**ạch anh tóc và**ng*giúp ngườiđeo sáng suốt, nhận thứcđược sựthật vấnđềđểkhông bịdụdỗ, lừa gạt bởi người khác.

[![mat-nhan-Ty-huu-thach-anh-toc-vang-18-2](/uploads/news/art-034-1-1-mat-nhan-ty-huu-thach-anh-toc-vang-18-2.jpg)](https://web.archive.org/web/20141214133139/http://thegioidaquy.net/phong-thuy/Mat-nhan-ty-huu-thach-anh-toc-vang-18-2974.html#.VHStPNKsVlw)

*[Mặt tỳ hưu phong thuỷ đá thạch anh tóc vàng](https://web.archive.org/web/20141214133139/http://thegioidaquy.net/phong-thuy/Mat-nhan-ty-huu-thach-anh-toc-vang-18-2974.html#.VHStPNKsVlw)phù hợp cho người mạng Thổ và mạng Kim*

[if !supportLists]**b.**[endif]**Th****ạ****ch anh t****ó****c xanh:**

-**Th****ạch anh tó****c xanh**được coi làviênđácủa may mắn, tài lộc,đem lại những cơhội tốt cho ngườiđeo trong công danh, sựnghiệp vàkinh doanh.

- Vào mỗi buổi sáng,*dùng thạch anh tóc xanh để vào vùng tim*, hít sâu từ 3 đến 5 lần giúp chúng ta tiếp thêm nguồn sinh khí, năng lượng làm tăng chí tiến thủ, tăng sức mạnh ý chí để đương đầu với những khó khăn thách thức, thay đổi cục diện.

[![vong-tay-thach-anh-toc-xanh-dam-9-ly](/uploads/news/art-034-2-1-vong-tay-thach-anh-toc-xanh-dam-9-ly-0.jpg)](https://web.archive.org/web/20141214133139/http://thegioidaquy.net/phong-thuy/vong-tay-thach-anh-toc-xanh-dam-9-ly-3042.html#.VHSuX9KsVlw)

*[Vòng tay thạch anh tóc xanh](https://web.archive.org/web/20141214133139/http://thegioidaquy.net/phong-thuy/vong-tay-thach-anh-toc-xanh-dam-9-ly-3042.html#.VHSuX9KsVlw)đem lại tài lộc may mắn, phù hợp cho người mạng Mộc mạng Hoả.*

[if !supportLists]**c.**[endif]**Th****ạ****ch anh t****ó****c****đỏ****:**

- T**h****ạch anh tócđó**cótác dụng tăng cường sức sống, sựhấp dẫn vàthân thiện cho ngườiđeo. Các bạn gái cóhiện tượng lãnh cảm, khôngđược người khác giới yêu quý nênđeo thạch anh tócđỏđểtăng cường sựhấp dẫn cho mình.

[![lac-tay-da-thach-anh-toc-do-dam-11-ly](/uploads/news/art-034-3-1-lac-tay-da-thach-anh-toc-do-dam-11-ly-0.jpg)](https://web.archive.org/web/20141214133139/http://thegioidaquy.net/phong-thuy/lac-tay-da-thach-anh-toc-do-dam-11-ly-3078.html#.VHSvKtKsVlw)

*[Lắc đeo tay đá thạch anh tóc đỏ](https://web.archive.org/web/20141214133139/http://thegioidaquy.net/phong-thuy/lac-tay-da-thach-anh-toc-do-dam-11-ly-3078.html#.VHSvKtKsVlw)tăng cường sự hấp dẫn, đem lại may mắn cho người đeo*

[if !supportLists]**d.**[endif]**Th****ạ****ch anh t****ó****c****đ****en**

-Thạch anh tócđenđược coi làbùa hộmệnh tốt trong những vấnđềtình cảm. Nógiúp ngườiđeo hòađồng với mọi người, xóa bỏmọi sựsợhãi, mangđến những may mắn vàsựlạc quan cho chủnhân.

- Đeo**trang s****ức thạch anh tócđ****en**cótác dụng phòng tránh sựquấy nhiễu của các hưkhíxung quanh.

[![mat-thach-anh-toc-den-reu](/uploads/news/art-034-4-1-mat-thach-anh-toc-den-reu-0.jpg)](https://web.archive.org/web/20141214133139/http://thegioidaquy.net/phong-thuy/mat-thach-anh-toc-den-reu-1192.html#.VHSwGtKsVlw)

*[Mặt dây chuyền thạch anh tóc đen rêu](https://web.archive.org/web/20141214133139/http://thegioidaquy.net/phong-thuy/mat-thach-anh-toc-den-reu-1192.html#.VHSwGtKsVlw)phù hợp cho người mạng Thuỷ mạng Mộc.*

[if !supportLists]**2.**[endif]**Tác****dụng của đá thạch anh tóc về mặt ch****ữ****a b****ệ****nh:**

[if !supportLists]**a.**[endif]**Th****ạ****ch anh t****ó****c v****à****ng:**

- Đặtthạch anh tóc vàngởgần vùng thần kinh thái dương cótác dụng tăng chítiến thủ, gan dạ. Nógiúp chủnhân phát huyđược tính sáng tạo vàsáng suốt trong những việc bản thân mình làmđểđạtđược kết quảcao nhất.

[if !supportLists]**b.**[endif]**Th****ạ****ch anh t****ó****c xanh:**

- Thạch anh tóc xanh cótácđộng mạnhđến vùng tim vàhệthống sinh lý nam.

- Đối với nam giới yếu sinh lý, có thể sử dụng thạch anh tóc xanh để vào huyệt mệnh môn thuộc khu vực luân xa 3, hít sâu và nghĩ đến màu xanh lục hòa vào cơ thể. Trừ trường của actinolit và thạch anh sẽ giúp cung cấp thêm năng lượng làm cân bằng hệ thống sinh lý.

[if !supportLists]**c.**[endif]**Th****ạ****ch anh t****ó****c****đỏ****:**

- Đối với các bạn gái có thể chất yếu, khí huyết không điều hòa, khi đeo thạch anh tóc đỏ sẽ có tác dụng bổ sung năng lượng cho 3 vùng mông, rốn và thái dương.

- Đeo thạch anh tóc đỏ ở vùng dưới eo có tác dụng điều tiết, chữa bệnh phụ khoa.

[if !supportLists]**d.**[endif]**Th****ạ****ch anh t****ó****c****đ****en**

- Thạch anh tóc đen giúp điều trị chứng nhồi máu và chống đột quỵ chống lại những mảng sơ vữa.

*[*Thegioidaquy.net*](https://web.archive.org/web/20141214133139/http://thegioidaquy.net/phongthuy.html)*',
    '2014-11-26 09:00:00', 0, 792, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-031', 'y-nghia-da-serpentine', 'Ý nghĩa đá Serpentine', 'Thế Giới Đá Quý',
    '/uploads/news/art-035-1-1-phat-ban-menh-a-di-da-da-serpentine-0.jpg', 'Đá Serpentine là một loại đá có sức mạnh thần kỳ. Nó có tác dụng kích thích và khơi dậy nguồn năng lượng dồi dào cho người đeo, thu hút tình yêu và tiền bạc.', '-[Đá](https://web.archive.org/web/20141218142025/http://thegioidaquy.net/phong-thuy/da-phongthuy-310-Da-Serpentine-ngoc-Secpentine-)[Serpentine](https://web.archive.org/web/20141218142025/http://thegioidaquy.net/phong-thuy/da-phongthuy-310-Da-Serpentine-ngoc-Secpentine-)cótên gọi bắt nguồn từtiếng La Tinh “Serpens” – cónghĩa là“Con rắn”, chỉra màu sắcđặc trưng của loạiđánày.***ĐáSerpentine***thường cómàu vàng phớt xanh lácây hay màu xanh lục sẫm với những vết rấtđặc trưng làm cho viênđátrông nhưda rắn, không trong suốt.ĐáSerpentine thường cócấu trúc dạng sợi hay phiến vàvẻngoài trông giống Ngọc Nephrite.

- ỞMông Cổ,*ĐáSerpentineđược coi làbùa hộmạ**ng*cótác dụng phùhộcho ngườiđeo chống lại rắn cắn vàcôn trùngđốt. Vìngười ta cho rằng, nhờcómàu sắc của con rắn màđáSerpentin cóthểđược coi làchất giảiđộc hiệu quả.ỞChâu Âu, nóđược sửdụng dùng làm cối giã vàđồđựng thuốc. Dođókhoáng vật này cònđược biếtđến với tên gọi là“Đáhiệu thuốc”

- ĐáSerpentine chủyếuđược sửdụng làmđồtrang sức cótác dụng hộmệnh cho ngườiđeo nhưsau:

[if !supportLists]**1.Phật bản mệnh A DiĐàĐá****Serpentine:**

- Mặt phật bản mệnh A Di Đà đá ngọc Serpentine có tác dụng hộ mạng cho người tuổi Tuất, Hợi. Mặt chạm kích thước nhỏ thích hợp cho nam và nữ đeo.

**-**Hình tượng**phật bản mệnh A Di Đà**thường thấy là Ngài ngồi kiết già trên Hoa sen, tóc búi cao, mặc áo hở ngực, trên ngực có chữ Vạn của Mật Tông, tay phải thủ ấn, tay trái ngang bụng cầm pháp khí Phật như Viên minh châu hoặc Búp sen, xung quanh Ngài luôn toả hào quang.

- Cần chú ý hình tượng để thỉnh Ngài cho đúng, nếu thỉnh nhầm vị phật khác không đúng với bản mệnh, sẽ không được sự phù hộ của Ngài.

[![phat-ban-menh-A-Di-Da-da-Serpentine](/uploads/news/art-035-1-1-phat-ban-menh-a-di-da-da-serpentine-0.jpg)](https://web.archive.org/web/20141218142025/http://thegioidaquy.net/phong-thuy/phat-ban-menh-a-di-da-da-serpentine-3281.html#.VG3zUTSsVlx)

[Phật bản mệnh A Di Đà đá Serpentine](https://web.archive.org/web/20141218142025/http://thegioidaquy.net/phong-thuy/phat-ban-menh-a-di-da-da-serpentine-3281.html#.VG3zUTSsVlx)thích hợp cho người Tuổi Tuất và tuổi Hợi

**2. Phật bản mệnh Bất Động Minh Vương Đá Serpentine:**

- Mặt phật bản mệnh Bất Động Minh Vươngđá ngọc Serpentinehộ mạng cho tuổi Dậu.

**- Bất Động Minh Vương**cùng vớiQuan Thế Âm Bồ tát,Địa Tạng Vương Bồ tátlà ba vị phật lớn thường gặp nhất ở Tây Tạng. Những người sinh năm Dậu được sự hộ mạng của Bất Động Minh Vương thì một đời được bình an sức khoẻ, thuận lợi như ý.

[![phat-ban-menh-Bat-Dong-Minh-Vuong-da-Serpentine](/uploads/news/art-035-2-1-phat-ban-menh-bat-dong-minh-vuong-da-serpentine-0.jpg)](phat-ban-menh-bat-dong-minh-vuong-da-serpentine)

*[Mặt phật bản mệnh Bất Động Minh Vương đá ngọc Serpentine](https://web.archive.org/web/20141218142025/http://thegioidaquy.net/phong-thuy/phat-ban-menh-bat-dong-minh-vuong-da-serpentine-3280.html#.VG3z3zSsVlw)mang đến sức khỏe, bình an cho người đeo*

**3. Phật bản mệnh Đại Thế Chí Đá Serpentine:**

- Mặt phật bản mệnh Đại Thế Chí đá ngọc Serpentine hộ mạng cho tuổi Ngọ.

- Hình tượng phật bản mệnh Đại Thế Chí hay thấy là Ngài ngồi trên Hoa sen tóc búi cao, tay cầm Tam Muội Đa tức cành Sen mới nở, để giáo hóa chúng sanh, xung quanh Ngài toả hào quang sáng rực.

[![phat-ban-menh-Dai-The-Chi-da-Serpentine](/uploads/news/art-035-3-1-phat-ban-menh-dai-the-chi-da-serpentine-0.jpg)](https://web.archive.org/web/20141218142025/http://thegioidaquy.net/phong-thuy/phat-ban-menh-dai-the-chi-da-serpentine-3279.html#.VG34gzSsVlx)
*[Mặt phật bản mệnh Đại Thế Chí](https://web.archive.org/web/20141218142025/http://thegioidaquy.net/phong-thuy/phat-ban-menh-dai-the-chi-da-serpentine-3279.html#.VG34gzSsVlx)đá ngọc Serpentine hộ mạng cho tuổi Ngọ.*

**4. Phật bản mệnh Như Lai Đại Nhật đá Serpentine:**

- Mặt phật bản mệnh Như Lai Đại Nhật đá ngọc Serpentine hộ mạng cho tuổi Mùi, Thân.

-Hình tượng**phật bản mệnh Đại Nhật Như Lai**là Ngài kiết già trên Hoa sen, mặc áo lụa đào, xung quanh Ngài toả hào quang, hai tay thủ ấn Như Lai trước ngực để giáo hóa chúng sanh, giúp khai mở trí tuệ để gặt hái nhiều thành công.

[![phat-ban-menh-Nhu-Lai-Dai-Nhat-da-Serpentine](/uploads/news/art-035-4-1-phat-ban-menh-nhu-lai-dai-nhat-da-serpentine-0.jpg)](https://web.archive.org/web/20141218142025/http://thegioidaquy.net/phong-thuy/phat-ban-menh-nhu-lai-dai-nhat-da-serpentine-3278.html#.VG35qzSsVlw)

*[Phật bản mệnh Như Lai Đại Nhật](https://web.archive.org/web/20141218142025/http://thegioidaquy.net/phong-thuy/phat-ban-menh-nhu-lai-dai-nhat-da-serpentine-3278.html#.VG35qzSsVlw)giúp khai mở trí tuệ, gặt hái nhiều thành công.*

**5. Phật bản mệnh Thiên Thủ đá Serpentine:**

-Mặt phật bản mệnh Thiên Thủ đá Serpentine hộ mạng cho tuổi Tý.

-Hình tượng Thiên Thủ mặt đeo thường thấy là Ngài ngồi trên đài sen, có nhiều tay như  6, 8, 14, 16 hoặc 18 tay ( do mặt đá nhỏ nên thợ chỉ chạm khắc hình tượng Ngài có nhiều tay, không thể nào chạm đủ nghìn tay được ) trên mỗi tay của Ngài cầm một pháp khí của Phật giáo, uy lực vô song.

[![phat-ban-menh-Thien-Thu-da-Serpentine](/uploads/news/art-035-5-1-phat-ban-menh-thien-thu-da-serpentine-0.jpg)](https://web.archive.org/web/20141218142025/http://thegioidaquy.net/phong-thuy/phat-ban-menh-thien-thu-da-serpentine-3277.html#.VG36gTSsVlw)

*[Mặt phật bản mệnh Thiên Thủ](https://web.archive.org/web/20141218142025/http://thegioidaquy.net/phong-thuy/phat-ban-menh-thien-thu-da-serpentine-3277.html#.VG36gTSsVlw)đá Serpentine hộ mạng cho tuổi Tý.*

**6. Phật bản mệnh Văn Thù đá Serpentine:**

**- Mặt phật bản mệnh Văn Thù đá Serpentine hộ mạng cho tuổi Mão.**

**-**Hình tượng**Văn Thù bồ tát**thường thấy là Ngài ngồi trên lưng Sư tử, tay phải Ngài cầm Gươm ánh sáng hoặc Viên minh châu giúp khai thông trí huệ hoặc tay trái cầm Gậy như ý. Đặc điểm dễ nhận thấy là tay Văn Thù bồ tát có thể cầm các pháp khí của phật khác nhau nhưng Ngài luôn ngồi trên lưng Sư Tử.

*[Mặt phật bản mệnh Văn Thù đá Serpentine](https://web.archive.org/web/20141218142025/http://thegioidaquy.net/phong-thuy/phat-ban-menh-van-thu-da-serpentine-3276.html#.VG37RDSsVlw)hộ mạng cho tuổi Mão.*

**7. Phật bản mệnh Phổ Hiền đá Serpentine:**

**-**Trang sức đá: mặt dây chuyền phật bản mệnh Phổ Hiền phong thuỷ cho tuổi Thìn và Tỵ ( tuổi Rồng, tuổi Rắn).

-Hình tượng mặt**phật bản mệnh Phổ Hiền**thường thấy là ngài ngồi trên lưng Voi, tay cầm pháp khí phật giáo như Cành sen, Gậy như ý hoặc thủ ấn trước ngực, quanh người toả hào quang sáng rực.

*[Mặt dây chuyền phật bản mệnh Phổ Hiền phong thuỷ](https://web.archive.org/web/20141218142025/http://thegioidaquy.net/phong-thuy/phat-ban-menh-pho-hien-da-serpentine-3275.html#.VG377DSsVlw)cho tuổi Thìn và Tỵ*

**8. Phật bản mệnh Hư Không Tạng đá Serpentine:**

- Mặt phật bản mệnh Hư Không Tạng đá ngọc Serpentine giúp hộ mạng cho tuổi Sửu, Dần. Đá ngọc xanh trong rất đẹp ít sớ, mặt chạm vừa phù hợp cho nam nữ vóc người Việt đeo.

*[Mặt phật bản mệnh Hư Không Tạng đá ngọc Serpentine](https://web.archive.org/web/20141218142025/http://thegioidaquy.net/phong-thuy/phat-ban-menh-hu-khong-tang-da-serpentine-3274.html#.VG38njSsVlw)giúp hộ mạng cho tuổi Sửu, Dần*

- Serpentine làbiểu tượng của chòm sao Thất NữvàThiênẤt trong cung hoàngđạo.

- Theo huyền thoại cổ, Adam mắc nghẹn quảtáo vàkhạc ra mẩuđáda rắn. Vìvậy,*ĐáSerpentine cònđược gọi là“Đácủa Adam”*vàđược cho làhònđáquỷquyệt, biểu tượng của cám dỗvàtội lỗi.Đôi khi một sốngườiđeo loạiđánàyđểthu hút sựchúý của những người khác.

- Đồng thời những người thông thái cổkhẳngđịnh rằng,đồtrang sức bằngĐáSerpentine chỉnên dùng cho những người muốn chạy trốn khỏi nguy hiểm trênđườngđời. Bởi loạiđánày cókhảnăng bảo vệchủnhân tránh khỏi những tácđộng tiêu cực từphía những người khác.

-**Serpentine c****óthểhoạtđộng với bất kỳcharka**đểxóa sạch hoặc ngăn chặn những năng lượng bịtắc nghẽn.ĐáSerpentine cótác dụng hỗtrợtrong việc chữa trịnhững bệnh vềtim vàphổi, tái tạo tếbào mới.

- Các nhàthạch trịliệu học ngày nay cho rằng,*Đá**Serpentine*giúpđiều trịchứngđauđầu, chứng ngủlịm vàgiúp cho xương mau liền.

[*Thegioidaquy.net*](https://web.archive.org/web/20141218142025/http://thegioidaquy.net/phongthuy.html)',
    '2014-11-20 09:00:00', 0, 835, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-032', 'da-thuy-tinh-nui-lua-obsidian', 'Đá thủy tinh núi lửa (Obsidian)', 'Thế Giới Đá Quý',
    '/uploads/news/art-036-1-1-quan-am-cam-chau-cuoi-rong-da-obsidian-0.jpg', 'Đá thủy tinh núi lửa (Obsidian) có nguồn gốc từ núi lửa được hình thành bằng cách nham thạch phun trào bị lạnh ngưng kết đột ngột tạo thành kết cấu của Đá núi lửa.', '[if !supportLists]**1.[endif]Nguồn gốc hình thành vàcấu tạoĐáthủy tinh núi lửa:**

[if !supportLists]-[endif][Đáthủy tinh núi lử](https://web.archive.org/web/20141218141956/http://thegioidaquy.net/phong-thuy/da-phongthuy-304-Obsidian-Da-Thuy-tinh-nui-lua-)[a](https://web.archive.org/web/20141218141956/http://thegioidaquy.net/phong-thuy/da-phongthuy-304-Obsidian-Da-Thuy-tinh-nui-lua-)cóthểđược tìm thấyởbất cứnơiđâu cóhoạtđộng núi lửa. Chúng ta cóthểtìm thấy chúngởvùng Đông Nam Bộ, Tây Nguyên, Tây Bắc Việt Nam; hayởcác nước Nam Mỹ, Mexico, Afghanistan, Nhật Bản,…

[if !supportLists]-[endif]Đánúi lửa giátrịnhất vàcónăng lượng nhất chính làloạiđánúi lửabịđóng băng tại các vùng băng tuyết. Khi năng lượng chưa kịp lan tỏa gặp băng lạnhđãđông kết lại.

[if !supportLists]-[endif]*Đáthủy tinh núi lửa làmột dạng khoáng vật vôđịnh hì**nh*, chúngđược hình thành do sựnguội lạnh quánhanh của nham thạch.**Đáthủy tinh núi lửa**códạng cấu trúc tinh thểtrung gian giữa cấu trúc của tinh thểrắn vàcấu trúc hỗnđộn của khí.

[if !supportLists]-[endif]Đáthủy tinh núi lửa còn cótên gọi khác là**đávỏ****chai (Obsidian)**, một lại thủy tinh rhyolite cóhàm lượng silicđiôxit cao (chúng chiếm khoảng 65%đến 80%).

[if !supportLists]-[endif]Loạiđánày thường chứaít nước (thấp hơn 1%) tính theo trong lượng. Dướiáp suất caoởđộsâu, chúng cóthểchứa lênđến 10% nước.

[if !supportLists]-[endif]Đáthủy tinh núi lửa cóđộcứng 5.5 với thành phần chính làSIO2.

[if !supportLists]-[endif]Đáthủy tinh núi lửa cóthành phần hóa học gần giống vớiĐáthạch anh.Điều này dẫnđến một sốngười cho rằngĐáthủy tinh núi lửa chính làĐáthạch anh. Nhưng thực tếcho thấy làkhông phải bởiĐáthủy tinh núi lửađược tạo thành do bịlạnh ngưng kếtđột ngột nên nókhông thểkết tinh mặc dùcóthành phần SiO2

[if !supportLists]**2.[endif]Màu sắcĐáthủy tinh núi lửa:**

[if !supportLists]-[endif]Đáthủy tinh núi lửa thường cómàu tối.*Điển hình làmàuđ**en*. Tuy nhiên màu cóthểthayđổi tùy thuộc vào lượng tạp chất của Sắt vàMagie. Hai loại tạp chất này cóthểlàm choĐánúi lửa cótừmàu lục sẫmđếnđen.

[![quan-Am-cam-Chau-cuoi-Rong-da-Obsidian](/uploads/news/art-036-1-1-quan-am-cam-chau-cuoi-rong-da-obsidian-0.jpg)](https://web.archive.org/web/20141218141956/http://thegioidaquy.net/phong-thuy/quan-am-cam-chau-cuoi-rong-da-Obsidian-3194.html#.VGjYyzSsVlw)

*[Mặt dây chuyền Quan Âm đá thủy tinh núi lửa](https://web.archive.org/web/20141218141956/http://thegioidaquy.net/phong-thuy/quan-am-cam-chau-cuoi-rong-da-Obsidian-3194.html#.VGjYyzSsVlw)hộ mạng đem lại bình an, giúp trí huệ minh mẫn.*

[if !supportLists]-[endif]Ngoài ra cũng córấtít mẫuđược tìm thấyởdạng gần nhưlàkhông màu

[if !supportLists]**3.[endif]Ý nghĩaĐáthủy tinh núi lửa:**

[if !supportLists]-[endif]Do chứa nguồn năng lượng lớn,Đáthủy tinh núi lửa thườngđược dùngđểchếtác thành trang sức mang nhiều ý nghĩa trong phong thủy rấtđược người tiêu dùngưa chuộng như:***m****ặt dây chuyền Phật Bản mệnhĐáthủy tinh núi lửa (Đá****obsidian)***, mặt tỳhưuĐáobsidian…Phật bản mệnhđược chếtác từĐáthủy tinh núi lửa thường mang màuđen.

*Mặt dây chuyền[phật bản mệnh A Di Đà đá thủy tinh núi lửa](https://web.archive.org/web/20141218141956/http://thegioidaquy.net/phong-thuy/phat-ban-menh-tuoi-hoi-a-di-da-da-obsidian-3187.html#.VGjZdDSsVlw)hộ mệnhcho người tuổi Hợi*

[if !supportLists]-[endif]Người Hindu tin rằng,Đáthủy tinh núi lửanhưlàlábùa hộmệnhđểgiúp họnhậnđược những mặt yếu của mình bởi vìchúng cókhảnăng hấp thụđược những dụng ý xấu xa.

[if !supportLists]-[endif]Đáthủy tinh núi lửa giúp ngăn ngừa những hành vi không chínhđáng, giúp con người không rơi vào vòng tội lỗi.

[if !supportLists]-[endif]Đáthủy tinh núi lửa trong phong thủy PhươngĐông thuộc vềHành Thủy, phùhợp với những người mạng Thủy vàmạng Mộc.

[if !supportLists]-[endif]Đáthủy tinh núi lửa chính làbiểu tượng của chòm sao Ma Kết, Nhân Mã, Sưtửtrong 12 cung hoàngđạo.

[if !supportLists]-[endif]Đáthủy tinh núi lửa sẽrất cólợi nếu chúngđược xếp bên cạnh những tinh thểthạch anh thiên nhiên, rất tốt trong việcđiều trịnhững bếtắc vềtâm lý vàtình cảm.

[if !supportLists]-[endif]Trong y học,**Đáthủy tinh núi lử****a**được sửdụng làm dao mổvìdaođược chếtạo từloạiđánày cólưỡi bén hơn nhiều lần so với dao mổlàm bằng thép.Đối với những dao mổlàm bằng kim loại, khi quan sát bằng kính hiển vi ta sẽthấy chúngđều cólưỡi lỡm chỡm nhưrang cưa. Trong khi dao làm từĐáthủy tinh núi lửa lại bằng phẳng vàđều ngay cảkhi quan sát dưới kính hiển viđiện tử. Một nghiên cứu cho thấy, các vết cắt bằngĐáthủy tinh núi lửa sẽgây ra vết sẹo hẹp hơn,ít tếbào viêm hơn.

[if !supportLists]-[endif]*Đáthủy tinh núi lử**a*cótácđộng tích cựcđến dạdày vàruột cũng nhưkích thích hoạtđộng của thân, giữổn dịnh huyếtáp vàcủng cốtính miễn dịch.

*[*Thegioidaquy.net*](https://web.archive.org/web/20141218141956/http://thegioidaquy.net/phongthuy.html)*',
    '2014-11-17 09:00:00', 0, 878, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-033', 'y-nghia-phong-thuy-da-ngoc-bich-nephrite', 'Ý nghĩa phong thủy Đá Ngọc Bích (Nephrite)', 'Thế Giới Đá Quý',
    '/uploads/news/art-037-1-1-phat-ban-menh-hu-khong-tang-da-ngoc-bich-to-60-0.jpg', 'Theo phong thủy, Đá Ngọc Bích (Nephrite) là biểu tượng của sức khỏe. Nó có tác dụng mang đến vận may, giúp người đeo tránh được những rủi ro, các thế lực tà ma và sự nguy hiểm.', '-[ĐáNgọc Bí](https://web.archive.org/web/20251204225201/http://thegioidaquy.net/phong-thuy/da-phongthuy-260-Ngoc-bich-Nephrite)[ch (Nephrite)](https://web.archive.org/web/20251204225201/http://thegioidaquy.net/phong-thuy/da-phongthuy-260-Ngoc-bich-Nephrite)làmột loại ngọc quý. Từthời xưa trước Công Nguyên,Đáphong thủy Ngọc Bíchđãđược biếtđến nhưlàloại ngọc quý rấtđược các tầng lớp vua chúa, quan lại xem nhưlàbảo bối.Đáphong thủy thủy Ngọc Bích không chỉđược sửdụngđểlàm các hình tượng thờphụng màcònđược dùngđểtrang hoàng mộphần của các thành viên cao cấp trong hoàng tộc.

- Ngày nay,ĐáNgọc Bíchvẫn luôn làloạiđáquýđược mọi ngườiưa chuộng. Làbiểu tượng của lòng bao dung,đức hạnh, tinh khiêm nhường.

- Thời Ai Cập CổĐại,**Đáphong thủy Ngọc Bíchđượcưa chuộng nhưloạiđácủa tình yêu**, mangđến sựbình an cho con người.

-Đáphong thủy Ngọc Bíchlàmột loạiđácósức mêhoặc. Loạiđánày chủyếu cómàu xanh lục hoặc xanh lục xám với tone màu từđậmđến trung bình. Một sốđáphong thủy Ngọc Bích cómàu trắng, vàng nhạt hoặcđỏlợt. GiátrịcủaĐáphong thủy Ngọc Bíchđược xácđịnh tùy theo màu sắc vàcườngđộcủa màu sắc này, tính rực rỡvàvân sọc cùng vớiđộsáng vàtính trong suốt củađá.

[![phat-ban-menh-Hu-Khong-Tang-da-ngoc-bich-to-60](/uploads/news/art-037-1-1-phat-ban-menh-hu-khong-tang-da-ngoc-bich-to-60-0.jpg)](https://web.archive.org/web/20251204225201/http://thegioidaquy.net/phong-thuy/phat-ban-menh-hu-khong-tang-da-ngoc-bich-to-60-3312.html#.VGjT8jSsVlw)

*[Mặt Phật bản mệnh Hư Không Tạngđá ngọc bích](https://web.archive.org/web/20251204225201/http://thegioidaquy.net/phong-thuy/phat-ban-menh-hu-khong-tang-da-ngoc-bich-to-60-3312.html#.VGjT8jSsVlw)sẽ đem lại sức khoẻ, hộ mệnh cho người đeo*

- Theo phong thủy, người ta cho rằng*đeođồtrang sức bằngĐáNgọc Bí**ch*như: mặt dây chuyềnĐáNgọc Bích, Vòng tayĐáNgọc Bích, NhẫnĐáNgọc Bích…sẽcótác dụng giúp làm cho mối quan hệcủa bạn với cấp trên vàđồng nghiệp trởnên suôn sẻ.

- Ngoài ra nócòn cótác dụng mangđến vận may cho ngườiđeo, giúp phát triển khảnăng giao tiếp.

- Các pháp sưcho rằng, NhữngĐáhộmệnh bằng Ngọc Bích gam màu lạnh cósức mạnh tiên tri, cókhảnăng nhìn vềtương lai. Những loạiđáNgọc Bích gam màu tối bảo vệngườiđeo tránh những “lời nói gở” rất tốt.ĐáNgọc Bích màu phớt xanh lácây giúp tập trung sựchúý vàkhơi mởnhữngđiều vô hình màmắt thường không thểnhìn thấyđược.

-**ĐáNgọc Bích biểu hiện cho lòng dũng cả****m**vàsựkhiêm tốn. Người ta cho rằng loạiđánày cókhảnăng truyền cho người chủsựvững tâm vàlàm cho ngườiđótrởnên thông thái hơn.

![vong-tay-da-Ngoc-bich-10-ly](/uploads/news/art-037-2-1-vong-tay-da-ngoc-bich-10-ly-0.jpg)

*[Vòng tay đá ngọc bích](https://web.archive.org/web/20251204225201/http://thegioidaquy.net/phong-thuy/vong-tay-da-ngoc-bich-10-ly-2897.html#.VGjV3TSsVlw)đ*em lại may mắn và sức khoẻ cho người đeo

-ĐáNgọc Bích làbiểu tượng của chòm sao Thất Nữ.

- Ngoài những ý nghĩa vềmặt phong thủy,ĐáNgọc Bích cònđược biếtđến với công dụng chữa bệnh. Người ta tin rằng,Đáphong thủy Ngọc Bích cótác dụng giúp cải thiện thịlực, chữa các bệnh vềđộng kinh vàgiảmđau răng.

- Các thầy lang Trung Quốc coiĐáNgọc Bích làmột trong những loại dược liệu quan trọng nhấtđểlàm thanh sạch các cơquan nội tạng.

-ĐáNgọc Bích màuđỏcókhảnăng cầm máu vàchữa các bệnh vềphụkhoa.

-ĐáNgọc Bích tăng cường sức mạnh thểchất vàkéo dài tuổi thọ.

-ĐặtđáNgọc Bích trên bụng cóthểchống lại những bệnh vềdạdày. Tương truyền thời xa xưa, HoàngđếcủaĐếQuốc Bizanxow làManuilđã tặng quàcho các vịtu sĩnúi Afon một cái bátđược làm từĐáNgọc Bích cótác dụng không chỉchữa các bệnh khác nhau màcòn chống lại mọi chấtđộc.

*[*Thegioidaquy.net*](https://web.archive.org/web/20251204225201/http://thegioidaquy.net/phongthuy.html)*',
    '2014-11-17 09:00:00', 0, 921, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-034', 'cach-nhan-biet-da-thien-thach', 'Cách nhận biết Đá Thiên Thạch', 'Thế Giới Đá Quý',
    '/uploads/news/art-038-1-1-quan-am-dung-da-thien-thach-0.jpg', 'Thiên Thạch là loại đá có nguồn gốc từ các mảnh vụn sao băng. Đá Thiên Thạch có rất nhiều loại khác nhau. Làm thế nào để nhận biết được Đá Thiên Thạch? Hãy cùng chúng tôi tìm hiểu nhé!', '-**[Đá](https://web.archive.org/web/20141208121606/http://thegioidaquy.net/phong-thuy/da-phongthuy-239-Da-Thien-Thach-Tektite-)**[**Thiên Thạ****ch**](https://web.archive.org/web/20141208121606/http://thegioidaquy.net/phong-thuy/da-phongthuy-239-Da-Thien-Thach-Tektite-)cókích thướcđa dạng từvài mmđến hàng nghìn km. Quan sát kỹta sẽthấyĐáThiên Thạch cólớp vỏmỏng vànhững rãnh không khírấtđặc trưng.

-*Thành phần chủyếu củaĐáThiên Thạch làsắt vàniken*. Trongđósắt chiếm khoảng 90%, niken 4-8%. Lượng niken trong sắt tựnhiên trên tráiđất không nhiều nhưvậy. Dođónếu mài nhẵn mặt cắt của thiên thạch sắt rồi dùng axit nitric bôi vào sẽxuất hiện những vết rổrấtđặc biệt, giống nhưcác ô hoa.Đólàvìthành phần các chất trong thiên thạch phân bốkhôngđều. Chỗchứa nhiều niken khóbịaxităn mòn vàngược lại nên làm tạo nên cácđường vân.Đólàmột trong những cách giúp ta cóthểnhận biếtđược thiên thạch.

-**B****ềmặtĐáThiên Thạch thườngđen nhẵn vàbó****ng**. Ngoài ra cũng cómột sốĐáThiên Thạch trên bềmặt cónhững vết lõm tròn nhẵn, hoặc cácđường nứt do quátrình bào mòn vàcháy nổtrong không khí.

- Quan sát kỹmặt cắt củaĐáThiên Thạch sẽthấy trongđócórất nhiều hạt tròn nhỏ,đường kính 1-3mmm.*90%**ĐáThiên Thạch*đều cónhững hạt tròn nhỏnhưvậy.

- Vềkhối lượng, với cùng một kích cỡthìĐáThiên Thạch sẽnặng hơn, cứng vàchắc hơnđáthường.

- Vềmàu sắc,**ĐáThiên Thạch thường cómàuđ****en**hoặc ngảmàuđen vàng do bịoxy hóa.

- Trên thịtrường Việt Nam hiện nay,ĐáThiên Thạchđược coi làmột loạiđáphong thủy với nhiều sức mạnh tâm linh. Theo phong thủy, việc sởhữu một khốiđá“Thiên Thạch” cóthểgiúp chủnhân chạm tới sức mạnh của vũtrụ. Năng lượng từĐáThiên Thạch cókhảnăng hút bách bệnh ra khỏi cơthể,đặc biệt làcác bệnh liên quan vềmáu vànão bộ.

- Chính vìlẽđó, gầnđây trên thịtrường xuất hiện nhiều viên thiên thạch cótrọng lượng lênđến vài chục kg không rõ xuất xứvàgiácảthìđược hétởmức trên trời. Người mua cần cẩn trọng với những loại này, cóthểnóđược làm giảvới mụcđích lừađảo.

- Dođótốt nhất trước khi muaĐáThiên Thạch chúng ta cần phải tìm hiểu, trang bịcho mình một sốkiến thức vềloạiđánày vàchọn muaởnhững cửa hàng Phong thủy cóuy tinđểđượcđảm bảo. Hãyđến với Cửa hàng phong thủy Hoa Mộc Lan của chúng tôiđểđược tưvấn kỹhơn, giúp các bạn cóthểlựa chọn cho mình sản phẩm phong thủy hợp ý lại vừađảm bảođược chất lượng.

- Sauđây làmột sốĐáThiên Thạchđược chếtác thành vật phẩm phong thủy trang sức hiệnđangđược trưng bán tại Cửa hàng chúng tôi nhưsau:

+[endif]Mặt Quan ÂmĐáThiên Thạch: Vật phẩm phong thủy này thườngđược dùngđểcầu bình an vàtài lộc cho gia chủ.

[![quan-am-dung-da-thien-thach](/uploads/news/art-038-1-1-quan-am-dung-da-thien-thach-0.jpg)](https://web.archive.org/web/20141208121606/http://thegioidaquy.net/phong-thuy/quan-am-dung-da-thien-thach-2760.html#.VGjN1zSsVlw)

*[Mặt Quan Âm phong thuỷ đá thiên thạch](https://web.archive.org/web/20141208121606/http://thegioidaquy.net/phong-thuy/quan-am-dung-da-thien-thach-2760.html#.VGjN1zSsVlw)dùng trấn trạch cầu bình an và tài lộc*

+ Mặt Di LặcĐáThiên Thạch giúp loại trừnhững tổn thương vềtình cảm,đem lại may mắn vàthành công. Giúp tăng cường năng lượng học vàcác quátrình traođổi chất trong cơthểngười.

[![mat-Di-Lac-inox-da-thien-thach-trung](/uploads/news/art-038-2-1-mat-di-lac-inox-da-thien-thach-trung-0.jpg)](https://web.archive.org/web/20141208121606/http://thegioidaquy.net/phong-thuy/mat-di-lac-inox-da-thien-thach-trung-2501.html#.VGjRLjSsVlx)

*[Mặt Di Lặc đá thiên thạch](https://web.archive.org/web/20141208121606/http://thegioidaquy.net/phong-thuy/mat-di-lac-inox-da-thien-thach-trung-2501.html#.VGjRLjSsVlx)[phong thuỷ](https://web.archive.org/web/20141208121606/http://thegioidaquy.net/phong-thuy/mat-di-lac-inox-da-thien-thach-trung-2501.html#.VGjRLjSsVlx)đem lại an lạc vàmay mắn*

+ Mặt Nhẫn Tỳ Hưu đá Thiên Thạch

[![mat-nhan-Ty-huu-da-thien-thach](/uploads/news/art-038-3-1-mat-nhan-ty-huu-da-thien-thach-0.jpg)](https://web.archive.org/web/20141208121606/http://thegioidaquy.net/phong-thuy/Mat-nhan-ty-huu-da-thien-thach-2843.html#.VGjRdjSsVlw)

*[Mặt nhẫn Tỳ Hưu đá thiên thạch phong thuỷ](https://web.archive.org/web/20141208121606/http://thegioidaquy.net/phong-thuy/Mat-nhan-ty-huu-da-thien-thach-2843.html#.VGjRdjSsVlw)đem lạitài lộc cho người đeo*

*[*Thegioidaquy.net*](https://web.archive.org/web/20141208121606/http://thegioidaquy.net/phongthuy.html)*',
    '2014-11-16 09:00:00', 0, 964, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-035', 'da-quy-labradorite', 'Đá quý Labradorite', 'Thế Giới Đá Quý',
    '/uploads/news/art-039-1-1-mat-chu-nhat-van-rong-xanh-biec-da-labradorite-0.jpg', 'Đá Labradorite là một loại đá phản quang. Loại đá này là một biến của Feldspar, thường được dùng để làm đồ trang sức phong thủy. Đá quý Labradorite (Đá xà cừ) được đặt theo tên của Labrador ở Canada, nơi nó được tìm thấy trên đảo Paul vào năm 1770.', '-[Đá quý Labradorite](https://web.archive.org/web/20150107204317/http://thegioidaquy.net/phong-thuy/da-phongthuy-235-Da-Xa-Cu-Labradorite-)(Đá xà cừ) được đặt theo tên của Labrador ở Canada, nơi nó được tìm thấy trên đảo Paul vào năm 1770. Ngoài ra,***Đá quý Labradorite***còn được tìm thấy ở những nơi khác như: Phần Lan, Madagascar và Úc. Sau khi phát hiện ra nó, loại đá này đã trở nên rất phổ biến, đặc biệt với các nhà truyền giáo.

- Đá quý Labradorite là một biến thể của Feldspar. Tùy vào từng góc nhìn mà chúng ta sẽ thấy loại đá này có màu trắng sữa hoặc trắng xanh khi di chuyển chúng. Chính hiệu ứng quang học độc đáo này mà Đá quý Labradorite được cho là một loại đá phản quang. Nó là kết quả của sự nhiễu xạ ánh sáng trong các lớp đá.

- Khi quan sát ở một góc độ nhất định, chúng ta sẽ thấy đá màu sắc của Labradorite vô cùng quyến rũ.

-Đá quý Labradoriteđược đánh giá là giá trị nhất khi nó thể hiện được đầy đủ quang phổ gồm một dãy 7 sắc cầu vồng trong sự phản quang của nó.

- Đá quý Labradorite có ba dạng: Spectrolite, Andesine-Labradorite và Rainbow moonstone (Đá mặt trăng cầu vồng).

- Đá mặt trăng cầu vòng đến từ Madagascar và nó có một màu xanh ngắt.

- Đá Spectrolite là một dạng hiếm của đá quý Labradorite. Nó được tìm thấy ở Phần Lan. Loại đá này được biết đến với một dãy màu sắc phản quang cực kỳ đẹp đúng như tên gọi của nó.

-*Đá quý Labradorite dễ dàng được nhận biết bởi sự phản quang của nó*. Đá quý Labradorite có màu sắc vô cùng rực rỡ, thông thường chúng có màu xanh blue hoặc màu xanh lá cây hoặc bảy sắc cầu vồng được biết đến như là một hiệu ứng phản quang.

- Khi di chuyển,***Đá Labradorite có thể phản quang thành màu trắng sữa hoặc trắng xanh***. Điều này dẫn đến một số người nhầm lẫn loại đá này với Đá Moonstone. Tuy nhiên đá Moonstone có mật độ và cấu trúc tinh thể thấp hơn.

[![mat-chu-nhat-van-Rong-xanh-biec-da-Labradorite](/uploads/news/art-039-1-1-mat-chu-nhat-van-rong-xanh-biec-da-labradorite-0.jpg)](https://web.archive.org/web/20150107204317/http://thegioidaquy.net/phong-thuy/mat-chu-nhat-van-rong-xanh-biec-da-labradorite-3110.html#.VGdx5TSsVlw)

*[Mặt Dây chuyền đá Labradorite vân Rồng phong thuỷ](https://web.archive.org/web/20150107204317/http://thegioidaquy.net/phong-thuy/mat-chu-nhat-van-rong-xanh-biec-da-labradorite-3110.html#.VGdx5TSsVlw)giúp hộ mệnh, tốt sức khoẻ, thăng tiến sự nghiệp.*

- Labradorite là viên đá của sức mạnh, cho phép bạn thấu suốt những ảo tưởng và xác định thực tế. Loại đá này có tác dụng tuyệt vời trong việc tăng mạnh trực giác cho chủ nhân.

- Đá quý Labradorite là một loại đá quý rất huyền diệu, chúng vừa có khả năng giúp khai mở tâm thức lại vừa có khả năng liên kết với năng lượng vũ trụ. Tạo vòng khí bao quanh để bảo vệ chủ nhân tránh được những thất thoát năng lượng do chấn thương.

-**Đ****á quý Labradorite**sắc vàng có tác dụng giúp người đeo hội nhập vào lĩnh vực tối của tâm thức.

- Một sốngười cho rằng,ĐáLabradoritecótác dụngđiều trịbệnh vô sinh,đau khớp vàbệnh tuyến tiền liệt.

[![giot-nuoc-da-Labradorite-lon](/uploads/news/art-039-2-1-giot-nuoc-da-labradorite-lon-0.jpg)](https://web.archive.org/web/20150107204317/http://thegioidaquy.net/phong-thuy/giot-nuoc-da-labradorite-lon-3107.html#.VGdzEDSsVlw)

*[Mặt dây chuyền đá Labradorite phong thuỷ](https://web.archive.org/web/20150107204317/http://thegioidaquy.net/phong-thuy/giot-nuoc-da-labradorite-lon-3107.html#.VGdzEDSsVlw)giúp hộ mệnh, hổ trợ trịđau khớp và bệnh ở tuyến tiền liệt.*

- Ngoài ra loạiđánày cũng rất tốt trong việcđiều trịnhững bệnh rối loạn vềmắt vànão bộ, các bệnh vềcột sống.

- Một sốnhàchiêm tinh học cho rằng,**Đá****quý Labradorite**làloại bùa hộmệnh rất tốt. Nóphát triển năng khiếu, thấu thịvàlinh cảm cho chủsởhữu.

- Trong thời kìtrăng nonđầu tháng, viênđánày trởnên lạnh giávàphát quang rực rõ hơn do tiếp thuđược sức mạnh huyền bí.

- ỞAnh, những nhàchiêm tinh học cho rằngđáLabradorite làbiểu tượng của sựtrong trắng vàthông thái. Nógiúp bảo vệngôi nhàkhỏi những người khách không mời,đồng thời phát triển tính kiên nhẫn của chủnhân.

[*Thegioidaquy.net*](https://web.archive.org/web/20150107204317/http://thegioidaquy.net/phongthuy.html)',
    '2014-11-15 09:00:00', 0, 1007, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-036', 'da-quy-lapis-lazuli', 'Đá quý Lapis lazuli', 'Thế Giới Đá Quý',
    '/uploads/news/art-040-1-1-te-giac-da-lapis-lazuli-lon-0.jpg', 'Đá quý Lapis Lazuli còn có tên gọi khác là Đá Thiên Thanh. Loại đá này có nhiều bề dày lịch sử. Ở Ai Cập, Đá quý Lapis Lazuli được cho là viên đá thần thánh tới từ thiên đường.', '- Tên gọi của[đáLapis Lazuli](https://web.archive.org/web/20150107204111/http://thegioidaquy.net/phong-thuy/da-phongthuy-232-Da-Lapis-Lazuli)được cấu tạo từ“Lapis” trong tiếng La Tinh cónghĩa làđávàtừ“Lazula” xuất phát từtiếngẢRập cónghĩa làmàu xanh. Chính vìvậy,Đáquý Lapis Lazuli còn cótên gọi khác làĐáThiên Thanh.

-**Đá****quý Lapis Lazuli**làmột loạiđákhông thấu quang. Thành phần chủyếu của loạiđánày bao gồm: Diopside vàlazurite. Nóđược tạo ra từhàng triệu năm trướcđây trong thời gian biến chất củađávôi thànhđáhoa.

- Khi chưa chếtác,*Đá**quý Lapis Lazuli*cóbềmặt mờ, màu xanh da trờiđậm, thường cóbao thểmàu vàngđi kèm vàchứa các mảnh nhỏđáhoa màu trắng hoặc vàng. Các bao thểnhỏvớiánh vàng lung linh cho chúng ta cảm giácđáLapis Lazuli nhưmột loạiđáma thuật chứa bầu trờiđầy sao. Nhưng thật ra, những bao thểnày không phải làmàu vàng nhưchúng ta tưởng, chúng lànhững tinh thểPyrite.**Màu xanh của Lapis Lazuli**xuất phát từhàm lượng lưu huỳnh trong Lazurite vànócóthểthayđổi từmàu xanh biếc thuần thiếtđến màu xanh da trời nhẹhơn.Đây làmột loạiđáquý cóđộcứng tươngđối trung bình.

-*Đá**quý Lapis Lazuli làmột trong nhữngđáquýđược con người chếtácđểlàmđồtrang sức sớm nhấ**t*.

- Tại cuộc khai quật các trung tâm của nền văn hóa cổxung quanhĐịa Trung Hải, các nhàkhảo cổhọcđã rất nhiều lần tìm thấy trong những ngôi mộcổthường cócácđồđạc trang trívàcác họa tiết làm bằng**đáLapis Lazuli màu xanh da trờ****i**.Điều này cho thấy rằng loạiđácómàu xanhđậm nàyđãđược dùng khálàphổbiến trướcđây trongđời sống của người Lưỡng Hà, Ai Cập, Ba Tư, Hy Lạp vàRome.

[![te-Giac-da-Lapis-lazuli-lon](/uploads/news/art-040-1-1-te-giac-da-lapis-lazuli-lon-0.jpg)](https://web.archive.org/web/20150107204111/http://thegioidaquy.net/phong-thuy/te-giac-da-lapis-lazuli-lon-2591.html#.VGTeBDSsVlw)

*[Tê giác Lapis Lazuli phong thuỷ](https://web.archive.org/web/20150107204111/http://thegioidaquy.net/phong-thuy/te-giac-da-lapis-lazuli-lon-2591.html#.VGTeBDSsVlw)đem lại may mắn cho chủ nhân*

- Ởnhiều nướctrên thếgiới,ĐáLapis Lazuliđược cọi làmột viênđáthánh, viênđácủa tình hữu nghịvàsựthật.Đámàu xanh da trờiđược cho làkhuyến khích sựhài hòa trong những mối quan hệvàgiúp ngườiđeo tạođược sựtin cậy cũng nhưđưa ra ý kiến của họmột cách công khai. RiêngởTrungĐông, nóđược coi làcósức mạnh ma thuật.

- ỞAi Cập,**Đá****Lapis Lazuli**chỉđược dùngởnhững ngôiđền thờthần bởi Người Ai Cập tin rằng, Lapis Lazuli làviênđáthần thánh tời từthiênđường. Vìmàu xanh của nógợiđến bầu trời ngảvềđêm vànhữngđốm pyrite nhỏmàu vàngánh kim khiến người ta liên tưởngđến những vìsao.

- Nhiều nơi tin rằng khimơthấyđáLapis Lazulilàđiềm báo trước một tình yêu chung thủy.Đặt viênđáLapis trên bàn làm việc sẽgiúp chođầuóc của bạn minh mẫn hơn.

- Các tínđồđạo Phật thìlại tin rằng,**Q****ủa cầ****u Lapis Lazuili**đem lại may mắn tài lộc, trừ tiểu nhân, giúp thăng tiến trong sự nghiệp. Nócóthểxuađuổi sựốm yếu vàlàm cho một người cóthểhànhđộng nhanh trí, linh hoạt. Con người cũng trởnên thành thật vàđáng tin hơn.

[![qua-cau-da-lapis-lazuli](/uploads/news/art-040-2-1-qua-cau-da-lapis-lazuli-0.jpg)](https://web.archive.org/web/20150107204111/http://thegioidaquy.net/phong-thuy/qua-cau-da-lapis-lazuli-2167.html#.VGTdKDSsVlw)

*[Quả cầu Lapis Lazuli phong thuỷ](https://web.archive.org/web/20150107204111/http://thegioidaquy.net/phong-thuy/qua-cau-da-lapis-lazuli-2167.html#.VGTdKDSsVlw)đem lại may mắn tài lộc, trừ tiểu nhân, giúp thăng tiến sự nghiệp*

- Lapis Lazuli làmột trong những loạiđácónăng lượng mạnh nhất, cần phảiđược sửdụng một cách cẩn thận.

- Ngoài ra việcđeo trang sứcđáLapis Lazuli cóthểgiúpđỡbạn trởnên mạnh mẽhơn. Lapis Lazuliđược dùng kết hợp với nhữngđáquý khácđểlàm sạch vàthanh khiết cơthể.

[*Thegioidaquy.net*](https://web.archive.org/web/20150107204111/http://thegioidaquy.net/phongthuy.html)',
    '2014-11-13 09:00:00', 0, 1050, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-037', 'thua-lo-vi-mua-da-phan-da-mem', 'Thua lỗ vì mua đá phấn đá mềm', 'Thế Giới Đá Quý',
    '/uploads/news/art-041-1-da-phan-da-mem-ban-da-phan-da-mem-gia-re.jpg', 'Sau vài ba lần mua bán đá phấn nhỏ lẻ trót lọt có lãi họ gom tiền thu mua vào số lượng lớn thì thương lái Trung Quốc ngừng mua khiến họ đọng hàng kẹt vốn, người gom ít thì vài trăm kg, nhiều thì đến vài tấn, giờ đang tìm đầu ra để bán ngay, chịu lỗ để thu hồi vốn.', '**Đ****á phấn - đá mềm**là loại[đá](https://web.archive.org/web/20141214162451/http://thegioidaquy.net/phongthuy.html)một số thương lái Trung Quốc  mang sang đặt mua,người dânhuyện Ngọc Hồi tỉnh Kon Tum gọi**đá mềm**hay**đá phấn**là vì đá này có độ cứng không cao, khi rạch xuống nền gạch nó cũng bị mài mòn.

-**Đá phấn**được rao mua giá khoảng từ vài trăm ngàn đến vài triệu đồng một kg.  Tuy nhiên, tại địa phương không có loại đá này, một số lái buôn lần dò  và biết bên Lào có loại đá giống mẫu như thương lái Trung Quốc  đặt mua nên sang đó thu gom, mang về nội địa tích trữ để bán dần.

- Phong trào thu gom**đá phấn**ngày một tăng, khởi nguồn từ huyện Ngọc Hồi và dần lan sang nhiều huyện khác của tỉnh Kon Tum. Song rầm rộ nhất vẫn là  Ngọc Hồi, bởi nơi đây có cửa khẩu Bờ Y, giao thương với nước Lào,  Campuchia thuận tiện cho việc qua lại thu gom.

- Theo một số lái buôn tại huyện Ngọc Hồi, loại**đá phấn**thương lái Trung  Quốc mua với giá cao nhất là loại*đá phấn*có chất lượng tốt, màu đồng nhất, ít bị  vẩn đục rạn nứt, độ xuyên sáng  cao, khi dùng đèn pin soi vào có thể xuyên thấu vô trong có màu sắc rất  đẹp,**đá phấn màu đỏ**được mua giá cao nhất.

[![da phan da mem dang khai thac](/uploads/news/art-041-1-da-phan-da-mem-ban-da-phan-da-mem-gia-re.jpg)](https://web.archive.org/web/20141214162451/http://thegioidaquy.net/tin-tuc/thua-lo-vi-mua-da-mem-da-phan-1931.html)

*Đá phấn đá mềm màu đỏ được chuộng nhất*

- Một lái buôn huyện Ngọc Hồi tiết lộ hiện đang làm ăn bên Lào  và thường xuyên mang**đá phấn**về Việt Nam qua cửa khẩu Bờ Y để bán cho thương  lái Trung Quốc. Khi thu mua tại Lào, tùy vào chất lượng từng  loại đá mà giá mua dao động từ 200 ngàn đến 4 triệu đồng một kg. Đá sau khi  được thu mua, sẽ thuê các chủ xe ô tô người Lào vận chuyển về nội địa. Khi được hỏi, thương lái Trung Quốc thu gom đá phấn để làm gì. Người thì nói không biết, chỉ biết họ mua giá cao thì mình mua về  bán lại để kiếm lời.Người thì nghĩ là họ mua về để chế tác làm**tượng đá phong thủy**.

- Người Việt sang Lào thu mua rồi vận chuyển đá qua cửa  khẩu. Tuy nhiên, khoảng nửa tháng nay, việc thu mua[đá](https://web.archive.org/web/20141214162451/http://thegioidaquy.net/phongthuy.html)tạm lắng  xuống, không còn rầm rộ như nhiều tháng trước do chính quyền Lào kiểm tra gắt gao.

**Ôm nợ vì đá phấn**

- Theo các lái buôn trước đây chỉ cần thu gom đủ số lượng rồi thuê chủ xe người Lào vận chuyển là có thể qua cửa khẩu dễ dàng. Nhưng nay thuê người Lào vận chuyển cũng bị bắt, tịch thu đá.  Nếu là người Việt vận chuyển, khi bị phát hiện không những**đá phấn**bị tịch  thu, người cũng có thể bị tạm giữ.

[![da-mem-da-phan-lam-nhieu-nguoi-thua-lo](/uploads/news/art-041-2-da-mem-da-phan.jpg)](https://web.archive.org/web/20141214162451/http://thegioidaquy.net/tin-tuc/thua-lo-vi-mua-da-mem-da-phan-1931.html)

***Đá phấn màu đỏ**được nhiều người gom hàng và nhiều người đã bị thua lỗ.*

- Từ khi chính phủ Lào mạnh tay truy quét việc**thu mua đá phấn**các  thương lái Trung Quốc hạn chế mua các loại đá lớn và chuyển qua thu mua  những loại**đá phấn dạng sỏi**nhỏ hơn. Loại đá này được mua giá rất cao, có thể lên  đến cả chục triệu đồng một viên nếu đá có chất lượng đẹp. Tuy nhiên loại đá  này rất hiếm.

- Sau khi phong trào thu mua đá chững lại, nhiều lái buôn cho biết, sau vài ba lần**mua bán đá phấn**nhỏ lẻ trót lọt có lãi họ gom tiền thu mua vào số lượng lớn thì thương lái Trung  Quốc ngừng mua khiến họ đọng hàng kẹt vốn, người gom ít thì vài trăm kg, nhiều thì đến vài tấn, giờđang tìm đầu ra để bán ngay, chịu lỗ để  thu hồi vốn. Người ít thì kẹt vài chục triệu, nhiều thì vài trăm triệu, có khi tới vài tỷ hoặc vài chục tỷ. Lời thì có lời mà lỗ thì nhiều hơn. Cũng có trường hợp vay tiền hơn 1 tỷ đồng thu mua gần 1 tấn**đá mềm**,  đang trên đường vận chuyển qua cửa khẩu về nước thì lực lượng chức năng ở Lào bắt giữ. Mất**đá**mà phải đi trốn nợ và suốt ngày bị con nợ  tìm đến nhà đòi tiền.

[*Thegioidaquy.net*](https://web.archive.org/web/20141214162451/http://thegioidaquy.net/phongthuy.html)',
    '2014-11-12 09:00:00', 0, 1093, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-038', 'da-thach-anh-hong', 'Đá Thạch Anh Hồng', 'Thế Giới Đá Quý',
    '/uploads/news/art-042-1-1-qua-cau-thach-anh-hong-dam-60-0.jpg', 'Thạch anh hồng là một trong ba loại thạch anh đứng đầu trong phong thủy bên cạnh thạch anh tím và thạch anh vàng. Ngay từ thời xưa, đá thạch anh hồng đã được yêu thích và điều đó cũng được duy trì cho đến ngày nay', '-[Th](https://web.archive.org/web/20141126194220/http://thegioidaquy.net/phong-thuy/da-phongthuy-133-Thach-Anh-Hong-Rose-quartz-/page/2)[ạch anh hồ](https://web.archive.org/web/20141126194220/http://thegioidaquy.net/phong-thuy/da-phongthuy-133-Thach-Anh-Hong-Rose-quartz-/page/2)[ng](https://web.archive.org/web/20141126194220/http://thegioidaquy.net/phong-thuy/da-phongthuy-133-Thach-Anh-Hong-Rose-quartz-/page/2)làmột biến thểphổbiến củađáthạch anh với thành phần chủyếu là: Granit, Permatit, Quartzit vànhiều loạiđáSilicat khác thườngđược tìm thấy trong các mạch nhiệt dịch.

-**Th****ạch anh hồ****ng**làmột trong ba loại thạch anhđứngđầu trong phong thủy bên cạnh thạch anh tím vàthạch anh vàng.

- Ngay từthời xưa,đáthạch anh hồngđãđược yêu thích vàđiềuđócũngđược duy trìchođến ngày nay. Chúng ta khádễdàngđểtìm thấy những vật phẩm phong thủy, trang sứcđược chếtác từđáthạch anh hồng với nhiều mẫu mãđa dạng vàphong phúởcác cửa hàng phong thủy.

- Thạch anh hồng cómặtởmọi châu lục.ỞViệt Nam, chúng ta cóthểtìm thấy thạch anh hồngởcác tỉnh NghệAn,Đắc Nông,ĐàNẵng. Tuy nhiên,*th**ạch anh hồng tốt nhất làloại cónguồn từBrazil, Mỹvà**Châu Phi*.

- Năng lượngđáthạch anh hồng lớn nhất khi nótồn tại dưới thểcòn nguyên thô.

-**Vi****ênđáthạch anh hồ****ng**càng trong vàcàngít vết rạn vàcàng to thìsẽcàng tích trữnhiều năng lượng.

- Năng lượngđáthạch anh hồngđược phát ra mạnh mẽhơn dưới dạng cầu.

[![qua-cau-thach-anh-hong-dam-60](/uploads/news/art-042-1-1-qua-cau-thach-anh-hong-dam-60-0.jpg)](https://web.archive.org/web/20141126194220/http://thegioidaquy.net/phong-thuy/qua-cau-thach-anh-hong-dam-60-2655.html#.VGDbDzSsVlw)

*[Quả cầu thạch anh hồng phong thuỷ](https://web.archive.org/web/20141126194220/http://thegioidaquy.net/phong-thuy/qua-cau-thach-anh-hong-dam-60-2655.html#.VGDbDzSsVlw)gia tăng tài lộc tăng nhân duyên trong giao tiếp.*

- Tác dụng chính củađáthạch anh hồng làkích thích nâng cấp daođộng song từcủa luân xa. Dođó, nócóthểgiúp cho chủnhân mởmang tầm thức, xoa diệu vàthậm chíxóa bỏnhững tâm tưtình cảm bịtổn thương.

- Vềmặt lý thể, những rungđộng sóng năng lượng củaĐáthạch anh hồng cótácđộng tích cựcđến hệtim mạch vàhệthần kinh nên nó có thể giúp điều hòa huyết áp, ổn định tim mạch, chống stress, loại trừ sự mệt mỏi của cơ thể, kiểm soát được cơn nóng giận, tăng cường sự sáng tạo và sự tự tin, làm hoạt hóa hệ lympha từ đó giúp tăng cường hệmiễn dịch cho cơthể.

- Ngoài ra,đáthạch anh hồng còn cótácđộngđến hệtiết niệu, tủy xương vàmạch máu, giúp kéo dài tuổi thọ, thanh lọc cơthểvàđào thảiđộc tốtrong người.

- Bên cạnhđó, những rungđộng sóng năng lượng củađáthạch anh hồngsẽđánh thức tình yêu thương trong con người bạn từđógiúp làm dịu cơnđau vềmặt tình cảm, những vết thương lòng. Giúp giađình hòa thuận, cải thiện tình cảm của bạn với những người xung quanh.

- Vềmặt phong thủy,Đáthạch hồngđược sửdụngđểtrấn trạch rất tốt. Những rungđộng năng lượng phát ra từloạiđánày sẽgiúp cân bằng từtrường cho căn nhà,đem lại nguồn sinh khícho ngôi nhàcũng nhưcác thành viên trong giađình.

-***Tr****ên mìnhđeo nhiều trang sứcđược làm từĐáthạch anh hồng như****:***mặt dây chuyềnđáthạch anh hồng…vànghĩđến màuđỏbao trùm toàn thân, sẽcótác dụng làm thayđổi tính nóng nảy, bộc trực vàsựthiếu kiên nhẫn. Nógiúp bạn tăng cường tính thân thiện, thayđổi mối quan hệcon người màmangđến tình yêu cho chúng ta.

[![mat-day-chueyn-bac-Quan-Am-thach-anh-hong-nho-](/uploads/news/art-042-2-1-mat-day-chueyn-bac-quan-am-thach-anh-hong-nho-0.jpg)](https://web.archive.org/web/20141126194220/http://thegioidaquy.net/phong-thuy/mat-day-chuyen-bac-quan-am-thach-anh-hong-nho-2650.html#.VGDbvDSsVlw)

*[Mặt dây chuyền Quan Thế Âm bồ tát thạch anh hồng](https://web.archive.org/web/20141126194220/http://thegioidaquy.net/phong-thuy/mat-day-chuyen-bac-quan-am-thach-anh-hong-nho-2650.html#.VGDbvDSsVlw)giúp hoá giải khó khăn đem lại bình an.*

- Các bạn trẻkhát vọng tình yêu, cóthểchọn thời gian lúc nửađem, khi trăng tròn,đốt một cây nếnđỏ,đằng su nến nênđặt một tấm gương rồi giờthạch anh hồng lên vùng mắt thứba thầm niệm vànghĩđến người bạnđời lý tưởng trong khoảng từ3đến 5 phút. Nhưvậy sẽcótác dụng thu hút người bạnđời lý tưởng xuất hiện trong cuộc sống của bạn.

[**Thegioidaquy.net**](https://web.archive.org/web/20141126194220/http://thegioidaquy.net/phongthuy.html)',
    '2014-11-10 09:00:00', 0, 1136, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-039', 'nguon-goc-da-quy-sugilite', 'Nguồn gốc Đá quý Sugilite', 'Thế Giới Đá Quý',
    '/uploads/news/art-043-1-1-mat-da-sugilite-0.jpg', 'Đá quý Sugilite còn được gọi là luvilite, tinh thể Royal Azel hay tinh thể New Age, nó có màu từ tím đậm đến tím. Đá quý Sugilite được tìm thấy đầu tiên bởi một nhà địa chất người Nhật Bản vào năm 1944.', '-[Đá](https://web.archive.org/web/20141126194715/http://thegioidaquy.net/phong-thuy/da-phongthuy-240-Da-Sugilite)[quý Sugilite](https://web.archive.org/web/20141126194715/http://thegioidaquy.net/phong-thuy/da-phongthuy-240-Da-Sugilite)còn được gọi là luvilite, tinh thể Royal Azel hay tinh thể New Age, nó có màu từ tím đậm đến tím.

- Đáquý Sugilite làmột trong những loạiđámới xuất hiện trên thịtrường trong những năm gầnđây. Tên gọi củađáquý Sugilite thường khôngđược nhiều người biếtđến. Tuy nhiên nếu bạn làngười chơiđáphong thủy thìcóthểbạnđã nhìn thấy nó.

- Sugilite làmột viênđáquý tuyệt vời với nhiều màu sắc trongđó, nổi bật nhất làmàu tímđậm. Thỉnh thoảng**đá****quý Sugilite**còn cóthểđược gọi làPurple Turquoise. Một sốĐáSugilite cómàu sắc rấtđẹp nhưmàu nâu, hồng nhạt, vàng vàđen.

-Đáquý Sugiliteđược tìm thấyđầu tiên bởi một nhàđịa chất người Nhật Bảncótên làKen-ichi Sugi vào năm 1944. Cóthểnói loạiđáquý này chỉmớiđược biếtđến trong khoảng 50 năm nhưngđóđang dần trởnên phổbiến.Đặc biệt lànhững viênđáquý Sugilite cósắc màu timđậm.

[![Mat-da-Sugilite](/uploads/news/art-043-1-1-mat-da-sugilite-0.jpg)](https://web.archive.org/web/20141126194715/http://thegioidaquy.net/phong-thuy/mat-da-sugilite-chu-nhat-1023.html#.VF9AWzSsVlw)

*[Mặt đá sugilite phong thuỷ](https://web.archive.org/web/20141126194715/http://thegioidaquy.net/phong-thuy/mat-da-sugilite-chu-nhat-1023.html#.VF9AWzSsVlw)giúpgiảm đau.*

- Đáquý Sugiliteđược tạo thành bởi một nhóm nhiều nguyên tố, tuy nhiên thành phần chủyếu cấu tạo nên**đá****Sugilite**gồm có: Kali, Natri, Lithi, Sắt, Magiê.

-*Đá**quý Sugilite làmột loạiđáquý hiế**m*. Nóthườngđược sửdụngđểchếtạo ra những trang sứcđáquý vô cùng xinhđẹp, lại vừa chứađựng rất nhiều ý nghĩa phong thủy. Theo phong thủy, người ta cho rằngĐáQúy Sugilite cóthểtácđộng tích cực trong việc bảo vệngườiđeo khỏi những tác hại xấu. Nógiúp ngườiđeo lọc ra những năng lượng tiêu cực nhưgiận dữ, thùđịch…

*[Mặt dây chuyền đá sugilite](https://web.archive.org/web/20141126194715/http://thegioidaquy.net/phong-thuy/mat-day-chuyen-bac-hinh-la-da-sugilite-1026.html#.VF8-VTSsVlw)mangđến may mắn sức khỏe phù hợp cho người mạng hoả mạng thổ*

-*Sugilite l**àmột viênđáquý vô cùng thúvị*.Đáquý Sugilite tương thích với chakra trán,đỉnhđầu vàtim.

- Với khảnăng nâng cao trực cảm vànăng lượng ngoại cảm của mình,Đáquý Sugilite giúp ta tin tưởng vào giác quan thứsáu của mình. Chính vìvậy, loạiđáquý này cóthểgiúp ta liên kết với thần thánh nên nórất tốt cho việc nhập thiền.

- Mặt khác,Đáquý sugilite cókhảnăng bảo vệnhững tâm hồn nhạy cảm. Rất cóích trong việc giữtỉnh táo, giúp ta hiểuđược lý do ta cómặt trênđời vànhững bài học ta cần học. Sugilite làmột viênđáhoàn hảo cho những ai cảm thấy mình không thuộc vềthếgiới này. Nógiúp tađối mặt với những tình huống khóxửvànỗi sợhãi cũng nhưđộng viên ta chấp nhận những gìmìnhđangđươngđầu.

- Ngoài rađáquý Sugilite còn cótác dụng rất tốt trong việc giảmđau bằng cáchđặt loạiđáquý này vào những chỗđau.

[*Thegioidaquy.net*](https://web.archive.org/web/20141126194715/http://thegioidaquy.net/phongthuy.html)',
    '2014-11-09 09:00:00', 0, 1179, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-040', 'da-phong-thuy-granat', 'Đá phong thủy Granat', 'Thế Giới Đá Quý',
    '/uploads/site_assets/Phongthuy-HoaMocLan-thegioidaquy.jpg', 'Đá phong thủy Granat là loại đá tự nhiên được ưa chuộng nhất hiện nay trong việc chế tạo ra những trang sức mang ý nghĩa phong thủy. Loại đá này có khả năng tăng cường ý chí và đem lại nhiều may mắn cho người đeo.', '-***Đá******phong thủ****y Granat***cótên gọi bắt nguồn từtiếng La Tinh “Granatus” – ý nghĩa làquảlựu vìbềngoài của loạiđáphong thủy này trong rất giống quảlựu.

- Nhắcđến Granat nhiều người vẫn nghĩloạiđánày cómàuđỏsẫm. Nhưng thực tế,Đáphong thủy Granatcórất nhiều màu sắc khác nhau như: màu cam, lục sáng, lam, tía, nâu,đen, hồng vàkhông màu…Hiếm nhất trong sốnày chính làGranat cómàu lam. Thông dụng vàphổbiến nhất vẫn làloạiđáGranat cómàuđỏ. Màu sắc củaĐáGranat tùy theo thành phần kim loại củađábao gồm: Magne, sắt, Canxi, Nhôm.

-*Đá**phong thủy Granat làviênđácủa tình yêu*.Đây làloạiđátựnhiênđượcưa chuộng nhất hiện nay trong việc chếtạo ra những trang sức mang ý nghĩa phong thủy như:[Vòng tayđáGranat](https://web.archive.org/web/20141104221926/http://thegioidaquy.net/phong-thuy/vong-tay-da-granat-13-ly-2955.html#.VE0X1Wd_tlw),[Dây chuyềnđáGranat hay mặt nhẫnđáGranat](https://web.archive.org/web/20141104221926/http://thegioidaquy.net/phong-thuy/day-chuyen-da-granat-1754.html#.VE0ZjGd_tlw)... Tuy cóđộcứng thấp hơn so với Kim cương vànhững loạiđáquý khác, nhưng với cấu tạo hạt vàsợi cực nhỏkết dính vào nhau nên loạiđánày cónhiều lợi thếtrong khâu cắt, mài vàchếtạo. Những viênđánàyđược mài giũa một cách tỉmỉvàtinh xảođểtạo ra những sản phẩm trang sức không chỉcực kỳsang trọng, quyến rũvàcon mang lại những ý nghĩa phong thủy vô cùng to lớn.

*[Dây chuyền phong thủy Đá Granat](https://web.archive.org/web/20141104221926/http://thegioidaquy.net/phong-thuy/day-chuyen-da-granat-tron-436.html#.VE0cUGd_tlw)tăng nét quyến rũ cho phái đẹp*

- Làloạiđácủa sức sống vànghịlực.Đáphong thủy Granatđược biếtđến nhưlàlábùa hộmệnh bảo vệsức khỏe, mangđến may mắn, bình an cho ngườiđeo.

-*Đá**Granat tượng trưng cho tình yêu chân thà**nh*, tin cậy vàbất tận, mang lại may mắn trong tình yêu, tình bạn, khơi dậy lòng dũng cảm, tăng cường ý chícho ngườiđeo cóthểvượt qua mọi trởngại.

- Nhiều người tin rằng,Đeođáphong thủy Granat bên người thìbạn sẽcókhảnăng giao tiếp với thếgiới của những ngườiđã khuất. Nócótác dụng với những người cómong muốn nhìn vào tương lai.

- Theo tương truyền, Ngài Noahđã dùngĐáGranat tímđểthắp sáng con thuyền của ông. Những chiến binh thời cổđại tin rằng**Đáphong thủ****y Granat**sẽgiúp họmang lại chiến thắng.

- Người Ai Cập xưa thường dùngĐáGranat làm trang sức khi sống vàkhi chếtĐáGranat cũngđược chôn theođểbảo vệhọan toàn khi qua thếgiới bên kia.

- Vào thời trung cổ,**con ng****ười mangđáGarnatđểchống lại quái thú**, chấtđộc, thương tích,ác mộng vàchữa những bệnh trầm uất…

- Ngoài ra,ĐáGranat sẽgia tăng quyền lực cho chủsởhữu trong việc giữquyền thống trịngười khác.

- Vòng tay phong thủy**Đá****Granat**cótác dụng rất tốt trong việc giúp phụnữsinh nởđược thuận lợi vàchữa trịnhững bệnh vềtiêu hóa, hô hấp, tuần hoàn vàhệthống miễn dịch.

*[Vòng tay phong thủy Đá Granat](https://web.archive.org/web/20141104221926/http://thegioidaquy.net/phong-thuy/vong-tay-da-granat-12ly-426.html#.VE0bmWd_tlw)giúp điều hòa kinh nguyệt cho phụ nũ*

-***Đ******eo dây chuyền bằngđá****Granat***cóthểgiúpđiều trịbệnh sốt cao, viêm họng vàđauđầu kinh niên.

- Những viênđáGranat màu vàng vànâu cótác dụngđểchữa trịbệnh da liễu, táo bón vàdịứng.

- Ngày nay, nhiều người tin rằngĐáphong thủy Granatcóthểtạo ra một trường bảo vệ, chống lại kẻtrộm vànhững người cóýđồxấu.

- ĐáGranat chính làbiểu tượng của chòm sao Thiên Bình vàThiên Yết trong mười hai cung hoàngđạo.

*[*Thegioidaquy.net*](https://web.archive.org/web/20141104221926/http://thegioidaquy.net/phongthuy.html)*',
    '2014-10-26 09:00:00', 0, 1222, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-041', 'vong-tay-da-phong-thuy', 'Vòng tay đá phong thủy', 'Thế Giới Đá Quý',
    '/uploads/site_assets/Phongthuy-HoaMocLan-thegioidaquy.jpg', 'Bạn có biết vòng tay phong thủy được tạo ra từ những loại đá có trong tự nhiên được xem là một vật phẩm phong thủy thiêng liêng giúp bạn cải thiện số phận, mang lại may mắn, sức khỏe và tài lộc cho người đeo.', '***Vòng tayđáphong thủy***được tạo thành từnhững viênđáquýđược hình thành từsâu trong lòngđất hàng trăm triệu năm. Những viênđánày mang trong mình nguồn năng lượng vàlinh tính rất cao làm cho chiếc vòng tayđáphong thủy không chỉcódáng vẻlung linh tuyệtđẹp màcòn cótác dụng phong thủy rất lớn. Chúng cókhảnăng bảo vệbạn khỏi tácđộng của những thếlực xấu, cải thiện sốphận, mang lại may mắn, tài lộc cho chủsỡhữu.

Vòng tayđáphong thủy với nhiều sản phẩm vàkiểu dángđa dạng từnhững loạiđáquý khác nhau cótrong tựnhiên cóthểtháo mởdễdàng phùhợp với mọi kích cỡtay.Đây làmột món quàthích hợpđểbạn dành tặng cho người yêu thương của mình. Theo phong thủy, nếu chọn trang sức phong thủy bằngđáquý phùhợp với cung mệnh của mệnh của mình sẽmangđến may mắn, cótác dụng hộmệnh…Dođócác cung hoàngđạo nên lưu ý tớiđặc tính của mìnhđểlựa chọn mộtchiếc vòng tayđáphong thủyphùhợp nhất.

[if !supportLists]**1.[endif]Bạch Dương:**

-[Vòngđeo tayđáphong thủy thạch anh trắ](https://web.archive.org/web/20141026174957/http://thegioidaquy.net/phong-thuy/vong-tay-thach-anh-trang-16-ly-1400.html#.VEaAmWd_tlw)[ng](https://web.archive.org/web/20141026174957/http://thegioidaquy.net/phong-thuy/vong-tay-thach-anh-trang-16-ly-1400.html#.VEaAmWd_tlw), ruby thích hợp với Cung hoàngđạo Bạch Dương. Làbiểu tượng của tình yêu vĩnh cửu, tinh khiết vàngây thơ, những viênđánày gắn kết lại mangđến cho bạn sức khỏe vàmay mắn.

**2.[endif]Kim Ngưu:**

[if !supportLists]-[endif]*Vòng tayđeođáphong thủy thạch anh hồng, ngọc bích,đá**sapphire…*thích hợp với Cung hoàngđạo Kim Ngưu. Những viênđánày cótác dụng nhưmột liều thuốc an thần tựnhiên, giúp cho ngườiđeo xóa tan những cảm giác buồn phiền, lo lắng…

*[Vòng tay đá phong thủy Sapphire đủ màu](https://web.archive.org/web/20141026174957/http://thegioidaquy.net/phong-thuy/vong-tay-sapphire-du-mau-8ly-697.html#.VEaDlWd_tlw)giúp cho ngườiđeo xóa tan những cảm giác buồn phiền, lo lắng*

**3.[endif]Song Tử****:**

[if !supportLists]-[endif]Cung hoàngđạo Song Tửthích hợp với nhữngvòngđeo tayđược chếtạo từđácẩm thạchđen,đámặt hổ,đáthạch anh trắng…

[if !supportLists]-[endif]Những màu sắc thích hợp: trắng, nâu,đen, bạc, kem hay hồng.

**4.[endif]CựGiả****i:**

[if !supportLists]-[endif]**Vòngđeo tayđáphong thủy ruby, ngọc bí****ch**thích hợp với cung hoàngđạo Cựgiải.ĐáRuby làbiểu tượng cho sựtình yêu, sựmay mắn,đeo vòng tay cóloạiđánày sẽgiúp cho tình yêu của Cựgiải thêm mặn nồng. Ngoài ra nócòn cótác dụng lưu thông máu.

**5.[endif]Sưtử****:**

[if !supportLists]-[endif]Vòngđeo tayđáphong thủy mắt hổ,đámã não, thạch anh trắng thích hợp với cung hoàngđạo Sưtử

**6.[endif]XữNữ****:**

[if !supportLists]-[endif]Cung hoàngđạo Xửnữthích hợp với những chiếc vòng tayđáSapphire,đámã não...Những viên đánày mangđến cho Xữnữnhữngđiều tốt lành nhất vàbiến giấc mơcủa họthành sựthật.

**7.[endif]Thiên Bì****nh:**

[if !supportLists]-[endif]Vòngđeo tayđámắt mèo, ngọc bích,đásapphire thích hợp với Cung hoàngđạo Thiên Bình.Đặc biệt vòngđeo tayđámắt mèo làbiểu tượng cho hy vọng, hànhđộng, tích cực vàsựthànhđạt.

*[Vòng tay dây rút Đá Ngọc Bích](https://web.archive.org/web/20141026174957/http://thegioidaquy.net/phong-thuy/vong-day-rut-10v-da-ngoc-bich-10-ly-3247.html#.VEaKG2d_tlw)thích hợp với Cung hoàng đạo Thiên Bình*

**8.[endif]Thiên Yế****t:**

[if !supportLists]-[endif]Vòngđeo tayđáthạch anh vàng, thạch anh trắngđục, Topaz thích hợp với Cung hoàngđạo Thiên Yết.

**9.[endif]****Nhân Mã:**

[if !supportLists]-[endif]V*òngđeo tayđángọc lam, thạch anh trắngđụ**c, Topa*z thích hợp với Cung hoàngđạo Nhân Mã

**10.[endif]Ma Kế****t:**

[if !supportLists]-[endif]Vòngđeo tayđáGarnet, thạch anh hồng, thạch anhám khói, ruby,đácẩm thạch thích hợp với Cung hoàngđạo Ma Kết.

**11.[endif]Bảo Bì****nh:**

[if !supportLists]-[endif]Vòngđeo tayđámã não, thạch anh tím,đácẩm thạch, ngọc lam thích hợp với Cung hoàngđạo Bảo Bình.

[if !supportLists]**12.[endif]Song Ngư****:**

[if !supportLists]-[endif]Vòng tayđeođáthạch anh tím,đámắt mèo thích hợp với Cung hoàngđạo Song Ngư.

[*Thegioidaquy.net*](https://web.archive.org/web/20141026174957/http://thegioidaquy.net/phongthuy.html)',
    '2014-10-21 09:00:00', 0, 315, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-042', 'y-nghia-mot-so-mau-sac-theo-phong-thuy-cua-da-thach-anh', 'Ý nghĩa một số màu sắc theo phong thủy của đá thạch anh', 'Thế Giới Đá Quý',
    '/uploads/site_assets/Phongthuy-HoaMocLan-thegioidaquy.jpg', 'Trong phong thủy, đá thạch anh là loại đá thiên nhiên kỳ diệu mang lại may mắn, sức khỏe, giúp gia chủ làm ăn thịnh vượng và phát đạt. Hãy cùng chúng tôi tìm hiểu ý một số màu sắc theo phong thủy của từng loại đá thạch anh này nhé!', '***Đá thạch anh là một viên đá phong thủy***được xem như là báu vật của trời đất do thiên nhiên ban tặng. Nếu đặt đá thạch anh đúng vị trí sẽ tạo ra dòng khí thiêng thu nạp năng lượng dương cực tốt giúp bảo vệ sức khỏe và mang lại nhiều may mắn cho gia chủ.

Đá thạch anh có rất nhiều màu sắc khác nhau và mỗi loại đều có một ý nghĩa phong thủy riêng của nó:

[if !supportLists]**1.[endif]****Thạch anh Tím:**

[if !supportLists]-[endif][Thạch anh tím](https://web.archive.org/web/20260519035840/http://thegioidaquy.net/phong-thuy/qua-cau-da-thach-anh-tim-63-3222.html#.VEFGtWd_tlw)có tên gọi xuất phát từ Hy Lạp Cổ Đại. Đây là một tinh thể quý và hiếm dược đánh giá rất cao trong***dòng họ Thạch anh***. Bởi nó vừa có một vẻ đẹp tự nhiên, vừa mang lại rất nhiều tác dụng kỳ diệu cho người sử dụng.

[if !supportLists]-[endif]Thạch anh tím đem lại sự bình tĩnh, cân bằng cả về thể chất, tinh thần, cảm xúc và tâm linh.

[if !supportLists]-[endif]Là viên đá của sự tinh khiết, trong trắng, ngoài những*ý nghĩa về mặt phong thủy*, thạch anh tím còn có tác dụng chữa nhiều bệnh cho con người như: chống lại sự nghiện rượu, chữa trị chứng mất ngủ, các bệnh về xương khớp, tiêu hóa…Chúng có khả năng kích hoạt, chuyển giao năng lượng, làm dịu tinh thần và lọc máu rất tốt.

[if !supportLists]**2.[endif]****Thạch anh Hồng:**

[if !supportLists]-[endif]**Thạch anh Hồng**được xem là viên đá của tình yêu. Năng lượng của thạch anh này phát ra là loại ánh sáng hồng nhạt có khả năng lôi cuốn người khác và làm cho những người xung quanh yêu thích mình hơn.

[if !supportLists]-[endif]*Theo phong thủy*, đặt Thạch anh Hồng dưới giường ngủ vợ chồng có thể giúp tránh những mối bất hòa có thể xảy ra.

[if !supportLists]-[endif]Ngoài ra Thạch anh Hồng còn giúp tăng cường sự tự tin và khả năng sáng tạo giúp ngủ ngon, xua đuổi muộn phiền, chống lại stress…

*[Đôi uyên ương Thạch anh Hồng](https://web.archive.org/web/20260519035840/http://thegioidaquy.net/phong-thuy/doi-uyen-uong-thach-anh-hong-nho-2659.html#.VEFH5Wd_tlw)kích hoạt vận may cung tình duyên*

[if !supportLists]**3.[endif]****Thạch anh Vàng:**

[if !supportLists]-[endif]Loại thạch anh này rất hiếm trong tự nhiên.***Thạch anh Vàng được gọi là viên đá kinh doanh***bởi nó thường được các chủ nhà hàng, siêu thị, khách sạn để ngay tại quầy thu ngân nhằm thu hút vận may, tài lộc, làm ăn phát đạt

[if !supportLists]-[endif]Thạch anh Vàng có tác dụng giải tỏa sự bế tắc giúp cho tâm hồn thanh thản.

[if !supportLists]**4.[endif]****Thạch anh Đen:**

[if !supportLists]-[endif]**Thạch anh Đen**là loại đá biểu tượng cho khả năng phân tích, khai tâm…Loại đá này có tác dụng trừ tà, giúp hòa đồng với mọi người, xóa tan sự sợ hãi, đem đến sự may mắn và giúp chúng ta vui vẻ, lạc quan trong cuộc sống.

[if !supportLists]-[endif]Năng lượng của Thạch anh Đen rất thích hợp với những người thuộc mạng Thủy, Mộc. Kim.

[if !supportLists]-[endif]Thạch anh Đen rất tốt trong việc điều trị các bệnh về máu và chống đột quỵ

[if !supportLists]**5.[endif]****Thạch anh Trắng:**

[if !supportLists]-[endif]Là loại đá biểu tượng cho tình yêu cao thượng, sắc đẹp, sự trong trắng, ngây thơ…Thạch anh Trắng có phẩm chất âm tính so với tinh thể đá là dương. Do vậy, loại đá này thường được sử dụng để làm dịu và xóa tan những căng thẳng. Có thể nói đây là một trong các loại đá có khả năng chữa trị bệnh tốt nhất.

*[Phật bản mệnh Hư Không Tạng đá Thạch anh Trắng](https://web.archive.org/web/20260519035840/http://thegioidaquy.net/phong-thuy/phat-ban-menh-hu-khong-tang-da-thach-anh-trang-3310.html#.VEFI92d_tlw)đem đến sự may mắn trong cuộc sống và công việc*

[if !supportLists]**6.[endif]****Thạch anh Xanh:**

[if !supportLists]-[endif]Thạch anh xanh giúp xoa dịu cơn giận dữ và lấy lại cảm xúc bình tĩnh. Màu xanh lá cây mang đến một cảm giác cân bằng và hài hòa. Nó là loại đá của may mắn và cơ hội, người ta thường giữ chặt trong lòng 2 bàn tay khi hình dung tiền bạc hoặc may mắn sẽ tìm đến, như là một lời nguyện cầu linh nghiệm.

[if !supportLists]**7.[endif]****Thạch anh Ám khói:**

[if !supportLists]-[endif]Thạch anh Ám khói có tác dụng bảo vệ chủ nhân tránh được những điềm gỡ trong cuộc sống và kinh doanh.

[*Thegioidaquy.net*](https://web.archive.org/web/20260519035840/http://thegioidaquy.net/phongthuy.html)',
    '2014-10-17 09:00:00', 0, 358, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-043', 'nhan-phong-thuy', 'Nhẫn phong thủy', 'Thế Giới Đá Quý',
    '/uploads/site_assets/Phongthuy-HoaMocLan-thegioidaquy.jpg', 'Bạn có biết nhẫn được xem là một vật phẩm phong thủy giúp phát huy sức mạnh ở nhiều khía cạnh như: vận may, tài lộc, tình cảm…Hãy cùng chúng tôi ý nghĩa của nhẫn phong thủy các bạn nhé!', 'Nhưcác bạnđã biết ngày nay**nhẫn**không chỉđơn thuần làmột món trang sức phổbiến dành cho cảnam lẫn nữmànócònđược xem nhưlàmột***vật phẩm phong thủy***.

*Trong phong thủ**y*, việcđeo nhẫnđược xem làmột cáchđểtăng sựmay mắn vàgiảm sựhao tài tổn khícho ngườiđeo.

Vịtríđeo nhẫn cũng quyếtđịnh khánhiềuđến khía cạnh màbạn mong muốn mang lại trong cuộc sống của mình. Khiđeo nhẫn chúng ta nên chọn những ngón thuộc hành sinh cho mạng của mìnhđểđem lại sựmay mắn vàthuận lợi. Những chiếc nhẫnđược làm từđáquý hoặc cóthêm viênđáquýđểlàm mặt nhẫn như:[Nh](https://web.archive.org/web/20141021181533/http://thegioidaquy.net/phong-thuy/nhan-bac-nam-da-sapphire-2-sao-2756.html)[ẫn bạc namđá](https://web.archive.org/web/20141021181533/http://thegioidaquy.net/phong-thuy/nhan-bac-nam-da-sapphire-2-sao-2756.html)[Sapphire 2 sao](https://web.archive.org/web/20141021181533/http://thegioidaquy.net/phong-thuy/nhan-bac-nam-da-sapphire-2-sao-2756.html),[mặt nhẫn TỳHưu Sapphire xanh lam](https://web.archive.org/web/20141021181533/http://thegioidaquy.net/phong-thuy/mat-nhan-Ty-huu-sapphire-xanh-lam-2837.html#.VEEzz2d_tlw),[Nhẫn veđángọc bích Nephrite](https://web.archive.org/web/20141021181533/http://thegioidaquy.net/phong-thuy/nhan-ve-da-ngoc-bich-nephrite-3044.html)…sẽmang lại tác dụng phong thủy rất lớn cho ngườiđeo. Sauđây làmột sốvịtríđeo nhẫn màbạn cần lưu ý:

[if !supportLists]-[endif]Đểtăng uy quyền,đường công danh bạn nên chọn*đeo nhẫnởvịtríngón trỏ*.

[if !supportLists]-[endif]Đeo nhẫnởvịtríngón tayđeo nhẫnđểtăng vậnđào hoađối với những người chưa cógiađình vàcótác dụng tăng sựyêu thươngđối với những ngườiđã cógiađình.

[if !supportLists]-[endif]Nếu chỉtay của bạnđang códấu hiệu hao tài, bạn cóthểđeo một chiếc nhẫn vào ngón giữađểngăn cản sựhao tổnđó.

[if !supportLists]-[endif]Lưu ý**không n****ênđeo nhẫnởvịtríngón tay cá****i**sẽlàm mấtđi sựmạnh mẽ, giàu cóvàkhóthành công trong cuộc sống.

Khiđeo nhẫn theo phong thủycần tuân thủquy tắc: Nam tảnữhữu tức nam thìphảiđeo tay trái, nữthìđeo nhẫnởtay phải thìnócóthểphát huy tác dụng phong thủyđược. Không nên chọnđeo nhẫnởtay không thuậnđểcóthểlàm việc thoải mái màquênđi nguyên tắc trên.

Hiện nay cónhiều loại nhẫn với nhiều màu sắc khác nhau.Đặc biệt các loại nhẫnđáquý cónhiều màu sắcđa dạng, phùhợp với từng bản mệnh.

[if !supportLists]-[endif]Người mệnh Kim nên**đeo nhẫn phong thủ****y**cómàu vàngđậm hoặc nâu hayđácómàu vàng nhưđáthạch anh vàng…Những chiếc nhẫn này sẽcótác dụng nuôi dưỡng, vàđemđến sức khỏe cho ngườiđeo.

*[Mặt nhẫn Tỳ Hưu thạch anh tóc vàng](https://web.archive.org/web/20141021181533/http://thegioidaquy.net/phong-thuy/Mat-nhan-ty-huu-thach-anh-toc-vang-18-2974.html#.VEE0kmd_tlw)đem lại tài lộc, phù hợp cho người mạng Thổ và mạng Kim*

[if !supportLists]-[endif]Người mệnh Mộc nên chọnđeo nhẫn phong thủy cómàu xanh nước biển,đen, tím xanh, xanh lácây.Điển hình làcác loạiđáquý cómàu xanh nhưđáSapphire,đáTopaz, ngọc lục bảo…Những màu này sẽnuôi dưỡng mộc, mangđến sức khỏe, tiền tài cho những người thuộc bản mệnh này. Ngoài ra bạn cũng cóthểchọn những gam màu nhưmàu nâu, vàngđậm bởi vìMộc chếkhắcđược Thổ.

[if !supportLists]-[endif]Đểđược tương hợp, người mệnh Thủy nên chọn nhẫnđáquý cómàu của mệnh Thủy vàchọnđáquý thuộc hành kim theo quy luật tương sinh của ngũhành. Những chiếc nhẫnđáquý cómàu trắng hoặc màuđen nhưđá mã não đen, sapphiređen,đáonyx…, màu xanh nhưđáTopaz…cũng rất hợpđối với người thuộc bản mệnh này.

*[Nhẫn đá mã não đen mặt tròn](https://web.archive.org/web/20141021181533/http://thegioidaquy.net/phong-thuy/nhan-da-ma-nao-den-mat-tron-3080.html#.VEE2Bmd_tlw)đem lại may mắn cho người đeo*

[if !supportLists]-[endif]Người mệnh Hỏa nênđeo nhẫnđáphong thủy cótông màu thuộc hành hỏa nhưtím,đỏ,cam, hồng…Những gam màu này sẽmangđến nguồn năng lượng mới, thểhiện cho sức mạnh, sựđam mê. Bạn cóthểchọn những loạiđásau:đáthạch anh tím,đáruby,đáthạch anh hồng…Ngoài ra theo quy luật tương sinh của Ngũhành, những gam màu như: xanh lácây, xanh da trời cũng rất hợp với người mệnh Hỏa bởi Mộc sinh Hỏa. Bạn cóthểchọn cho mình một chiếc nhẫnđáquý phong thủy bằng ngọc lục bảo,đáperidot,đáthạch anh xanh….

[if !supportLists]-[endif]Người mệnh Thổnênđeo nhẫnđáquý phong thủy cómàu tím,đỏ, vàng nhạt, nâu. Những gam màu này sẽcótác dụng đem lại sự thịnh vượng, may mắn và sức khỏe cho người đeo.

[*Thegioidaquy.net*](https://web.archive.org/web/20141021181533/http://thegioidaquy.net/phongthuy.html)',
    '2014-10-17 09:00:00', 0, 401, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-044', 'da-phong-thuy-chalcedony', 'Đá phong thủy Chalcedony', 'Thế Giới Đá Quý',
    '/uploads/news/art-048-1-1-mat-quan-am-dong-tu-chalcedony-xanh-day-0.jpg', 'Theo phong thủy, Đá Chalcedony được xem là bùa hộ mệnh cho những người đi biển. Ngoài ra, Chalcedonn còn được coi là viên đá của tình yêu, thu hút trái tim của người đàn ông về phía phụ nữ.', 'Tên gọi của**đáquý Chalcedon**được bắt nguồn từchữcalxedon hoặc calchedon (một cảng biển cổởvùng Marmara).*Chalcedon l**àbiến thểvi tinh của thạ**ch anh*. Với màu sắc hấp dẫn vàcóđộcứng cao nên loạiđánày thườngđược dùng cho mụcđích trang trívàchạm khắc.

ĐáChalcedon làloạiđácóhoa văn vàmàu sắc kháđặc biệt,được coi làđánửa quý. Chalcedon thườngđược dùngđểgọi những viênđácótông màu nhạt như: màu xanh da trời sữa, xanh da trời phớt xanh lácây, phớt vàng…)

**1. Một sốbiến thểchính củaĐá****Chalcedon:**

- Carnelian: Làbiến thểmàuđỏcủa**Đá****Chalcedon**,đôi khi chúng cómàuđỏnâu hoặc màu camđậm.

- Sard: Làbiến thểmàu nâuđỏtới nâu củaĐáChalcedon. Nhưng so với Carnelian thìSard thường cómàuđậm vànâu hơn.Đa sốSard trên thịtrường hiện nay làdo nhuộm màu.

- Chrysopas: LàloạiĐáChalcedon cómàu lục.

- Bloodstone (Đámáu): LàloạiĐáChalcedon cómàu lục với cácđốm vàsọc dải màuđỏ.

- Agat:*L**àloạiĐáChalcedon cócấu trúc màu dạng sọ**c*. Agat thường bánđục, tuy nhiênởdạng các lớp mỏng ta cóthểthấy chúng bán trong. Màu của Agat tựnhiên thường mờ, ranh giới giữa các màu thường không rõ rang vàngười ta thường dùng phương pháp nhuộm màuđểcho Agat cómàu sốngđộng hơn.

- Agat dạng cành cây (Dendritic Agate): Làloại Chalcedon cómàu trắng hoặc trắng xám với các cấu trúc dạng cành cây.

- Agat dạng rêu (Moss Agate): Làtên gọi của loại Chalcedon không màu, bán trong cóchứa các bào thểhorblen hoặc clorit màu lục, trông rất giống dạng rêu mờ.

- Onyx: Làloại Chalcedon cóhai lớp màu với phần nền cómàuđen vàlớp bên trên cómàu trắng.

- Jasper: Làtên gọi biến thểnằm giữa Thạch anh vàChalcedon. Ta cóthểgọi chúng làloạiChalcedoncócấu trúc hạt.

[![mat-Quan-Am-Dong-Tu-Chalcedony-xanh-day](/uploads/news/art-048-1-1-mat-quan-am-dong-tu-chalcedony-xanh-day-0.jpg)](https://web.archive.org/web/20141021181521/http://thegioidaquy.net/phong-thuy/mat-Quan-Am-Dong-Tu-Chalcedony-xanh-day-2851.html#.VD6UYWd_tlw)

*[Mặt quan âm đồng tử đá Chalcedony](https://web.archive.org/web/20141021181521/http://thegioidaquy.net/phong-thuy/mat-Quan-Am-Dong-Tu-Chalcedony-xanh-day-2851.html#.VD6UYWd_tlw)đem lại nhiều may mắn cho người đeo*

**2. Công dụngđá****Chalcedon:**

**- Theo phong thủ****y**,ĐáChalcedon chứa trong mình các túi khívàete. Vìvậy loạiđánày cótác dụng mangđến sựbình tĩnh cho ngườiđeo. Dođóđối với những người dễbịkíchđộng thìnênđeođồtrang sức bằngđáChalcedon như:[mặt nhẫn tỳhưu Chalcedon](https://web.archive.org/web/20141021181521/http://thegioidaquy.net/phong-thuy/mat-nhan-Ty-Huu-Chalcedony-vang-2853.ht),[mặt Quan Âmđồng tửChalcedon](https://web.archive.org/web/20141021181521/http://thegioidaquy.net/phong-thuy/mat-Quan-Am-Dong-Tu-Chalcedony-do-day-2852.html),[mặt Quan Công đá Chalcedon](https://web.archive.org/web/20141021181521/http://thegioidaquy.net/phong-thuy/quan-cong-da-chalcedony-do-2761.html#.VD6T-2d_tlw)….

[![vong-tay-da-chalcedony-xanh-12-ly-0](/uploads/news/art-048-2-1-vong-tay-da-chalcedony-xanh-12-ly-0.jpg)](https://web.archive.org/web/20141021181521/http://thegioidaquy.net/phong-thuy/vong-tay-da-chalcedony-xanh-12-ly-2744.html#.VD6Vkmd_tlw)

*[Vòng tay Đá Chalcedony phong thủy](https://web.archive.org/web/20141021181521/http://thegioidaquy.net/phong-thuy/vong-tay-da-chalcedony-xanh-12-ly-2744.html#.VD6Vkmd_tlw)làm giảm căng thẳng, mang lại sự bình tĩnh cho người đeo*

-**Đá****Chalcedon**còn cótác dụng giúpđiều trịbệnh trầm uất vàcác chứng loạn thần kinh.

-*Đá**phong thủ**y Chalcedon*làbiểu tượng của chòm sao Nhân Mã trong mười hai Cung hoàngđạo.

- Chalcedon màu xanh da trời trong phong thủy cókhảnăng xua tan sựsợhãi,đemđến cho ngườiđeo niềm tin vào sức mạnh của bản thân, giải thoát họkhỏi những cơn sầu muộn, giận dữ.

- Ngoài raĐáChalcedon cònđược coi làbùa hộmệnh cho những ngườiđi biển.

- ĐáChalcedon mang trong mình tính nữ. Dođóviênđánàyđược xem làviênđácủa tình yêu, thu hút trái tim của ngườiđàn ông vềphía phụnữ.

*[*Thegioidaquy.net*](https://web.archive.org/web/20141021181521/http://thegioidaquy.net/phongthuy.html)*',
    '2014-10-15 09:00:00', 0, 444, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-045', 'y-nghia-phong-thuy-cua-da-quy-theo-thang-sinh', 'Ý nghĩa phong thủy của đá quý theo tháng sinh', 'Thế Giới Đá Quý',
    '/uploads/news/art-049-1-1-mat-nhan-da-thach-anh-tim-chu-nhat-giac-0.jpg', 'Trong phong thủy, mỗi loại đá quý đều mang một ý nghĩa tượng trưng cho từng tháng sinh của con người trong năm. Hãy cùng chúng tôi khám phá xem ý nghĩa thần bí của từng loại đá quý này nhé!', '***Theo phong thủy phương Tây***, mỗi tháng sinh trong năm đều được biểu tượng bởi mỗi loại đá quý riêng. Nếu chọn được viênđáquý phùhợp tươngứng với tháng sinh của mình sẽ mang đến cho bạn sự may mắn, giúp bạn vượt qua được mọi khó khăn.

[if !supportLists]**1.**[endif]**Tháng 1:Đá Garnet (Ngọc Hồng Lựu)**

-**[Ngọc Hồng Lựu](https://web.archive.org/web/20141018044154/http://thegioidaquy.net/phong-thuy/da-garnet-do-mai-giac-3320.html#.VDl6P2d_tlw)**cómàuđỏthẫm tượng trưng cho tình yêu vợchồng, làbiểu tượng của lòng chung thủy.*Lo**ạiđáquý này cótác dụng mangđến may mắn trong tình yê**u*, tình bạn vàngăn chặn kẻthùtấn công bạn.

- Viênđánàyđược dùng làm kỷniệm 2 năm ngày cưới.

[if !supportLists]**2.**[endif]**Tháng 2:Đá Amethyst (Thạch Anh Tím)**

-Đáthạch anh tímlàbiểu tượng của sựkhôn ngoan, sức mạnh vàtựtin.Đeo thạch anh tím trên người sẽbảo vệta tránh khỏi những sựtấn công vềmặt tinh thần cũng nhưnhững tổn hại khác, giúp ta bình tĩnh vàlinh hoạt hơn,đem lại nhiều vận may.

- Viênđánàyđược dùng làm kỷniệm 6 năm ngày cưới.

[![mat-nhan-da-thach-anh-tim-chu-nhat-giac](/uploads/news/art-049-1-1-mat-nhan-da-thach-anh-tim-chu-nhat-giac-0.jpg)](https://web.archive.org/web/20141018044154/http://thegioidaquy.net/phong-thuy/Mat-da-thach-anh-tim-chu-nhat-giac-3305.html#.VDl6e2d_tlw)

*[Mặt nhẫn đá thạch anh tím](https://web.archive.org/web/20141018044154/http://thegioidaquy.net/phong-thuy/Mat-da-thach-anh-tim-chu-nhat-giac-3305.html#.VDl6e2d_tlw)đem lại vận may cho người đeo*

[if !supportLists]**3.**[endif]**Th****á****ng 3:****Đá****Aquamarine (Ng****ọ****c Xanh Bi****ể****n)**

- Ngọc xanh biển,đúng nhưvới tên gọi của nó, loạiđánày tượng trưng cho sựhòa bình vàyên tĩnh.**Lo****ạiđánàyđược xem làbùa may mắ****n**cho những ngườiđi biển, bảo vệta chống lại những thiên tai, bệnh tật.

- Viênđánàyđược dùng làm kỷniệm 19 năm ngày cưới.

[if !supportLists]**4.**[endif]**Th****á****ng 4: Diamond (Kim C****ươ****ng)**

- Viênđáquý này làsựgắn kết giữa sức mạnh vàsựmay mắn, mang ý nghĩa vềsựvĩnh cửu trong tình yêu. Một tình yêu hoàn hảo, trong sáng vàthuần khiết. Qua nhiều thếkỷ, kim cươngđã trởthành món quàtối thượng của tình yêu.

-Viênđánàyđược dùng làm kỷniệm 10 năm và60 năm ngày cưới.

[if !supportLists]**5.**[endif]**Th****á****ng 5:****Đá****Emerald (Ng****ọ****c L****ụ****c B****ả****o)**

Với màu xanh lácây thuần khiết, ngọc lục bảođược xem làNữhoàng của các loạiđá. Nótượng trưng cho tình yêu vàhạnh phúc. Tương truyền ngọc lục bảo cókhảnăng dựđoánđược tương lai, tăng cường trínhớvàkhảnăng phánđoán.

- Viênđánàyđược dùng làm kỷniệm 20 năm và35 năm ngày cưới.

[if !supportLists]**6.**[endif]**Th****á****ng 6:****Đá****Pearl (Ng****ọ****c Trai)**

- Ngọc traiđược vínhư**vi****ênđácủa mặt tră****ng**, làbiểu tượng của sựmay mắn, mangđến sựthong thái, tình yêu vàsức khỏe cho ngườiđeo. Ngọc trai thườngđược nhưmột món quàcưới. Bởi chúng còn làhìnhảnh tượng trưng cho một cuộc hôn nhân hạnh phúc.

- Viênđánàyđược dùng làm kỷniệm 3 năm ngày cưới.

[if !supportLists]**7.**[endif]**Th****á****ng 7:****Đá****Ruby (H****ồ****ng Ng****ọ****c)**

*ĐáRubyđược mệnh danh là“Vua của các loạiđá*”.**Theo phong th****ủ****y**, Ruby chính làgiọt tinh huyết củađất trời với ý nghĩa mang lại may mắn vàthành công cho ngườiđeo. Ngoài ra viênđánày còn cógiúp cho tình yêu của bạnđược mặn nồng.

- Viênđánàyđược dùng làm kỷniệm 15 năm và40 năm ngày cưới.

*[Mặt Di Lặc đá Ruby](https://web.archive.org/web/20141018044154/http://thegioidaquy.net/phong-thuy/mat-di-lac-da-ruby-18-3026.html#.VDl7c2d_tlw)mang lại sức khỏe và giảm stress cho người đeo*

[if !supportLists]**8.**[endif]**Th****á****ng 8:****Đá****Reridot (Ng****ọ****c c****ả****n lãm)**

- Làloạiđátượng trưng cho lòng nhiệt tình, khoan dung, giúp cân bằng cảm xúc vàchữa lành những vết thương tình cảm.

- Thời cổđại, Viênđánày cósức mạnh bảo vệngườiđeo tránhđược sựnguy hiểm vàđốkỵ.

- Viênđánàyđược dùng làm kỷniệm 16 năm ngày cưới.

[if !supportLists]**9.**[endif]**Th****á****ng 9:****Đá****Sapphire**

-Làviênđácủađịnh mệnh, mangđến sựmay mắn trong tình yêu,đại diện cho lòng trung thành vàniềm hy vọng.

[if !supportLists]**10.**[endif]**Th****á****ng 10:****Đá****Opal (****Đá****m****ắ****t m****è****o)**

- Opal biểu tượng cho sựhy vọng, hànhđộng tích cực vàthànhđạt.

[if !supportLists]**11.**[endif]**Th****á****ng 11:****Đá****Citrie**

-ĐáCitrie tượng trưng cho lòng trung thành, mangđến sựấmáp cho cuộc sống của bạn. Loạiđánày cókhảnăng chữa bệnh rất tốt. Giảm stress,điều tiết cơn giận, xua tan những u mêvàcải thiện thịlực.

[if !supportLists]**12.**[endif]**Th****á****ng 12:****Đá****Topaz xanh d****ươ****ng**

**- Theo phong thủy**, loạiđánày cókhảnăng thu hút tiền bạc, thành công vàtình yêu. Người xưa cho rằng, khi loạiđánày ngảsang màu khác thìđólàsựcảnh báo chon guy hiểm hoặc bệnh tật.

[*Thegioidaquy.net*](https://web.archive.org/web/20141018044154/http://thegioidaquy.net/phongthuy.html)',
    '2014-10-12 09:00:00', 0, 487, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-046', 'cach-lua-chon-da-quy-theo-phong-thuy', 'Cách lựa chọn đá quý theo phong thủy', 'Thế Giới Đá Quý',
    '/uploads/news/art-050-1-1-vong-tay-da-granat-12-ly-0.jpg', 'Trên thị trường hiện nay có rất nhiều loại đá quý. Nhưng không phải loại nào cũng có tác dụng phong thủy. Theo quan niệm dân gian, việc chọn lựa được đá quý theo phong thủy phù hợp với bản mệnh sẽ mang đến những may mắn, niềm tin và sức khỏe cho con người.', '-***Theo phong th****ủ****y***,[**đáquý**](https://web.archive.org/web/20141018042227/http://thegioidaquy.net/phongthuy.html)làloạiđáđược dùngđểxuađuổi tàma, cũng nhưxuađuổi nhữngđiềm xấu ra khỏi cuộc sống của con người. Loạiđánàyđược nuôi dưỡng hàng triệu năm từsâu trong lòngđất bởi mẹthiên nhiên, mang trong mình thiên nắng của trờiđất. Chính vìlẽđó,**đáquý**đã trởthành một vật tâm linh của con người với hy vọng sẽmangđến cho người sởhữu những may mắn vàniềm tin vững chắc trong cuộc sống.

-[ĐáThạch anh](https://web.archive.org/web/20141018042227/http://thegioidaquy.net/phong-thuy/da-phongthuy-23-Da-Thach-Anh),[đá Sapphire](https://web.archive.org/web/20141018042227/http://thegioidaquy.net/phong-thuy/da-phongthuy-119-Da-Sapphire),[đáRuby](https://web.archive.org/web/20141018042227/http://thegioidaquy.net/phong-thuy/da-phongthuy-120-Da-Ruby),[đángọc bích](thegioidaquy.net/phong-thuy/da-phongthuy-260-Ngoc-bich-Nephrite),đáCẩm thạch… làmột trong những loạiđáquý nổi tiếng cókhảnăng phong thủy caođược mọi ngườiưa chuộng hiện nay.

**1. Ch****ọ****n****đá****quý theo th****á****ng sinh - theo phong thuỷ phương Tây:**

**Theo phong thủ****y phương Tây**, mỗi tháng sinh trong nămđềuđược biểu tượng bởi mỗi loạiđáquý riêng. Cụthểnhưsau:

[if !supportLists]-[endif]Tháng 1:ĐáGarnet (Ngọc Hồng Lựu)

[if !supportLists]-[endif]Tháng 2:ĐáAmethyst (Thạch Anh Tím)

[if !supportLists]-[endif]Tháng 3:ĐáAquamarine (Ngọc Xanh Biển)

[if !supportLists]-[endif]Tháng 4: Diamond (Kim Cương)

[if !supportLists]-[endif]Tháng 5:ĐáEmerald (Ngọc Lục Bảo)

[if !supportLists]-[endif]Tháng 6:ĐáPearl (Ngọc Trai)

[if !supportLists]-[endif]Tháng 7:ĐáRuby (Hồng Ngọc)

[if !supportLists]-[endif]Tháng 8:ĐáReridot (Ngọc cản lãm)

[if !supportLists]-[endif]Tháng 9:ĐáSapphire

[if !supportLists]-[endif]Tháng 10:ĐáOpal (Đámắt mèo)

[if !supportLists]-[endif]Tháng 11:ĐáCitrie

[if !supportLists]-[endif]Tháng 12:ĐáTopaz xanh dương

Nếu chọnđượcviênđáquý phùhợp tươngứng với tháng sinhcủa mình sẽmangđến cho bạn sựmay mắn, giúp bạn vượt quađược mọi khókhăn.

[![vong-tay-da-Granat-12-ly](/uploads/news/art-050-1-1-vong-tay-da-granat-12-ly-0.jpg)](https://web.archive.org/web/20141018042227/http://thegioidaquy.net/phong-thuy/vong-tay-da-granat-12ly-426.html#.VDQjv2d_tlw)

*[Vòng tay đá granat phong thuỷ](https://web.archive.org/web/20141018042227/http://thegioidaquy.net/phong-thuy/vong-tay-da-granat-12ly-426.html#.VDQjv2d_tlw)giúp điều hoà kinh nguyệt cho phụ nữ.*

**2. Ch****ọ****n m****à****u s****ắ****c****đá****quý ph****ù****h****ợ****p v****ớ****i cung m****ệ****nh - theo phong thuỷ phương Đông:**

- Khác với phong thuỷ phương Tây chọnđáquý theo tháng sinh, thì phong thuỷ phương Đông coi trọng phong thuỷ hơn, tính theo năm sinh, ngũ hành để chọnđáquý cómàu sắc phùhợp với cung mệnh,*phong thủy*tương sinh tương hợp mang lại sức khỏe, may mắn vàhưng vượng cho ngườiđeo.

- Theo nguyên lý phong thủy Châu Á, môi trường tự nhiên gồm 5 yếu tố: Kim, Mộc Thủy, Hỏa, Thổ. Mỗi yếu tốđều cónhững màu sắcđặc trưng.

+**Ng****ười mệnh Kim nênđeođá****quý**cómàu vàng sậm, nâuđất, vàng, vàng cam, vàng chanh, màu trắng như gỗhóa thạch vàng nâu,đámắt hổ vàng nâu,đáthạch anh vàng Citrine, đá thạch anh tóc vàng, đá thạch anh trắng...

+**Đá quý chongười mệnh Mộc**: VìThủy sinh Mộc nênđối với những người thuộc cung mệnh này thì*các loạiđáquý cómàuđen, xanh nước biển, xanh da trời, xanh lam,**xanh lá**cây, xanh lục, xanh ngọc*làthích hợp nhất cótác dụng xua tan mọi lo lắng cho ngườiđeo.

+**Người mệnh Thủy hợp với đá nào**: những đá có màu trắng, bạc,đen, xanh nước biển. Dođó, các loạiđáquý như: Kim cương, Lapis lazuli, Sapphire xanh, Sapphire đen, Sapphire trắng, Aquamarine, Topaz xanh dương, đá thạch anh trắng... lànhững viênđátuyệt vời bởi chúng cómàu sắc phùhợp với bản mệnh của bạn.

+**Nh****ững viênngọc quý như****đá ngọc bích**rất thích hợp với**người mệnh Hỏa**bởi trong ngũhành Mộc sẽsinh Hỏa. Ngoài ra các loạiđáquý cómàuđỏ, hồng, tím nhưThạch Anh Tím, Thạch anh tóc đỏ, Ruby… làmàu bản mệnh của mệnh Hỏa sẽmang lại may mắn, hưng thịnh cho người thuộc mệnh này.

+**Ngườimệnh Th****ổ đeo đá quý gì**:theo nguyên lý ngũhành, Hỏa sẽsinh Thổ, cho nên**ng****ười mệnh Thổthích hợpđeo những viênđáquý cómàu của Hỏ****a**(Đỏ, hồng, tím) và màu vàng nhưđáruby, đá thạch anh tím, đá thạch anh tóc đỏ, đá thạch anh tóc vàng, đá thạch anh vàng, đá mắt hổ vàng, đá sapphire vàng…

[![mat-nhan-Ty-huu-sapphire-xanh-lam-](/uploads/news/art-050-2-1-mat-nhan-ty-huu-sapphire-xanh-lam-0.jpg)](https://web.archive.org/web/20141018042227/http://thegioidaquy.net/phong-thuy/mat-nhan-Ty-huu-sapphire-xanh-lam-2837.html#.VDQixWd_tlw)

*[Mặt Tỳ hưu Sapphire phong thuỷ](https://web.archive.org/web/20141018042227/http://thegioidaquy.net/phong-thuy/mat-nhan-Ty-huu-sapphire-xanh-lam-2837.html#.VDQixWd_tlw)đem lại may mắn thịnh vượng*

Cóthểnói việc**l****ựa chọnđáquý theo phong thủ****y**phùhợp với**b****ản mệ****nh**của mình làđiều rất quan trọng. Bởi nókhông chỉgiúp bạn tôn lên nét quyến rũmàconđem lại nhiều may mắn.

*[*Thegioidaquy.net*](https://web.archive.org/web/20141018042227/http://thegioidaquy.net/phongthuy.html)*',
    '2014-10-08 09:00:00', 0, 530, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-047', 'y-nghia-phong-thuy-da-cam-thach', 'Ý nghĩa phong thủy Đá Cẩm Thạch', 'Thế Giới Đá Quý',
    '/uploads/site_assets/Phongthuy-HoaMocLan-thegioidaquy.jpg', 'Trong phong thủy, Cẩm thạch là loại đá quý rất được mọi người ưa chuộng từ xưa đến nay với ý nghĩa sẽ mang lại may mắn, xua đuổi tà ma mang đến cảm giác yên bình cho người đeo.', '- Người dân Việt Nam từ xưa đến nay rấtưa chuộng***ĐáCẩm Thạch***. Họđã chọn trang sức bằngĐáCẩm Thạchđểlàm phụkiện cho mình như:[m](https://web.archive.org/web/20141018044213/http://thegioidaquy.net/phong-thuy/phat-ban-menh-van-thu-da-cam-thach-xanh-3198.html#.VDFj9Gd_tlw)[ặt Phật bản mệnh Văn Thùđácẩm thạ](https://web.archive.org/web/20141018044213/http://thegioidaquy.net/phong-thuy/phat-ban-menh-van-thu-da-cam-thach-xanh-3198.html#.VDFj9Gd_tlw)[ch xanh](https://web.archive.org/web/20141018044213/http://thegioidaquy.net/phong-thuy/phat-ban-menh-van-thu-da-cam-thach-xanh-3198.html#.VDFj9Gd_tlw),[vòng tay dây rút hoa mẫuđơnđácẩm thạch](https://web.archive.org/web/20141018044213/http://thegioidaquy.net/phong-thuy/vong-day-rut-hoa-mau-don-cam-thach-3112.html)… vàgiữgìn nhưbáu vật. Bởi họcho rằng việcđeoĐáCẩm Thạch trên người sẽtốt cho vận khí, tài lộc, sức khỏe.

- Cẩm thạch cònđược gọi là“Đátrời” mangđến sựtinh khiết, ngọt ngào,đem lại sựan tâm vàgiảm bớt căng thẳng cho ngườiđeo.

-**Trong phong th****ủ****y**,ĐáCẩm Thạchđược sửdụng trong nhiều thếkỷqua bởi loạiđánày cótác dụng làm hài hòa các khía cạnh trong cuộc sống,  xuađuổi tàma, làm cho ngườiđeo cảm thấy an tâm, hạnh phúc vàtrànđầy năng lượng.

*[Mặt dây chuyền Phật bản mệnh Văn Thù đá cẩm thạch xanh](https://web.archive.org/web/20141018044213/http://thegioidaquy.net/phong-thuy/phat-ban-menh-van-thu-da-cam-thach-xanh-3198.html#.VDFkxWd_tlw)mang đến sự may mắn, giúp học hành thi cử được thuận lợi*

- Một trong những mónđồtrang sức bằngĐácẩm thạchcực tốt màbạn nên thường xuyênđeođólàhình tượngĐức Phật. Nam thìnênđeo các mặt ngọc cẩm thạch cóhìnhĐức Quan ThếÂm, nữthìnênđeo mặt hìnhĐức Phật Di Lặc.

+ Bởi trong một giađình người nam làchủngoại thường xuyên ngoại giao bên ngoài nhiều nên dễphát sinh gặp nhiều tình huống xấu. Dođó, Quan ThếÂm BồTát làvịBồTát “Cứu khổcứu nạn” sẽphùhộvàgiúpđỡngườiđeo vượt qua mọi kiếp nạn một cách nhanh chóng vàkịp thời, gặp hung hóa cát, gặp nạn hóa lành.

+ Người nữthích hợpđẹo Ngọc Phật Di Lặc tứcđểnhắc nhởhọcần học hỏi theoĐức Phật, cólòng dạkhoángđạt, rộng lượng, bao dung, biết tha thứ, khôngđốkỵ, thịphị, miệng luôn tươi cười vàvui vẻ, hài lòng với cuộc sống của mình.

*[Mặt dây chuyền Di Lặc đá cẩm thạch xanh lớn](https://web.archive.org/web/20141018044213/http://thegioidaquy.net/phong-thuy/di-lac-da-cam-thach-xanh-lon-3039.html#.VDFm0Wd_tlw)mang lại tài lộc, may mắn và thành công cho người đeo.*

-**M****ụcđích của việcđeođồtrang sức cẩm thạ****ch**làđểluôn bảo vệbạn. Dođóchúng ta nênđeo chúng cảngày lẫnđêm, tránh tình trạng thích thìđeo, còn không thìcởi ra vàđểlung tung, tùy tiện. Tuy nhiên bạn nên chúý rằng, nếu bạnđeo trang sứcđácẩm thạchcóhìnhảnh củaĐức Phật thìbạn nên cởi ra, vàđặtởnhững vịtrícao ráo, sạch sẽtrước khi vào nhàtắm, nhàvệsinh.Đóchính làthểhiện sựtôn kính của bạnđối vớiĐức Phật.

**- Ý nghĩa màu sắc củaĐácẩm thạch trong phong thủy:**

+ Cẩm thạch màu xanh lácây truyền thống: giải quyết những bếtắc trong quan hệtình cảm vànhững hiểu lầm.

+ Cẩm thạch màuđỏ: tăng cường vận may trong tình cảm

+ Cẩm thạch trắng: giảm bớt căng thẳng, lo âu, mang lại sựbình yên trong tâm hồn

+ Cẩm thạch màu vàng: mangđến nguồn năng lượng dồi dào, thích hợp với những người thiếu nghịlực,ùlìhay mắc bệnh trầm cảm.

- Cần lưu ý rằng, tránh đeo cẩm thạch bị bể vỡ vì như thế nó sẽ mất tác dụng phong thủy. Nên chọn loại cẩm thạch phù hợp với cung mệnh của bạn khi mua.

- Ngoài những lợiích vềmặtphong thủy,*Đácẩm thạch*còn cótác dụng rất nhiều trong việc chữa bệnh, giúp loại bỏđộc tốkhỏi cơthể, chữa trịcác bệnh vềtiết niệu vàbàng quang. Ngoài ra nócũng cótác dụng giảmđauởcác khớp vàcơbắp.

- Các loạiđáquý cẩm thạch cókhảnăng phục hồi vàcân bằng năng lượng trong chu trình sinh sản, bảo vệthai nhi vàngười mẹđược bình an, giảm chứngđau bụng trong khi hành kinhởphụnữ.

*[Vòng tay mẫu đơn phong thủy đá cẩm thạch](https://web.archive.org/web/20141018044213/http://thegioidaquy.net/phong-thuy/vong-day-rut-hoa-mau-don-cam-thach-3112.html#.VDFl5Gd_tlw)mang lại nhiều may mắn về tình duyên*

- Cóthểnói,**Đácẩm thạch làmột loạiđárất tố****t**, mangđến rất nhiều lợiích cho cơthểbạn. Nócókhảnăng xua đuổi tà ma,đồng thời mang lại may mắn cho người sửdụng nó. Dođónếu bạn khôngđeođược nóbên mình thìbạn hãy chọnđặt nóởvịtrítốt nhất của cung hoàngđạo trong nhàhay văn phòng…đểmang lại may mắn.

[*Thegioidaquy.net*](https://web.archive.org/web/20141018044213/http://thegioidaquy.net/phongthuy.html)',
    '2014-10-05 09:00:00', 0, 573, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-048', 'choi-go-hoa-thach-hang-trieu-nam-tuoi', 'Chơi gỗ hoá thạch hàng triệu năm tuổi', 'Thế Giới Đá Quý',
    '/uploads/news/art-052-1-go-hoa-thach-trieu-nam.jpg', 'Gỗ hoá thạch đang được nhiều người chơi đá sưu tầm. Nguyên tắc cho việc lựa chọn gỗ hoá thạch làm cảnh là đá phải đẹp, đá phải đáp ứng một trong các tiêu chuẩn như Sấu, Thẩm, Lộ, Thấu.', '## Gỗ hoá thạch trong nghiên cứu khoa học

Trong một cuộc  săn tìm kim cương ở vùng bắc Canada đã tìm thấy một khúc[**gỗ hoá thạch**](thegioidaquy.net/phong-thuy/da-phongthuy-236-Go-hoa-thach-Fossil-wood-)**Tùng bách**nằm trong đá núi lửa suốt hơn 50 triệu năm.

**Gỗ hóa  thạch**hiếm hoi này khi phát hiện đã giúp giới chuyên gia tìm hiểu được khí hậu thời  đầu kỷ Ecocene, kéo dài từ 34 đến 56 triệu năm trước. Theo đó khu vực  đầy băng giá này từng có quá khứ là đầm lầy.

[![go-hoa-thach-triieu-nam](/uploads/news/art-052-1-go-hoa-thach-trieu-nam.jpg)](https://web.archive.org/web/20141007070245/http://thegioidaquy.net/tin-tuc/choi-go-hoa-thach-hang-trieu-nam-tuoi-1919.html)

*Gỗ hoá thạch có niên đại từ 34 - 56 triệu năm.*

Khúc**gỗ hoá thạch**đã được tìm thấy bên trong dãy đá  kimberlite, một dạng đá núi lửa đặc biệt do đôi khi có chứa kim cương,  gọi là mạch Gấu trúc nằm ở độ sâu 315m ở mỏ kim cương Ekati, thuộc phía  nam vùng cực bắc thuộc Lãnh thổ phía bắc của Canada.

Theo báo cáo đăng trên chuyên san PLoS  ONE, khu vực chứa mạch Gấu trúc vào thời đầu của thể Eocene từng được  bao phủ bởi một rừng Thủy sam, giống như gỗ Tùng bách sậm ngày nay.

Một vụ phun trào kimberlite diễn ra  khoảng 53,3 triệu năm trước đã mở toang một lỗ hổng xuyên tới bề mặt  Trái đất, “nuốt” một số loại gỗ này, theo trưởng nhóm nghiên cứu Alex  Wolfe của Đại học Alberta (Canada).

Do lớp**gỗ hóa thạch**được bảo quản hoàn hảo, nó  cho phép giới khoa học hình dung một bức tranh toàn thể rõ ràng hơn về  khí hậu vào thời đầu thể Eocene.

## Thú chơi gỗ hoá thạch ngày nay

Ngoài nghiên cứu khoa học thì ngày nay,**gỗ hoá thạch**đang được nhiều người chơi đá sưu tầm. Gỗ hoá thạch non tuổi còn gọi là gỗ hoá thạch mềm, gỗ hoá thạch bột sẽ đề cập ở bài viết khác, bài viết này chỉ đề cập đến gỗ hoá thạch lâu năm, chắc thịt, có hàng triệu năm tuổi. Nguyên tắc cho việc lựa chọn gỗ hoá thạch làm cảnh làđá phải đẹp, phải đáp ứng một trong các tiêu chuẩn như Sấu, Thẩm, Lộ, Thấu. Trong đó:

- Sấu là gầy guộc, nhìn theo tổng thể thì thân gầy guộc nhưng đá phải rắn rỏi, chắc chắn.

[![go hoa thach dang dung](/uploads/news/art-052-2-ban-go-hoa-thach-go-hoa-thach-do-go-hoa-thach-trang-go-hoa-thach-vang-go-hoa-thach-nau.jpg)](https://web.archive.org/web/20141007070245/http://thegioidaquy.net/phong-thuy/go-hoa-thach-go-hoa-da-ban-gia-re-3324.html#.VC_RiXbQxaU)

*Dáng gỗ hoá thạch thon dài rắn chắc.*

- Thẩm là gân sớ bên ngoài nhăn nheo, lằn ngoằn biểu trưng cho tính cổ lão, vừa mang lớp vỏ xù xì của gỗ vừa có chất mát lạnh cứng rắn của đá.

[![ban go hoa thach myanma](/uploads/news/art-052-3-go-hoa-thach-ban-go-hoa-thach-tphcm-ban-go-hoa-thach-q11-ban-go-hoa-thach-sai-gon.jpg)](https://web.archive.org/web/20141007070245/http://thegioidaquy.net/phong-thuy/go-hoa-thach-go-hoa-da-ban-gia-re-3324.html#.VC_RiXbQxaU)

*Gỗ hoá thạch có vân sớ bên ngoài nổi rõ cũng là một tiêu chí để chơi đá*

- Lậu là hang ốc lồi lõm biểu hiện sự âm u, có chổ tạo mắc như mắc gỗ hoặc lên nu lằn ngoằn như nu gỗ.

[![gia go hoa thach](/uploads/news/art-052-4-ban-go-hoa-thach-cua-hang-phong-thuy-3-thang-2-go-hoa-thach-tphcm-go-hoa-thach-o-sai-gon.jpg)](https://web.archive.org/web/20141007070245/http://thegioidaquy.net/phong-thuy/go-hoa-thach-go-hoa-da-ban-gia-re-3324.html#.VC_RiXbQxaU)

*Mắc gỗ hoá thạch nhìn như mắc gỗ thật, người chơi đá thường giữ lại các thế này*

- Thấu là có tạo dạng hang hoặc lỗ có thể nhìn qua để biểu hiện sự thông suốt.

[![go hoa thach la gi](/uploads/news/art-052-5-ban-go-hoa-thach-gia-go-hoa-thach-go-hoa-thach-dep-nhat-go-hoa-thach-phong-thuy.jpg)](https://web.archive.org/web/20141007070245/http://thegioidaquy.net/phong-thuy/go-hoa-thach-go-hoa-da-ban-gia-re-3324.html#.VC_RiXbQxaU)

*Vết lõm trên gỗ hoá thạch nhìn tựa như dấu chân của Cọp để lại.*

- Những người**đam mê gỗ hoá thạch**thường coi hành trình của mình là tìm kiếm nhân duyên. Bởi khi được đem về, tuổi của**gỗ hoá đá**có khi đã qua hàng triệu năm, qua sự mài mòn của thiên nhiên mới có hình dáng như vậy. Duyên là yếu tố đầu tiên để viên[đá](https://web.archive.org/web/20141007070245/http://thegioidaquy.net/phongthuy.html)lộ ra với người, vào lúc đó nó đối với người sưu tầm là đẹp nhất, và duyên của người chơi đá thì không ai giống ai.

*Gỗ hoá thạch có mặt trước phẳng bên cạnh có các gân nổi rõ bên phải nhìn như chiếc cánh*

-Chơi**gỗ hoá thạch**cảnh thì không cầu kì và tốn nhiều công chăm sóc như với hoa, bonsai hay chim cảnh nhưng nó mê hoặc người chơi theo cách riêng. Những viên***gỗ hoá thạch***thường có một không hai, và cái đẹp còn ẩn giấu của nó chính là sự thử thách của người đi tìm nhân duyên. Và vì lý do đó đã có nhiều người không ngần ngại bỏ hàng trăm triệu, thậm chí hàng tỷ đồng để tìm được nhân duyên cho đam mê của riêng mình.

*Gỗ hoá thạch có các vân các thế khác nhau đang có bán tại cửa hàng phong thuỷ Hoa Mộc Lan.*

Đại gia bỏ tiền tỷ chơi đá ngày TếtĐến bây giờ, chuyện bỏ tiền tỉ chơi đào, mai, chơi gốm,  chơi cây  ngày  Tết đã không phải là chuyện hiếm thấy. Và chuyện đại gia  bỏ tiền  tỉ ra  chơi tranh đá ngày Tết cũng được coi là chuyện thường  tình!

Cũng như Bonsai, nghệ thuật chơi đá cảnh  xuất phát  từ  Trung Quốc.Nhưng cho dù có xuất xứ từ đâu, thú chơi đá  cảnh cũng là  một  nét mới trong đời sống văn hóa, khiến người ta yêu  mến và gần gũi  với  thiên nhiên hơn, giảm được những căng thẳng trong  cuộc sống.

Theo  sử sách,Tô Đông Pha là người đặt  ra những nguyên  tắc đầu tiên cho việc  lựa chọn đá cảnh. Đá đẹp phải có  đủ bốn tiêu  chuẩn là Sấu, Thẩm, Lậu,  Thấu. Trong đó: Sấu là gầy, gầy  guộc nhưng  phải rắn rỏi, Thẩm là gân sớ,  nhăn nheo biểu hiện tính cỗ  lão, tang hải  thương điền, Lậu là lồi lõm,  hang hốc biểu hiện sự thâm  u, Thấu là có  hang lỗ thủng xuyên qua biểu  thị sự triệt thông (thông  suốt).

Những người săn đá  thường coi hành trình  của mình là  "cuộc tìm kiếm nhân duyên". Bởi khi  được đem về, tuổi của  viên đá có  khi đã hàng triệu năm, lại qua sự bào  mòn của dòng nước mới  có hình  dáng như khi được tìm thấy. "Duyên" là yếu  tố đầu tiên để  viên đá lộ ra  với người, vào lúc nó xinh đẹp nhất.

Chơi   đá cảnh không cầu kỳ và tốn nhiều công chăm chút  như với hoa, bonsai   hay chim chóc, nhưng nó mê hoặc người chơi theo  cách riêng. Những viên   đá thường có một không hai và cái đẹp còn ẩn  giấu của nó chính là sự  thử  thách với "người đi tìm nhân duyên". Và vì  lý do đó, nhiều người  đã  không ngần ngại bỏ hàng trăm triệu, thậm chí  hàng tỉ đồng để tìm  được  “nhân duyên” trong ngày Tết này.

- See more at: http://www.datrangtri.vn/dai-gia-bo-tien-ty-choi-da-ngay-tet.html#sthash.cDFKwkwV.dpuf

-**Cửa hàng phong thuỷ Hoa Mộc Lan đang bán gỗ hoá thạch thô**,  đá vân đẹp, vỏ đẹp ai chơi thế hãy đến chọn ngay cho mình một viên đẹp, đá có thịt chắc không phải hàng bột nên đánh bóng hay trưng thế đều được.Cửa hàng có các viên vừa từ 9-10 kg cho đến vài chục kg, rất thích hợp để trưng trên bàn làm việc, trong phòng khách, đặt trong hồ thuỷ sinh hoặc làm tiểu cảnh, hòn non bộ.

*- Nếu quý khách cần đặt số lượng lớn hoặc viên to nặng từ vài trăm kg đến vài tấn vui lòng liên hệ Mr.Sơn 0909.468.057bán gỗ hoá thạchđể đặt hàng*.

-Vào đây để xem**[giá gỗ hoá thạch](https://web.archive.org/web/20141007070245/http://thegioidaquy.net/phong-thuy/go-hoa-thach-go-hoa-da-ban-gia-re-3324.html#.VC_GFHbQxaU)**, bán tính theo kilogram(giá có thể thay đổi theo thời giá).

*[TheGioiDaQuy.Net](https://web.archive.org/web/20141007070245/http://thegioidaquy.net/phongthuy.html)*',
    '2014-10-04 09:00:00', 0, 616, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-049', 'y-nghia-vong-deo-tay-da-mat-ho', 'Ý nghĩa vòng đeo tay đá mắt hổ', 'Thế Giới Đá Quý',
    '/uploads/site_assets/Phongthuy-HoaMocLan-thegioidaquy.jpg', 'Ngày nay, Vòng đeo tay đá phong thủy đã trở thành vật phẩm trang sức đẹp được mọi người ưa chuộng. Trong đó có vòng đeo tay phong thủy đá mắt hổ với ý nghĩa đem lại sự mạnh mẽ và giàu có cho người đeo.', '[Đámắt hổ](https://web.archive.org/web/20141004203955/http://thegioidaquy.net/phong-thuy/chuoi-108-hat-da-mat-ho-12-ly-2944.html#.VCwiVmd_tlw)(Tiger eyes) làmột chếtácđộcđáo từđáquý tựnhiên thuộc dòng họthạch anh. Loạiđánày cótác dụng mangđến sựhài hòa, bình yên cho cuộc sống của bạn.Được làm từloạiđáquý cótrong tựnhiên nàyđã tạo nên*chi**ếc vòngđeo tayđámắt hổ*vừa sang trọng lại vừa mang ý nghĩa phong thủy rất lớnđối với ngườiđeo. Sauđây làmột số**ý nghĩa phong thủy của chiếc vòngđeo tay**kỳdiệu này:

[if !supportLists]-[endif]*Vòng tayđeođámắt hổ*đem lại sựmạnh mẽvàmay mắn cho ngườiđeo. Từthời trung cổ, loạiđánàyđược dùngđểxuađuổi tàma, mang lại sựthịnh vượng cho gia chủ.

[if !supportLists]-[endif]Giải tỏa căng thẳng trong công việc vàcuộc sống, giúp bạn tập trung tinh thần, mang lại cảm giác bình tĩnh, cókhảnăng xuyên thấu trong mọi hoàn cảnh. Nógiúp ta nhìn nhận vấnđềmột cách khách quan màkhông bịcảm xúcảnh hưởng.

*[Vòng tay đá mắt hổ xanh phong thủy](https://web.archive.org/web/20141004203955/http://thegioidaquy.net/phong-thuy/vong-tay-da-mat-ho-xanh-tron-dep-2748.html#.VCweyGd_tlw)có tác dụng giảm trầm uất, đem lại may mắn cho người đeo*

[if !supportLists]-[endif]Vòng tayđámắt hổcótác dụng kích thích lòng tin, giúp duy trìvàgia tăng quyết tâm của ngườiđeo, nâng cao năng lực hànhđộng, dámđươngđầu vàvượt qua mọi khókhan thửthách.

[if !supportLists]-[endif]**Đeo vòng tayđámắt hổ**hình cầu, hình kim tựtháp tụng tinh, niệm thần chúsẽtăng cường sức mạnh của kinh văn vàlời chú.

[if !supportLists]-[endif]Nếu bạn yếu bóng vía, sợma, không dámđiđêm, hãyđeo vòng tayđámắt hổsẽgiúp bạn tăng cường trạng thái tinh thần, dũng cảm hơn.

*[Vòng tay đá mắt hổ đỏ mặt dẹp vuông](https://web.archive.org/web/20141004203955/http://thegioidaquy.net/phong-thuy/vong-tay-da-mat-ho-do-dep-vuong-2727.html#.VCwgp2d_tlw)đem lại sự nhanh nhẹn và can đảm*

[if !supportLists]-[endif]Những người khíhuyết hưnhược, thiếu dũng khí, hãy luôn nắmđámắt hổtrong tay kết hợp với thởsâu cóthểtăng cường sức sống vàsức mạnh cơbắp.

[if !supportLists]-[endif]**Đámắt hổgiúp xóa bỏsựsợ****hãi**, buồn phiền, lo lắng hoang tưởng…Chính vìvậy, nólàmột liệu thuốc hiệu quảđểchữa trịcác bệnh căng thẳng vềthần kinh.

[if !supportLists]-[endif]Đámắt hổcònđược dùngđểchữa các bệnh vềcổhọng, vềmắt vàsinh sản.Đồng thời làm xương cột sống thêm cứng cáp, loại bỏcác chấtđộc vàgiảmđau.

[if !supportLists]-[endif]Ngoài ra,đámắt hổđỏcónăng lượng chiếu xạ, giúpđiều trịrất tốt các bệnh hen phếquản, bệnh vảy nến.

*Vòng đeo tay[đá mắt hổ đỏ](https://web.archive.org/web/20141004203955/http://thegioidaquy.net/phong-thuy/vong-tay-da-mat-ho-do-14-ly-406.html#.VCwf1Wd_tlw)gia tăng tài lộc, may mắn cho người đeo*

Nhưvậy, việc mang một chiếc***vòngđeo tayđámắt hổlàm trang sức phong thủy***khiđi làm, du lịch, dựtiệc,đi chơi hayđi học sẽgiúp bạn tựtin vàthành công hơn trong nhiều phương diện của cuộc sống.

*[*Thegioidaquy.net*](https://web.archive.org/web/20141004203955/http://thegioidaquy.net/phongthuy.html)*',
    '2014-10-01 09:00:00', 0, 659, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-050', 'da-phong-thuy-ruby', 'Đá phong thủy Ruby', 'Thế Giới Đá Quý',
    '/uploads/site_assets/Phongthuy-HoaMocLan-thegioidaquy.jpg', 'Đá Ruby được mệnh danh là “Vua của các loài đá”. Theo phong thủy, Ruby chính là giọt tinh huyết của đất trời với ý nghĩa mang lại may mắn và thành công cho người đeo.', '[if !supportLists]**1.[endif]Ý nghĩa phong thủ****y:**

-[**Đá****Ruby**](https://web.archive.org/web/20141004203909/http://thegioidaquy.net/phong-thuy/da-phongthuy-120-Da-Ruby)được coi làloạiđáquý mạnh nhất trong vũtrụ. Ruby cótên gọi bắt nguồn từtiếng La Tinh “Rubens” cónghĩa làmàuđỏ. Người ta cho rằng*Ruby*chính lànhững giọt máu rỉra từtrái tim người mẹvĩđại của muôn loài ThầnĐất. Chính vìvậy, Ruby thườngđược các nhàlãnhđạo, các vịvua tin vàlinh mục tin dùng. Từthời xa xương, Hoàng Gia Anh thường sửdụngđáRubyđểgắn vào vương miện của các vịvua trong lễđăng quang với quan niệmđáRubycótác dụng giúp ngườiđeođưa rađược những quyếtđịnh khôn ngoan vàcao quý.

-**Đá****Ruby**cómột năng lượng vô cùng mạnh mẽvà*mangđến rất nhiều ý nghĩa vềmặt phong thủy*.Đặt một viênđáRuby dưới gối sẽgiúp bạn xuađuổiđược những giấc mơxấu, mangđến cho bạn giấc ngủngon cũng nhưcải thiệnđượcđời sống tình dục.

-Đeo**trang s****ức phong thủy cógắnđá****Ruby**như:***[mặt nhẫn](https://web.archive.org/web/20141004203909/http://thegioidaquy.net/phong-thuy/da-ruby-sao-3322.html#.VCwFJHbQxaU)***,[TỳHưuđáRuby](https://web.archive.org/web/20141004203909/http://thegioidaquy.net/phong-thuy/mat-nhan-ty-huu-ruby-3216.html#.VCd_YWd_tlw),[mặt Di LăcđáRuby](https://web.archive.org/web/20141004203909/http://thegioidaquy.net/phong-thuy/mat-di-lac-da-ruby-18-3026.html#.VCd_pmd_tlw)…sẽmangđến sức khỏe, hạnh phúc, may mắn vàsựbình yên cho bạn. Nókhuyến khích bạn theođuổiước mơvàhạnh phúc của mình, giúp bạn thayđổi cuộc sống theo chiều hướng tích cực.

*[Mặt dây chuyền Quan Công đá Ruby](https://web.archive.org/web/20141004203909/http://thegioidaquy.net/phong-thuy/mat-day-chuyen-quan-cong-da-ruby-97ct-3308.html#.VCeBRWd_tlw)bảo vệ chủ nhân chống lại các thế lực đen tối, mang lại bình an và may mắn.*

-**Đá****Ruby**được xem làbiểu tượng của tình yêu, biểu trưng cho sựnồng nàn vàlãng mạn. Chính vìvậy, NhẫnđáRuby thườngđược chọn làm món quàtruyền thống dành cho các cặp vợchồng nhân kỷniệm 40 năm ngày cưới của mình.

- Ruby thích hợp với những người Mệnh Thủy, Hỏa vàThổ. Theo quan niệm của PhươngĐông, việcđeo trang sức,đáquý hợp với mệnh sẽđem lại sựmay mắn vàhưng vượng cho ngườiđeo.

*[Mặt nhẫn Tỳ Hưu đá Ruby](https://web.archive.org/web/20141004203909/http://thegioidaquy.net/phong-thuy/mat-nhan-ty-huu-ruby-3215.html#.VCeCMWd_tlw)đem lại giàu sang và may mắn, phù hợp cho người mạng Hỏa và mạng Thổ*

[if !supportLists]**2.[endif]Tác dụng chữa bệ****nh:**

- Từthời xa xưa,**Vi****ênđá****Ruby**đãđược mọi người biếtđến với những tính chất siêu nhiên của nótrong việcđiều trịcác loại bệnh khác nhau.

- Ruby chữa các bệnh vềtim, não, máu, các bệnhởcột sống vàkhớp, cótác dụng giảiđộc,  làm tăng thêm sức mạnh vàtrínhớcho con người.

- Ngoài ra*Ruby c**òn cókhảnăng trong việc ngăn ngừa những cơnđộ**ng kinh*, cókhảnăng chữa trứng trầm uất vàtâm thần phân liệt.

- Cóthểnói,[***đáruby***](https://web.archive.org/web/20141004203909/http://thegioidaquy.net/phong-thuy/da-phongthuy-120-Da-Ruby)cókhảnăngđuổi khỏi cơthểkhỏi mọi loại bệnh tật vàtạo cho cơthểmột nguồn năng lượng mới.

[****Thegioidaquy.net****](https://web.archive.org/web/20141004203909/http://thegioidaquy.net/phongthuy.html)',
    '2014-09-28 09:00:00', 0, 702, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-051', 'cong-dung-cua-thach-anh-tim', 'Công dụng của thạch anh tím', 'Thế Giới Đá Quý',
    '/uploads/news/art-056-1-1-vong-tay-thach-anh-tim.jpg', 'Thạch anh tím là một loại đá phong thủy quý giúp chúng ta giữ sự bình tĩnh, cân bằng cả về thể chất, cảm xúc và tâm linh. Đây là một tinh thể được đánh giá rất cao trong dòng họ thạch anh.', '**[Thạch anh tím](https://web.archive.org/web/20140925005110/http://thegioidaquy.net/phong-thuy/Hang-da-thach-anh-tim-dam-nho-3303.html)**có tên gọi xuất phát từ Hy Lạp Cổ Đại. Đây là một tinh thể được đánh giá rất cao trong dòng họ thạch anh. Bởi nó vừa có một vẻ đẹp tự nhiên, vừa mang lại rất nhiều tác dụng kỳ diệu cho người sử dụng.

Thạch anh tím là loại đá có thể giúp chúng ta giữ sự bình tĩnh, cân bằng cả về thể chất, tinh thần, cảm xúc và tâm linh. Sau đây là một số công dụng cụ thể của thạch anh tím.

[if !supportLists]**1.[endif]Công dụng về mặt phong thủy:**

[if !supportLists]- Thạch anh tím có tác dụng đem lại sự tỉnh táo cho mọi người, xóa bỏ sự sợ hãi và xua tan những cảm giác tiêu cực.[endif]

[if !supportLists]-***Đeo trang sức bằng thạch anh tím***trên người như vòng tay thạch anh, dây chuyền thạch anh… sẽ bảo vệ ta tránh khỏi những sự tấn công về mặt tinh thần cũng như những tổn hại khác, giúp ta bình tĩnh và linh họat hơn, đem lại nhiều vận may.[endif]

- Thạch anh tím hợp với những người tuổi Sửu tượng trưng cho sự bình yên và sức khỏe dồi dào.

[![vong-tay-thach-anh-tim](/uploads/news/art-056-1-1-vong-tay-thach-anh-tim.jpg)](https://web.archive.org/web/20140925005110/http://thegioidaquy.net/phong-thuy/vong-da-thach-anh-tim-10-ly-3060.html#.VCDssXbQxaU)

*[Vòng tay đá thạch anh tím](https://web.archive.org/web/20140925005110/http://thegioidaquy.net/phong-thuy/vong-da-thach-anh-tim-10-ly-3060.html#.VCDssXbQxaU)giúp đem lại sức khoẻ và may mắn, phù hợp cho người mạng Hoả và mạng Thổ*

[if !supportLists]- Ngoài ra năng lượng kỳ diệu củathạch anh tímcòn có dụng xua tan vận rủi, mang đến sự giàu có và thịnh vượng cho gia chủ.[endif]

[if !supportLists]-*Đặt đá thạch anh tím ở góc Đông Bắc*của phòng học có tác dụng tang cường vận may về con đường học vấn cho con em chúng ta. Treo thạch anh tím ở góc Tây Bắc trong phòng ngủ sẽ có tác dụng kích hoạt vận may về quan hệ tình cảm.[endif]

[if !supportLists]- Những bạn khi lái xe có tính nóng nảy, hay phóng nhanh vượt ẩu, nên đặt thạch anh tím tròn dưới ghế ngồi sẽ có tác dụng giải tỏa tính nóng nảy, giúp cho lái xe được an toàn hơn.[endif]

[![mat-da-thach-anh-tim-giac](/uploads/news/art-056-2-1-mat-da-thach-anh-tim-giac.jpg)](https://web.archive.org/web/20140925005110/http://thegioidaquy.net/phong-thuy/Mat-da-thach-anh-tim-giac-ban-theo-cara-3306.html#.VCBNrJR_tlw)

*[Mặt đá thạch anh tím](https://web.archive.org/web/20140925005110/http://thegioidaquy.net/phong-thuy/mat-ty-huu-da-thach-anh-tim-dam-3294.html#.VCDtN3bQxaU)đem lại may mắn và tài lộc cho người đeo*

[if !supportLists]**2.[endif]Đặc tính chữa bệnh:**

[if !supportLists]- Thạch anh tím có tên gọi xuất phát từ Hy Lạp Cổ Đại với ý nghĩa là “Không say rượu”. Người Hy Lạp Cổ Đại tin rằng, thạch anh tím là một loại đá có thể giúp chúng ta chống lạI sự nghiện rượu cũng như một số loại chất gây nghiện khác như thuốc lá….[endif]

[if !supportLists]- Thạch anh tím còn được dùng để chữa các bệnh về xương khớp, hô hấp, tiêu hóa, các rối loạn về tim.[endif]

[if !supportLists]- Đặt**đá thạch anh tím**tròn vào trong gối có tác dụng chữa trị chứng mất ngủ, mang lại cho những người già hoặc suy nhược cơ thể có một giấc ngủ ngon.[endif]

[if !supportLists]- Nếu không được khỏe, chỉ cần giữ một***viên thạch anh tím***trong người và đặt trên cơ thể nơi cần chữa bệnh như tim, phổi.[endif]

Tóm lại,[thạch anh tím](https://web.archive.org/web/20140925005110/http://thegioidaquy.net/phong-thuy/da-phongthuy-36-Thach-Anh-Tim/)là một loại đá phong thủy quý hiếm vừa có giá trị về mặt thẩm mỹ, đại diện cho sự cao sang lại vừa mang đến nhiều ý nghĩa về mặt phong thủy cũng như chữa bệnh cho con người.

[**Thegioidaquy.net**](https://web.archive.org/web/20140925005110/http://thegioidaquy.net/phongthuy.html)',
    '2014-09-22 09:00:00', 0, 788, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-052', 'seraphinite-va-cong-dung-da-seraphinite', 'Seraphinite và công dụng đá Seraphinite', 'Thế Giới Đá Quý',
    '/uploads/news/art-057-1-da-seraphinite-tho.jpg', 'Seraphinite còn được gọi là Serafinite. Đá Seraphinite có nhiều công dụng và được coi là một trong những viên đá chữa bệnh quý nhất trên thế giới.', '**Seraphinite**được đặt tên theo*Seraphim*nghĩa là các cánh nhiều hoặc con thiên thần lửa được mô tả trong Kinh Thánh.**Đá Seraphinite**được tìm thấy ở gần khu vực hồ Baikal miền đông Siberia, Nga.Seraphirite là một trong những loại đá chữa bệnh, đá có màuđẹp,sắc xanh lục đậm lấp lánh ánh sáng bạc bên trong.

## Thành phần hóa học:

(Mg, Fe, Al)6 (Si, Al)4 O10 (OH)8 - Magnesium sắt hydroxit nhôm silicat.

Hệ thống tinh thể:đơn tà

Độ cứng:2-2,5 trên thang Mod

Tên gọi khác của**Seraphinite**:Serefina, Serafinite, Seraphanite, Seraphenite, Clinochlore, Chlorite.

[![Đá Seraphinite xanh lục có những dãy sáng ánh bạc](/uploads/news/art-057-1-da-seraphinite-tho.jpg)](https://web.archive.org/web/20140819170559/http://thegioidaquy.net/tin-tuc/seraphinte-va-cong-dung-daseraphinite-1912.html)

*Đá Seraphinite xanh lục có những dãy sáng ánh bạc*

## Quá trình Hình thành Seraphinite:

-**Seraphinite**là một silicat thuộc lớp clorit khoáng sản, và nó tích hợp ánh sáng bạc.Nó được phát hiện trong thế kỷ 19 ở Nga, và được biết đến trong ngành địa chất với tên là**Clinochlore**(từ tiếng Hy Lạp, "Clino", có nghĩa là "nghiêng" - đề cập đến hệ thống tinh thể đơn tà của nó - và "chloros", có nghĩa là "xanh" ).

- Seraphinite được hình thành khi mà các khoáng chất sắt và magnesium silicat trải qua quá trình biến đổi ởnhiệt độ cao, áp lực tác động lên làm các khoáng đổi chất.Dòng chảy nóng giàu các khoáng này tích tụ lại, sau một thời gian dài nguội dần lại và kết tinh.

-**Đá Seraphinite**có nhiều màu như nâu, trắng, vàng, đỏ nhưng đa phần seraphinite thường được tìm thấy là màu**xanh lá cây sậm có dãy sáng**, xen lẫn với các đốm ánh bạc.Những đốm bạc này là**đặc trưng riêng của seraphinite**, nó thể hiện sự tôn kính với thần Seraphim.

![Vòng tay đá Seraphinite đeo tay](/uploads/news/art-057-2-vong-tay-da-seraphinite.jpg)

*Vòng tay đá Seraphinite đeo tay giúp tăng sức khoẻ của Tim*

## Công dụng đá Seraphinite:

- Từ lâu**Seraphinite**được coi là một trong những**viên đá chữa bệnh**quý nhất trên thế giới.

- Các thầy thuốc xưa tin rằng seraphinite là đá hiệu quả nhất để tái tạo tế bào, giúp thanh trừ các độc tố trong máu và cơ thể.

- Seraphinite tác động tích cực làm tăng sức khỏe của Gan và Thận.

- Seraphinite giúp chữa lành bệnh liên quan đến cuộc sống trong quá khứ.

-**Seraphinite giúp**làm giảm cảm lạnh, năng lượng của nó tác động thúc đẩy quá trình**giảm cân hiệu quả**hơn.

-Màu xanh lục**đá Seraphinite giúp****tạo năng lượng****và  tăng sức sống cho Tim**.

- Seraphinite giúp cân bằng và kích hoạt các  luân xa, giải phóng các mô cũ tạo điều kiện cho mô tế bào mới tái  sinh.

- Đặt**viên seraphinite**trên đầu hoặc trán sẽ tạo ra sự liên kết của tất cả các luân xa.

- Đá Seraphinite tạo ra môi trường hỗ trợ cho sự phát triển tâm linh tương thông của những người thân trong gia đình.

- Năng lượng của Seraphinite giúp tăng những cảm nhận trực giác và nhận thức.

- Seraphinitelà đá biểu tượng của chòm saoKim Ngưu vàNhân Mã trong cung hoàng đạo.

-**Đá Seraphinite**phù hợp với những người mệnh Mộc và mạng Hỏa.

-**S****eraphine**giúp chữa lành cho các dây thần kinh và tế bào  não. Kích hoạt các dây thần kinh cột sống và giúp nó liên kết nó với cơ thể.

[*TheGioiDaQuy.Net*](https://web.archive.org/web/20140819170559/http://thegioidaquy.net/phongthuy.html)',
    '2014-08-04 09:00:00', 0, 831, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-053', 'da-thach-anh-hong-hieu-ung-mat-meo-do-chua-tourmaline', 'Đá thạch anh hồng hiệu ứng mắt mèo do chứa Tourmaline', 'Thế Giới Đá Quý',
    '/uploads/site_assets/Phongthuy-HoaMocLan-thegioidaquy.jpg', 'Mẫu đá thạch anh hồng này nặng 34,65 ct, có một dãy sáng rộng, rõ nét với ánh thủy tinh mờ. Ban đầu mới nhìn, gợi ta liên tưởng đến loại tourmaline óng ánh do màu sắc của nó. Quan sát kỹ hơn bằng mắt thường thì thấy có sự tập trung màu tại nhiều vùng khác nhau, đặc biệt là về hai phía bên hông.', '[**Thạch anh**](https://web.archive.org/web/20140715080255/http://thegioidaquy.net/phong-thuy/da-phongthuy-23-Da-Thach-Anh)có dãy lụa  		óng ánh tồn tại dưới rất nhiều màu như xám, vàng, lục và nó thường được  		miêu tả nhầm là chrysoberyl có dãy lụa óng ánh. Mới đây, phòng giám định[đá quý](https://web.archive.org/web/20140715080255/http://thegioidaquy.net/tin-tuc/tac-dung-cua-da-ruby-686.html)ở Ấn Độ có giám định một**viên thạch anh**[mắt mèo](https://web.archive.org/web/20140715080255/http://thegioidaquy.net/phong-thuy/da-phongthuy-118-Da-Mat-Meo-Chrysoberyl-)màu hồng rất thú vị do  		nguyên nhân tạo nên màu sắc và hiệu ứng óng ánh của nó.

*Viên thạch anh hồng hiệu ứng mắt mèo*

- Mẫu**đá thạch anh hồng**này nặng 34,65 ct, có một dãy sáng rộng, rõ nét với ánh thủy tinh mờ. Ban đầu  		mới nhìn, gợi ta liên tưởng đến loại**[Tourmaline](https://web.archive.org/web/20140715080255/http://thegioidaquy.net/tin-tuc/cong-dung-cua-da-tourmaline-1409.html)**óng ánh do màu sắc của  		nó. Quan sát kỹ hơn bằng mắt thường thì thấy có sự tập trung màu tại  		nhiều vùng khác nhau, đặc biệt là về hai phía bên hông. Điều này gợi nhớ  		đến sự hiện diện của màu tẩm dọc theo các ống tăng trưởng/ vết nứt bề  		mặt. Khoáng vật này dị hướng dưới hai nicol phân cực vuông gốc với vài  		màu giao thoa vuông góc với dãy óng ánh hay dọc theo phương của các que  		bao thể. Có thể suy đoán khoáng vật này có một trục quang, tuy nhiên con  		số trục quang không quyết định được mọi điều do khoáng này còn chứa một  		lượng bao thể dày đặc khác nữa. Chiết suất điểm RI và tỷ trọng thủy tĩnh đo được lần lượt là 1,54 và 2,68. Mẫu khoáng này**không phản ứng dưới  		chiếu xạ cực tím**và không có đặc điểm phổ nào được ghi nhận dưới phổ kế  		để bàn. Những đặc điểm này cho biết đây là**thạch anh**nhưng cần phải phân  		tích thêm mới có kết luận chính xác được.

*Thạch anh hồng có khoáng vật hình que[Tourmaline](https://web.archive.org/web/20140715080255/http://thegioidaquy.net/phong-thuy/da-phongthuy-247-Da-Tourmaline)*

- Dưới kính phóng đại,  		mẫu khoáng này có chứa các bao thể dạng ống dài hay dạng que.  		Nhìn từ bên hông, thấy dọc các ống này có**màu hồng**, làm tăng thêm khả  		năng nghi ngờ về nguyên nhân tạo màu của nó. Mặt cắt ngang của các ống  		này thậm chí còn sậm màu hơn. Dưới độ phóng đại lớn hơn thấy có một số  		hình tam giác rất hoàn chỉnh.

*[Thạch anh hồng](https://web.archive.org/web/20140715080255/http://thegioidaquy.net/phong-thuy/da-phongthuy-133-Thach-Anh-Hong-Rose-quartz-/)chứa hệ ba phương Tourmaline hình tam giác dưới kính phóng đại 64 lần*.

- Đặc điểm đặc trưng này phù hợp  		với các**khoáng vật kết tinh hệ ba phương như tourmaline**. Điều này được  		củng cố thêm bởi màu sắc của các ống và sự hấp thu dọc theo trục c: các  		bao thể này trông sậm màu hơn khi nhìn từ mặt cắt ngang. Do đó bản thân  		mẫu khoáng này là không màu nhưng màu hồng có được là do màu của bao thể.

- Phổ hồng ngoại được quan sát trên cả hướng song song và vuông góc với các  		que bao thể. Đối với phương song song, có hai tập hợp đỉnh hấp thu sắc  		nét được nhìn thấy trong vùng 4800 – 4200 cm-1và trong vùng 3700 – 3000 cm-1. Dựa trên những  		dữ liệu và nghiên cứu trước đây của L. T. M. Oanh và nhóm  		tác giả “**Phân loại tourmaline thiên nhiên bắng phổ hấp thu gần hồng  		ngoại**”,*VNU Journal of Science: Mathematics – Physics*, Vol. 26,  		2010, trang 207 – 212; G. Choudhary và S. Fernandes, “Nghiên cứu đặc  		điểm phổ của các loại thạch anh hiện diện trên thị trường: trên phương  		diện ngọc học”, G&G Summer 2011, trang 146 – 147, tập hợp đầu tiên của  		các đỉnh thì giống với những đặc điểm hấp thu trên**tourmaline**, tập hợp  		thứ hai thì tương ứng với**phổ của thạch anh**. Đối với phương vuông góc  		thì chỉ có một dãy hấp thu rộng được nhìn thấy trong vùng 3700 – 3000 cm-1,  		do mức độ dẫn truyền theo phương này thấp hơn.

- Những  		kiểm tra dưới kính hiển vi và các đặc điểm quang phổ có thể xác định  		được rằng mẫu khoáng này là**thạch anh có chứa các bao thể tourmaline màu  		hồng**.[Tourmaline](https://web.archive.org/web/20140715080255/http://thegioidaquy.net/phong-thuy/vong-tay-da-tourmaline-8-ly-3239.html#.U7zhT3bQxaU)thường hiện diện là bao thể khoáng trong thạch anh  		nhưng thường sắp xếp theo những hướng bất kỳ. Do đó mẫu khoáng này là  		rất thú vị và đặc biệt bởi có màu hồng ( mặc dù nó không phải là thạch  		anh hồng ) cũng như hiệu ứng óng ánh màu của nó. Cả hai yếu tố này có  		được là do sự hiện diện của các**que tourmaline**sắp xếp song song nhau.

*[TheGioiDaQuy.Net](https://web.archive.org/web/20140715080255/http://thegioidaquy.net/phongthuy.html)sưu tầm*',
    '2014-07-09 09:00:00', 0, 874, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-054', 'cac-thiet-bi-ngoc-hoc-giam-dinh-da-quy-tren-the-gioi', 'Các thiết bị ngọc học giám định đá quý trên thế giới', 'Thế Giới Đá Quý',
    '/uploads/news/art-059-1-may-giam-dinh-da-quy-1.jpg', 'Ngành ngọc học trên thế giới đang phát triển mạnh với nhiều thiết vị giám định đá quý hiện đại nhằm xác định rõ nguồn gốc, chiết suất, quang phổ... của các loại đá quý.', '**1. LA-ICP-MS (Laser Ablation Inductively Coupled Plasma Mass Spectrometry)**

[![máy giám định đá quý phân tích định lượng](/uploads/news/art-059-1-may-giam-dinh-da-quy-1.jpg)](https://web.archive.org/web/20140605150150/http://thegioidaquy.net/tin-tuc/cac-thiet-bi-ngoc-hoc-giam-dinh-da-quy-tren-the-gioi-1905.html)

*Máy giám định đá quý phân tích định lượng*

Phương  		pháp này được sử dụng để phân tích thành phần định lượng và định tính  		bằng cách đo mức độ tập trung khối lượng của vật chất. Phân tích định  		tính và định lượng các thành phần nhẹ như Berilyum có trong**Sapphire**xử  		lý nhiệt theo quy trình mới.

**2. 		Laser  		Tomograph**

![Máy giám định đá quý tia laser chụp cắp lớp](/uploads/news/art-059-2-may-giam-dinh-da-quy-2.jpg)

*Máy giám định đá quý phân tích định lượng*

Phương  		pháp chụp cắt lớp bằng laser nhằm quan sát cấu trúc tinh thể. Có thể  		nhận diện được các cấu trúc rất nhỏ và các khuyết tật bên trong viên đá  		quý  bằng các ảnh quét hoặc ảnh phát quang bằng cách quét tia laser hẹp  		(tia laser argon bước sóng 488nm). Kỹ thuật phân tích này được công nhận  		cao trên thế giới như là một kỹ thuật duy nhất hiệu quả để phát hiện  		nguồn gốc thành tạo hoặc quá trình xử lý nhiệt của[**ruby**](https://web.archive.org/web/20140605150150/http://thegioidaquy.net/phong-thuy/da-phongthuy-120-Da-Ruby),[**sapphire**](https://web.archive.org/web/20140605150150/http://thegioidaquy.net/phong-thuy/da-phongthuy-119-Da-Sapphire)và  		nguồn gốc[**thạch anh**](https://web.archive.org/web/20140605150150/http://thegioidaquy.net/phong-thuy/da-phongthuy-23-Da-Thach-Anh).

**3. LIBS  		(Laser Induced Breakdown Spectrometry)**

![máy giám định đá quý tia laser hồng ngoại](/uploads/news/art-059-3-may-giam-dinh-da-quy-3.jpg)

*Máy giám định đá quý tia laser hồng ngoại*

Khi  		tia laser hồng ngoại chiếu lên bề mặt mẫu vật rắn, nhiệt độ bề mặt bị  		đốt nóng nhanh chóng và hoá hơi, khí hơi này (các phân tử khí) trở thành  		trạng thái kích thích điện tử. Khi xung laser suy giảm các điện tử bị  		kích thích này toả ra ánh sáng có đặc điểm bước sóng phân biệt với các  		nguyên tố khác khi chúng nhảy xuống mức năng lượng thấp hơn Mặc dù giới  		hạn nhận biết của chúng không thấp như phương pháp LA-ICP-MS, nó có độ  		nhạy cao (1ppm) đối với Be. Với khả năng tuyệt vời như vậy nó được sử  		dụng rất hiệu quả trong nhận biết**corundum**xử lý nhiệt khuyếch tán Be.

**4. 		Raman  		spectroscope**

*Máy giám định đá quý chiếu tia Raman*

Quét  		tia Raman được sử dụng  để xác định vật chất hoặc phân tích cấu trúc  		phân tử. Trong lĩnh vực ngọc học, phương pháp này được kỳ vọng trong  		nghiên cứu bao thể đá quý, bằng cách sử dụng năng lượng chuyển đổi cao  		trong khong gian của laser. Phổ Raman được sử dụng để phân tích mẫu  		trong phạm vi định sẵn hoặc kích thước cỡ vài micrometer, để xác định  		bao thể trong**đá quý**. Khi phát huỳnh quang là yếu tố nhận biết như trong**kim cương**thì kỹ thuật này được sử dụng như là sự phân tích ảnh phát  		quang. Phương pháp ảnh phát quang hiện nay là cách hiệu quả nhất để nhận  		biết**kim cương****xử lý**HPHT.

**5. 		Cathod  		Luminescene Equipment**

Máy giám định đá quý chiếu tia electron

Đây  		là thiết bị để quan sát hiện tượng phát quang của[đá quý](https://web.archive.org/web/20140605150150/http://thegioidaquy.net/phong-thuy/da-phongthuy-247-Da-Tourmaline)khi chiếu tia  		electron, hiện tượng đó gọi là phát quang âm cực. Kim cương đều phát  		quang dưới ánh sáng cực tím, nhưng phát quang âm cực của mỗi viên**kim  		cương**thể hiện một kiểu duy nhất tùy theo sự khác nhau về chi tiết và  		cường độ, điều này có ý nghĩa hiệu quả nhất trong việc phân biệt từng  		viên và xác định đá tổng hợp. Đặc biệt đá tự nhiên thể hiện ảnh phát  		quang riêng biệt phản ánh quá trình thành tạo của chúng, điều này sẽ  		không bao giờ thấy được ở các viên khác. Tương tự như vân tay của con  		người, bằng đặc tính này vân tay của kim cương có thể là mộtlai lịch  		của viên kim cươngđó.

**6. 		Spectrophotometer**

![Máy giám định đá quý đo ảnh phổ cao](/uploads/news/art-059-6-may-giam-dinh-da-quy-9.jpg)

*Máy giám định đá quý đo ảnh phổ cao*

Ngày nay phương pháp  		đo ảnh phổ độ chính xác cao đang là công việc hàng ngày ở các phòng thí  		nghiệm ngọc học. Có rất nhiều loại thiết bị đo phổ phạm vi từ ánh sáng  		cực tím đến vùng thấy được, vùng cận hồng ngoại, vùng hồng ngoại, mỗi  		loại thích hợp sẽ được chọn tùy theo mục đích**giám định các loại đá**khác  		nhau.

**7. UV-Visiable**

![Máy giám định đá quý đo bước sóng](/uploads/news/art-059-7-may-giam-dinh-da-quy-6.jpg)

*Máy giám định đá quý đo bước sóng*

Đo  		trong khoảng bước sóng từ 200 – 900nm có thể phân tích phổ đặc trưng của  		đá quý trong vùng cực tím đến vùng ánh sáng thấy được, nó rất hiệu quả  		để xác định màu nguyên thủy của**kim cương màu**, màu xử lý ở**ngọc trai**hoặc trai nước mặn (vd như trai mép đen), và nhận diện nguồn gốc tự  		nhiên hay nhân tạo của**ruby**,***emerald***,***alexandrite***.

**8. 		Near  		Infrared Region**

*Máy giám định đá quý đo vùng cực tím*

Đo  		trong khoảng 200 – 2700nm trải dài từ vùng cực tím đến vùng thấy được và  		vùng cận hồng ngoại. Vì nó có thể đo được phổ của nước và vật chất hữu  		cơ (không nhìn thấy được trong vùng ánh sáng thấy được), do đó thiết bị  		này có thể**phân biệt đá quý**gốc hữu cơ và đá quý chứa nhóm hydroxyl hoặc  		H2O từ các loại tương tự. Đặc biệt hiệu quả khi nhận biết*đá bị tẩm nhựa*(ví dụ như bột đá cẩm thạch trộn với keo).

**9. 		Infrared Region**

*Máy giám định đá quý đo vùng cận hồng ngoại*

Có  		khả năng đo khoảng bước sóng từ 1250 và 25000nm và không chỉ đo ở vùng  		giữa hồng ngoại mà còn ở vùng cận hồng ngoại và hồng ngoại. Chủ yếu nhận  		biết xử lý tẩm keo, xác định loại kim cương và*phân biệt các loại thạch  		anh*khác nhau. Chúng rất hữu dụng trong việc xác định các loại*đá quý*có  		giá trị RI tương tự nhau.

**10. 		X-Ray  		Fluorescene Analysis Device**

*Máy giám định đá quý chiếu xạ tia x*

Khi  		vật chất được chiếu xạ với tia X, các nguyên tố bên trong vật chất phát  		ra tia X thứ cấp đặc trưng riêng cho từng nguyên tố. Bằng cách xem xét  		tia X thứ cấp này (huỳnh quang tia X), số lượng và loại nguyên tố tạo  		nên vật chất có thể được nhận diện. Do***đá quý***được cấu thành từ nhiều  		nguyên tố hóa học riêng biệt, thì việc phân tích các thành phần này là  		phương pháp hiệu quả cao để nhận diện các**chủng loại đá quý**, nguồn gốc  		tự nhiên hay nhân tạo và ngọc trai nước mặn. Nó cũng hiệu quả khi nhận diện nguồn gốc tự nhiên hay nhân tạo bằng cách phân tích các nguyên tố  		vết. Các thiết bị phân tích thông thường có thể nhận diện các nguyên tố  		có số nguyên tử là 11 (Natri) hoặc hơn, trong khi với thiết bị này có  		thể phân tích các nguyên tố có số nguyên tử là 6 (Cacbon) hoặc hơn. Tất  		nhiên việc phân tích này không cần phải hủy mẫu.

**11. 		X-Ray  		Radiography Device**

*Máy giám định đá quý đo thẩm thấu của tia x*

Thiết  		bị phân tích này dùng để quan sát sự xuyên thấu khác nhau của tia X đối  		với mỗi loại vật chất. Rất hiệu quả trong xác định**kim cương nhái**và**xử  		lý tẩm màu**, và ngay cả*nhận diện ngọc trai*được cấy nhân hay không cấy  		nhân.

**12. Differential Interference Microscope**

*Máy giám định đá quý quan sát độ dày và chiết suất*

Rất  		thích hợp để quan sát trong phạm vi nhỏ với độ dày và chiết suất thay  		đổi ít cũng như cấu trúc bề mặt mịn. Hơn nữa ngay cả sự thay đổi bất  		thường nhẹ cho màu giao thoa sáng có thể quan sát ở dạng ảnh 3D. Rất hữu  		dụng để quan sát lớp phủ mỏng trên bề mặt**đá quý**hoặc vật liệu lấp đầy.  		Cũng thu được thông tin hiệu quả  trong việc xác định xử lý**độ sạch kim  		cương**bằng laser.

*[TheGioiDaQuy.Net](https://web.archive.org/web/20140605150150/http://thegioidaquy.net/phongthuy.html)sưu tầm*',
    '2014-06-02 09:00:00', 0, 917, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-055', 'tac-dung-cua-da-aquamarine', 'Tác dụng của đá Aquamarine', 'Thế Giới Đá Quý',
    '/uploads/site_assets/Phongthuy-HoaMocLan-thegioidaquy.jpg', 'Aquamarine có tên gọi là Ngọc xanh biển do có màu sắc đặc trưng của xanh nước biển. Aquamarine là loại đá quý có cấu trúc gần với Emerald Ngọc lục bảo, nhiều mỏ Aquamarine được tìm thấy ở các nước Bzaxin, Liên Xô, Pháp, Namibia.', '**Aquamarine**có tên gọi là Ngọc xanh biển hay Ngọc berin là một loại đá quý màu xanh  berin.**Aquamarine**theo tiếng Latinh có nghĩa là Nước biển bởi nó  có màu xanh biếc, giống hệt với màu của nước biển.

- Công thức hóa học của**Đá  Aquamarine**là Be3Al2(SiO3)6,  rất gần với Ngọc lục bảo.

- Mỏ[Aquamarine](https://web.archive.org/web/20140527065845/http://thegioidaquy.net/phong-thuy/da-phongthuy-126-Da-Aquamarine/)được tìm thấy nhiều ở các nước Bzaxin, Liên Xô, Pháp,  Namibia.  Ở Việt Nam hiện nay chưa phát hiện được trữ lượng mỏ đá  Aquamarine.

- Màu sắc đặc trưng của Aquamarine là màu xanh dương, màu xanh lục, hoặc xanh dương phớt xanh lá.

-Aquamarinecó độ tinh khiết cao được cắt mài đa giác làm mặt trang sức hình oval, tròn, trái tim. Aquamarine bán trong được mài thành mặt Giọt nước, Oval để đeo cổ hoặc làm các vòng chuỗi đeo tay.

*Vòng tay đá Aquamarine cho người mạng Mộc và mạng Thuỷ.*

**[Tác dụng của đá Aquamarine](https://web.archive.org/web/20140527065845/http://thegioidaquy.net/tin-tuc/tac-dung-cua-da-aquamarine-1904.html):**

-Đá Aquamarineđược hình thành từ sâu trong  lòng đất, trải qua nhiều điều kiện địa chất phức tạp trong thời gian dài nên nó mang nguồn năng lượng tinh khiết, rất tốt để làm trang sức đá đeo trên người.

-**Aquamarine**làm lợi cho hệ miễn dịch,  làm dịu những cơn giận dữ và giảm sốt khi được  đeo trên người hoặc đặt lên chỗ  đau nhức, sưng tấy.

- Do là một tinh thể tĩnh tâm  giảm căng thẳng nên Aquamarine rất tốt cho những người hay nghiến răng  khi giận giữ.

- Đeotrang sức đá Aquamarinesẽ làm cho con  người có cái nhìn trong sáng, tốt đẹp hơn cuộc sống. Aquamarine còn giúp chữa được  chứng mất ngủ, nấc cục và hắt hơi. Nhiều người còn tin rằng đá Aquamarine sẽ là  món quà tuyệt vời dành cho các thủy thủ hoặc những người hay đi biển bởi  cho rằng màu xanh của viên đá tuyệt vời này sẽ đem lại bình an, may mắn những cuộc  hành trình dài trên biển.

**Mặt Aquamarine có kiểm định đá quý SJC của TheGioiDaQuy.Net**

- Đá Aquamarine được  xếp cùng loại với những loại đá quý nhất hiện nay như Kim cương,  Ruby và Sapphire và nó luôn sở hữu một vẻ đẹp hoàn hảo.

- Theo phương Tây đá  Aquamarine thích hợp cho những người sinh vào tháng 3 và những người tuổi  Sửu. Theo phương Đông thì nó phù hợp cho người mạng Mộc, mạng thuỷ.

- Aquamarine đem lại nhiều may mắn, làm tăngvẻ đẹp của người sở hữu và  thịnh vượng cho gia chủ. Người Trung Hoa thì cho rằng**đá quý  Aquamarine**sẽ giúp bạn trở nên thông thái,  tinh thông và có một sức mạnh phi phàm.

[*TheGioiDaQuy.Net*](https://web.archive.org/web/20140527065845/http://thegioidaquy.net/phongthuy.html)',
    '2014-05-22 09:00:00', 0, 960, 'published'
);

