INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-057', 'vo-so-khong-lo-o-quan-dao-truong-sa', 'Vỏ sò khổng lồ ở quần đảo Trường Sa', 'Thế Giới Đá Quý',
    '/uploads/news/art-062-1-vo-so-khong-lo-hoa-thach.jpg', 'Vỏ sò khổng lồ nghìn năm ở quần đảo Trường Sa được kết tinh từ hàng nghìn năm, trải qua quá trình biến đổi lâu dài và khắc nghiệt, chiếc vỏ sò khổng lồ hóa thành ngọc quý giá trị có thể sánh ngang với bất cứ một loại đá quý nào.', '## Trầm tích nghìn năm của Biển

Phải thấy tận mặt, sờ tận tay mới có thể tin được trên  đời này lại có một[**chiếc vỏ sò khổng lồ**](https://web.archive.org/web/20140313232858/http://thegioidaquy.net/phong-thuy/vo-so-khong-lo-hoa-thach-3202.html#.UwJsrieahaV)lớn và to như vậy. Nhìn kích cỡ có thể  hình dung đó phải là một**con Sò khổng lồ**với độ dài tầm 1m, dày khoảng  50-60cm, nặng trên 100kg. Theo ý kiến của một số chuyên gia, để đạt  được kích thước khổng lồ như vậy, con Sò có thể đã phải sống đến một ngàn  năm tuổi dưới đáy biển.

- Xung quanh xuất xứ chiếc*vỏ sò khổng lồ*này, ông  Đông không giấu nổi xúc động khi nhớ lại những giây phút đầu tiên được  chạm tay vào báu vật của biển. Đó là năm 2009, khi ông có mặt ở TP. Đà  Lạt để tham dự một cuộc*triển lãm cổ vật*quy mô lớn. Ngay khi nghe giới  thiệu về chiếc**vỏ sò hóa thạch 1.000 năm**được trục vớt từ Trường Sa cập  bến đất liền, ông đã nảy sinh lòng yêu mến. Và khi được chạm tay vào lớp  trầm tích lắng đọng bao vết tích của thời gian, trong đầu ông đã   mường tượng ra vẻ đẹp tuyệt mỹ bên trong của nó và thầm ao ước sẽ được  trở về cùng báu vật này. Tất nhiên, ông chỉ là một trong vô số những  nhân vật có tiếng tăm trong giới buôn bán, sưu tầm cổ vật có mặt tại  buổi triển lãm muốn có được chiếc**vỏ sò hóa thạch hiếm hoi**này.

[![Vỏ sò khổng lồ ở phong thuỷ Hoa Mộc Lan](/uploads/news/art-062-1-vo-so-khong-lo-hoa-thach.jpg)](https://web.archive.org/web/20140313232858/http://thegioidaquy.net/phong-thuy/vo-so-khong-lo-hoa-thach-3202.html#.UwJsrieahaV)

***Vỏ sò khổng lồ ở cửa hàng phong thuỷ Hoa Mộc Lan***

-*Giá trị của chiếc vỏ sò được đẩy lên mỗi lúc một cao*khi số người đến  trả giá ngày càng đông và mức giá đưa ra ngày một lớn. Mặc dù rất muốn  có được chiếc*vỏ sò quý hiếm*này, một kỷ vật vô giá được mang đến từ Trường  Sa nhưng do điều kiện kinh tế nên ông không thể  đưa ra mức giá cao hơn 50 triệu đồng. Trong khi đó, hai thương gia  đến từ Trung Quốc và Đài Loan sẵn sàng trả gấp 10 số tiền đó để có được  chiếc vỏ sò hóa thạch khổng lồ quý giá kia.

- Họ còn tận dụng tất cả những mối quan hệ trong  giới làm ăn để thuyết phục chủ nhân của chiếc**vỏ sò**đồng ý bán. Lo lắng  khi một**báu vật biển của Việt Nam**, nhất là khi báu vật ấy lại được đưa  về từ Trường Sa, vùng đảo thiêng liêng của tổ quốc có thể bị người nước  ngoài mua mất, ông đã trực tiếp gặp chủ nhân của nó để bày tỏ những  suy nghĩ của mình. Không ngờ, vị chủ nhân của chiếc vỏ sò cũng có những  suy nghĩ giống y như vậy. Cảm kích trước tấm lòng đáng quý đó vị chủ nhân kia đã không ngần ngại*trao lại chiếc vỏ sò khổng lồ  quý giá cho nhà điêu khắc với giá 50 triệu đồng*. Thế mới biết, người  dân Việt Nam yêu quý Trường Sa biết nhường nào và trong trường hợp này,  tiền bạc không còn sức mạnh mua, bán nữa.

## Chạm khắc vỏ sò khổng lồ thành tác phẩm "Tùng Hạc"

*Vỏ sò khổng lồ chạm cây Tùng và chim Hạc*

- Mảnh vỏ sò mới khai thác vẫn còn  nguyên lớp trầm tích bên ngoài.  Nhưng sau quá trình làm sạch, loại bỏ lớp vỏ bọc bên ngoài, lớp hóa  thạch bên trong dần lộ ra sáng trong như ngọc. Trước vẻ đẹp tuyệt mỹ thiên nhiên ấy, dường như không ai có thể cầm lòng được. Khó có thể diễn  tả được cảm xúc của ông và đồng nghiệp khi bắt  tay vào   việc tạo tác trên**vỏ ngọc quý**. Bởi họ chưa từng thực hiện một tác phẩm  điêu khắc trên một vật báu mà ai cũng cảm thấy nó rất đỗi thiêng liêng  đối với mình. Chiếc vỏ sò không chỉ là một tặng phẩm tuyệt mỹ của thiên  nhiên mà còn mang dấu ấn chủ quyền thiêng liêng của Tổ quốc.

- Xuất phát từ giá trị vật chất lẫn tinh thần của**vỏ sò hóa thạch**được  mang về từ Trường Sa, ông  quyết định sẽ thực hiện tác  phẩm điêu khắc với tên gọi "Tùng Hạc" thể hiện khát vọng trường tồn của dân  tộc.

- Tùng là loài cây mọc trên những đỉnh núi cao chót  vót, quanh năm khô cằn, thiếu dinh dưỡng. Cây thường mọc trên những mỏm  núi chênh vênh, chịu nhiều sương gió, quanh năm phải đương đầu với bão  tố, mưa giông nhưng vẫn hùng dũng vươn thẳng lên trời xanh. Bởi vậy   người xưa xem Tùng là đại diện cho trăm cây, là biểu tượng cho sức  sống bền bỉ, sự trường tồn và khí tiết của người quân tử. Ngoài ra,  người xưa còn coi Tùng như một cây thiêng có khả năng trừ tà, đuổi ma,  mang lại sự yên lành cho cuộc sống của con người. Còn hạc trong truyền  thuyết là một loài chim tiên vừa tượng trưng cho sự trường thọ vừa thể  hiện khí tiết thanh cao, không chịu cúi mình trước khó khăn, thử thách.

- Từ đó ông cùng đồng nghiệp đã thực hiện tuyệt phẩm "Tùng Hạc" trên  sò   ngọc khổng lồ, vừa thể hiện khát vọng về sự trường tồn dân tộc vừa gửi gắm tình  cảm của mình tới Trường Sa thân yêu.

- Với tuyệt phẩm này, ông Đông tin rằng bất cứ ai  mỗi khi được chiêm ngưỡng nó sẽ thêm yêu và tự hào về quê hương đất  nước mình. Ông cũng cho biết, cách đây không lâu, có một nhà sưu tập cổ  vật đến từ Thái Lan đã trả giá hơn 200 triệu đồng cho tác phẩm "Tùng Hạc"  được tạo tác trên vỏ sò hóa thạch từ Trường Sa nhưng ông không bán. Bởi  ngay từ đầu,khi mảnh vỏ sò vẫn còn nằm trong những lớp trầm tích bao  bọc, vị chủ nhân của nó đã từ chối món tiền bạc   tỷ của những vị khách nước ngoàiđể trao lại cho ông. Và giờ, sau bao  tháng ngày cực khổ để tạo nên một tuyệt tác nghệ thuật, ông lại  càng không thể bán[**vỏ sò khổng lồ**](https://web.archive.org/web/20140313232858/http://thegioidaquy.net/phong-thuy/vo-so-khong-lo-hoa-thach-3202.html#.UwJsrieahaV)này cho một vị khách nước ngoài khác để phụ tấm lòng  của người đã tin tưởng trao nó cho ông.

*[Thegioidaquy.net](https://web.archive.org/web/20140313232858/http://thegioidaquy.net/phongthuy.html)sưu tầm*',
    '2014-02-18 09:00:00', 0, 1046, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-058', 'cong-dung-da-rhodonite', 'Công dụng đá Rhodonite', 'Thế Giới Đá Quý',
    '/uploads/news/art-063-1-1cong-dung-da-rhodonite.jpg', 'Rhodonite được đặt tên theo từ Hy Lạp rhodos có nghĩa là màu hồng. Nó có màu hồng với những chấm mangan đen nhưng có thể có màu vàng, nâu đỏ hoặc đen.', '**Đặc tính chữa bệnh**

-[Đá](https://web.archive.org/web/20260411174044/http://thegioidaquy.net/tin-tuc/cong-dung-da-tanzanite-1453.html)Rhodonite tương thích mạnh mẽ với chakra tim. Nó giúp ta quên đi những vết thương trong quá khứ và chữa lành trái tim.

-**Rhodonite**là tinh thể của lòng thương giúp ta thể hiện được tình yêu với chính mình và với mọi người.

-*Rhodonite*xua tan sợ hãi và lo lắng. Nó có thể được dùng ngay sau một sự kiện đau buồn nhằm đem lại cân bằng và bình tĩnh.

- Ở những nơi mà cay đắng, đố kỵ, giận dữ, ích kỉ và buồn phiền được kìm nén,***rhodonite***giúp chúng nổi lên bề mặt để được giải phóng.

-*Rhdonite*cực kỳ hiệu quả cho các vết cắt, vết thương và vết côn trùng cắn. Nó hút chất độc ra khỏi cơ thể để nhanh lành vết thương.

- Nó còn tăng khả năng sinh sản và ham muốn. Tinh thể này cũng rất tốt cho bệnh tim.

[![cong-dung-da-rhodonite](/uploads/news/art-063-1-1cong-dung-da-rhodonite.jpg)](https://web.archive.org/web/20260411174044/http://thegioidaquy.net/tin-tuc/danh-muc-tin-56-The-gioi-da-quy/page/7)

*[Thế giới đá quý](https://web.archive.org/web/20260411174044/http://thegioidaquy.net/tin-tuc/cong-dung-da-beryl-1452.html)-Rhdonitecực kỳ hiệu quả cho các vết cắt, vết thương và vết côn trùng cắn*

[*TheGioiDaQuy.net*](https://web.archive.org/web/20260411174044/http://thegioidaquy.net/phongthuy.html)',
    '2013-12-26 09:00:00', 0, 1089, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-059', 'cong-dung-da-tanzanite', 'Công dụng đá Tanzanite', 'Thế Giới Đá Quý',
    '/uploads/news/art-064-1-1cong-dung-da-tanzanite.jpg', 'Tanzanite là một khoáng vật màu xanh dịu thuộc nhóm zoisite. Tanzanite có màu từ trong suốt đến nâu vàng, xanh lá và xanh lam đến tím. Loại tanzanite xanh tím chữa bệnh rất tốt.', 'Tanzanite có tính đổi 3 màu: nghĩa là khi nhìn viên đá theo các phương khác nhau sẽ thấy màu màu khác nhau. Một phương thấy màu xanh, phương thì màu tím và còn lại là màu đồng thau, cùng với độ màu thay đổi nhẹ.

[Đá](https://web.archive.org/web/20140105083505/http://thegioidaquy.net/tin-tuc/cong-dung-da-beryl-1452.html)Tanzanite có màu từ xanh mạnh đến tím phớt xanh mạnh. Màu xanh là được ưa thích nhất.

Tanzanite thường phổ biến nhất ở dạng cắt hình nệm, nhưng những dạng khác cũng có. Đá thành phẩm cỡ lớn cũng có khá nhiều.

**Đặc tính chữa bệnh**

-**Tanzanite**tương thích với chakra trán và đỉnh đầu cũng như chakra cổ họng.

- Bằng cách kích hoạt khả năng ngoại cảm và nâng cao rung động của ta, nó tăng cường sự liên lạc với thế giới tâm linh, giúp ta kết nối được với các thế giới khác.

- Thêm vào đó, nó còn cho ta khả năng nhận được hình ảnh từ thế giới tâm linh.

- Là một tinh thể của sự thay đổi sẽ loại bỏ những căn bệnh và nghiệp chướng từ kiếp trước,*tanzanite*giúp ta tiến lên với sự lạc quan và cảm hứng, cho ta định hướng rõ ràng và giúp ta có thể biểu lộ sức mạnh của bản thân.

-**Tanzanite**đẩy mạnh sự hồi phục ở mọi cấp độ, cũng như bảo vệ những người đang làm nhiệm vụ chữa bệnh.

- Nó kết hợp rất tốt với iolite, kunzite, phenacite và morganite. Về thể chất,***tanzanite làm sạch cổ họng***và phổi đồng thời chữa các bệnh da liễu, mắt và tai.

- Nó còn tăng cường hệ miễn dịch, tăng tốc độ hồi phục sau một căn bệnh và giải độc cũng như tái sinh các tế bào và các mô. Những tác dụng khác của tanzanite bao gồm chữa bệnh xương khớp và hệ sinh dục.

[![cong-dung-da-tanzanite](/uploads/news/art-064-1-1cong-dung-da-tanzanite.jpg)](https://web.archive.org/web/20140105083505/http://thegioidaquy.net/tin-tuc/danh-muc-tin-56-The-gioi-da-quy/page/6)

*[Thế giới đá quý](https://web.archive.org/web/20140105083505/http://thegioidaquy.net/tin-tuc/cong-dung-da-hematite-1451.html)-Tanzaniteđẩy mạnh sự hồi phục ở mọi cấp độ*

[*TheGioiDaQuy.net*](https://web.archive.org/web/20140105083505/http://thegioidaquy.net/phongthuy.html)',
    '2013-12-26 09:00:00', 0, 1132, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-060', 'cong-dung-da-beryl', 'Công dụng đá Beryl', 'Thế Giới Đá Quý',
    '/uploads/site_assets/Phongthuy-HoaMocLan-thegioidaquy.jpg', 'Tên gọi berin bắt ngồn từ Berillos được người Hy Lạp cổ đại dùng để gọi những khoáng vật trong suốt có màu xanh lá cây bất kỳ. Berin giúp điều trị đau lưng, cảm lạnh, sổ mũi. Có khả năng điều hòa các phản ứng trao đổi chất.', 'Beryl là biểu tượng của[chòm sao Song tử](https://web.archive.org/web/20140105083459/http://thegioidaquy.net/tin-tuc/tinh-cach-dac-biet-cua-nhom-khi-bao-binh-thien-binh-va-song-tu-1364.html)và Thiên Ất trong cung hoàng đạo. Bery là một loại khoáng vật có rất nhiều màu sắc khác nhau đỏ, hồng, tím, vàng, lam,...

**Công dụng của đá Beryl:**

**1. Tính chất chữa bệnh:**

**- Beryl**giúp điều trị đau lưng, cảm lạnh, sổ mũi. Có khả năng điều hòa các phản ứng trao đổi chất.

- Đeo đồ trang sức có gắn Beryl để chữa các bệnh phụ khoa.

- Từ xa xưa ở Phương Đông, beryl được xem là đá màu nhiệm truyền năng lượng hồi sinh cho cơ thể, và ngược lại lấy đi năng lượng tiêu cực. Nó giúp cho con người gìn giữ được sự sảng khoái tinh thần và ngăn ngừa sự mệt mỏi.

**2. Tính chất màu nhiệm:**

-*Beryl*gắn kết với tư duy và trí lực, trợ giúp trong những vụ kiện tụng.

- Những người chậm hiểu và lười biếng khi đeo loại đá này có thể trở nên chăm chỉ và thông minh hơn.

-Berylcòn có khả năng khơi lại tình yêu của các cặp vợ chồng.

**3. Công dụng khác**

- Thứ trong suốt có màu đẹp làm ngọc. Quặng của**beryl**là kim loại nhẹ tạo nên những hợp kim rất bền với Al và Mg, rất quan trọng trong kỹ nghệ chế tạo máy bay. Ngoài ra còn tạo nên nhiều hợp kim quan trọng với các kim loại khác. Các muối của beryl dùng trong công nghệ và y học.

*[Thế giới đá quý](https://web.archive.org/web/20140105083459/http://thegioidaquy.net/tin-tuc/cong-dung-da-hematite-1451.html)-Berylcòn có khả năng khơi lại tình yêu của các cặp vợ chồng.*

[*TheGioiDaQuy.net*](https://web.archive.org/web/20140105083459/http://thegioidaquy.net/phongthuy.html)',
    '2013-12-26 09:00:00', 0, 1175, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-061', 'cong-dung-da-hematite', 'Công dụng đá Hematite', 'Thế Giới Đá Quý',
    '/uploads/news/art-066-1-1cong-dung-da-hematite.jpg', 'Tên của Hematite bắt nguồn từ tiếng Hy Lạp haimatites, có nghĩa là “giống như máu” (ám chỉ màu đỏ tươi của tinh thể). Trong thời Trung cổ, nó được biết đến như “blood-stone”. Hematite được dùng để cầm máu và là chất cấu thành máu tại Ai Cập.', '[Đá](https://web.archive.org/web/20140105073955/http://thegioidaquy.net/tin-tuc/cong-dung-da-kianite-1450.html)Hematite thường có màu đen, xám, đỏ hoặc đỏ nâu.

**Đặc tính chữa bệnh**

**- Hematite**tương thích với chakra gốc cột sống và củng cố mối lien hệ của ta với trái đất, giúp ta thấy an toàn và ban cho ta can đảm, sức mạnh, sức chịu đựng và sức sống.

- Vừa giải phóng khí độc khỏi cơ thể,*hematite*vừa giữ bạn khỏi năng lượng bất lợi từ người khác, nên bạn có thể đem theo một viên trong túi nhằm bảo vệ mình.

- Đây là một tinh thể giữ bình tĩnh, nên bạn có thể dùng nó để chữa chứng mất ngủ, stress và lo lắng.

- Nó cũng có lợi vào cuối buổi trị liệu với những người còn chưa tỉnh táo hoàn toàn.**Hematite có năng lực giữ bạn bình tĩnh**và làm mát người, nên hãy đặt một viên lên trán khi sốt hay đặt nó trên những nơi bị sưng tấy để làm dịu chúng.

- Thường được cho là có liên hệ với máu,***hematite***được dùng để chữa bệnh thiếu máu, dù nó cũng tăng chất lượng máu và giảm huyết áp. Nó được khuyên dùng trong khi sinh, phần để tránh mất máu, phần giúp mọi người bình tĩnh hơn.

- Những người bị viêm khớp, chuột rút và các chứng thuộc cơ xương có thể đặt một viên hematite dưới gối để giảm đau.

[![cong-dung-da-hematite](/uploads/news/art-066-1-1cong-dung-da-hematite.jpg)](https://web.archive.org/web/20140105073955/http://thegioidaquy.net/tin-tuc/danh-muc-tin-56-The-gioi-da-quy/page/4)

*[Thế giới đá quý](https://web.archive.org/web/20140105073955/http://thegioidaquy.net/tin-tuc/cong-dung-da-emerald-1449.html)-Hematite có năng lực giữ bạn bình tĩnhvà làm mát người*

[*TheGioiDaQuy.net*](https://web.archive.org/web/20140105073955/http://thegioidaquy.net/phongthuy.html)',
    '2013-12-26 09:00:00', 0, 1218, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-062', 'cong-dung-da-kianite', 'Công dụng đá Kianite', 'Thế Giới Đá Quý',
    '/uploads/site_assets/Phongthuy-HoaMocLan-thegioidaquy.jpg', 'Kyanite là loại đá có màu xanh lam đậm, trông rất sang trọng. Kích thước đá vừa vặn để làm mặt nhẫn. Kyanite là viên đá củng cố quyền lực và có tác dụng tốt cho cổ họng.', 'Kyanite là loại[đá](https://web.archive.org/web/20140105081416/http://thegioidaquy.net/tin-tuc/cong-dung-da-emerald-1449.html)được dùng thay thế cho Royal Blue Sapphire là đá tháng sinh của tháng 9 với giá thành rẻ hơn, và màu sắc đẹp hơn nhiều. Đá có màu xanh lam đậm, trông rất sang trọng. Kích thước đá vừa vặn để làm mặt nhẫn. Đá tự nhiên hoàn toàn và có độ cứng khá cao (Ngang thạch anh), rất thích hợp để làm trang sức.

***Kyanite***được phát hiện ra vào thế kỉ 19. Kyanite có màu xanh lam hoặc xanh lục – lam là đắt tiền nhất. Ngoài ra người ta cũng tìm thấy Kyanite màu vàng, xám, trắng và không màu được cho là khá hiếm.

**Công dụng đá Kyanite:**

-Kyanite là viên đá củng cố quyền lựcvà có tác dụng tốt cho cổ họng.

- Có thời người ta đã tin rằng dùng một sợi tóc treo viên đá Kyanite lơ lửng trong không khí sẽ sinh ra lực hút trái đất. Những nhà thám hiểm đầu tiên đã sử dụng nó như một la bàn trong khi khám phá những lãnh thổ chưa được biết đến.

-***Kyanite***là viên đá tạo ra sự cân bằng cho toàn bộ các phần của cơ thể, mang đến sự yên tĩnh và thanh thản cho tâm hồn,giúp con người tập trung và tái tạo nguồn năng lượng mới.

- Kyanite hợp với những người mệnh Thủy hoặc Mộc.

-*Kyanite*là biểu tượng của chòm sao Bạch Dương, Kim Ngưu, Thiên Bình trong[cung hoàng đạo](https://web.archive.org/web/20140105081416/http://thegioidaquy.net/tin-tuc/su-nghiep-nguoi-tuoi-mao-theo-cung-hoang-dao-1439.html).

*Kyanitelà[viên đá](https://web.archive.org/web/20140105081416/http://thegioidaquy.net/tin-tuc/cong-dung-da-bloodstone-1448.html)tạo ra sự cân bằng cho toàn bộ các phần của cơ thể*

[*TheGioiDaQuy.net*](https://web.archive.org/web/20140105081416/http://thegioidaquy.net/phongthuy.html)',
    '2013-12-26 09:00:00', 0, 311, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-063', 'cong-dung-da-emerald', 'Công dụng đá Emerald', 'Thế Giới Đá Quý',
    '/uploads/news/art-068-1-1cong-dung-da-emerald.jpg', 'Emerald là một trong bốn loại đá quý nhất, được xếp vào nhóm I chỉ đứng sau Kim Cương, Ruby và Sapphire. Emerald rất hiếm và có giá trị cao. Với những viên màu đẹp nhỏ hơn 5 carat thì Emerald có thể sẽ cao giá hơn Ruby hay Sapphire.', '***Emerald***là biểu tượng của sự phát triển, sinh sôi, tính sáng tạo và tượng trưng cho sự thanh bình, hạnh phúc và tình yêu viên mãn. Đây là viên đá mang lại may mắn cho gia chủ sinh vào tháng 5, gia chủ[tuổi Mùi](https://web.archive.org/web/20140922054435/http://thegioidaquy.net/tin-tuc/hoa-giai-su-bat-hoa-giua-tuoi-suu-va-tuoi-mui-1225.html)và cũng là viên đá kỷ niệm năm cưới thứ 20, 35 hoặc 50.

Ở Việt Nam, đôi khi người ta gọi***Emerald***là lục ngọc hay lục bảo ngọc. Nhiều nhà cai trị khác nhau như nữ hoàng Ai Cập Cleopatra, vua Ấn Độ Shah Jahan và các vua Tây Ban Nha xem Emerald là báu vật nên nó đã trở thành một loại tiền tệ quốc tế trong hàng ngàn năm qua.

*Emerad giá trị nhất khi có màu lục mạnh sáng của cỏ mùa xuân sau cơn mưa*. Vì Emerald ở Columbia đã được xem là chuẩn mực bao thế kỷ nay cho nên loại màu lục thuần khiết, như thấy ở Columbia, thường được ưa chuộng hơn là màu lục hơi xanh sẫm của Emerald tại Phi châu.

Vì Emerald không tạp chất thường hiếm cho nên người ta chấp nhận Emerald có một số tạp chất nhất định và chúng không làm giảm giá trị viên đá. Tuy nhiên khi mua, bạn không nên chọn những viên nào có khe nứt quá lớn hay viên đá quá đục, vì chúng sẽ làm cho viên đá yếu đi và dễ bị nứt, bể khi vô tình va chạm mạnh.

Emerald thường được cắt mài theo kiểu hình chữ nhật, giác tầng mà mọi người hay gọi là kiểu Emerald. Các viên đá nhỏ thì lại được mài theo dạng tròn, ovan, giọt nước, hạt dưa. Nhờ màu đậm nên Emerald cũng rất đẹp khi được mài theo dạng cabochon.

Emerald phân bố chủ yếu tại Zambia, Brasil, Nova Era, Nga, Ural, Zimbabwe, Sandawana, Madagascar, nhưng ngọc lục bảo nhiều, đẹp và tinh khiết nhất lại nằm ở các mỏ tại Colombia.

**Emerald – Đá hộ mệnh**

- Ngày nay,***đá Emerald được gắn lên trang sức***để làm tôn lên vẻ đẹp, sự quyến rũ cho nữ giới cũng như sự sang trọng cho những ai sở hữu. Lục bảo ngọc rất đặc biệt, nó không có vẻ kiêu sa của hồng ngọc hay vẻ thùy mị của ngọc trai mà mang một nét đẹp đầy sức sống. Các quý bà giàu có và giới doanh nhân rất ưu chuộng loại đá quý này.

- Ngoài ra, Emerald được biết đến như sự hy vọng và khôn ngoan. Viên đá sẽ mang đến sự tập trung cao độ, cho phép nhìn thấy giải pháp tối ưu nhất để vượt qua những khó khăn. Nếu bạnđặt Emerald nơi làm việc, nó sẽ giúp cải thiện trí nhớ và tăng cường khả năng trí tuệ. Qua năng lực kích thích hoạt động não bộ và tăng cường trí nhớ, Emerald giúp ta ra quyết định chính xác hơn.

[![cong-dung-da-emerald](/uploads/news/art-068-1-1cong-dung-da-emerald.jpg)](https://web.archive.org/web/20140922054435/http://thegioidaquy.net/tin-tuc/danh-muc-tin-56-The-gioi-da-quy/page/2)

*[Thế giới đá quý](https://web.archive.org/web/20140922054435/http://thegioidaquy.net/tin-tuc/cong-dung-da-bloodstone-1448.html)- Đặt đá Emerald tại nơi làm việcsẽ giúp cải thiện trí nhớ và tăng cường khả năng trí tuệ*

- Bên cạnh đó,**đá quý Emerald**được coi là bùa hộ mệnh đem lại may mắn, sức khoẻ, thành công cho những người sinh vào tháng 5 theo quan niệm phương Tây và mang lại những điều tốt đẹp cho những gia chủ tuổi Mùi theo quan niệm phương Đông. Nó cũng là viên đá kỷ niệm 20 và 35 năm ngày cưới. Một món trang sức gắn đá Emerald tặng cho mẹ cũng mang nhiều ý nghĩa, vì tháng 5 được quan niệm là tháng của mẹ.

[*TheGioiDaQuy.net*](https://web.archive.org/web/20140922054435/http://thegioidaquy.net/phongthuy.html)',
    '2013-12-26 09:00:00', 0, 354, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-064', 'cong-dung-da-bloodstone', 'Công dụng đá bloodstone', 'Thế Giới Đá Quý',
    '/uploads/site_assets/Phongthuy-HoaMocLan-thegioidaquy.jpg', 'Đá bloodstone còn có tên khác là heliotrope. Tên này bắt nguồn bằng một từ Hy Lạp có nghĩa là “chí điểm”, chỉ ra khả năng chữa bệnh của nó. Đôi khi nó được gọi là ngọc thạch anh lục hoặc ngọc thạch anh máu.', '[Đá](https://web.archive.org/web/20140429231359/http://thegioidaquy.net/tin-tuc/cong-dung-da-moonstone-da-mat-trang-1447.html)Bloodstone có màu vân thạch xanh lục chấm chấm những đốm màu đỏ sáng ngời của ôxit sắt. Bloodstone thuộc nhóm Thạch anh chalcedony. Nó được biết như đá tháng sinh trong Tháng ba.

Những tín đồ Cơ đốc thời Trung cổ thường sử dụng**bloodstone**để nhắc những cảnh đóng đinh vào thánh giá của Chúa. Theo lời chú thích về*nguồn gốc của bloodstone*, nó đã được thành lập khi máu của Chúa rơi và làm biến màu vân thạch ở nơi bàn chân Chúa đi qua khi mang Thập giá. Một ví dụ, bloodstone được khắc làm con dấu của Hoàng đế Đức Rudolf II và trưng bày tại bảo tàng Louvre ở Paris.

***Bloodstone***được sử dụng cho sự khôi phục. Nó có lợi cho máu và hệ tuần hoàn, da và tóc. Thậm chí ngày nay, bloodstone được nghiền thành bụi sử dụng như một thuốc kích dục ở ấn Độ. Bloodstone được đào ở Ấn Độ, Australia và Mỹ.

**Đặc tính chữa bệnh**

-*Bloodstone tương thích với chakra gốc*, cho ta cột chống mạnh mẽ và sự kiên định. Đây là tinh thể của sức mạnh và lòng can đảm, nên rất tốt cho việc củng cố sức mạnh thể chất và tinh thần.

-***Bloodstone***rất hữu dụng để giảm bớt các rắc rối về tinh thần và thể chất liên quan đến tim mạch nên rất tốt cho những người muốn thiết lập quan hệ mạnh mẽ và vững chắc.

- Thường được dùng cho rối loạn về máu, nó tẩy uế và củng cố cho máu, nênbloodstone hoàn hảo cho bệnh thiếu máu. Là một trong những loại tinh thể hiệu quả nhất cho hệ miễn dịch, ta nên đặt nó trên ức hoặc tim. Do khả năng làm tan mủ, trung hòa chất độc và kích hoạt hệ bạch huyết, bloodstone rất tốt để chữa sưng tấy và viêm nhiễm.

*[Thế giới đá quý](https://web.archive.org/web/20140429231359/http://thegioidaquy.net/tin-tuc/cong-dung-da-opal-1446.html)- Đá bloodstone rất hữu ích trong việc chữa trị bệnh thiếu máu*

[*TheGioiDaQuy.net*](https://web.archive.org/web/20140429231359/http://thegioidaquy.net/phongthuy.html)',
    '2013-12-26 09:00:00', 0, 397, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-065', 'cong-dung-da-moonstone-da-mat-trang', 'Công dụng đá MoonStone (Đá mặt trăng)', 'Thế Giới Đá Quý',
    '/uploads/news/art-070-1-1cong-dung-da-moonstone-da-mat-trang.jpg', 'Hình ảnh ánh trăng màu xanh chiếu xuyên qua bầu trời làm cho bạn hiểu vì sao một loại đá thuộc nhóm fenpat đã được đặt tên là đá mặt trăng (moonstone). Ánh sáng lung linh của nó di chuyển khắp mặt viên đá y như ánh trăng.', '[Đá](https://web.archive.org/web/20161002164708/http://thegioidaquy.net/tin-tuc/cong-dung-da-opal-1446.html)mặt trăng có thể có nhiều màu. Đá thường không màu, trắng hay xám phớt xanh nhạt có hiệu ứng ngời sáng màu trắng hay xanh. Những màu khác như nâu, vàng, lục hay hồng xanh thì hiếm hơn. Đá từ trong suốt đến trong mờ. Đá mặt trăng đẹp nhất thì có độ trong cao, không màu, ngời sáng màu xanh. Đôi khi đá cũng giống như con mắt ngời sáng.

Đá được khai thác ở Sri Lanka, miền nam Ấn Độ, Miến Điện, và Mexico. Loại cầu vồng có ở Ấn Độ và Madagasca.

**Công dụng đá Moonstone:**
**1. Tính chất trị liệu**

- Trong y học Tây Tạng ,**đá mặt trăng**được dung để chữa bệnh động kinh và bệnh tâm thần. Các nhà thạch trị liệu học hiện đại cũng viết rằng, đá mặt trăng ngăn ngừa các căn bệnh động kinh và thần kinh khác. Cho rằng, đồ trang sức bằng đá mặt trăng có tác dụng tốt tới thận, bang quang và niệu đạo, giúp điều trị phù thũng .

**2. Tính chất mầu nhiệm**

- Trong yêu thuật có truyền thống cho rằng, loại đá này có liên hệ mật thiết với mặt trăng, vì vậy sức mạnh tác động của nó tăng lên trong kỳ trăng tròn. Cho rằng,*đá mặt trăng*có thể xoa dịu những ngưòi bị ảnh hưởng không tốt trong kỳ trăng tròn bằng cách hấp thụ năng lượng kích thích của Mặt Trăng.

-*Đá mặt trăng tiếp thụ và hấp dẫn tình yêu*; đeo nó để đem lại tình cảm trong cuộc sống.

- Ngưòi Hindu cho rằng, nó hấp thụ năng lượng mát dịu của mặt trăng, trấn an trí não, khơi dậy trong con ngưòi ứơc mơ và sự trìu mến. Đá mặt trăng có khẳ năng làm nguôi cơn giận và loại bỏ sự căng thẳng thần kinh.

[![cong-dung-da-moonstone-da-mat-trang](/uploads/news/art-070-1-1cong-dung-da-moonstone-da-mat-trang.jpg)](https://web.archive.org/web/20161002164708/http://thegioidaquy.net/tin-tuc/danh-muc-tin-56-The-gioi-da-quy/page/5)

*[Thế giới đá quý](https://web.archive.org/web/20161002164708/http://thegioidaquy.net/tin-tuc/cong-dung-da-Sodalite-1445.html)- Đá mặt trăng tiếp thụ và hấp dẫn tình yêu; đeo nó để đem lại tình cảm trong cuộc sống.*

**3. Ảnh hưởng tới luân xa**

- Đối với luân xa ở vùng tim; ảnh hưởng tới hệ tim mạch, tế bào tuyến vú, cột sống và hai tay; luân xa này khoi gợi long nhân ái, tính cởi mở chân thành và sự nhạy cảm.

*[*TheGioiDaQuy.net*](https://web.archive.org/web/20161002164708/http://thegioidaquy.net/phongthuy.html)*',
    '2013-12-26 09:00:00', 0, 440, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-066', 'cong-dung-da-opal', 'Công dụng đá opal', 'Thế Giới Đá Quý',
    '/uploads/news/art-071-1-1cong-dung-da-opal.jpg', 'Opal là một trong những loại đá quý đẹp nhất trên Trái Đất. Những viên đá Opal có thể phản chiếu ánh sáng tạo thành hiện tượng như cầu vồng xuất hiện trên bề mặt đá, gọi là hiệu ứng lưỡng sắc Opan.', 'Trên thế giới,[đá](https://web.archive.org/web/20140806200316/http://thegioidaquy.net/tin-tuc/cong-dung-da-Sodalite-1445.html)Opal được chia làm hai nhóm chính: Opal quý và Opal thường. So với Opal thường, Opal quý rất dễ nhận biết bởi đặc điểm lóe sáng các sắc màu sặc sỡ khi người xem thay đổi hướng nhìn.

Căn cứ vào màu sắc, hiệu ứng lưỡng sắc Opan, độ trong của đá mà các nhà nghiên cứu đã chia Opan thành 400 kiểu, nhưng trong đó phổ biến nhất vẫn là các loại: Opan trắng, Opan đen, Opal nước, Opan pha lê, Opal lửa, v.v… Mặt khác, màu sắc của đá Opan cũng khác đa dạng bao gồm trắng, xám, đen, cam, vàng, xanh lá cây, xanh biển, đỏ tươi, màu ô-liu v.v…

**Công dụng của đá Opal**

**1. Tính chất chữa bệnh:**

- Người Hinđu tin rằng, opal giúp cho trẻ em mau lớn.

- Có ý kiến cho rằng, khi opal mất đi ánh lấp lánh là dấu hiệu báo có bệnh ở chủ nhân của đá.

- Các nhà thạch học trị liệu hiện đại cho rằng, opal phát triển trực giác và có ảnh hưởng tốt tới hệ thần kinh, tuyến yên và đầu xương. Cho rằng, opal điều hoà tất cả các chức năng của cơ thể và bảo vệ chống bệnh nhiễm khuẩn.

**2. Tính chất khác:**

- Nhờ có sự phong phú về sắc màu mà từ thời cổ opal đã là biểu tượng của sự thất thường, tượng trưng cho số phận hay thay đổi, nó làm cho trực giác trở nên tinh nhạy và giúp tạo ra cảm hứng.

- Ở Phương Đông, nhất là Ấn Độ, opal từ lâu đã được coi là đá của tình yêu, sự tin tưởng và lòng trắc ẩn. Bằng ánh lấp lánh trên bề mặt viên đá, opal soi sáng trí tuệ, xua đuổi những ý nghĩ u tối và nỗi sợ hãi.

- Khi nhìn vào opal, những thầy pháp Ấn Độ hồi tưởng lại những hóa thân của mình trước kia.

[![cong-dung-da-opal](/uploads/news/art-071-1-1cong-dung-da-opal.jpg)](https://web.archive.org/web/20140806200316/http://thegioidaquy.net/tin-tuc/danh-muc-tin-56-The-gioi-da-quy/page/4)

*Opal được coi là[đá](https://web.archive.org/web/20140806200316/http://thegioidaquy.net/tin-tuc/cong-dung-da-carnelian-1444.html)của tình yêu*

- Opal là biểu tượng của hạnh phúc, hy vọng và tình yêu trìu mến dịu dàng. Những loại đá này liên tưởng đến những ý nghĩ trong sáng và sự đồng cảm.

- Opal là biểu tượng của chòm sao Song ngư trong[cung hoàng đạo](https://web.archive.org/web/20140806200316/http://thegioidaquy.net/tin-tuc/bach-duong-hop-gu-nhat-cung-hoang-dao-nao-1337.html), năng lượng chiếu xạ của Dương tuỳ thuộc vào màu sắc của đá.

**3. Công dụng khác :**

- Opal quý dùng làm đá trang sức, trang hoàng. Đá khuê tảo (tripôli) dùng để đánh các đồ kim khí. Kissengua dùng để chế đồ gốm, làm gạch nhẹ.

[*TheGioiDaQuy.net*](https://web.archive.org/web/20140806200316/http://thegioidaquy.net/phongthuy.html)',
    '2013-12-26 09:00:00', 0, 483, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-067', 'cong-dung-cua-da-thien-thach', 'Công dụng của đá Thiên thạch', 'Thế Giới Đá Quý',
    '/uploads/site_assets/Phongthuy-HoaMocLan-thegioidaquy.jpg', 'Thầy lang địa phương Thái Lan thường dùng thiên thạch để chữa bệnh, giúp loại trừ những tổn thương về tình cảm, tăng cường năng lượng trao đổi chất trong cơ thể. Các Trạch Gia sử dụng trong việc chấn trạch cầu bình an và tài lộc cho gia chủ.', 'Trong vài năm gần đây phong trào chơi đá,[**đá phong thủy**](https://web.archive.org/web/20240222233205/http://thegioidaquy.net/phongthuy.html),[đá quý](https://web.archive.org/web/20240222233205/http://thegioidaquy.net/phong-thuy/da-phongthuy-119-Da-Sapphire)rộ lên  mạnh mẽ ở nhiều tỉnh thành trên cả nước thì[**đá thiên thạch**](https://web.archive.org/web/20240222233205/http://thegioidaquy.net/phong-thuy/da-phongthuy-239-Da-Thien-Thach-Tektite-)([Tektite](https://web.archive.org/web/20240222233205/http://thegioidaquy.net/phong-thuy/da-phongthuy-239-Da-Thien-Thach-Tektite-))  là một  trong số các loại đá được giới*chơi đá quý*tích cực săn lùng.  Cái tên**Tektite**xuất phát từ tiếng Hi Lạp cổ “tektos” nghĩa là nóng  chảy, ngụ ý nói về vai trò của nhiệt lượng từ thiên thạch trong nguồn gốc phát sinh Tektite. Tại Việt Nam có nhiều cách gọi loại đá này như đá thiên thạch, đá tektite, đá cứt sao, ngọc thiên thạch.

- Theo 2 cuốn "Tất cả về khoáng vật chữa bệnh mầu nhiệm" và cuốn "Tất cả về đá quý" của Jasper Stone, này thì**thiên thạch**được  hình thành do sự va đập của mảnh vỡ các tiểu hành tinh lên bề mặt  trái  đất. Sự va đập này tạo nên một vụ nổ lớn, những mảnh vỡ của tiểu  hành  tinh và những mảnh vật chất của trái đất bị nóng chảy, bị bắn lên  không  trung, lại bị nóng chảy một lần nữa do ma sát với tầng khí quyển  khi rơi  xuống, xoay tròn trong không khí tạo nên vô vàn hình thù đặc  biệt.

- Theo Tiến sỹ Trịnh Sơn- một chuyên gia của Bộ Tài Nguyên và  Môi Trường,  người có nhiều công trình**nghiên cứu về****thiên thạch**và đã  bảo vệ luận văn tiến sỹ về đề tài này tại nước ngoài thì thiên  thạch  thường có nguồn gốc từ trái đất hơn là từ các mảnh vỡ của các tiểu  hành  tinh.

- Theo cuốn Meteors and Meteorites của David C.Knight (Mỹ) thì có**nhiều loại thiên thạch**,  có thể là mảnh vụn của sao băng khi rơi qua tầng khí quyển vào trái đất  hoặc hình thành do sự va chạm của thiên thạch lên trái đất, hấp thu  năng lượng từ vụ va chạm này tạo nên thiên thạch.

- Cũng  có nhiều tác giả lại cho rằng nó chỉ là tro của núi lửa bắn lên,  đông  cứng lại mà thành. Tuy nhiên giả thuyết này ít thuyết phục hơn, bởi  nếu  hình thành qua con đường này thì thiên thạch không thể bị đến hai  lần  “thủy tinh hóa” được. Qua nghiên cứu địa tầng và phân tích đồng vị  phóng  xạ thì**thiên thạch có tuổi khoảng 10 triệu năm**và thành phần chủ  yếu là silic dioxit (68 -  82%); kích thước trung bình hiếm khi vượt quá  5cm, nặng chừng 500g.  Loại thiên thạch phân lớp có thể có trọng lượng  lớn hơn.

- Nhiều  năm trước đây, Liên doanh Đá quý Việt Nhật (Thanh Xuân - Hà Nội)  đã cho  nhân viên đi khắp các vùng miền đất nước mua gom một lượng**thiên thạch  khổng  lồ**về để chế tác và xuất khẩu. Việc này khiến cho số lượng*[thiên  thạch  tại Việt Nam](https://web.archive.org/web/20240222233205/http://thegioidaquy.net/phong-thuy/vien-da-thien-thach-tho-2508.html#.USZdb6zlbIU)*trở nên khan hiếm. Ngày nay chủ yếu chỉ còn xuất  hiện thiên  thạch loại nhỏ, được chế tác thành các trang sức đá hoặc để[**thiên thạch thô**](https://web.archive.org/web/20240222233205/http://thegioidaquy.net/phong-thuy/vien-da-thien-thach-tho-2508.html#.USZdb6zlbIU)bán cho  người sưu tầm.

- Theo  một “đại gia” trong giới đá quý, người đã dám bỏ ra hàng trăm  triệu  đồng để mua toàn bộ số thiên thạch còn sót lại của Liên doanh Đá  quý  Việt Nhật (khoảng 3 tấn), thì số[viên thiên thạch](https://web.archive.org/web/20240222233205/http://thegioidaquy.net/phong-thuy/vien-da-thien-thach-tho-2508.html#.USZdb6zlbIU)có trọng lượng xấp xỉ 400g hầu như không còn.

- Nhiều  người trong giới sưu tầm đá quý, kể cả những tay trùm buôn bán  đá quý  trong và ngoài nước, đôi khi cũng mua nhầm**Thiên Thạch giả**là những loại đá có  hình  dạng bề ngoài gần giống với thiên thạch.  Những loại đó có thể là  thủy tinh núi lửa (obsiđian), bom núi lửa, tro  của hỏa thạch và một  loại sỏi màu đen có nhiều ở vùng Yên Bái và Lâm  Đồng.

-[Đá Thiên Thạch](https://web.archive.org/web/20240222233205/http://thegioidaquy.net/phong-thuy/Mat-nhan-ty-huu-da-thien-thach-2843.html#.Ughq1zes_0U)về bề ngoài thường có màu đen gần giống với đá thủy tinh núi lửa nhưng khi đập vỡ thì thiên thạch  có tính chất trong sáng của**đá quý**và có thêm sắc màu nâu sáng ở viền. Trên   bề mặt đá thiên thạch thô có những nốt lõm lỗ chỗ, li ti do vết tích của bọt khí trên bề mặt đá bị vỡ khi đi ngang qua tầng khí quyển, những lằn xoắn ốc trên mặt đá chứng tỏ đá bị làm nguội, đông đặc khi rơi   trong tầng khí quyển.

- Gần  đây trên thị trường xuất hiện nhiều[**viên thiên thạch**](https://web.archive.org/web/20240222233205/http://thegioidaquy.net/phong-thuy/vien-da-thien-thach-tho-2508.html#.UghqqDes_0U)có trọng  lượng lên  đến vài chục kg không rõ xuất xứ được bán với giá “trên  trời”. Người  mua cần thận trọng với những loại này, có thể nó được làm  giả với mục  đích lừa đảo. Do thiên thạch bị nóng chảy 2 lần trong vụ va  chạm giữa thiên thạch và trái đất nên nó  không dễ gì bị đốt cháy. Hãy  lấy một mảnh thiên thạch nhỏ đốt dưới ngọn  lửa bếp ga, nếu nó cháy và  có mùi khét là đá giả đá thiên thạch.

Về giá cả trên thị trường:

- Không   có một tỷ giá**thiên thạch**nhất định như tỷ giá vàng hay tỷ giá đô la.   Cũng giống như các loại đá quý khác, giá trị của thiên thạch phụ thuộc   vào kích thước, trọng lượng, hình dạng đặc biệt và mức độ say mê của   người mua.

- Một  ví dụ đơn giản,[**Ruby**](https://web.archive.org/web/20240222233205/http://thegioidaquy.net/phong-thuy/da-phongthuy-120-Da-Ruby)là một loại đá quý ở  Việt Nam. Có những khối ruby lớn được coi là quốc bảo của Việt Nam  như ngôi  sao Việt nam 1 và ngôi sao Việt nam 2. Cũng có những*[viên Ruby](https://web.archive.org/web/20240222233205/http://thegioidaquy.net/phong-thuy/nhan-nu-ruby-anh-sao-1313.html#.USZgZazlbIU)*khi  đem chế tác thành đồ trang sức có giá trị ngang với một chiếc  ôtô đắt  tiền và cũng có những**viên Ruby**được giới chơi đá chơi ngông  đem rải đầy  vào bể cá cảnh cho đẹp, hoặc trải trong vườn thay sỏi để  mỗi sáng đi bộ  giúp cho việc massage chân nhằm tăng cường sức khỏe.**Thiên thạch**cũng  vậy, có những loại có giá vài trăm USD một kilogram, cũng có  loại  mà người sưu tập sẵn sàng bỏ ra vài trăm nghìn USD chỉ để sở hữu một  viên chỉ vài lạng.

- Giống  như đồ cổ, giá trị về tinh thần của**thiên thạch**nhiều khi gấp  hàng trăm  lần giá trị về vật chất. Tuy nhiên cũng đừng vì quá đam mê mà để  bị lừa  hàng tỷ đồng như nhiều vụ báo chí đã nêu gần đây. Thiên thạch là   loại đá mang năng lượng ở mức độ thấp, thường là lợi nhiều hại ít. Nếu   giả sử có loại thiên thạch khác có năng lượng mạnh làm gương vỡ thì   cũng không nên mang về nhà vì năng lượng phóng xạ của nó có thể gây ra   những tác hại đến sức khỏe như biến loạn nhiễm sắc thể, ung thư gây   hại cho chính bạn và gia đình bạn.

- Tùy thuộc vào tuổi cung mạng và mục đích,[mặt Quan âm đá thiên thạch](https://web.archive.org/web/20240222233205/http://thegioidaquy.net/phong-thuy/mat-quan-am-da-thien-thach-2106.html#.UghwBzes_0U)hay được các trạch gia phong thủy sử dụng để cầu  bình an và  tài lộc cho gia chủ. Những giá trị thực sự của loại thiên  thạch này cho  đến nay còn nhiều tranh cãi và dù đúng hay sai thì nó  cũng là một loại  khoáng vật cần được quan tâm và lưu giữ trong các**bộ  sưu tập đá quý**của mình.

- Cũng theo cuốn“Tất cả về khoáng vật chữa bệnh màu nhiệm” của Jasper Stone, các thầy lang địa phương Thái Lan thường dùng thiên thạch để chữa bệnh.[Mặt Di lặc đá thiên thạch](https://web.archive.org/web/20240222233205/http://thegioidaquy.net/phong-thuy/mat-di-lac-inox-da-thien-thach-trung-2501.html#.UghwLTes_0U)giúp loại trừ những tổn   thương về tình cảm, đem lại may mắn và thành công. Giúp tăng cường năng lượng học và các quá trình   trao đổi chất trong cơ thể người.

-**Công dụng màu nhiệm**đặc biệt của**đá thiên thạch**chính là nguồn gốc ngoài  trái đất và hấp thu năng lượng ngoài trái đất của  nó. Thổ dân châu Úc gọi[*đá thiên thạch*](https://web.archive.org/web/20240222233205/http://thegioidaquy.net/phong-thuy/da-phongthuy-239-Da-Thien-Thach-Tektite-)là sự hộ phù của trời, giúp tạo lập mối liên hệ với quá khứ, có ích lợi cho cuộc hành trình bằng ý nghĩ theo thời gian vào vũ trụ.

[*thegioidaquy.net*](https://web.archive.org/web/20240222233205/http://thegioidaquy.net/phongthuy.html)',
    '2012-01-17 09:00:00', 0, 655, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-068', 'cong-dung-cua-thach-anh-xanh', 'Công dụng của thạch anh xanh', 'Thế Giới Đá Quý',
    '/uploads/site_assets/Phongthuy-HoaMocLan-thegioidaquy.jpg', 'Các bạn trai nếu chức năng đàn ông kém, hãy để thạch anh tóc xanh vào huyệt mệnh môn của luân xa mông, vùng bụng dưới, vùng lưng ngay với rốn, kết hợp hít một hơi dài, nghĩ đến màu xanh hoà trong cơ thể, từ trường của actinolit và thạch anh hợp lại có tác dụng tự cải thiện đáng kể tình hình. Thạch anh tóc xanh cũng được gọi là một loại thạch anh tài lộc.', 'Thạch anh xanh ( Quartz Aventurine)

Thạch anh xanh giúp xoa dịu cơn giận dữ và lấy lại  cảm xúc bình tĩnh. Màu xanh lá cây mang đến một cảm giác cân bằng và hài  hòa. Nó là loại đá của may mắn và cơ hội, người ta thường giữ chặt  trong lòng hai bàn tay khi hình dung đến tiền bạc, may mắn sẽ tìm đến như  là một lời nguyện cầu linh nghiệm.

Tác dụng:

- Đeo[mặt dây chuyền thạch anh tóc xanh](https://web.archive.org/web/20121007053242/http://thegioidaquy.net/phong-thuy/mat-thach-anh-toc-xanh-1240.html)lục gần vùng tim, trước khi đi làm  vào buổi sáng mỗi ngày hít thở sâu từ ba đến năm  lần để tăng chí tiến thủ, có  thể thích nghi với mọi thách  thức, thay đổi tình thế tạo cục diện mới.
-  Các bạn trai nếu chức năng đàn ông kém hãy để thạch anh tóc xanh vào   huyệt mệnh môn của luân xa mông, vùng bụng dưới, vùng lưng ngay với  rốn,  kết hợp hít một hơi dài chậm và đều để cải thiện tình hình trên.
- Khi đi du lịch đàm phán, công tác nghiệp vụ hãy đeo[vòng tay thạch anh tóc  xanh](https://web.archive.org/web/20121007053242/http://thegioidaquy.net/phong-thuy/vong-tay-thach-anh-toc-xanh-11-ly-1793.html)để mang lại may mắn và tạo ra cơ hội tốt.[**Đá quý**](https://web.archive.org/web/20121007053242/http://thegioidaquy.net/phongthuy.html)thạch anh  tóc xanh cũng  được gọi là một loại thạch anh đem lại tài lộc.

*thegioidaquy.net*',
    '2012-01-12 09:00:00', 0, 698, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-069', 'cong-dung-cua-thach-anh-toc-den', 'Công dụng của thạch anh tóc đen', 'Thế Giới Đá Quý',
    '/uploads/site_assets/Phongthuy-HoaMocLan-thegioidaquy.jpg', 'Thạch anh tóc chứa nhiều chất Black Tourmaline nên tạo nên những sợi tóc có màu đen. Thạch anh tóc đen giúp xua đuổi nỗi ưu phiền rầu rĩ và cô đơn, truyền cho chủ nhân của nó khả năng thiên nhãn và tiên đoán tương lai. Thạch anh tóc đen còn được coi là lá bùa hộ mệnh có tác dụng trong những vấn đề tình cảm.', 'Thạch anh tóc ( rutilated quartz) là loại thạch anh  chứa các bao thể dạng kim,   que có màu sắc khác nhau. Chúng có thể là các  bao thể thuộc nhóm   amphibol (actinolit), các bao thể rutil, các bao thể  clorit, hematit   hoặc các bao thể tuamalin.

Một số tính chất cơ bản:

Công thức hoá học : SiO2

Cấu trúc tinh thể: Lục phương

Độ cứng : 7

Tỷ trọng : 2.50 - 2.80

Chiết suất: 1.54 - 1.55

Nguồn gốc:

[**Đá quý**](https://web.archive.org/web/20121002000908/http://thegioidaquy.net/phongthuy.html)thạch anh phân bố chủ yếu ở Brazin, Châu Phi

Bình thường Thạch anh tóc   chứa   nhiều chất Rutile sợi thường có màu vàng, màu đỏ, màu sữa, cũng  có   thể  gọi Thạch anh tóc màu vàng là Thạch anh Titan. Thạch anh tóc chứa  nhiều chất Black  Tourmaline thường có sợi màu tóc đen, Thạch anh tóc  chứa nhiều chất  Actinôlit thường sợi có màu xanh lục. Từ trường của  Thạch anh tóc so  với các*[Thạch anh](https://web.archive.org/web/20121002000908/http://thegioidaquy.net/phong-thuy/da-phongthuy-23-Da-Thach-Anh)*khác thường rắn hơn mạnh hơn, vì màu  sắc, tần suất rung khác nhau    nên có tác dụng khác nhau lên các vùng của  cơ thể.

Tác dụng:

- Đeo[vòng tay thạch anh tóc đen](https://web.archive.org/web/20121002000908/http://thegioidaquy.net/phong-thuy/vong-tay-thach-anh-khoi-14-ly-dam-1867.html)để phòng tránh vẩn khí và sự quấy nhiễu của các hư khí xung quanh.

- Thạch anh tóc đen giúp hoà đồng với mọi người, xoá đi sự sợ hãi, gặp được nhiều may mắn vui vẻ lạc quan.

- Thạch anh tóc đen giúp xua đuổi nỗi ưu phiền rầu rĩ và cô đơn, truyền cho chủ nhân của nó khả năng thiên nhãn và tiên đoán tương lai.

- Thạch anh tóc đen còn được coi là lá bùa hộ mệnh có tác dụng tốt trong những vấn đề tình cảm.

-[Mặt thạch anh rêu đen](https://web.archive.org/web/20121002000908/http://thegioidaquy.net/phong-thuy/mat-thach-anh-toc-den-reu-1192.html)thích  hợp với người mạng Thủy mạng Mộc, giúp cho người sở  hữu gặp nhiều may mắn,   tiếp  xúc được với quyền năng huyền bí của vũ trụ.

- Thạch  anh tóc đen giúp điều   trị chứng  nhồi máu và chống đột  quỵ chống lại những mảng sơ vữa.

*thegioidaquy.net*',
    '2012-01-12 09:00:00', 0, 741, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-070', 'cong-dung-cua-thach-anh-toc-do', 'Công dụng của thạch anh tóc đỏ', 'Thế Giới Đá Quý',
    '/uploads/news/thumb-art-078-cong-dung-cua-thach-anh-toc-do-0.jpg', 'Các bạn gái nếu có thể chất yếu khí huyết không điều hoà nên đeo thạch anh tóc đỏ để bổ sung từ trường cho ba vùng( vùng mông, vùng rốn, vùng thái dương), có thể đeo thạch anh tóc đỏ dưới vùng eo, đeo cả lúc ngủ, có tác dụng điều tiết chữa các bệnh phụ khoa.', '[**Đá thạch   anh**](https://web.archive.org/web/20121002000931/http://thegioidaquy.net/phong-thuy/da-phongthuy-23-Da-Thach-Anh)hàm chứa nhiều loại quặng hình kim như những   sợi tóc thì được gọi là thạch anh tóc. Thạch anh tóc  chứa   nhiều chất Rutile thường có màu vàng, màu đỏ, màu sữa (tóc bạc). Thạch anh tóc  màu vàng có những sợi óng ánh nên còn được gọi là thạch anh Titan. Thạch anh tóc chứa  nhiều chất Black   Tourmaline thường có màu tóc đen. Thạch anh tóc  chứa nhiều chất   Actinôlit thường có màu xanh lá cây. Từ trường của  Thạch anh tóc so   với các Thạch anh  thường khác thường rắn hơn mạnh hơn, và màu  sắc-tần suất rung khác nhau  nên nó có các tác dụng khác nhau lên các vùng khác nhau của  cơ thể.

**Công dụng:**

- Các  bạn gái nếu có thể chất yếu khí huyết  không ổn định hãy  đeo[vòng tay  thạch anh tóc đỏ](https://web.archive.org/web/20121002000931/http://thegioidaquy.net/phong-thuy/vong-tay-thach-anh-toc-do-12-ly-1182.html)để bổ sung từ trường cho ba  vùng(vùng  mông,  vùng rốn, vùng thái dương) sẽ giúp khí huyết lưu thông điều hoà.

- Các bạn gái nếu không đủ lòng nhiệt  tình, tính nhỏ mọn, không chủ    động và có  hiện tượng lãnh cảm, dù có vẻ  ngoài xinh đẹp cũng không    được chồng hay bạn trai  yêu quý thì nên  đeo[mặt thạch anh tóc đỏ](https://web.archive.org/web/20121002000931/http://thegioidaquy.net/phong-thuy/mat-thach-anh-reu-do-dam-1239.html#.UGCmaKC__Mo)

để tăng cường sức sống, sức  hấp dẫn quyến rũ và sự  thân thiện.

- Các bạn gái có thể đeo*[thạch anh tóc đỏ](https://web.archive.org/web/20121002000931/http://thegioidaquy.net/phong-thuy/da-phongthuy-140-Thach-Anh-Toc-Do/)*dưới vùng eo, đeo cả lúc ngủ để điều tiết, chữa các bệnh phụ khoa.

*thegioidaquy.net*',
    '2012-01-12 09:00:00', 0, 784, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-071', 'cong-dung-cua-da-lapis-lazuli', 'Công dụng của Đá Lapis lazuli', 'Thế Giới Đá Quý',
    '/uploads/news/art-079-1-dscn8100.jpg', 'Lapis lazuli mở rộng nạp năng lượng cho vùng cổ nên được dùng để chữa các bệnh về họng, tuyến ức, cổ, thanh quản, tai, ngực, phổi, nó làm dịu mát và giảm đau cho những vết sưng tấy, nâng cao hiệu quả của hệ miễn dịch để mau hồi phục.', '[**Lapislazuli**](https://web.archive.org/web/20121101055321/http://thegioidaquy.net/phong-thuy/da-phongthuy-232-Da-Lapis-Lazuli)được  người xưa tin thờ nên giá  trị rất  cao, người Ai Cập thường dùng  nó trong    những ngôi đền bởi họ  tin đây là  tinh  thể đến từ thiên đường  (màu    xanh của nó gợi đến bầu  trời và những  đốm  pyrite trắng nhỏ nhắc ta nhớ  đến    những ngôi sao)

Lapis Lazuli là loại ngọc cổ  có nhiều bề dày lịch sử. Tiếng Hy Lạp cổ nói về  		một ngọc xa phia có   chứa vàng. Những văn hóa cổ đánh giá**[đá quý](https://web.archive.org/web/20121101055321/http://thegioidaquy.net/phong-thuy/da-phongthuy-232-Da-Lapis-Lazuli)**Lapis Lazuli giá trị cao hơn vàng. Văn   hóa Ai Cập cổ đại thường dùng một con bọ hung bằng*[Đá 		Lapis Lazuli](https://web.archive.org/web/20121101055321/http://thegioidaquy.net/phong-thuy/da-phongthuy-232-Da-Lapis-Lazuli)*để   chôn cất cùng với người chết và tin là được sự bảo vệ.   Nhiều nơi tin rằng khi mơ thấyLapis Lazuli là báo trước một tình yêu  		chung thủy. Khi làm việc hay ngẫm nghĩ về nó có thể làm đầu  		óc minh mẫn hơn. Các tín đồ đạo Phật tin rằng lapis lazuli  có thể xua bỏ sự ốm yếu và  làm cho một người có thể hành động nhanh trí, nó sẽ làm cho   con người trở nên thành thật và  đáng tin.

Lapis Lazulilà   những một  		trong những loại đá có năng lượng mạnh nhất, cần phải  được  sử dụng cẩn  		thận. Mang[vòng tay đá lapizlazuli](https://web.archive.org/web/20121101055321/http://thegioidaquy.net/phong-thuy/vong-tay-da-lapis-lazuli-1800.html#.UGCeWKC__Mo)có thể giúp đỡ  bạn trở nên mạnh mẽ.  		Người Ai Cập cổ xem nó như biểu tượng của sự thật  lòng.  Lapis Lazuli được dùng  		với những[**đá quý**](https://web.archive.org/web/20121101055321/http://thegioidaquy.net/phongthuy.html)khác để làm sạch và thanh  khiết  cơ thể.

Lapis Lazuli có thể được  		tìm thấy ở Chi lê, Nga, Mỹ và ở những núi của Afghanistan,  		Pakistan.

![te-giac-da-lapiz-lazuli](/uploads/news/art-079-1-dscn8100.jpg)

*Tê giác Lapis Lazuli bảo vệ, đánh đuổi thị phi, tiểu nhân đem lại may mắn.*

**Đặc tính chữa bệnh:**

- Lapislazulicó liên quan với cà  chakra trán   và cổ họng. Khi được đặt trên chakra    trán, nó kết nối ta  với quyền vạn   năng và bộc lộ sự thật bên  trong.  Lapislazulilàm nâng cao mở rộng trực   cảm, tăng cường năng lực ngoại cảm và cho ta tầm nhìn để hiểu thấu  những  giấc mơ.

- Đeo thường xuyên[mặt dây chuyền đá lapislazuli](https://web.archive.org/web/20121101055321/http://thegioidaquy.net/phong-thuy/mat-da-lapis-lazuli-1798.html)sẽ mở rộng và  nạp  năng lượng cho trung tâm vùng ngực, chữa  các bệnh về  họng, tuyến ức, cổ, thanh quản, tai, ngực,     phổi, nó làm dịu  mát và  giảm đau cho những vết sưng tấy, nâng cao    hiệu quả của hệ miễn  dịch  nhằm đẩy nhanh sự hồi phục.

- Đeo[vòng tay đá Lapislazuli](https://web.archive.org/web/20121101055321/http://thegioidaquy.net/phong-thuy/vong-tay-da-lapis-lazuli-1800.html)rất tốt để xua tan  giận dữ và  làm  tính khí ôn hòa hơn.    Nó được khuyên dùng cho những ai đang gặp khó khăn   trong việc nói ra cảm xúc của mình, nó  khuyến khích chúng   ta nói ra sự  thật để tự tin hơn. Tinh thể này cũng  đem lại sự sáng suốt   cũng  như sự  rõ  ràng mạch lạc trong lời nói.

- Lapislazulicó thể được đeo nhằm  ngăn chặn   những đòn tấn công ngoại cảm. Một số tác dụng khác của nó  bao gồm giảm   đau giúp ngủ ngon, chống hoa mắt chóng mặt và tăng tác  dụng tẩy uế.

*thegioidaquy.net*',
    '2011-12-26 09:00:00', 0, 827, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-072', 'cong-dung-cua-da-san-ho', 'Công dụng của đá San hô', 'Thế Giới Đá Quý',
    '/uploads/news/thumb-art-080-cong-dung-cua-da-san-ho-0.jpg', 'Đá San hô là đá quý cấp quốc gia của Tây Tạng, chúng mang đến sức khỏe tốt, may mắn và giúp tránh những rủi ro, đeo trang sức Turquoise sẽ được thượng đế bảo vệ. Người Aztec và Incas xem Turquoise quý hơn vàng.', 'Với màu quá đặc trưng nên tên của đá đã được dùng để chỉ cho màu này.  Thời trung cổ Turquoise là báu vật trong hàng nghìn năm. Các nền văn hóa cổ xưa như Tây   Tạng, Mỹ bản xứ, Aztecs, Trung Hoa và Ai Cập đã tôn vinh*[đá Turquoise](https://web.archive.org/web/20121002002216/http://thegioidaquy.net/phong-thuy/da-phongthuy-234-Da-Turquoise)*vì   sức mạnh tinh thần và vẻ đẹp chủa chúng.

Người   Ai Cập cổ từng giữ Turquoise làm tài sản và các nhà khảo cổ tìm thấy nữ  trang   hoàng gia có những**[đá quý](https://web.archive.org/web/20121002002216/http://thegioidaquy.net/phongthuy.html)**này có tuổi đến hơn 5000 năm.

[Dây chuyền đá San hô](https://web.archive.org/web/20121002002216/http://thegioidaquy.net/phong-thuy/day-chuyen-da-san-ho-1725.html)(Turquoise ) mang đến sức khỏe tốt, sự may mắn và giúp tránh những điều rủi ro. Đá Turquoiselà đá quý cấp quốc gia của Tây Tạng
Người Aztec và Incas xem turquoise quý hơn vàng nên đã đưa các đá này về   từ  những mỏ ở phía bắc bây giờ là vùng tây nam nước Mỹ. Đeo[nhẫn đá Turquoise](https://web.archive.org/web/20121002002216/http://thegioidaquy.net/phong-thuy/nhan-da-san-ho-2018.html)sẽ  được thượng đế bảo vệ.

Những   chiến binh Apache gắn Turquoise vào cung tên để gia tăng độ chính  xác.   Các nhà sưu tập đã đánh giá cao những[trang sức đá Turquoise](https://web.archive.org/web/20121002002216/http://thegioidaquy.net/phong-thuy/da-phongthuy-234-Da-Turquoise)được làm bởi người Navajo, Pueblo và Zuni.

Turquoise  được khai thác ở vùng tây nam nước Mỹ và Trung Quốc. Các bang ở Mỹ  khai thác và sản xuất   nhiều đá Turquoise nhất là Arizona, New Mexico, Colorado và  Nevada.

Trong Viện Smithsonian, đá turquoise nổi bật cùng với 700 carat kim  cương trong vương miện Marie-Louise, là   một quà tặng của hoàng đế  Napoleon cho vợ ông trong lễ cưới. Vương   miện này đầu tiên được gắn đá  emerald, sau này được thay thế bằng[*đá Turquoise*](https://web.archive.org/web/20121002002216/http://thegioidaquy.net/phong-thuy/da-phongthuy-234-Da-Turquoise)phù hợp bởi công ty Van  Cleef & Arpels vào những năm   1950.

Theo truyền thống Châu Âu tặng quà bằng đá turquoise mang ý nghĩa là “xin đừng quên tôi”.

Turquoise là một trong những đá mừng sinh nhật tháng 12.

Turquoise còn được gọi là Ngọc Lam Thạch.

*thegioidaquy.net*',
    '2011-12-25 09:00:00', 0, 870, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-073', 'phan-biet-chalcedony-voi-thach-anh-va-opal', 'Phân biệt Chalcedony với Thạch anh và Opal', 'Thế Giới Đá Quý',
    '/uploads/site_assets/Phongthuy-HoaMocLan-thegioidaquy.jpg', 'Chúng ta đã nghe rất nhiều về đá thạch anh nhưng ít khi nghe tên Chalcedony hoặc Opal. Các nhà ngọc học xếp ba đá quý này thành 3 nhóm riêng biệt: thạch anh, chalcedony và opal. Ba nhóm đá này có liên quan ít nhiều với nhau. Bản tin này đề cập chi tiết về đá chalcedony nhằm giúp khách hàng biết về chúng và gọi tên chính xác hơn các loại đá này.', 'Chúng ta đã nghe rất  		nhiều về*[đá thạch anh](https://web.archive.org/web/20121007042159/http://thegioidaquy.net/phong-thuy/da-phongthuy-23-Da-Thach-Anh)*, nhưng ít khi nghe tên chalcedony hoặc opal. Các  		nhà ngọc học xếp ba[**đá quý**](https://web.archive.org/web/20121007042159/http://thegioidaquy.net/phongthuy.html)

này thành 3 nhóm riêng biệt: đá thạch anh,[**đá chalcedony**](https://web.archive.org/web/20121007042159/http://thegioidaquy.net/danh-muc-tin/The-gioi-da-quy-56.html)và opal. Ba nhóm đá này có liên quan ít nhiều với nhau.

*Vỏ trái đất rất mỏng, lớp vỏ chỉ là một  				viền màu cam phủ lên phần bên trong rất dày là các lớp manti và  				nhân.*

Lớp vỏ trái đất của  		chúng ta rất mỏng so với đường kính (12.740 km) của nó, nơi dày nhất là  		khoảng 60 km. Oxid silic (SiO2) chiếm đến 60% khối lượng của  		vỏ trái đất (hình 1). Oxid silic là thành phần cơ bản tạo nên hầu hết  		khoáng chất của lớp vỏ trái đất. Thành phần hóa học của thạch anh và  		chalcedony là SiO2, opal là SiO2.n(H2O).  		Cả ba khoáng vật này đều được cấu tạo bởi oxid silic, cho nên chúng rất  		phổ biến khắp nơi trên trái đất và chúng cũng là những[**đá quý**](https://web.archive.org/web/20121007042159/http://thegioidaquy.net/phongthuy.html)phổ thông  		nhất.

Đá Opal

Là khoáng  		vật không có cấu trúc tinh thể, gọi là vô định hình. Vật chất trong Opal  		kết lại không theo quy luật (không có ô mạng tinh thể), giống như thủy  		tinh. Opal luôn ở dạng đặc sít không có đơn tinh, vi tinh hoặc ẩn tinh  		như thạch anh hoặc chalcedony. Trong ngành đá quý, người ta gọi trường  		hợp đá có cấu tạo như Opal là đá có một chiết suất. Opal có chiết  		suất dao động từ 1,37 đến 1,47. Thị trường chia Opal thành nhiều loại như Opal đen, Opal trắng, Opal pha lê, Opal nước…

Đá Thạch  		anh

Là  		khoáng vật kết tinh, nghĩa là có cấu trúc tinh thể. Hình thái hiện diện  		có thể là dạng tinh thể riêng biệt (đơn tinh thể) hoặc khối đặc sít gồm  		nhiều tinh thể nhỏ kết lại. Thị trường đá quý có rất nhiều thạch anh đơn  		tinh.[*Đá Thạch anh*](https://web.archive.org/web/20121007042159/http://thegioidaquy.net/phong-thuy/da-phongthuy-23-Da-Thach-Anh)là đá có hai chiết suất, thường là: 1,553 – 1,544. Thị  		trường cũng chia thạch anh thành nhiều loại như thạch anh khói( smoke quazt), thạch anh trắng( crystal quazt), thạch anh vàng( citrine), thạch anh tím ( amethyst), thạch anh tóc vàng, thạch anh tóc xanh, thạch anh tóc đỏ, thạch anh đen( morion quazt)

Đá Chalcedony

Cũng là một dạng thạch anh nhưng dạng tinh thể rất nhỏ (không lớn như thạch anh)  		gọi là ẩn tinh. Như vậy, thực chất chalcedony không khác thạch anh về  		các tính chất hóa lý, mà chỉ khác về kích thước. Với thạch anh, có thể  		nhìn thấy bằng mắt thường hoặc với độ phóng đại nhỏ. Còn chalcedony  		muốn thấy chúng phải dùng kính hiển vi có độ phóng đại lớn, thậm chí  		ngay cả kính hiển vi ngọc học đôi khi không phân biệt được từng tinh thể  		của chúng.**[Chalcedony](https://web.archive.org/web/20121007042159/http://thegioidaquy.net/phong-thuy/da-phongthuy-62-Da-Chacedol)**cũng là thạch anh nên cũng có hai chiết suất nhưng  		không thể đo được vì tinh thể cực nhỏ. Với chiết suất kế, người ta chỉ  		đo được một giá trị tương đối là 1,53 hay 1,54. Thị trường chia  		chalcedony ra nhiều loại hơn so với thạch anh hay opal.

*theo rongvanglab*',
    '2011-12-20 09:00:00', 0, 913, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-074', 'tieu-chuan-phan-loai-chalcedony', 'Tiêu chuẩn phân loại chalcedony', 'Thế Giới Đá Quý',
    '/uploads/news/art-082-1-da-chalcedony-du-loai.jpg', 'Phân loại chalcedony dựa vào các tiêu chuẩn chính như màu sắc, độ trong, cấu trúc, hiệu ứng quang học, tạp chất đặc biệt. Họ cũng phân loại dựa vào sự kết hợp các tiêu chuẩn. Chalcedony là đá đa khoáng (đa tinh thể) và rất phổ biến, chúng xuất hiện quá nhiều vẻ khác nhau nên được chia ra rất nhiều loại chalcedony.', 'Cũng như những đá  		quý khác, các nhà ngọc học phân loại**[đá chalcedony](https://web.archive.org/web/20120930022932/http://thegioidaquy.net/phong-thuy/da-phongthuy-62-Da-Chalcedony)**dựa vào các tiêu chuẩn  		chính như màu sắc, độ trong, cấu trúc, hiệu ứng quang học, tạp chất đặc  		biệt… Họ cũng phân loại dựa vào sự kết hợp các tiêu chuẩn. Chalcedony là  		đá đa khoáng (đa tinh thể) và rất phổ biến, chúng xuất hiện quá nhiều vẻ  		khác nhau nên được chia ra rất nhiều loại.

[![Đá chacedol đủ màu](/uploads/news/art-082-1-da-chalcedony-du-loai.jpg)](https://web.archive.org/web/20120930022932/http://thegioidaquy.net/phong-thuy/da-phongthuy-62-Da-Chalcedony)

*Các màu sắc của đá chalcedony.*

**Màu  		sắc:**

Chalcedony xuất hiện với nhiều màu khác nhau như vàng, cam, nâu, đỏ, lục  		nhạt, xanh dương nhạt, trắng, xám và đen. Tuy nhiên đa số màu ở  		chalcedony thì nhạt hay quá sẫm, ít có sắc tươi và mạnh như[**đá ruby**](https://web.archive.org/web/20120930022932/http://thegioidaquy.net/phong-thuy/da-phongthuy-120-Da-Ruby),[**sapphia**](https://web.archive.org/web/20120930022932/http://thegioidaquy.net/phong-thuy/da-phongthuy-119-Da-Sapphire)hay emerald. Các đá nhóm này thường phân bố màu không đều và  		nhiều màu sắc trên cùng một viên đá vì đá hay có những cấu trúc phức  		tạp. Điều này thấy rõ ở các đá thô lớn, tuy nhiên với những đá thành  		phẩm nhỏ thì cũng có viên chỉ có một màu. Phân loại theo màu có các đá  		đặc trưng như carnelian, sard, chrysoprase, prase...

**Độ  		trong:**

Chalcedony là đá đa khoáng nên hầu như không trong suốt bằng đá đơn  		khoáng. Độ trong gồm các cấp từ cao đến thấp: nửa trong suốt (bán  		trong), trong mờ, nửa trong mờ, đục (chắn sáng). Độ trong chỉ có vai trò  		nhỏ trong phân loại nhóm đá này. Thí dụ các đá như carnelian, sard,  		chrysoprase… có độ trong thuộc loại cao nhất trong nhóm, đó là từ bán  		trong cho đến trong mờ.

**Cấu  		trúc:**

Chalcedony kết tinh tạo nên nhiều kiểu cấu trúc và màu sắc đặc biệt, làm  		cho khoáng vật này là một trong những đá có nhiều vẻ đa dạng nhất. Chúng có thể có dạng các lớp song song, lớp uốn cong hay góc cạnh,  		dạng chùm nho hoặc đặc sít, dạng đốm, rêu, phân nhánh và bất kỳ. Phân  		loại theo cấu trúc có các loại như[agate](https://web.archive.org/web/20120930022932/http://thegioidaquy.net/phong-thuy/da-phongthuy-127-Da-Agate), onyx,[gỗ hóa thạch](https://web.archive.org/web/20120930022932/http://thegioidaquy.net/phong-thuy/da-phongthuy-236-Go-hoa-thach).

![Hình ảnh đá quý phong thủy](/uploads/news/art-082-5-da-chalcedony-cau-truc-goc-cong.jpg)

*Các dạng cấu trúc đá chalcedony.*

Ở đá thô lớn ta  		thấy các kiểu cấu trúc rõ ràng hơn, còn với các thành phẩm nhỏ xíu thì  		khó thấy hoặc không thấy chúng. Một viên đá thô có cấu trúc lớp góc cạnh  		hoặc uốn cong, khi mài thành các viên đá rất nhỏ thì chúng có thể thành  		dạng đồng nhất không có cấu trúc gì hoặc thành dạng lớp song song.

**Tạp chất đặc biệt:**

Tạp chất trong chalcedony khi hiện diện nhiều và phân bố theo nhiều kiểu  		và màu đặc biệt thì tên đá sẽ dựa vào tạp chất này. Thí dụ như agate  		rêu, agate nhánh cây, agate phong cảnh, chalcedony chrysocolla,  		chalcedony đốm đỏ.

**Hiệu  		ứng quang học:**

*Hiệu ứng quang học đá chalcedony.*

Đó là hiệu ứng tán sắc. Nó xảy ra trên[**chalcedony**](https://web.archive.org/web/20120930022932/http://thegioidaquy.net/phong-thuy/da-phongthuy-62-Da-Chalcedony)khá hiếm, gần  		giống hiệu ứng lóe màu sặc sỡ ở opal nhưng không phổ biến bằng. Hiệu ứng  		này là do ánh sáng khi chiếu vào bề mặt đá, gặp các lớp mỏng khác nhau  		nên tán sắc tạo nên màu cầu vồng trên các lớp. Không phải bất kỳ đá chalcedony phân lớp nào cũng có hiệu ứng này, mà chỉ một số ít đá có sự  		sắp xếp các vi tinh tương đối đều đặn mới có hiệu ứng này. Phân loại  		theo hiệu ứng có các đá là agate lửa, agate tán sắc tùy theo kiểu cấu  		trúc.

*theo rongvanglab.*',
    '2011-12-20 09:00:00', 0, 956, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-075', 'cong-dung-cua-go-hoa-thach', 'Công dụng của gỗ hoá thạch', 'Thế Giới Đá Quý',
    '/uploads/news/thumb-art-083-cong-dung-cua-go-hoa-thach-0.jpg', 'Gỗ hóa thạch có nguồn gốc từ những cây rừng nguyên sinh, sau tác động của trận phun trào của núi lửa những thân gỗ này đã bị chôn vùi trong nham thạch hàng triệu năm dần dần biến thành đá. Gỗ hóa thạch mang đến may mắn bình an, sức khỏe và trường thọ.', 'Gỗ    hóa thạch có nguồn gốc từ những cây rừng nguyên  sinh, sau tác động  của   một trận phun trào của núi lửa, những thân gỗ này  đã bị chôn vùi   trong  nham thạch hàng triệu năm và dần biến thành đá.

**[Gỗ hóa thạch](https://web.archive.org/web/20121007053247/http://thegioidaquy.net/phong-thuy/da-phongthuy-236-Go-hoa-thach)**được tìm thấy ở Indonesia, Australia, Hoa Kỳ và Việt Nam. Mỏ gỗ  hóa thạch còn có ở vùng Primorie thuộc Nga, Ukraina và Acmênia.

Giải thích  theo cơ chế phương Đông thì Gỗ hóa thạch là    một loại hình  trang sức  rất tuyệt vời. Nguồn gốc của nó vốn từ gỗ có    từ hàng triệu năm được kết cấu lại thành một dạng như thạch anh do    quá trình bị chôn   vùi trong nham thạch hàng triệu năm mới hình thành nên.

Còn các    nhà thần học Phương Tây thì cho rằng Gỗ hoá thạch nguyên bản là một khúc gỗ mục  nát,    sau khi trải qua quá trình bị Thạch anh hóa nó biến thành một loại[**đá    quý**](https://web.archive.org/web/20121007053247/http://thegioidaquy.net/phongthuy.html), nên gỗ hoá thạch có đặc tính từ trường bền vững trường  thọ và vĩnh cửu.

Ngay    từ thời các quốc gia cổ đại như Assyria, Babilon và La Mã cổ  đại, gỗ    hóa thạch đã được dùng làm đá mỹ nghệ. Từ gỗ hóa thạch người ta chế tác ra    chuỗi hạt, mặt nhẫn, ngọc treo và ngọc bội. Từ thế kỷ  19,  20   từ[*gỗ hóa thạch*](https://web.archive.org/web/20121007053247/http://thegioidaquy.net/phong-thuy/da-phongthuy-236-Go-hoa-thach)Arizona đã xuất khẩu chế tác thành những chiếc  bàn nhỏ, các chuỗi   hạt gỗ hoá thạch, lọ hoa, giá nến....

Màu sắc Gỗ hoá thạch:

Gỗ  hóa  thạch có màu xám nâu, màu phớt xanh lá, màu  phớt đỏ, màu vàng và màu   xanh da trời.  Đôi  khi còn xuất hiện những họa tiết thứ cấp của gỗ hoá thạch  trông giống  như  đường phân  chia trên bề mặt của đá ngọc bích hoặc đá agate.

*Tác dụng:*

Tác dụng chung của Gỗ hóa thạch là bồi bổ giúp cơ thể dẻo dai và mạnh khoẻ.

-[Vòng tay gỗ hóa thạch](https://web.archive.org/web/20121007053247/http://thegioidaquy.net/phong-thuy/vong-tay-go-hoa-thach-10-ly-1690.html)được dùng chữa các chứng đau nhức khớp, viêm thấp khớp.

- Gỗ hóa thạchlàm cho hệ thần kinh vững vàng hơn trước stress.

-[Mặt dây chuyền gỗ hoá thạch](https://web.archive.org/web/20121007053247/http://thegioidaquy.net/phong-thuy/mat-go-hoa-thach-nau-2043.html)làm tăng lưu thông máu huyết đểnâng cao tuổi thọ.

- Gỗ hóa thạch tạo ý chí trong cuộc sống, khơi dậy tiềm năng và giúp người đeo nó vững tin và kiên định.

- Gỗ hoá thạch dùng để trị thương, đuổi trừ âm khí phù chú để tăng cường năng lượng tốt.

Do    vậy, từ mà Gỗ hoá thạch (màu xanh– hành Mộc)– chuyển sang gỗ hoá thạch   màu đỏ (hành  Hỏa)–  chuyển tiếp gỗ hoá thạch màu trắng (hành Kim)–   chuyển tiếp gỗ hoá thạch màu Vàng (hành  Thổ)–  chuyển tiếp gỗ hoá thạch   màu đen nâu (hành Thủy) khi chuyển tiếp gỗ hoá thạch màu xanh da  trời    thì loại Gỗ hóa thạch đó đá biến thành[*Ngọc quý*](https://web.archive.org/web/20121007053247/http://thegioidaquy.net/phong-thuy/da-phongthuy-236-Go-hoa-thach)

Sử dụng theo màu gỗ hóa thạch:

-[Gỗ hóa thạch đỏ](https://web.archive.org/web/20121007053247/http://thegioidaquy.net/phong-thuy/mat-go-hoa-thach-do-1654.html#.UGCU5qC__Mo):    dùng chữa các bệnh về sưng nóng, đỏ, đau  (như các chứng viêm khớp có  kèm   sưng nóng), các bệnh thuộc tim mạch, huyết  áp, giúp ổn định  tinh   thần.

-[Gỗ hóa thạch trắng](https://web.archive.org/web/20121007053247/http://thegioidaquy.net/phong-thuy/ty-huu-go-hoa-thach-trang-2275.html#.UGCUtKC__Mo): dùng chữa các bệnh thuộc đường hô hấp như viêm phế quản, viêm họng, viêm suyễn và viêm mũi dị ứng.

-[Gỗ hóa thạch vàng](https://web.archive.org/web/20121007053247/http://thegioidaquy.net/phong-thuy/vong-tay-go-hoa-thach-12-ly-1691.html#.UGCUbaC__Mo):    dùng chữa các bệnh về Tỳ vị như rối loạn tiêu  hóa, tiêu chảy thường    xuyên, ăn uống không tiêu gầy yếu, chữa các chứng  tê bại, giúp trừ chứng    lo âu suy nghĩ vẩn vơ.

-[Gỗ hóa thạch nâu đen](https://web.archive.org/web/20121007053247/http://thegioidaquy.net/phong-thuy/mat-go-hoa-thach-nau-1358.html#.UGCVKaC__Mo): dùng để để chữa các chứng bệnh thuộc Thận  như suy yếu sinh dục (nam    liệt dương, nữ lãnh cảm), hiếm muộn, viêm thận  mãn, thường hay đau lưng    nhức mỏi, giúp trừ chứng sợ hải vô cớ.

-[Gỗ hóa thạch xanh](https://web.archive.org/web/20121007053247/http://thegioidaquy.net/phong-thuy/mat-go-hoa-thach-xanh-1652.html#.UGCUT6C__Mo): dùng để chữa các bệnh về Gan Mật.

*thegioidaquy.net*',
    '2011-12-11 09:00:00', 0, 999, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-076', 'cong-dung-cua-thach-anh-trang', 'Công dụng của thạch anh trắng', 'Thế Giới Đá Quý',
    '/uploads/news/thumb-art-084-cong-dung-cua-thach-anh-trang-0.jpg', 'Thạch anh trắng có trường năng lượng dương cực mạnh, có thể đem đến sự may mắn trong cuộc sống và công việc. Đặt viên Thạch anh trắng có kích thước vừa phải bày trên bàn hoặc đặt xung quanh máy vi tính, ti vi, lò vi sóng và các đồ điện khác để giảm nhẹ độ phóng xạ, bảo vệ cơ thể con người không bị nhiễm xạ.', 'Thạch anh còn được gọi là*viên[**Đá Phong Thủy**](https://web.archive.org/web/20121002000709/http://thegioidaquy.net/phongthuy.html)([**Fengshui Stone**](https://web.archive.org/web/20121002000709/http://thegioidaquy.net/phongthuy.html))*vì trải qua vài triệu năm hình thành,*[đá thạch anh](https://web.archive.org/web/20121002000709/http://thegioidaquy.net/phong-thuy/da-phongthuy-23-Da-Thach-Anh)*thu hút năng lượng         vũ trụ và phát ra 1 trường năng lượng dương cực mạnh, có thể đem   đến    sự    may mắn trong cuộc sống và công việc, chống lại sự ảnh   hưởng    của năng    lượng xấu.

Các doanh nhân Châu Á thường đặt đá Thạch Anh tại góc THỔ (Tây Nam hoặc Đông Bắc) của bàn làm việc, phòng làm việc         hoặc phòng khách, giúp tăng cường mối quan hệ khách hàng, đồng    nghiệp,      đem lại thành công trong kinh doanh.

Chính         vì sự màu nhiệm này Thạch Anh đang là món quà được ưa chuộng   dành      tặng  khách hàng, đối tác và Sếp, nó mang nhiều ý nghĩa tinh    thần cầu     chúc  may mắn cho người sở hữu.

**Đặc tính:**

Thạch anh trắng trong suốt là loại đá quý  đại biểu cho Thạch anh thời đại mới, có nhiều chức năng, công dụng lớn,  được mệnh danh là “Thạch anh Đế vương ”：Đồng thời cũng là sự kết hợp  tổng thể các màu sắc gồm màu đỏ, da   cam, vàng, lục, lam, chàm và tím,  thể hiện sự cân bằng viên mãn.

**Cách dùng:**

- Đeo[mặt dây chuyền thạch anh trắng](https://web.archive.org/web/20121002000709/http://thegioidaquy.net/phong-thuy/oval-thach-anh-trang-2031.html)trước ngực để có từ  trường cân bằng nhất, nó bảo vệ sự bình an, làm lá bùa hộ mệnh đem lại bình an tốt nhất.

-[*Thạch anh trắng*](https://web.archive.org/web/20121002000709/http://thegioidaquy.net/phong-thuy/da-phongthuy-139-Thach-Anh-Trang/)được sự dụng để làm dịu hay tan biến các căng thẳng giảm trầm uất và  chữa trị các bệnh có tính chất dương.

- Với những người bạn khi ngồi thiền mà tâm bất an không tập  trung, tinh thần phân tán có thể cầm[quả cầu thạch anh trắng](https://web.archive.org/web/20121002000709/http://thegioidaquy.net/phong-thuy/qua-cau-thach-anh-trang-2095.html)áp sát nơi  Đan điền ở bụng dưới da tác dụng giúp tập trung tinh thần để chuyên  tâm hơn.

- Đeo[vòng tay thạch anh trắng](https://web.archive.org/web/20121002000709/http://thegioidaquy.net/phong-thuy/vong-tay-thach-anh-trang-14-ly-1399.html)trên tay có thể  tăng từ   trường ý thức, được dùng để cầu  phúc cầu   nguyện rất tốt.

- Đem Thạch anh trắng đặt vào phương tài lộc làm cho khí vượng, có tác dụng sinh tài sinh lộc.

- Đặt Thạch anh trắng phía sau bên phải của chủ quản để giúp củng cố uy  danh, cấp dưới chấp hành mệnh lệnh tuyệt đối không dám chậm chạp ỷ  lại.

- Đặt[Quả cầu thạch anh trắng](https://web.archive.org/web/20121002000709/http://thegioidaquy.net/phong-thuy/qua-cau-thach-anh-trang-lon-2025.html)có kích thước phù hợp bày trên bàn làm việc hoặc  đặt quanh máy vi tính, truyền hình, lò vi sóng và các đồ điện khác để giảm   nhẹ độ phóng xạ bảo vệ cơ thể con người tránh nhiễm xạ.

- Đối với những góc nhỏ bên ngoài nhà có thể đặt thạch anh trắng ở những  vị trí đối xứng nhau, để hoá giải sát  trạch.

- Trong nhà khi có cửa đối cửa có thể để[Quả cầu thạch anh trắng](https://web.archive.org/web/20121002000709/http://thegioidaquy.net/phong-thuy/qua-cau-thach-anh-trang-lon-2025.html#.UGCF56C__Mo)làm tuyến nối giữa hai cửa để hoá giải xung khắc.

- Trên bàn làm việc tuân theo nguyên lý Hữu Viên Tả Phương (bên phải tròn, bên trái vuông) là bên phải đặt Quả cầu Thạch anh trắng, bên trái đặt Que thạch anh để phòng tiểu nhân, và giúp bạn biết cách đối nhân xử thế hơn.    Nếu vị trí bàn hẹp thì đặt theo phương thức Tiền Viên Hậu Phương (phía trước tròn, phía sau vuông).

*thegioidaquy.net*',
    '2011-11-21 09:00:00', 0, 1042, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-077', 'cong-dung-da-chalcedony', 'Công dụng đá Chalcedony', 'Thế Giới Đá Quý',
    '/uploads/site_assets/Phongthuy-HoaMocLan-thegioidaquy.jpg', 'Chalcedony có những hoa văn hoặc màu sắc đặc biệt đẹp được coi là đá bán quý. Đeo đồ trang sức đá Chacedol giúp điều trị bệnh loạn thần kinh chức năng và trầm uất, có khả năng loại trừ nỗi sợ hãi, đem đến cho người chủ niềm tin vào sức mạnh của chính mình.', 'Chalcedony có những hoa văn hoặc màu sắc đặc biệt, đẹp được coi là đá quý và đá bán  quý.   Trong tự nhiên tạo thành những tập hợp có dạng rất khác nhau, có  ánh mỡ   đến ánh sáp, thường bị nhuộm màu do bụi hematit thì tạo thành màu đỏ,  limonit tạo màu vàng, clorit tạo màu xanh. Những biến   thể Chalcedony  được chia thành: heliotrop, cacneon, xacđe, crizopra và   onix.[**Đá Chalcedony**](https://web.archive.org/web/20121203194648/http://thegioidaquy.net/phong-thuy/da-phongthuy-62-Da-Chalcedony)thường có những viên đá có   tông màu như màu  xanh da trời nhạt, xanh phớt xanh lá cây,  phớt vàng,  phớt đỏ.

Chalcedony còn được một số người gọi là caxedon.

*Tính chất chữa bệnh:*

Người   ta cho rằng, Chalcedony có khả   năng giải thoát người chủ khỏi cơn giận dữ  và nỗi sầu muộn. Theo quan   niệm cổ xưa, Chalcedony chứa trong mình các  nguyên tố tự nhiên như không khí và ete, vì   vậy có tác dụng làm an bình môi trường tâm  lý tình cảm của con người. Đeo đồ[trang sức Chalcedony](https://web.archive.org/web/20121203194648/http://thegioidaquy.net/phong-thuy/da-phongthuy-62-Da-Chalcedony)đối  với những người dễ bị kích động, nó giúp điều trị bệnh loạn  thần kinh chức năng và trầm uất.

Theo các văn bản viết tay cổ, Chalcedony cũng giống  như agate là bùa hộ mệnh của những người đi biển. Chalcedony cũng được coi  là viên đá của tình   yêu, nó thu hút trái tim của đàn ông về phía người  phụ nữ. Chalcedony đem lại sự quyến rũ cho phụ nữ. Người Mông Cổ gọi những viên Chalcedony màu xanh  da trời được tìm   thấy trong hoang mạc Gôbi là “đá niềm vui” và tin rằng  chúng có khả   năng xua đuổi nỗi buồn và tạo ra tâm trạng hứng khởi. Trong  một văn bản   cổ của Ấn Độ nói rằng loại đá này có ánh sáng của ý thức  tinh khiết. Đồ trang sức[vòng tay đá Chalcedony](https://web.archive.org/web/20121203194648/http://thegioidaquy.net/phong-thuy/vong-tay-da-chacedol-10-ly-1530.html)có khả năng  loại trừ nỗi sợ hãi, đem đến cho người chủ niềm tin vào   sức mạnh của  chính mình. Chalcedony là biểu tượng của chòm sao Nhân Mã   trong cung  hoàng đạo, có năng lượng cảm thụ âm và nó tác dụng tới các luân xa   tùy thuộc  vào màu sắc của đá.

Chalcedony thường được dùnglàm đồ trang sức đá,[*đá quý phong thủy*](https://web.archive.org/web/20121203194648/http://thegioidaquy.net/phongthuy.html)

*thegioidaquy.net*',
    '2011-11-12 09:00:00', 0, 1085, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-078', 'tac-dung-cua-thach-anh-khoi', 'Tác dụng của thạch anh khói', 'Thế Giới Đá Quý',
    '/uploads/site_assets/Phongthuy-HoaMocLan-thegioidaquy.jpg', 'Thạch anh khói là một loại thạch có khả năng làm mạnh các tế bào liên kết như gân cốt, gân khớp. Kích thích khả năng thụ tinh qua việc kích thích điều tiết hormone ở tuyến thượng thận. Nếu cặp vợ chồng hiếm muộn muốn tăng khả năng thụ tinh thì nên uống nước ngâm của thạch anh khói một thời gian.', 'Thạch anh khói (Smoky quartz)thường   dùng như là một hộ thạch, chúng báo hiệu người đeo khi đá chuyển sang  màu đậm hơn. Do đó[vòng tay thạch anh khói](https://web.archive.org/web/20120730102023/http://thegioidaquy.net/phong-thuy/vong-tay-thach-anh-khoi-14-ly-1868.html)để đeo trên tay hay[mặt thạch anh khói](https://web.archive.org/web/20120730102023/http://thegioidaquy.net/phong-thuy/mat-thach-anh-khoi-giot-nuoc-2057.html#.UAfUE1Lt7Mo)để trước ngực rất  thích hợp cho những người đi rừng, đi biển, tại các khu hầm mỏ và  khu vực  có nhiều chất bức xạ không tốt.

**Tác dụng:**

- Thạch anh khói có khả năng làm mạnh các mô tế bào liên kết như gân cốt và gân khớp. Kích thích khả năng thụ tinh   qua việc kích thích điều tiết hormone ở tuyến thượng thận. Nếu cặp vợ chồng hiếm muộn muốn tăng khả năng thụ tinh thì nên uống nước ngâm của thạch anh khói trong một thời gian. Đeo trang sức phong thuỷ làm từ thạch anh khói giúp đem lại may mắn và giàu có.

- Về cảm xúc, thạch anh khói có thể giúp mang lại sự bình tỉnh khi bị kích   thích căng thẳng quá mức. Có thể cầm nắm trong tay để giải   trừ những trượt khí do tư tưởng gây nên.

- Trong nghệ thuật***[Phong Thủy](https://web.archive.org/web/20120730102023/http://thegioidaquy.net/phongthuy.html)***hay Kiến trúc nội-ngoại thất, thạch anh khói rất được yêu chuộng và rất   quý vì nó là một ‘Hộ thạch’ có thể bảo vệ nhà cửa, người, sinh vật  xung  quanh từ những tia bức xạ độc hại như tầng sóng từ cao thế, sóng  radio,  sóng điện thoại, TV.… Đặt thạch anh khói trước cửa nhà hay phòng làm việc có  thể  giải trừ những điều xấu từ các tia bức xạ gây nên. Ngoài ra, với  tính  năng của đá chuyển trượt thành thanh, hóa suy thành vượng nên  có  thể dùng để trấn các khu vực xấu, yếu kém.

- Người Hindu cổ đại cho rằng, thạch anh khói trục ra khỏi cơ thể con  người tiêu cực và cặn bã. Truyền thuyết Ấn Độ   kể về mọt cái cốc được làm  từ nguyên khối tinh thể thạch anh khói có   thể chữa khỏi bách bệnh. Thạch anh khói giúp tránh khỏi stress và   mất cảm giác đau. Có tài liệu cho rằng  thạch anh khói còn giúp điều trị viêm tuyến tiền liệt và thậm chí cả u  xơ tử cung, tuy nhiên những tài liệu này chỉ nên để tham khảo.

- Các nhà chiêm tinh học cho rằng,**[thạch anh khói](https://web.archive.org/web/20120730102023/http://thegioidaquy.net/phong-thuy/da-phongthuy-136-Thach-Anh-Khoi/)**giúp nâng ý nghĩ từ  vùng tối tăm của tiềm thức lên tầm của linh cảm và   siêu ý thức. Nên các tín đồ phật giáo Ấn Độ gọi thạch anh khói là    "đá của phật ". Thạch anh khói trung hòa cái xấu và giảm  tính kích   thích, những người hay mơ mộng  thạch anh khói giúp họ trở về hiện   thực . Thạch anh khói có khả năng bảo vệ chủ nhân của  nó tránh điềm   gở và sự hư hỏng.

*thegioidaquy.net*',
    '2011-11-12 09:00:00', 0, 1128, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-079', 'tac-dung-cua-thach-anh-den', 'Tác dụng của thạch anh đen', 'Thế Giới Đá Quý',
    '/uploads/site_assets/Phongthuy-HoaMocLan-thegioidaquy.jpg', 'Thạch anh đen có khối lượng riêng rất nặng và độ cứng cao nhất trong các loại thạch anh. Thạch anh đen tự nhiên cực kỳ hiếm. Năng lượng của thạch anh đen giúp cho người sở hữu có thể tiếp xúc với quyền năng huyền bí của vũ trụ.', 'Thạch  anh khói và thạch anh tóc đen ở trong một số điều kiện môi trường đặc biệt sẽ chuyển   thành  thạch anh đen.**[Thạch anh đen](https://web.archive.org/web/20120721171343/http://thegioidaquy.net/phong-thuy/da-phongthuy-135-Thach-Anh-Den/)**có khối lượng riêng rất nặng và độ   cứng  cao nhất trong các loại thạch anh. Năng lượng của thạch anh đen cực mạnh giúp cho người sở hữu có thể   tiếp  xúc với quyền năng huyền bí của vũ trụ, thích  hợp với người mạng Thủy, mạng Mộc, mạng Kim. Thạch anh đen trong tự nhiên rất  hiếm.

- Thạch  anh đen được coi là “thầy thuốc chữa bệnh máu ”, đeo[vòng tay thạch anh đen](https://web.archive.org/web/20120721171343/http://thegioidaquy.net/phong-thuy/vong-tay-thach-anh-den-12-ly-1869.html#.UAfd-lLt7Mo),[mặt dây chuyền thạch anh đen](https://web.archive.org/web/20120721171343/http://thegioidaquy.net/phong-thuy/vong-tay-thach-anh-den-12-ly-1869.html#.UAfd-lLt7Mo)để giúp điều   trị chứng  nhồi máu chống đột quỵ và chống lại những mảng sơ vữa.

-Thạch   anh đen  có tác dụng tốt đến bộ máy nâng đỡ vận động và củng cố cột   sống.

*thegioidaquy.net*',
    '2011-11-12 09:00:00', 0, 1171, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-080', 'tac-dung-cua-thach-anh-vang', 'Tác dụng của thạch anh vàng', 'Thế Giới Đá Quý',
    '/uploads/site_assets/Phongthuy-HoaMocLan-thegioidaquy.jpg', 'Thạch anh vàng(citrine)tượng trưng cho tài lộc phú quý nên được gọi là viên đá kinh doanh, thường được các chủ kinh doanh để ngay tại bàn làm việc hay quầy thu ngân để thu hút may mắn tài lộc.', 'Tên    của***[đá quý](https://web.archive.org/web/20250113111547/http://thegioidaquy.net/phongthuy.html)***thạch anh vàng có nguồn gốc từ tiếng Pháp citron là quả  	 	   chanh, vì  thạch anh vàng phần lớn có màu của quả chanh tây, có màu vàng từ nhạt đến sậm.

Đôi    khi bạn  nghe người ta gọi nhầm thạch anh vàng là  thạch anh topaz. Vì     		topaz  là một loại khoáng vật khác hẳn nên ngành  kỹ nghệ buộc phải    loại  		bỏ  tên này.Đứng về góc độ chức năng  tâm linh và cảm xạ thìcùng là màu vàngnhưngtừ trườngtần số dao động của hai loại không giống nhau.

Tính chất vật lý:

Công thức hoá học : SiO2

Kết cấu : Lục giác
Độ cứng : 7
Tỷ trọng : 2,6
Độ khúc xạ : 1,54-1,55
Các nước sản xuất chủ yếu : Brazin

**[Thạch anh vàng](https://web.archive.org/web/20250113111547/http://thegioidaquy.net/phong-thuy/da-phongthuy-134-Thach-Anh-Vang/)**tượng trưng cho tài lộc phú quý. Thạch anh   vàng được    gọi là viên  đá kinh doanh nên  thường được các chủ nhà hàng,   siêu thị và dân buôn bán để  ngay tại quầy thu  ngân, quầy thu tiền để thu hút vận may tài   lộc  buôn   may bán đắt.

Thạch anh vàng có tên gọi quốc tế là[**Citrine**](https://web.archive.org/web/20250113111547/http://thegioidaquy.net/phong-thuy/da-phongthuy-134-Thach-Anh-Vang/).

**Tác dụng của thạch anh vàng:**

- Thạch anh vàng có tác dụng    rất tốt cho việc chữa các  bệnh về đường ruột hoặc dạ dày.

- Thời xưa người ta đeo thạch anh vàng để chống lại nọc rắn độc và quỷ  	 	ám.

-    Những người có bệnh đường ruột hoặc dạ dày, dùng tay phải cầm[quả cầu thạch anh vàng](https://web.archive.org/web/20250113111547/http://thegioidaquy.net/phong-thuy/qua-cau-thach-anh-vang-42-2091.html)kích thước tương đối nhỏ đặt lên bụng, lên vùng dạ dày hay ruột và kết hợp thở  sâu    sẽ có  tác dụng chữa bệnh rất tốt.

- Thạch anh vàng rất có tác dụng đối với lý trí (Mental Body) trong cụm  thần kinh Thái    dương, giúp tăng cường trí nhớ, tư duy logic mạch  lạc, chóng thuộc    bài may mắn cho thi cử. Là học sinh nếu có điều  kiện nên cầm trên tay  trái   một viên Thạch anh vàng khi học bài sẽ mau thuộc  bài hơn.

- Học sinh khi đi thi nên mang theo người viên Thạch  anh vàng khi trước đã giúp bạn học thuộc bài, nó sẽ là “Bùa may mắn” cho  bạn, giúp bạn tự tin và may mắn trong thi cử.

- Những người do bộ não bị lão hoá hay quên, người già bị lú lẫn,  nên cầm một viên Thạch anh vàng to hoặc nhỏ tuỳ theo, rồi đặt vào vùng  ngực tâm niệm mỗi ngày, làm như thế sẽ cải thiện đáng kể tình trạng  trên.

- Người Hồng Kông tin rằng đeo nhiều[*trang sức đá*](https://web.archive.org/web/20250113111547/http://thegioidaquy.net/phongthuy.html)Thạch anh vàng sẽ đem đến cho con người  những tài lộc may mắn, vì vậy những  người đi cá cược đua ngựa, mua sổ số hoặc đến Macau cá cược, đua chó, đánh bạc sẽ được may mắn nhiều.

- Nhiều người muốn làm giàu nhanh, đã từng đặt viên Thạch anh vàng dưới lệnh mua cổ phiếu rồi chăm chú tâm niệm, với mong muốn cầu được ước thấy.

- Đặt[miếng thạch anh vàng](https://web.archive.org/web/20250113111547/http://thegioidaquy.net/phong-thuy/mieng-thach-anh-vang-1629.html)trên bàn làm việc,    có tác dụng đối với  những người làm công tác biên tập, nghiên cứu  hay   những công việc có  tính chất tỷ mỷ như lập báo biểu kế toán, soạn   thảo  các điều luật, soạn  thảo hợp đồng, xây dựng kế hoạch của doanh   nghiệp  hay vẽ bản vẽ thiết kế  công trình.

-    Khi chơi bài đặt một viên Thạch anh vàng bên cạnh người, sẽ giúp cho    bạn nhớ lâu, giỏi tính toán làm tăng khả năng thắng đối phương.

-  Những   bạn hay mơ mộng viển vông, tính tình kênh kiệu, nói năng khách   sáo,  hãy  thường xuyên đeo trên người Thạch anh vàng. Làm như thế sẽ giúp bạn thực tế hơn, dễ hoà đồng hơn,  gần gũi hơn với cuộc sống đời thường.

Bảo quản  và làm sạch:

- Thạch anh vàng có độ cứng 7 trên thang  Mohs. Nó vững bền và có thể đeo  		hàng ngày.

- Rửa thạch anh  vàng với xà phòng: dùng bàn chải chà phía sau viên đá là  		nơi có thể  dính chất dơ.

- Không nên để trang sức thạch anh vàng dưới nhiệt độ hay ánh sáng mặt trời trong  		thời gian lâu, đá quý thạch anh sẽ giảm giá trị.

*thegioidaquy.net*',
    '2011-11-12 09:00:00', 0, 1214, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-081', 'tac-dung-cua-thach-anh-tim', 'Tác dụng của thạch anh tím', 'Thế Giới Đá Quý',
    '/uploads/news/thumb-art-072-tac-dung-cua-thach-anh-tim-0-new.jpg', 'Đặt mặt đá Thạch anh vào trong gối đầu sẽ làm cho những người già hay những người ốm do suy nhược cơ thể có giấc ngủ ngon hơn. Đặt đá Thạch anh tím tại bàn làm việc, phòng làm việc hay phòng khách sẽ giúp tăng cường mối quan hệ khách hàng, đồng nghiệp, đem lại thành công may mắn trong kinh doanh.', 'Thạch anh còn được gọi là*viên[**đá Phong Thủy**](https://web.archive.org/web/20120730102034/http://thegioidaquy.net/phongthuy.html)(Fengshui Stone)*vì trải qua vài triệu năm hình thành, đá Thạch Anh thu hút năng lượng      vũ trụ và phát ra 1 trường năng lượng dương cực mạnh, có thể đem đến   sự    may mắn trong cuộc sống và công việc, chống lại sự ảnh hưởng   của năng    lượng xấu.

**Đặc điểm:**

Thạch anh tím (Amethyst)là    loại đá kiêu sa và đẹp  nhất trong dòng họ Thạch anh. Oxit sắt là   thành  phần chủ yếu để tạo nên  màu tím rực rỡ của loại đá này. Tần số   của màu  tím rất có tác dụng với hệ thần kinh  trung ương, sẽ giúp cho   người ta  ổn định tâm thần. Năng lượng tinh tuý  của Thạch anh tím làm   cho người  ta như có cảm giác đang được tận hưởng  những luồng gió xuân.

**Công dụng:**

- Thả mặt Thạch anh tím vào trong rượu,    sẽ làm mất đi vị cay sặc mũi, làm cho  rượu thơm hơn, dễ uống và khó    say hơn. Bản thân chữ “Amethyst” trong  tiếng Hilạp trước đây có nghĩa    là “không say”.

- Đặt     một[mặt thạch anh tím](https://web.archive.org/web/20120730102034/http://thegioidaquy.net/phong-thuy/mat-da-thach-anh-tim-tho-2143.html#.UAXItVLt7Mo)vào trong gối đầu sẽ làm cho những người già  hay    những người ốm do suy nhược cơ thể có    giấc ngủ ngon hơn. Chú ý nếu như là người trẻ hay những người khoẻ   bình   thường mà đặt mặt Thạch anh tím vào dưới gối sẽ rất khó ngủ, bởi vì  Thạch anh tím phát khí mạnh mà đầu là bộ phận cảm nhận khí nhiều  nhất.

- Trẻ    em khi ngồi học hay làm bài có đặt  một quả cầuThạch anh tím tròn trên    bàn học sẽ làm cho học tập chuyên tâm  hơn, nâng cao khả năng tư duy  học   bài và kết quả học tập.

- Trong một gia đình nếu có trẻ em quá hiếu động, hãy đặt vào đệm trên  chiếc ghế ngồi học của cháu một mặt Thạch anh tím, sẽ giúp cho  cháu bớt hiếu động, tập trung chú ý nâng cao kết quả học tập và hoà nhã  hơn trong khi giao thiệp với người khác.

- Để trên bàn học một[quả cầu thạch anh tím](https://web.archive.org/web/20120730102034/http://thegioidaquy.net/phong-thuy/qua-cau-thach-anh-tim-1261.html#.UAXISlLt7Mo),    từ trường của Thạch anh tím sẽ  làm cho việc học bài, thuộc bài, nhớ    bài được tốt hơn, rất có lợi trong  việc nghiên cứu, tìm tòi, sáng  tạo.

- Đặt trong nhà, phòng làm việc, cửa hàng hay cuối một hành lang hoặc lối  đi một miếng Thạch anhtím, sẽ có tác dụng thu tài nạp khí và tụ tài.

- Khi  xem phong thuỷ, thấy trong nhà có sự xung hoặc sát, hãy để một quả cầu Thạch anh tím nhỏ trước một hang Thạch anh tím rồi cùng đặt vào  trước những chỗ xung sát, làm như thế sẽ có tác dụng giải sát trừ xung.

-  Những người mới học ngồi thiền, hãy đặt dưới đệm ngồi một mặtThạch anh  tím sẽ có tác dụng lắng tâm, loại bỏ những suy nghĩ mông lung, rất dễ  nhập    thiền. Thạch anh tím còn có tác dụng  điều hoà sự vận động của hai    mạch.

- Trẻ em nên đeo vòng tay thạch anh tím, dây chuyền thạch anh tím hay vòng cổ Thạch anh tím, sẽ có tác dụng kích thích niềm vui chơi đam mê, sẽ hiếu  học hơn.

-  Những người làm lãnh đạo, nên đeo nhiều đồ trang sức được làm thành từ[**Thạch anh tím**](https://web.archive.org/web/20120730102034/http://thegioidaquy.net/phong-thuy/da-phongthuy-36-Thach-Anh-Tim/), sẽ có tác dụng làm giảm sự chuyên quyền, tăng cường lòng  bao dung,    nhẫn nại, có lợi cho công tác lãnh đạo, tăng cường quan hệ  giữa người    với người, làm cho cấp dưới hết lòng với mình, có được sự  tương tác    truyền thống do “ở hiền gặp lành”

-  Phụ nữ liễu yếu đào tơ, nên đeo đồ trang sức Thạch  anh tím,    sự trang nhã cao sang của Thạch anh tím sẽ làm tăng sự kiêu sa,  làm    tăng niềm đam mê nghiên cứu tri thức, trí tuệ, từ đó cải thiện được   vẻ   đẹp và thể chất.

- Các doanh   nhân Châu Á thường đặt đá Thạch anh tím tại góc THỔ (Tây Nam hoặc Đông  Bắc)  của bàn làm việc, phòng làm việc hoặc phòng    khách, giúp tăng cường  mối  quan hệ khách hàng, đồng nghiệp, đem lại    thành công trong kinh  doanh,cầu chúc may mắn cho người sở hữu.

*thegioidaquy.net*',
    '2011-11-06 09:00:00', 0, 526, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-082', 'tac-dung-cua-da-ma-nao', 'Tác dụng của đá mã não', 'Thế Giới Đá Quý',
    '/uploads/news/thumb-art-073-tac-dung-cua-da-ma-nao-0.jpg', 'Đá mã não đem lại sức khỏe, sự hưng thịnh và trường thọ. Đồ trang sức đá Mã Não làm cho chủ của nó trở nên dễ mến trong giao tiếp và biết ăn nói, cũng như bảo vệ chủ chống lại kẻ thù thâm độc.', 'Tên gọi Mã Não (Agate)bắt nguồn từ tiếng Hy Lạp cổ Ahates – có nghĩa  là “hạnh phúc”.

Tên gọi  khác biến thể đá Mã não: đá Mã Não pháo đài  (Có hoa văn giống như   hình vẽ trên bản đồ cổ), đá Mã Não cành cây (Phân nhánh hình cành  cây,  có hoa  văn trông như cây rừng), đá Mã Não mắt cú (Có hình con mắt).Nguồn gốc Mã Não gặp chủ yếu trong  hốc của đá phun trào và các thành tạo nhiệt dịch nhiệt độ thấp.

Đặc điểm chính:

Mã Não(Agat) là dạng biến thể của  chalcedony thớ  mịn mà đặc trưng là có màu phân lớp. Những lớp màu có  dạng đồng tâm  hoặc dạng dài. Màu của đá Mã Não dao động từ trắng sữa, phớt vàng, phớt xanh  lục, đỏ đen.  Loại đẹp nhất được gọi là Mã Não “mắt” hoặc Mã Não  “mắt kính” với những lớp đồng tâm  quanh một điểm ở trung tâm.

Tính chất:

Ở châu Âu,*[đá mã mão](https://web.archive.org/web/20120923040142/http://thegioidaquy.net/phong-thuy/da-phongthuy-116-Da-Ma-Nao)*là biểu tượng của  sức khỏe,  sự hưng thịnh và trường thọ. Ở Ấn Độ là biểu tượng của của  sự hưng thịnh. Đồ  trang sức đá Mã Não làm cho chủ của nó trở nên dễ mến  trong giao tiếp và biết ăn  nói,  cũng như bảo vệ chủ chống lại kẻ thù  thâm độc. Bằng cách hấp thụ năng  lượng  có hại, đá Mã Não có thể bảo vệ chủ  chống lại những xung năng lượng xấu, mã não là loại đá của  nữ  thần màu mỡ–bảo  trợ cho những chủ trang trại và người làm vườn. Nhẫn  gắn  mặt đá Mã Não làm cho người đàn ông trở nên quyến rũ hơn trong mắt phụ nữ. Mã Não là    biểu tượng của chòm sao Kim Ngưu và Song Tử trong cung hoàng đạo, năng   lượng cảm  thụ âm có tác dụng tới tất cả các luân xa tuỳ theo vào   màu sắc của đá.

Mã Não có độ cứng cao chịu được axit nên được  dùng để  chế tác các trục máy, chốt căn chính xác. Loại đẹp dùng để  làm**[trang sức đá](https://web.archive.org/web/20120923040142/http://thegioidaquy.net/phongthuy.html)**

Công dụng:

-[Miếng đá mã não](https://web.archive.org/web/20120923040142/http://thegioidaquy.net/phong-thuy/mat-dong-dieu-da-ma-nao-1919.html)được cắt ra tương đối to có thể đặt dưới bàn  chân, ngồi thiền theo tư   thế thoải mái tự nhiên, lượng khí sẽ đi từ trên  đi xuống, còn tà khí  sẽ  được thoát ra từ gan bàn chân, làm như thế rất  có tác dụng làm hết  áp lực, giảm mệt mỏi và những tà khí trong người.

- Có thể đặt miếng Mã não dưới mông và ngồi lên khi luyện khí công, sẽ  rất có tác dụng kích thích từ  trường luân xa mông, nâng cao sức công,  làm tăng thêm khả năng tĩnh tâm  của con người.

- Những viên đá mã não có  vân khi được mài giũa, có thể tạo thành những “con mắt”, có tác dụng trừ   tà, rất thích hợp được dùng đeo làm bùa hộ mệnh hay vật trừ tà.

- Nông dân phương Tây thời xưa còn có thể treo đá mã não lên thân cây làm cho  cây sai quả; chôn đá mã não xuống ruộng hay treo đá mã não lên sừng trâu đi cầy  để làm cho mùa màng bội thu.

- Nếu có người đột nhiên phát sốt mà  chưa kịp đưa đi bệnh viện, có thể đặt lên trán, lên họng hay lên ngực người ấy một miếng đá nã não sẽ làm hạ sốt, giảm cường độ cơn đau và đi bệnh viện chữa trị.

- Đặt một miếng đá mã não vừa phải xuống dưới gối nằm sẽ làm cho ngủ ngon và đem lại cho  những giấc mơ đẹp.

- Hộp đựng đồ làm bằng đá mã não có thể làm cho  những đồ trang sức như  nhẫn, hoa tai, khuyên tai hay vòng tay giảm  thiểu từ tính, nhưng bạn  nhớ rằng những thứ này khi để vào hộp phải dùng  giấy hoặc vải bọc lại  kẻo bị trầy xước.

- Những em bé đang đi học tiếp xúc nhiều với đá mã não sẽ thông minh, linh hoạt, học giỏi, tính thích nghi cao.

- Nhân viên tiếp thị đeo vào người[vòng tay đá mã  não](https://web.archive.org/web/20120923040142/http://thegioidaquy.net/phong-thuy/vong-tay-ma-nao-hoa-sen-8-ly-1716.html#.UAXF_lLt7Mo)có thể tăng cường khả năng thân mật, linh hoạt ứng biến,  ngoại giao giỏi, rất có lợi cho hoạt động tiếp thị, nâng cao hiệu quả công việc.

- Trong buồng the đặt Mã não, sẽ làm tăng  thêm sự ái ân vợ chồng, làm cho cuộc sống buồng the càng thêm mặn mà.

- Một số Mã não còn hàm chứa một lượng oxit sắt rất phong phú gọi là  Mã não lửa (Fire  Agate),  khi được cắt mài sẽ hiện ra những đốm hoa như  có trong lòng  trắng  trứng ( Như hoa lửa-Play of Fire), màu sắc ấm áp,  lung linh, rất  được  ưa dùng làm đồ trang sức, vài người cho rằng đeo loại trang  sức này vào có thể phòng được cảm sốt, cảm lạnh hay thương hàn.

- Những người có cá tính  kiêu kỳ, lạnh nhạt không hoà mình với mọi  người,  những người không  muốn chia sẻ với những người khác hay những  người  luôn tự ty, khi đeo  vào người[vòng tay mã não](https://web.archive.org/web/20120923040142/http://thegioidaquy.net/phong-thuy/da-phongthuy-116-Da-Ma-Nao)sẽ làm tăng nhiệt huyết, dần bỏ  được những cá tính nêu trên.

- Những người da nóng, da  gà, bao gồm cả chứng hay ra mồ  hôi tay mồ hôi chân, nếu thường xuyên  tiếp xúc với*[đá mã não](https://web.archive.org/web/20120923040142/http://thegioidaquy.net/phong-thuy/da-phongthuy-116-Da-Ma-Nao)*có thể  cải thiện được tình trạng trên.

- Đeo những[**trang sức đá**](https://web.archive.org/web/20120923040142/http://thegioidaquy.net/phongthuy.html)chế tác từ đá Mã Não có  thể làm giảm tính bảo thủ, làm mất đi áp lực, hoá giải những  sự cãi vã của các mối quan hệ, đem lại sự êm ấm, bình  thản và may  mắn.

*thegioidaquy.net*',
    '2011-11-06 09:00:00', 0, 569, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-083', 'cong-dung-cua-thach-anh-hong', 'Công dụng của thạch anh hồng', 'Thế Giới Đá Quý',
    '/uploads/site_assets/Phongthuy-HoaMocLan-thegioidaquy.jpg', 'Thạch anh hồng là loại đá tượng trưng cho tình yêu, có tác dụng tốt với các bệnh ở hệ tim mạch và hệ thần kinh loại trừ sự mệt nhọc ra khỏi cơ thể. Thạch anh hồng còn có tác dụng làm hoạt hóa hệ thống lympha làm tăng hệ miễn dịch.', 'Thạch     anh hồng có màu hồng phấn tươi, mịn,   có  thể được coi là biểu tượng của  trái tim, là một  trong   những loại đá quý về tình yêu được mọi người  yêu thích.

Thạch  anh hồngcòn là lá bùa hộ mệnh cho các mối quan hệ của  bạn, ko chỉ    thế nó còn giúp bạn giảm tress và giảm thiểu những cơn nóng  giận bộc    phát, giúp bạn thoải mái và tự tin hơn.

*[Thạch anh hồng](https://web.archive.org/web/20121018010515/http://thegioidaquy.net/phong-thuy/da-phongthuy-133-Thach-Anh-Hong/)*có tên gọi quốc tế là*[Rose Quazt](https://web.archive.org/web/20121018010515/http://thegioidaquy.net/phong-thuy/da-phongthuy-133-Thach-Anh-Hong/)*,*[Milk Rose Quazt](https://web.archive.org/web/20121018010515/http://thegioidaquy.net/phong-thuy/da-phongthuy-133-Thach-Anh-Hong/)*

Đặt tính:

Có      rất nhiều loại thạch anh, chiếm một  vị trí đặc biệt trong họ thạch    anh là thạch anh hồng. Sắc hồng của  thạch anh hồng do tạp chất chứa    mangan và titan. Cho đến giữa thế kỷ hai  mươi đối với những người yêu    chuộng khoáng vật mới chỉ biết đến thạch  anh hồng không trong suốt( rose quazt). Tuy nhiên vào năm 1959 , họ đã tìm thấy trên  lãnh thổ Braxin những viên**[thạch anh hồng](https://web.archive.org/web/20121018010515/http://thegioidaquy.net/phong-thuy/da-phongthuy-133-Thach-Anh-Hong/)**trong mờ ( milk rose quazt) và gần như trong suốt. Ngay từ  thời xưa đá thạch anh hồng đã được quí mến và điều đó được duy trì cho  đến tận ngày nay.

Công dụng:

- Thạch anh hồng có tác dụng tốt  với các bệnh ở hệ tim mạch và hệ thần kinh, loại trừ sự mệt nhọc ra khỏi cơ thể.    Thạch anh hồng còn có tác  dụng làm hoạt hóa hệ thống lympha làm tăng hệ miễn dịch. Thạch anh hồng còn ảnh hưởng đến hệ tiết niệu, mạch  máu và tủy xương. Có vài ý kiến cho    rằng thạch anh hồng có thể giúp tránh thụ  thai ngoài ý muốn và giúp kéo  dài   tuổi thọ. Thạch anh hồng ít được biết đến ở dạng   tinh  thể mà thường tồn tại ở dạng tổ hợp.

-    Thạch anh hồng giúp  chống lại stress, nó dập tắt những cơn nóng giận    bộc phát. Đeo các**[trang sức đá quý](https://web.archive.org/web/20121018010515/http://thegioidaquy.net/phongthuy.html)**như[vòng tay thạch anh hồng](https://web.archive.org/web/20121018010515/http://thegioidaquy.net/phong-thuy/vong-tay-thach-anh-hong-6ly-1402.html#.UAXM_VLt7Mo)tăng cường sự  sáng   tạo và đem lại cảm  giác tự tin. Thạch anh  hồng có   ích lợi  trong việc bảo vệ tình yêu, bảo vệ hạnh phúc gia đình  và giúp   những phụ  nữ chưa chồng sớm tìm được tình yêu của mình.  Thạch anh  hồng  làm dịu  những cơn đau về mặt tình cảm và những vết  thương lòng.  Nó còn  là lá bùa  hộ mệnh giúp cải thiện quan hệ giữa chủ  nhân với  người khác.

-*[Thạch anh hồng](https://web.archive.org/web/20121018010515/http://thegioidaquy.net/phong-thuy/da-phongthuy-133-Thach-Anh-Hong/)*tác động tốt đến luân xa ở vùng tim như: hệ tim mạch, tế bào tuyến    vú, cột  sống và hai tay. Thạch anh hồng mang năng lượng cảm thụ  của   Âm.

-Trên    mình đeo thạch anh hồng, có tác dụng làm thay đổi tính nóng, tính thiếu kiên  nhẫn, tăng cường thân thiện, cải thiện tốt các mối  quan hệ.

-Giữa các cặp vợ chồng các đôi trai gái thường xảy ra cãi cọ nên để**[Thạch anh hồng](https://web.archive.org/web/20121018010515/http://thegioidaquy.net/phong-thuy/da-phongthuy-133-Thach-Anh-Hong/)**vào gối của hai người để cải thiện mối quan hệ tình cảm.

-Nơi    kinh doanh nên để nhiều Thạch anh  hồng trong tầm mắt để    giảm tính đa nghi của khách hàng, làm  cho khách hàng ít so sánh và an    tâm khi mua hàng.

- Nhân viên đeo vòng tay Thạch  anh hồng hoặc đeo[mặt thạch anh hồng](https://web.archive.org/web/20121018010515/http://thegioidaquy.net/phong-thuy/giot-nuoc-nho-thach-anh-hong-2110.html#.UAXNUFLt7Mo)để có thái độ thân thiện nhằm phục vụ khách tốt hơn.

*thegioidaquy.net*',
    '2011-11-06 09:00:00', 0, 307, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-084', 'tac-dung-cua-da-mat-ho', 'Tác dụng của đá mắt hổ', 'Thế Giới Đá Quý',
    '/uploads/site_assets/Phongthuy-HoaMocLan-thegioidaquy.jpg', 'Đá mắt hổ chứa nhiều chất amiăng xếp thành những dãy song song, dễ phản ứng với ánh sáng tạo nên những tia nhấp nháy trông giống như mắt hổ nên có tên gọi là đá mắt hổ.', '**Đặc điểm:**

Đá mắt hổ là một thành viên quan trọng của gia tộc thạch anh. Nó hàm chứa  nhiều chất amiăng xếp thành những dãy song song, dễ phản ứng với ánh  sáng tạo nên những nhấp nháy trông giống như mắt hổ nên có tên  gọi là đá mắt hổ. Đá mắt hổ là một loại**[đá quý phong thuỷ](https://web.archive.org/web/20121020014243/http://thegioidaquy.net/phongthuy.html)**đem lại giàu có và may mắn, từ trường của nó rất lớn và mạnh mẽ kích ứng thần  kinh thái dương nên còn được dùng để trị bệnh.

Đá mắt hổ có tên gọi quốc tế là[**Tiger Eye**](https://web.archive.org/web/20121020014243/http://thegioidaquy.net/phong-thuy/da-phongthuy-24-Da-Mat-Ho)

Cách dùng:

- Những người luôn có rất nhiều dự định nhưng lại không thực hiện được,   hãy đeo các trang sức đá mắt hổ, nó sẽ kích thích lòng tin và  dũng  khí hành động.

- Những người khí huyết  hư  nhược, thiếu dũng khí, hãy luôn nắm đá mắt hổ trong tay  kết  hợp với thở sâu để tăng cường sức sống và sức mạnh của cơ  bắp.

- Khi làm việc gặp khó khăn, khó kiên trì chỉ muốn  bỏ cuộc,   hãy    nắm  đá mắt hổ ở tay trái kết hợp thở sâu, sẽ có được  những   phán  đoán   và  hành động quả quyết chính xác.

- Những người  trí nhớ kém, khả  năng tính toán kém, hay  quên, hãy đeo đá mắt hổ ở gần vùng thần kinh thái dương,  như vậy sẽ  tăng cường năng lượng tốt cho luân xa thái dương.

-Đeo đá mắt hổtrên người để đem lại sự  giàu có và may mắn. Trong thời Trung cổ đá mắt hổđược dùng để xua đuổi  những phép thuật ma quỷ và tránh tà.

- Những người hay ốm vặt, thân thể bị suy nhược, hãy cầm mỗi tay một  viên  đá mắt hổ tương đối to rồi đi dạo, chạy, vận động cho đến khi  ra mồ  hôi thì     dừng lại, cứ  mỗi tuần làm từ hai đến bốn lần như thế thì  sẽ cải      thiện được sức  khoẻ.

- Những người bị suy yếu dạ dày và  đường  ruột, cầm quả cầu đá mắt hổ xoa vào vùng bụng, làm cho chức  năng của  các bộ phận vùng bụng khoẻ      lên.

- Khi làm việc tại văn phòng, có  thể đặt  trên bàn**[đá mắt hổ](/web/20121020014243/http://thegioidaquy.net/phong-thuy/da-phongthuy-24-Da-Mat-Ho)**hình cầu, hình thỏi, hình kim tự tháp hoặc  các vật  điêu khắc, như vậy sẽ làm cho tinh thần được tập trung ổn  định, hoàn  thành công việc một cách đầy đủ, chu đáo.

- Trong  một tập thể,  có người nào đó do không biết phải làm việc  như     thế nào,  phải cống hiến  như thế nào, từ đó sinh ra lơ là thờ  ơ,  hãy   để người đó  đeo đá mắt hổ, như vậy thì sẽ hiểu rõ được góc độ và vai trò của mình  để hoà nhập      với  tập thể cộng đồng.

- Đeo[vòng tay đá mắt hổ](https://web.archive.org/web/20121020014243/http://thegioidaquy.net/phong-thuy/vong-tay-da-mat-ho-8-ly-1418.html)tụng kinh, niệm thần chú sẽ tăng cường sức mạnh của kinh văn và lời chú.

- Những người yếu bóng vía không dám đi đêm, hãy đeo đá mắt hổ để tăng   cường trạng thái tinh thần, dũng khí.

-Đá mắt hổ giúp xóa bỏ sợ hãi, lo lắng hoang tưởng, do vậy  nó là một         liều thuốc cực kỳ hiệu quả với  bệnh căng thẳng thần kinh.

- Những người nhát gan, sức khoẻ yếu, người làm việc không tới nơi   tới chốn hãy đeo[vòng tay đá mắt hổ](https://web.archive.org/web/20121020014243/http://thegioidaquy.net/phong-thuy/vong-tay-da-mat-ho-8-ly-1418.html#.UAWsplLt7Mo)vào tay, người đó   sẽ trở nên hoạt bát hơn. Người phụ nữ sức khoẻ yếu sẽ trở nên khoẻ mạnh   hơn.

-Một  vài  người dùng đá mắt hổ để      chữa các bệnh  về cổ họng, về mắt và sinh  sản,  đồng  thời làm   xương    cột sống thêm cứng  cáp, loại bỏ các chất độc  và  giảm  đau.

*thegioidaquy.net*',
    '2011-06-10 09:00:00', 0, 612, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-085', 'thach-anh-xanh', 'Thạch anh xanh', 'Thế Giới Đá Quý',
    '/uploads/news/art-085-1-1-trung-phong-thuy-ngu-sac-lon-0.jpg', 'Thạch anh xanh là một trong những loại đá quý và hiếm gặp nhất trong dòng họ thạch anh. Với màu sắc đặc trưng là màu xanh lá cây, chúng được nuôi dưỡng từ sâu trong các hang động lớn.', '**-[Thạch anh xanh](https://web.archive.org/web/20150211044116/http://thegioidaquy.net/phong-thuy/da-phongthuy-137-Thach-Anh-Xanh-Green-quartz-/)**làmột trong những loạiđáquý vàhiếm gặp nhất trong dòng họthạch anh. Công thức hóa học làSiO2.Thạch anh xanhđược tìm thấy tại các mỏđáởÚc, Áo, Braxin, Tây Ban Nha, Na Uy, Chi Lê, Hoa KỳvàTrung Quốc. Chúng cótrọng lượng khoảng từ2.6 – 2.7g/cm3vớiđộcứng củađálà7 Mohs.

- Thạch anh xanh cómàu sắcđặc trưng làmàu xanh lácây. Gam màu tượng trưng cho thiên nhiên. Chúng thườngđược nuôi dưỡng từsâu trong các hangđộng lớn.

- So với một sốloạiđákhác trong dòng họthạch anh như:**thạch anh trắng, thạch anh hồng, thạch anh tím…**thìthạch anh xanhđược xem làloạiđácónhiều công dụng nhất.

- Các nghệ nhân đã chế tác những viên thạch anh thô sơ, nguyên thủy thành những vật phẩm phong thủy không chỉ đẹp mà còn cuốn hút ánh nhìn. Màu sắc xanh tự nhiên kết hợp với những góc cạnh của thạch anh làm cho vẻ đẹp của vật phẩm phong thủy lại càng tinh tế, cuốn hút hơn bao giờ hết.

**-*******Đ********áthạch anh xanh***thườngđược đặt trong những bình chứa có hình dạng quả trứng hay hồ lô cùng với một số thạch anh có màu sắc khácđểđặt trong nhà, văn phòng. Việc đặt những vật phẩm phong thủyđược làm từloạiđáthạch anh này không những mang lại may mắn cho bạn màtrông chúng còn vô cùng tinh tếvàcuốn hút.

[![trung-phong-thuy-ngu-sac-lon](/uploads/news/art-085-1-1-trung-phong-thuy-ngu-sac-lon-0.jpg)](https://web.archive.org/web/20150211044116/http://thegioidaquy.net/phong-thuy/trung-phong-thuy-ngu-sac-lon-2447.html#.VM-p-9KsVlw)

*[Trứng phong thuỷ ngũ sắc đ](https://web.archive.org/web/20150211044116/http://thegioidaquy.net/phong-thuy/trung-phong-thuy-ngu-sac-lon-2447.html#.VM-p-9KsVlw)[ựng năm loại thạch anh](https://web.archive.org/web/20150211044116/http://thegioidaquy.net/phong-thuy/trung-phong-thuy-ngu-sac-lon-2447.html#.VM-p-9KsVlw): Xanh, hồng, vàng, đen trắngđem lại tài lộc may mắn bất tận.*

- Chính nhờ “thiên năng” vốn có củađá thạch anh xanh, mà từ xa xưa con người ta đã sử dụng nó như một lá bùa hộ mệnh bảo vệ mình.Đáthạch anh xanhđược xem nhưmột vịthần vàthờcúng nhằmđemđến may mắn, sức khỏe cho con người. Bởi họquan niệm rằng màu sắc xanh lácây tựnhiên củađáchính làdo mẹthiên nhiên ban tặng.

- Những vua chúa, quý tộc thời xưa thường sử dụng*thạch anh xanh làm vật trang trí phong thủy*hoặc dùng làm trang sức để mang đến sức khỏe, chữa bệnh.

- Nhờ khả năng phong thủy mà thạch anh xanh có khả năng giúp chống lại các bệnh về da, tóc. Những viên**đá thạch anh**hay trang sức thạch anh có thể làm giảm áp lực, chữa các bệnh liên quan đến tim mạch, tuần hoàn máu và cảm lạnh.

- Ngoài ra,đáthạch anh xanh còn làbiểu tượng “Thạch anh tài lộc” với ý nghĩa rộng là khí vận tốt, may mắn, cơ hội tốt, những người bạn tốt, và quý nhân phù trợ ...vv. Màu xanh của thạch anh cũng được gọi “Tài lộc chính đáng ”, thể hiện chúng ta nỗ lực, chăm chỉ làm việc thì đạt được thành quả chính đáng, khác với tài lộc không phải do cần cù lao động làm ra hay tài lộc không chính đáng.

- Khi sử dụng những sản phẩm từ***đá thạch anh xanh***sẽ giúp cho con người ta tìm thấy được tinh thần sảng khoái, đầu óc sáng suốt, tăng cường lạc quan và sự tự tin, nó như một vật khơi thông suy nghĩ của con người làm cho con người cảm thấy tốt hơn, không bị bế tắc bởi cuộc sống hiện tại. Đặc biệt, sử dụng những sản phẩm từ thạch anh còn có khả năng làm này sinh tình cảm quý mến với nhau, gia tăng cảm xúc, và gắn kết các mối quan hệ thêm bền chặt hơn.

*[*Thegioidaquy.net*](https://web.archive.org/web/20150211044116/http://thegioidaquy.net/phongthuy.html)*',
    '2015-02-03 09:00:00', 0, 1085, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-086', 'cong-dung-phong-thuy-chung-cua-nhom-da-thach-anh', 'Công dụng phong thủy chung của nhóm Đá Thạch anh', 'Thế Giới Đá Quý',
    '/uploads/news/art-086-1-1-vong-tay-thach-anh-toc-ba-mau-11-ly-dam-trong-0.jpg', 'Nhóm đá thạch anh có rất nhiều dạng: Thạch anh tím, thạch anh vàng, thạch anh trắng, thạch anh ám khói, thạch anh tóc…Chúng được sử dụng phổ biến khắp mọi nơi nhờ vô vàn những tính năng đặc hiệu. Hãy cùng chúng tôi khám phá những công dụng phong thủy chung của nhóm Đá thạch anh này nhé!', '***[Đáthạch anh](https://web.archive.org/web/20150211044056/http://thegioidaquy.net/phong-thuy/da-phongthuy-23-Da-Thach-Anh)***làmột trong những loại khoáng vật phổbiến nhất trên thếgiới. Chúngđược sửdụng phổbiến rộng rãi khắp mọi nơi từhàng ngàn năm trước nhờvô vàn những công dụng kỳdiệu từloạiđánày mang lại. Loạiđáphong thủy này códương khírất mạnh. Mỗi loạiđáthạch anh cómột công dụng riêng khi sỡhữu chúng tùy thuộc vàođặc tính vàmàu sắc riêng của từng loại.

Nhómđáthạch anh córất nhiều dạng:**Th****ạch anh tím, thạch anh vàng, thạch anh trắng, thạch anhám khói, thạch anh tó****c…**

Đáthạch anhđã xuất hiện từthời CổĐạiđược xem là“Viênđátrời” linh thiêng. Chúngđược các nhàtiên tri này sửdụng nhưlàcông cụđểdựđoán tương lai.

Người MỹLa Tinh xem*đáthạ**ch anh*lànhững viênđáthiêng liêng. Người Nhật thìcho rằng loạiđánày chính làhơi thởcủa con rồng trắng vàcũng làbiểu tượng cho sựhoàn hảo. Bên cạnhđó,Đáthạch anh thườngđược người dân Úc sửdụng trong các lễhội cầu mưa. Các vịvua chứa, quan lại Truong Quốc cũng sớm phát hiện ra những công năngđặc hiệu của loạiđánày vàsửdụng chúng trong việc trưng bày tại tưgia vàchốn quan trường từthời Chiến Quốc.

Ngày nay,**đáthạch anh cũng cónhiều ý nghĩa quan trọ****ng**.Đáthạch anh đã giúp loài người tạo ra nhiều ứng dụng của nền văn minh hiện đại như: laze, quang học, máy tính, hệ thống thông tin liên lạc, phát thanh, truyền hình, siêu âm và nhiều hơn nữa….

Trong điều kiện địa chất nhất định và rất đặc biệt, đồng thời phải trải qua hàng triệu năm hình thành,*đá thạch anh đã tích luỹ nguồn năng lượng cực mạnh*có tác dụng rất lớn trong việc tăng cường sức khoẻ, giải trừ bệnh tật, tốt cho tình duyên, sự may mắn trong cuộc sống và công việc, tốt cho việc xây dựng các mối quan hệ xã hội, và chống lại sự ảnh hưởng của năng lượng xấu.

[![vong-tay-thach-anh-toc-ba-mau-11-ly-dam-trong](/uploads/news/art-086-1-1-vong-tay-thach-anh-toc-ba-mau-11-ly-dam-trong-0.jpg)](https://web.archive.org/web/20150211044056/http://thegioidaquy.net/phong-thuy/vong-tay-thach-anh-toc-ba-mau-11-ly-dam-trong-1181.html#.VM-UZ9KsVlw)

*[Vòng tay thạch anh tóc](https://web.archive.org/web/20150211044056/http://thegioidaquy.net/phong-thuy/vong-tay-thach-anh-toc-ba-mau-11-ly-dam-trong-1181.html#.VM-UZ9KsVlw)đem lại tài lộc và may mắn, phù hợp cho tất cả các mạng*

**Sauđây làmột sốcông dụng chính của nhómđáthạch anh mang lại. Hãy cùng chúng tôi khám phá****!**

**1. Gia đình bình an – đem lại may mắn:**

- Đặtquả cầu thạch anhtrong nhàcótác dụng truyền khí từ tường, không những bảo hộ gia trung bình an, tránh tà mà còn giúp lưu thông không khí trong nhà đem lại nhiều may mắn.

[![qua-cau-da-thach-anh-tim](/uploads/news/art-086-2-1-qua-cau-da-thach-anh-tim-63-1.jpg)](https://web.archive.org/web/20150211044056/http://thegioidaquy.net/phong-thuy/qua-cau-da-thach-anh-tim-63-3222.html#.VM-TVtKsVlw)

*[Quả cầu thạch anh tím phong thuỷ](https://web.archive.org/web/20150211044056/http://thegioidaquy.net/phong-thuy/qua-cau-da-thach-anh-tim-63-3222.html#.VM-TVtKsVlw)giúp xoay chuyển tạo vận khí tốt, đem lại may mắn và giàu có.*

**2. Đá thạch anh cải thiện phong thủy và thu hút tài khí:**

- Đặt đáthạch anh trong nhà có tác dụng hóa xung giải sát, ngoài ra còn có thể thu hút và tích lũy tài lộc.

**3. Trấn thạch, trừ tà, vừa vượng vừa phát:**

- Đặtđáthạch anh phong thủy ở góc tài lộc trong phòng làm việc, công ty hoặc trong nhà có tác dụng trấn án – trừ tà – ngăn chặn sát khí, giúp bạn làm ăn thịnh vượng, phát tài.

**4. Đá thạch anh tím tăng cường trí tuệ và cân bằng trạng thái tinh thần:**

- Đặt thạch anh tím trên bàn học hoặc đầu giường giúp bạn phát huy trí tuệ và cải thiện thị lực.

**5. Đá thạch anh trắng khử sóng điện từ phát ra từ tivi, máy tính, lò vi sóng:**

- Bên cạnh tivi, máy tính, lò vi sóng đặt một sản phẩm thuộc họ thạch anh màu trắng, có tác dụng giảm bớt bức xạ phát ra.

**6. Nhà không được hướng:**

- Đối diện chính cửa ra vào là đường cái hoặc vị trí nhà ở góc đường hình chữ L, cửa nhà có cây to hoặc cột điện nên đặt động thạch anh tímđểhóa giải.

**7. Khử mùi:**

- Cửa nhà vệ sinh treo thạch anh hoặc đặt thạch anh có thể giải uế khí.

**8. Hóa giải hiện tượng bóng đè:**

- Đầu giường hoặc dưới chân giường nênđặt một sản phẩm bất kỳ thuộc họ thạch anh có thể hóa giải hiện tượng bị bóng đè.

**9. Nơi kinh doanh, buôn bán:**

- Tại quầy bán hàng, hay showroom đặt thạch anh tím hoặc thạch anh hồng giúp tăng cường nhân duyên và duyên bán hàng.

**10. Cách cầu tài với đĩa thất tinh đá thạch anh:**

- Dùng Trận thất tinh (đĩa thất tinh thạch anh) hoặc thạch anh vàng cầu tài.

**11. Đá thạch anh hồng cải thiện tình cảm, thắt chặt tình duyên:**

- Đầu giường đặt thạch anh hồng có tác dụng dung hòa tình cảm giữa bạn bè, người thân, cải thiện mối quan hệ chăn gối hai vợ chồng.

[*Thegioidaquy.net*](https://web.archive.org/web/20150211044056/http://thegioidaquy.net/phongthuy.html)',
    '2015-02-02 09:00:00', 0, 1128, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-087', 'mua-hang-va-chinh-sach-bao-hanh-da', 'Mua hàng và chính sách bảo hành đá', 'Thế Giới Đá Quý',
    '/uploads/site_assets/Phongthuy-HoaMocLan-thegioidaquy.jpg', 'Để bảo đảm quyền lợi, chúng tôi khuyên khách hàng nên mua hàng đúng chổ chuyên về đá như TheGioiDaQuy.Net, chúng tôi cam kết đem đến sản phẩm chất lượng loại 1 với giá cạnh tranh.', '## Lời nói đầu

Đến với**phong thuỷ**là bạn đang muốn cải biến số mạng của mình, cầu tài lộc may mắn, sức khoẻ, tình duyên, sự nghiệp... thì trước tiên bạn phải cầu tâm trước rồi hãy chọn vật phẩm phong thuỷ cho mình. Các vật phẩm phong thuỷ**bằng đá tự nhiên**chỉ có ở cửa hàng chuyên doanh, uy tín lâu năm như**TheGioiDaQuy.Net**mới có, phần nhiều các cửa hàng hiện nay chuyên bán bột đá, đá nhân tạo và nhựa đổ khuôn.

- Vì vậy để bảo đảm quyền lợi, chúng tôi khuyên khách hàng nên mua hàng đúng chổ, đúng giá để ủng hộ cửa hàng chi trả tiền lương cho thợ chạm đá và các chi phí tối thiểu khác, và nhất là để**cung cấp hàng hóa chất lượng**tốt nhất cho khách hàng. TheGioiDaQuy.Net cam kết đem đến sản phẩm chất lượng loại 1 với giá cạnh tranh nhất.

- Xin lưu ý về vấn đề tâm linh thì khi trả giá để**mua đá**,**mặt phật bản mệnh**... thì đồng nghĩa với  việc bạn đang trả giá cho giá trị năng lượng đá của linh vật mình  đang thỉnh về, điều này là không nên. Bạn nên tìm hiểu giá và chọn mua đá tại cửa hàng uy tín như TheGioiDaQuy.Net, bạn chi vài trăm nghìn, vài triệu nhưng lợi ích của những linh vật đem lại cho bạn là vô cùng lớn.

- Một điều chú ý nữa là khi bạn đã**thỉnh mặt phật**, mặt đá trên website thì nên cố gắng thu xếp thời gian, công việc để tiếp nhận, tránh tâm lý nhận hay không nhận cũng chẳng sao " hàng sẽ trả về tôi chẳng mất mát gì ". Với suy nghĩ như vậy bạn đã bị mất mát, cầu tâm không thấy và còn đùa giỡn với vận số của mình.

Sau đây là những chính sách mua hàng, vận chuyển, thanh toán và bảo hành dành cho khách hàng mua đá tại TheGioiDaQuy.Net

## Hình thức thanh toán

1. Khách mua hàng tại chổ: thanh toán tiền mặt

2. Khách mua hàng trên mạng: cửa hàng vận chuyển qua cty chuyển phát nhanh uy tín. Có hai hình thức vận chuyển:

- Nhận hàng và trả tiền tại chổ: còn gọi là COD tức là chuyển phát nhanh đến tận nhà và thu hộ tiền hàng. Có thu phí dịch vụ

- Chuyển khoản trước, nhận hàng sau: khách chuyển tiền hàng và tiền cước trước thông qua chuyển khoản ngân hàng, sau khi nhận cửa hàng sẽ chuyển hàng cho khách sau. Có thu phí, phí rẻ hơn hình thức COD một chút.

Số tài khoản ngân hàng ĐÔNG Á: 0102060783, chủ TK: Đoàn Quốc Sơn,chi nhánh Sư Vạn Hạnh, Q10 TP.HCM

## Bảo đảm chất lượng

Giá**đá thô**trên thị trường hay thay đổi do**đá - ngọc**có chất lượng và tính quý hiếm khác nhau, nhưng TheGioiDaQuy.Net đảm bảo giá của sản phẩm bán ra luôn có giá cạnh tranh, và bảo đảm các yêu cầu  sau:

- Sản phẩm đăng bán đúng chất liệu đá.

- Hình chụp trên website là ảnh chụp của sản phẩm, không dùng Photoshop chỉnh sửa thêm màu.

- Giá niêm yết trên website và tại cửa hàng là một, chỉ một số ít trường hợp đặc biệt giá đá thô thay đổi liên tục cửa hàng không cập nhật kịp thời.

- Các mặt chạm khắc như**Mặt phật**,**Quan âm**,**Di lặc**,**Đức mẹ**,**Giêsu**,**Rồng**... đều đẹp và có giá vừa phải.

## Qui định về bảo hành, đãi ngộ và sửa chữa

- Được thay dây và bớt hạt miễn phí tại lúc mua ( nếu thêm hạt thì tính thêm tiền hạt thêm theo giá hiện tại ).
- Được gửi tặng miễn phí một dây kết dự phòng kèm theo cho khách mua Vòng tay đá đặt qua online.
- Được mua thêm dây kết: cửa hàngcó bán cuộn dây, có đủ các màu cho quý khách lựa chọn.

- Được hưởng chính sách khuyến mãi của cửa hàng tại thời điểm đó, kể cả khách mua tại cửa hàng và mua online.

- Được**bảo hành sản phẩm, hổ trợ chạm khắc**: trong quá trình sử dụng khách làm rơi mặt đá, bị va đập mạnh. Mặt đá bị mẻ chút thì cửa hàng nhận mài lại mặt ( ít thì miễn phí, nhiều thì có tính chút phí cho thợ ). Nếu bị vỡ đôi thì cửa hàng sẽ tư vấn cho khách chạm thành các sản phẩm khác theo kích thước đá vỡ hiện có ( có tính công chạm khắc của thợ ).

- Được tư vấn phong thuỷ miễn phí: khách mua tại cửa hàng thì tư vấn ngay tại cửa hàng, khách mua online thì được tư vấn bằng các tin nhắn qua các chương trình viber, wechat, tango.

- Được đảm bảo mua sản phẩm đúng như đã đăng. ( lưu ý: đá tự nhiên thì có ít hoặc nhiều vân, mây, sớ... là bình thường, đá tự nhiên sẽ không hoàn hảo 100% như đá nhân tạo hay thuỷ tinh )

- Được giảm giá khi khách đặt chạm khắc riêng các mặt đá theo yêu cầu ( đãi ngộ này chỉ dành cho khách đã mua hàng của TheGioiDaQuy.Net )

- Không được bảo hành khi bị gãy vỡ, nhạt màu do phơi nắng, do hóa chất, hoặc đốt…

## Đặt hàng sau bao lâu tôi nhận được hàng

- Hiện nay, chúng tôi vận  chuyển theo hệ thống chuyển phát nhanh của Bưu điện Việt  Nam EMS, với phương châm phục vụ “Nhanh chóng và bảo đảm”. Từ thời điểm đơn hàng của khách đặt và cửa hàng đã xác nhận bằng điện thoại với khách thì thời gian vận chuyển từ 2-3 ngày. Vùng sâu, vùng xa trung tâm thành phố thì 4-5 ngày.

- Khách mua hàng ở TPHCM, chúng tôi áp dụng hình thức chuyển phát nhanh của Bưu điện Việt Nam hoặc chúng tôi sẽ có nhân viên giao tận nhà cho khách, có tính phí.
- Sản phẩm của Quý khách**đặt mua online****tại TheGioiDaQuy.Net**sau khi được xác nhận sẽ được gửi đi ngay trong ngày trước 17h30 hoặc 8g sáng hôm sau.

-  Riêng đối với những đơn hàng đặt trong ngày thứ bảy và trong ngày Chủ  nhật, hàng của Quý khách sẽ được chuyển đi vào ngày thứ hai của tuần kế  tiếp.
- Khi chuyển hàng chúng tôi ghi rõ thông tin họ tên người nhận, địa chỉ và số điện thoại của khách trên bưu phẩm. Quý khách cần**sắp xếp thời gian để nhận**hoặc uỷ quyền cho người thân nhận dùm mình. Cty EMS mỗi lần đi giao là rất nhiều bưu phẩm và phải chuyển nhanh ở vô số địa chỉ khác nhau nên họ không thể chờ bạn lâu được.
- Nếu  đơn hàng đã gửi đi, chậm nhất sau 5  ngày ( không tính Thứ 7 và Chủ Nhật ) bạn sẽ có hàng, trường hợp hàng chưa chuyển đến nhà bạn vì lý do nào đó, bạn có thể  liên lạc với TheGioiDaQuy.Net để lấy**mã bưu phẩm**và đến nhận tại bưu điện gần nhất.

## Biểu phí chuyển phát nhanh sau khi đóng gói bưu phẩm:

- Kiện hàng < 50g có nhờ thu hộ COD < 1 triệu VND: phí 40k.

- Kiện hàng 50g - 100g có nhờ thu hộ COD < 1triệu VND: phí 50k.

- Kiện hàng < 50g có nhờ thu hộ COD 1 triệu - 5 triệu VND: phí 60k

- Kiện hàng 50-100g có nhờ thu hộ COD 1 triệu - 5 triệu VND: phí 80k.

- Kiện hàng lớn, mua 1 lần nhiều hàng >20 triệu VND: miễn phí vận chuyển.

- Kiện hàng chuyển nhanh không có COD thì phí có rẻ hơn chút, nhưng khách chuyển khoản ngân hàng thì có khi ngân hàng tính phí cao hơn phí nhờ thu hộ COD. Chúng tôi khuyên khách mua online nên dùng dịch vụ COD.

- Quý khách có thể đề xuất 1 dịch vụ vận chuyển khác mà mình hay dùng, sau khi nhận được tiền chuyển khoản, cửa hàng sẽ chuyển theo yêu cầu.

[*TheGioiDaQuy.Net*](https://web.archive.org/web/20140714075751/http://thegioidaquy.net/phongthuy.html)',
    '2014-07-02 09:00:00', 0, 1171, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-088', 'da-mat-meo-chrysoberyl', 'Đá mắt mèo (Chrysoberyl)', 'Thế Giới Đá Quý',
    '/uploads/news/art-088-1-1-cau-da-mat-meo-xanh-luc-0-new.jpg', 'Đá mắt mèo hay còn gọi là Chrysoberyl, là một loại đá quý tương đối cứng, chắc và bền với độc cứng chắc tuyệt vời là 8.5 trên thang Mohs. Loại đá này rất được ưa chuộng trong việc chế tạo trang sức phong thủy như: Vòng tay đá mắt mèo, nhẫn đá mắt mèo…', '**-[Đámắt mèo](https://web.archive.org/web/20150107183820/http://thegioidaquy.net/phong-thuy/da-phongthuy-118-Da-Mat-Meo-Chrysoberyl-)**hay còn gọi làChrysoberyl làloại khoáng vật thuộc hệtrực thoi với công thức hóa học làBeAL2O4.Người Hy Lạp cổđại gọi loạiđánày là“cymophane”, nghĩa làánh sáng di chuyển.

- Đámắt mèo làmột loạiđáquý tươngđối cứng, chắc vàbền vớiđộc cứng chắc tuyệt vời là8.5 trên thang Mohs. Dođóloạiđánày rấtđượcưa chuộng trong việc chếtạo trang sức phong thủy như:*V**òng tayđámắt mè**o*,*nhẫnđámắt mèo*…

- Từthời xa xưa, người Hy Lạp cổđại gọiđámắt mèo là“Cymophane” nghĩa làánh sáng di chuyển. Bởi**đámắt mèo cóthểthayđổi màu sắ****c**vàlấp lánh nhưmắt con mèo dướiánhđiện vàánh nắng. Nếu quan sát kỹ, khi nhìn vào viênđámắt mèo ta sẽthấy một dải rực sáng phản chiếu quét ngang qua phần vòm làm cho viênđágiống y mắt của một con mèo. Chúng cùng một họhàng với alexandrite vềviệc thayđổi màu sắc. Loạiđáquý thuộc nhóm chrysoberyl này làmộtđiển hình nổi tiếng nhất về*hiệuứng mắt mèo*. Hiệuứng này cóđược làdo sựtácđộng củaánh sáng lên các bao thểli ti hình kim bên trong viênđá.

-**Màu c****ủađámắt mè****o**cótừmàu nâu chođến màu lục. Trongđó*màu vàng kim làcógiátrịcao nhất*.**Đámắt mèo**được cho làđẹp thường cóhiện tượng sữa vàmật ong. Khi chiếu sáng theo chiều thẳng góc với mắt, hướng vào hông viênđáthìchúng ta sẽthấy một bên mắt sẽcómàu trắng sữa, bên kia vẫn giữa màu vàng kimđến nâu.

[![cau-da-mat-meo-xanh-luc](/uploads/news/art-088-1-1-cau-da-mat-meo-xanh-luc-0-new.jpg)](https://web.archive.org/web/20150107183820/http://thegioidaquy.net/phong-thuy/qua-cau-da-mat-meo-xanh-luc-tuoi-1739.html#.VISBxNKsVlw)

*[Quả cầu đá mắt mèo xanh lục](https://web.archive.org/web/20150107183820/http://thegioidaquy.net/phong-thuy/qua-cau-da-mat-meo-xanh-luc-tuoi-1739.html#.VISBxNKsVlw)[phong thuỷ](https://web.archive.org/web/20150107183820/http://thegioidaquy.net/phong-thuy/qua-cau-da-mat-meo-xanh-luc-tuoi-1739.html#.VISBxNKsVlw)phù hợp cho người mạng Mộc mạng Hoả*

- Màu sắc sẽxoay theo hướng viênđáxoay.**Khi b****ạn chiếu hai nguồn sáng lênđámắt mè****o**vàrồi xoay viênđáthìviênđánày sẽnháy vàtách ra thành hai dải sáng xa dần rồi sauđóchập lại. Người ta gọi hiệuứng này là“Mởvàkhép”.

- Yếu tốgiátrịquan trọng nhất củađámắt mèo chính làđộsắc nét của mắt. Người ta thường rửađámắt mèo bằng xàphòng trong nướcấm rồi dùng bàn chải chàvào phía sau viênđá. Bởi vìnơiđóthường hội tụvàdính nhiều chất dơ.

- Trong nhiều nền văn hóa xưa, người ta cho rằngđámắt mèocókhảnăng rất tốt trong việc trịliệu các bệnh liên quan vềmắt.

-**Đá****mắt mè****o**thườngđược tìm thấyởSri Lanka, Brazin, Tanzania, Madagasca,ẤnĐộvàmột sốnơi khác.

[![vong-tay-da-mat-meo-Vang-12-ly](/uploads/news/art-088-2-1-vong-tay-da-mat-meo-vang-12-ly-0.jpg)](https://web.archive.org/web/20150107183820/http://thegioidaquy.net/phong-thuy/vong-tay-da-mat-meo-vang-12-ly-2309.html#.VISC4NKsVlw)

*[Vòng tay đá mắt mèo phong thuỷ](https://web.archive.org/web/20150107183820/http://thegioidaquy.net/phong-thuy/vong-tay-da-mat-meo-vang-12-ly-2309.html#.VISC4NKsVlw)đem lại may mắn cho người đeo*

- Với người La Mã cổđại thìloại khoáng chất này không cógìxa lạ, nóđã trởnên quen thuộc vàphổbiến ngay từthếkỷđầu tiên.

- Tại PhươngĐông, người ta tin rằng,**n****ếu aiđóđặt viênđámắt mèo lên trá****n**tại vùng chính giữađôi mắt thìnósẽgiúp họcóthểnhìnđược thông suốt mọi vấnđề.

- CònởSri Lanka, cómột câu chuyện truyền tụng vềđámắt mèo rằng nócókhảnăng bảo vệcon người khỏi ma quỷ. Vìvậyđámắt mèođược xem nhưlàbùa hộmệnh, cókhảnăng tăng cường sức mạnh vềthểchất, khuyến khích sáng tạo, giúp tinh thần minh mẫn tập trung.

- Ngoài ra**lo****ạiđámắt mè****o**còn cóthểmang lại sựmay mắn, tài lộc cho chủnhân.

[*Thegioidaquy.net*](https://web.archive.org/web/20150107183820/http://thegioidaquy.net/phongthuy.html)',
    '2014-12-08 09:00:00', 0, 1214, 'published'
);

INSERT INTO posts (
    id, slug, title, category, thumbnail, excerpt, content, published_at, is_page, views, status
) VALUES (
    'art-leg-089', 'y-nghia-phong-thuy-cua-da-ma-nao', 'Ý nghĩa phong thủy của đá mã não', 'Thế Giới Đá Quý',
    '/uploads/news/art-089-1-1-vong-tay-phat-ban-menh-pho-hien-da-ma-nao-10-ly-0.jpg', 'Đá mã não (Agate) là một loại đá tự nhiên với tên gọi bắt nguồn từ Tiếng Hy Lạp cổ đại. Theo phong thủy, đá mã não chính là biểu tượng của sức khỏe, mang lại sự sung túc và trường thọ.', '[if !supportLists]

**1. Ý nghĩa phong thủy:**

- Về bản chất**[đá mã não](https://web.archive.org/web/20141004203943/http://thegioidaquy.net/phong-thuy/da-phongthuy-116-Da-Ma-Nao-Agate-)**chính là một biến thể của thạch anh. Bằng cách hấp thụ năng lượng có hại, đá mã não có thể giúp bảo vệ chống lại những xung năng lượng, đem lại sự an toàn cho chủ sỡ hữu. Đá mã não rất được ưa chuộng ở các nước Châu âu và Ấn Độ,**loại đá phong thủy này**được xem là sự biểu tượng của sức khỏe, sự hưng thịnh và trường thọ.

- Với ý nghĩa là loại đá hộ mệnh, mang mã não như mang một lá bùa may mắn và hạnh phúc cho con người, ngày nay***đá mã não***được ứng dụng rất nhiều trong việc chế tạo các loại trang sức như:[mặt dây chuyền Phật bản mệnh bằng đá mã não](https://web.archive.org/web/20141004203943/http://thegioidaquy.net/phong-thuy/phat-ban-menh-tuoi-Thin-da-ma-nao-3147.html#.VCRLHZR_tlw),[nhẫn đá mã não,](https://web.archive.org/web/20141004203943/http://thegioidaquy.net/phong-thuy/nhan-da-ma-nao-den-mat-tron-3080.html#.VCRL-ZR_tlw)[vòng tay Phật bản mệnh bằng đá mã não](https://web.archive.org/web/20141004203943/http://thegioidaquy.net/phong-thuy/vong-tay-phat-ban-menh-a-di-da-da-ma-nao-10-ly-3072.html#.VCRLeJR_tlw)

- Việc đeo trang sức bằng đá mã não có thể làm giảm tính bảo thủ, áp lực, hóa giải những sự cãi vã, mâu thuẫn đem lại sự bình yên và may mắn.

[![vong-tay-phat-ban-menh-Pho-Hien-da-ma-nao](/uploads/news/art-089-1-1-vong-tay-phat-ban-menh-pho-hien-da-ma-nao-10-ly-0.jpg)](https://web.archive.org/web/20141004203943/http://thegioidaquy.net/phong-thuy/vong-tay-phat-ban-menh-pho-hien-da-ma-nao-10-ly-3071.html#.VCRM6ZR_tlw)

*[Vòng đá đeo tay Phật bản mệnh Phổ Hiền đá mã não](https://web.archive.org/web/20141004203943/http://thegioidaquy.net/phong-thuy/vong-tay-phat-ban-menh-pho-hien-da-ma-nao-10-ly-3071.html#.VCRM6ZR_tlw)hộ mệnh cho Tuổi Thìn, Tuổi Tỵ đem lại sự bình an*

- Đàn ông đeo[*nhẫn*](https://web.archive.org/web/20141004203943/http://thegioidaquy.net/phong-thuy/nhan-da-ma-nao-do-ban-nho-2012.html#.VCwI0HbQxaU)*[mã não](https://web.archive.org/web/20141004203943/http://thegioidaquy.net/phong-thuy/nhan-da-phat-son-trung-2008.html#.VCwJtHbQxaU),*[*mặt đá mã nã*o](https://web.archive.org/web/20141004203943/http://thegioidaquy.net/phong-thuy/vong-tay-ty-huu-da-ma-nao-nau-10-ly-2927.html#.VCwJNHbQxaU)sẽ giúp họ trở nên quyến rũ hơn trong mắt phụ nữ.

- Mang mã não chứa nước có tác dụng tăng cường khả năng giao tiếp, ngoại giao giỏi và tang cường khả năng ứng xử linh hoạt.

- Người Ai Cập cổ đại tin rằng, khi đi giữa sa mạc, việc**ngậm một viên mã não**có tác dụng vượt qua những cơn khát nước.

-Đá mã nãochính là biểu tượng của chòm sao Kim ngưu và Song tử trong 12 cung hoàng đạo.

[![phat-ban-menh-tuoi-Ngo-da-ma-nao](/uploads/news/art-089-2-1-phat-ban-menh-tuoi-ngo-da-ma-nao-0.jpg)](https://web.archive.org/web/20141004203943/http://thegioidaquy.net/phong-thuy/phat-ban-menh-tuoi-Ngo-da-ma-nao-3144.html#.VCRN45R_tlw)

*[Mặt dây chuyền Phật bản mệnh Tuổi Ngọ](https://web.archive.org/web/20141004203943/http://thegioidaquy.net/phong-thuy/phat-ban-menh-tuoi-Ngo-da-ma-nao-3144.html#.VCRN45R_tlw)đá mã não giúp tích lũy được tiền bạc, thuận lợi và bình an*

[if !supportLists]**2. Tác dụng chữa bệnh:**

Ngoài những ý nghĩa về mặt phong thủy, mã não còn có tác dụng chữa bệnh cho con người như sau:

[if !supportLists]-*Tinh thể mã não*là một tinh thể tuyệt vời để làm cân bằng và hài hòa cơ thể, loại bỏ sự tiêu cực.

[if !supportLists]-*[Vòng tay đá mã não](https://web.archive.org/web/20141004203943/http://thegioidaquy.net/phong-thuy/vong-tay-phat-ban-menh-thien-thu-thien-nhan-da-ma-nao-10-ly-3068.html#.VCwKMXbQxaU)làm xoa dịu cơn đau*cho những phụ nữ trong thời kỳ đang mang thai và ngăn tình trạng lệch dạ con sau khi sinh.

[if !supportLists]- Khi cơ thể có biểu hiện nóng sốt bất thường, dùng**đá mã não**lăn nhiều lần trên da, có tác dụng làm giảm nhiệt độ cơ thể.

[if !supportLists]- Ngoài ra[***đá mã não***](https://web.archive.org/web/20141004203943/http://thegioidaquy.net/phong-thuy/da-phongthuy-116-Da-Ma-Nao-Agate-)còn có tác dụng làm giảm co giật, bảo vệ cơ thể chống lại một số bệnh về dạ dày.

[***Thegioidaquy.net***](https://web.archive.org/web/20141004203943/http://thegioidaquy.net/phongthuy.html)',
    '2014-09-25 09:00:00', 0, 307, 'published'
);

